        (uint256 renterAmount, uint256 lenderAmount) = _calculatePaymentProRata(
            amount,
            elapsedTime,
            totalTime
        );

        // Send the lender portion of the payment if non-zero.
        if (lenderAmount != 0) {
            _safeTransfer(token, lender, lenderAmount);
        }

        // Send the renter portion of the payment if non-zero.
        if (renterAmount != 0) {
            _safeTransfer(token, renter, renterAmount);
        }
    }
```

