            STORE.addRentals(orderHash, _convertToStatic(rentalAssetUpdates));

            // Interaction: Increase the deposit value on the payment escrow and ensure
            // each ERC20 item is backed by the actual escrow balance.
            for (uint256 i = 0; i < items.length; ++i) {
                if (items[i].isERC20()) {
                    ESCRW.increaseDeposit(items[i].token, items[i].amount);
                    if (
                        IERC20(items[i].token).balanceOf(address(ESCRW)) <
                        ESCRW.balanceOf(items[i].token)
                    ) {
                        revert Errors.PaymentEscrowModule_InsufficientBalance(
                            items[i].token
                        );
                    }
                }
            }

            // Interaction: Process the hooks associated with this rental.
            if (payload.metadata.hooks.length > 0) {
                _addHooks(
                    payload.metadata.hooks,
                    seaportPayload.offer,
                    payload.fulfillment.recipient
