```

Validate in `_executionInvariantChecks` that every rental item and ERC20 payment item in the order is explicitly matched by a corresponding execution in `executions` with the expected token, identifier, amount, and recipient (`expectedRentalSafe` for rental assets and `address(ESCRW)` for ERC20 tokens), and ensure that Seaport populates `totalExecutions` across all supported fulfillment entrypoints (or disable `fulfillAdvancedOrder` if `totalExecutions` is not populated).

```solidity
    function _executionInvariantChecks(
        SpentItem[] memory offer,
        ReceivedItem[] memory consideration,
        OrderType orderType,
        ReceivedItem[] memory executions,
        address expectedRentalSafe
    ) internal view {
        if (orderType.isBaseOrder() || orderType.isPayOrder()) {
            for (uint256 i = 0; i < offer.length; ++i) {
                SpentItem memory item = offer[i];
                address expectedRecipient = item.isERC20()
                    ? address(ESCRW)
                    : expectedRentalSafe;

                if (!item.isERC20() && !item.isRental()) {
                    revert Errors.CreatePolicy_SeaportItemTypeNotSupported(
                        item.itemType
                    );
                }

                bool found;
                for (uint256 j = 0; j < executions.length; ++j) {
                    ReceivedItem memory execution = executions[j];
                    if (
                        execution.itemType == item.itemType &&
                        execution.token == item.token &&
                        execution.identifier == item.identifier &&
                        execution.amount == item.amount &&
                        execution.recipient == expectedRecipient
                    ) {
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    revert Errors.CreatePolicy_UnexpectedTokenRecipient(
                        item.itemType,
                        item.token,
                        item.identifier,
                        item.amount,
                        address(0),
                        expectedRecipient
                    );
                }
            }
        }

        if (orderType.isBaseOrder()) {
            for (uint256 i = 0; i < consideration.length; ++i) {
                ReceivedItem memory item = consideration[i];
                if (!item.isERC20()) {
                    revert Errors.CreatePolicy_SeaportItemTypeNotSupported(
                        item.itemType
                    );
                }
                _checkExpectedRecipient(item, address(ESCRW));
            }
        }
    }
```

Validate in `_processBaseOrderConsideration` that every consideration item's `recipient` is `address(ESCRW)`, and ensure that the executions in `totalExecutions` strictly match the expected transfers for the order's `offer` and `consideration` items (both in item counts/amounts and recipients, forbidding self-transfers where `offerer == fulfiller` or `offerer == recipient`).

```solidity
    function validateOrder(
        ZoneParameters calldata zoneParams
    ) external override onlyRole("SEAPORT") returns (bytes4 validOrderMagicValue) {
        // Disallow self-fulfillment where the offerer and fulfiller are the same address,
        // as Seaport skips executions when sender equals recipient.
        if (zoneParams.offerer == zoneParams.fulfiller) {
            revert Errors.CreatePolicy_UnexpectedTokenRecipient(
                SeaportItemType.NATIVE,
                address(0),
                0,
                0,
                zoneParams.offerer,
                zoneParams.fulfiller
            );
        }

        // Decode the signed rental zone payload from the extra data.
        (RentPayload memory payload, bytes memory signature) = abi.decode(
            zoneParams.extraData,
            (RentPayload, bytes)
        );

        // Ensure the offerer is not the rental safe recipient.
        if (zoneParams.offerer == payload.fulfillment.recipient) {
            revert Errors.CreatePolicy_InvalidRentalSafe(payload.fulfillment.recipient);
        }

        // Verify all consideration items on BASE orders explicitly target ESCRW.
        for (uint256 i = 0; i < zoneParams.consideration.length; ++i) {
            if (
                zoneParams.consideration[i].itemType == SeaportItemType.ERC20 &&
                zoneParams.consideration[i].recipient != address(ESCRW)
            ) {
                revert Errors.CreatePolicy_UnexpectedPaymentEscrowRecipient(
                    zoneParams.consideration[i].recipient
                );
            }
        }

        // Create a payload of seaport data.
        SeaportPayload memory seaportPayload = SeaportPayload({
            orderHash: zoneParams.orderHash,
            zoneHash: zoneParams.zoneHash,
            offer: zoneParams.offer,
            consideration: zoneParams.consideration,
            totalExecutions: zoneParams.totalExecutions,
            fulfiller: zoneParams.fulfiller,
            offerer: zoneParams.offerer
        });
```

Additionally, for `PAY` orders, verify that each item in `zoneParams.offer` has a matching execution in `zoneParams.totalExecutions` with the exact token, identifier, amount, and expected recipient (`payload.fulfillment.recipient` for ERC721/ERC1155 and `address(ESCRW)` for ERC20).

Bind the `CREATE_SIGNER` signature to the specific Seaport `orderHash` being validated in `Create.validateOrder` (and ensure `_deriveOrderMetadataHash` hashes all fields of `OrderMetadata`, including `orderType` and `emittedExtraData`).

Specifically, include `orderHash` in the payload hash verification in `Create.validateOrder` (or validate `payload.orderHash == zoneParams.orderHash` when constructing `seaportPayload`):

```solidity
    function validateOrder(
        ZoneParameters calldata zoneParams
    ) external override onlyRole("SEAPORT") returns (bytes4 validOrderMagicValue) {
        // Decode the signed rental zone payload from the extra data.
        (RentPayload memory payload, bytes memory signature) = abi.decode(
            zoneParams.extraData,
            (RentPayload, bytes)
        );

        // Create a payload of seaport data.
        SeaportPayload memory seaportPayload = SeaportPayload({
            orderHash: zoneParams.orderHash,
            zoneHash: zoneParams.zoneHash,
            offer: zoneParams.offer,
            consideration: zoneParams.consideration,
            totalExecutions: zoneParams.totalExecutions,
            fulfiller: zoneParams.fulfiller,
            offerer: zoneParams.offerer
        });

        // Check: The signature from the protocol signer has not expired.
        _validateProtocolSignatureExpiration(payload.expiration);

        // Check: The fulfiller is the intended fulfiller.
        _validateFulfiller(payload.intendedFulfiller, seaportPayload.fulfiller);

        // Recover the signer from the payload bound to the specific Seaport orderHash.
        address signer = _recoverSignerFromPayload(
            _deriveRentPayloadHash(payload, seaportPayload.orderHash),
            signature
