                _loadValueFromCalldata(data, e721_transfer_from_token_id_offset)
            );

            // Check if the selector is allowed for both the caller safe and the token owner.
            _revertSelectorOnActiveRental(selector, from, to, tokenId);
            if (owner != from) {
                _revertSelectorOnActiveRental(selector, owner, to, tokenId);
