            address recipient = holders[i];
            uint256[] memory receipts = new uint256[](
                distributableERC20s.length
            );
            for (uint j = 0; j < distributableERC20s.length; j++) {
                IERC20 toDistribute = IERC20(distributableERC20s[j]);
                uint256 entitlement = erc20EntitlementPerUnit[j] *
                    this.balanceOf(recipient);
                if (toDistribute.transfer(recipient, entitlement)) {
                    receipts[j] = entitlement;
                }
            }

            emit Distribution(recipient, distributableERC20s, receipts);
        }
```

findings.technical_details:
In `LiquidInfrastructureERC20`, revenue distributions occur in two steps:

1. When a distribution begins in `_beginDistribution()` (lines 270–277), the contract computes the per-unit entitlement for each reward token `distributableERC20s[i]` using unscaled integer division:
   ```solidity
   uint256 supply = this.totalSupply();
   for (uint i = 0; i < distributableERC20s.length; i++) {
       uint256 balance = IERC20(distributableERC20s[i]).balanceOf(
           address(this)
       );
       uint256 entitlement = balance / supply;
       erc20EntitlementPerUnit.push(entitlement);
   }
   ```
2. During `distribute()` (lines 220–227), each approved holder's payout is calculated by multiplying the pre-divided `erc20EntitlementPerUnit[j]` by the holder's token balance:
   ```solidity
   for (uint j = 0; j < distributableERC20s.length; j++) {
       IERC20 toDistribute = IERC20(distributableERC20s[j]);
       uint256 entitlement = erc20EntitlementPerUnit[j] *
           this.balanceOf(recipient);
       if (toDistribute.transfer(recipient, entitlement)) {
           receipts[j] = entitlement;
       }
   }
   ```

Because integer division `balance / supply` is performed before multiplying by `this.balanceOf(recipient)`—instead of computing `(balance * this.balanceOf(recipient)) / supply` or scaling `erc20EntitlementPerUnit` by a high-precision multiplier—severe truncation occurs in two common scenarios:

- **Reward balance smaller than `totalSupply()` (`balance < supply`):** `LiquidInfrastructureERC20` inherits `decimals() = 18` from OpenZeppelin's `ERC20`. If `totalSupply()` is `1,000e18` (`1,000` tokens), any reward token with fewer decimals (e.g., USDC or USDT with 6 decimals, WBTC with 8 decimals) will practically always have `balance < supply` (for example, `1,000,000e6` USDC is `1e12 < 1e21`). Similarly, even for an 18-decimal reward token, if the revenue collected for the period is `500e18` (`0.5` reward tokens per share token), `balance / supply` evaluates to `500e18 / 1,000e18 = 0`. Consequently, `erc20EntitlementPerUnit[j]` is `0`, and `entitlement` at lines 222–223 evaluates to `0` for every holder.
- **Reward balance not an exact multiple of `totalSupply()` (`balance % supply != 0`):** Even when `balance >= supply`, up to `supply - 1` wei of each reward token is discarded during the integer division. For example, if `supply = 1,000e18` and `balance = 1,999e18`, `erc20EntitlementPerUnit[j]` is `1`, so only `1,000e18` is distributed across all holders while `999e18` (nearly half of the accrued revenue) remains stuck in the contract until a future distribution.

findings.remediation:
Store the snapshot of each distributable token's balance at the beginning of the distribution (or scale `erc20EntitlementPerUnit` by a precision multiplier such as `1e18`), and perform the multiplication by `this.balanceOf(recipient)` before dividing by `totalSupply()` in `distribute()`.

In `_beginDistribution()` and `distribute()`:

```solidity
    function distribute(uint256 numDistributions) public nonReentrant {
        require(numDistributions > 0, "must process at least 1 distribution");
        if (!LockedForDistribution) {
            require(
                _isPastMinDistributionPeriod(),
                "MinDistributionPeriod not met"
            );
            _beginDistribution();
        }

        uint256 limit = Math.min(
            nextDistributionRecipient + numDistributions,
            holders.length
        );

        uint256 supply = this.totalSupply();
        uint i;
        for (i = nextDistributionRecipient; i < limit; i++) {
            address recipient = holders[i];
            if (isApprovedHolder(recipient)) {
                uint256[] memory receipts = new uint256[](
                    distributableERC20s.length
                );
                uint256 recipientBalance = this.balanceOf(recipient);
                for (uint j = 0; j < distributableERC20s.length; j++) {
                    IERC20 toDistribute = IERC20(distributableERC20s[j]);
                    uint256 entitlement = (erc20EntitlementPerUnit[j] *
                        recipientBalance) / supply;
                    if (toDistribute.transfer(recipient, entitlement)) {
                        receipts[j] = entitlement;
                    }
                }

                emit Distribution(recipient, distributableERC20s, receipts);
            }
        }
        nextDistributionRecipient = i;

        if (nextDistributionRecipient == holders.length) {
            _endDistribution();
        }
    }

    function _beginDistribution() internal {
        require(
            !LockedForDistribution,
            "cannot begin distribution when already locked"
        );
        LockedForDistribution = true;

        if (erc20EntitlementPerUnit.length > 0) {
            delete erc20EntitlementPerUnit;
        }

        for (uint i = 0; i < distributableERC20s.length; i++) {
            uint256 balance = IERC20(distributableERC20s[i]).balanceOf(
                address(this)
            );
            erc20EntitlementPerUnit.push(balance);
        }

        nextDistributionRecipient = 0;
        emit DistributionStarted();
    }
```

findings.technical_details:
`LiquidInfrastructureERC20` maintains a KYC allowlist (`HolderAllowlist`) queried via `isApprovedHolder(address)`. An account that is initially approved via `approveHolder` can receive `LiquidInfrastructureERC20` tokens (increasing `totalSupply()` and adding the account to the `holders` array) and later be disapproved via `disapproveHolder`. Disapproving an account sets `HolderAllowlist[holder] = false`, which prevents the account from receiving additional `LiquidInfrastructureERC20` tokens in `_beforeTokenTransfer` (lines 133–138), but leaves the holder's existing token balance intact in `totalSupply()` and keeps the address in `holders`.

When a distribution starts in `_beginDistribution()` (lines 257–281), the reward entitlement per unit of `LiquidInfrastructureERC20` is calculated across the entire `totalSupply()`:

```solidity
uint256 supply = this.totalSupply();
for (uint i = 0; i < distributableERC20s.length; i++) {
    uint256 balance = IERC20(distributableERC20s[i]).balanceOf(
        address(this)
    );
    uint256 entitlement = balance / supply;
    erc20EntitlementPerUnit.push(entitlement);
}
```

However, in `distribute(uint256 numDistributions)` (lines 214–236), the contract only transfers entitlements to holders that currently pass `isApprovedHolder(recipient)`:

```solidity
for (i = nextDistributionRecipient; i < limit; i++) {
    address recipient = holders[i];
    if (isApprovedHolder(recipient)) {
        ...
        emit Distribution(recipient, distributableERC20s, receipts);
    }
}
nextDistributionRecipient = i;

if (nextDistributionRecipient == holders.length) {
    _endDistribution();
}
```

When `isApprovedHolder(recipient)` evaluates to `false`:
1. The loop body is skipped (closing at line 230) without transferring the `entitlement` reserved for `recipient`'s balance during `_beginDistribution()`.
2. `nextDistributionRecipient` still advances past `recipient` at line 232.
3. Once `nextDistributionRecipient == holders.length` at line 234, `_endDistribution()` is called at line 235, deleting `erc20EntitlementPerUnit`, unlocking the contract (`LockedForDistribution = false`), and updating `LastDistribution = block.number`.

This causes two payout accounting failures:
- **If disapproved holders are still entitled to revenue accrued by their existing shares** (as implied by `disapproveHolder`'s NatSpec: *"Marks `holder` as NOT approved to hold the token, preventing them from receiving any more of the underlying ERC20"*): skipping them in `distribute()` while advancing `nextDistributionRecipient` and calling `_endDistribution()` permanently deprives them of that epoch's distribution. Their unpaid share remains in the contract and is redistributed to other holders in subsequent epochs (for instance, after the disapproved holder burns their tokens via `burn()` or after new tokens are minted to other holders).
- **If disapproved holders are intended to be excluded from reward distributions**: including their token balances in `this.totalSupply()` during `_beginDistribution()` dilutes `erc20EntitlementPerUnit` for all approved holders. Approved holders receive less than 100% of the distributable revenue for the epoch, leaving the disapproved holders' proportional share stranded in the contract at `_endDistribution()`.

findings.remediation:
If `disapproveHolder` is only intended to prevent an account from receiving additional `LiquidInfrastructureERC20` transfers (while still paying out revenue on existing shares until burned or transferred out), remove the `isApprovedHolder(recipient)` check in `distribute()`.

Alternatively, if disapproved holders must not receive distributions, exclude disapproved holders' balances from the denominator in `_beginDistribution()` (by summing only approved holders' balances instead of `this.totalSupply()`) so that 100% of the distributable rewards are distributed among eligible approved holders.

#### Option 1: Pay existing holders proportionally regardless of subsequent disapproval

```solidity
        uint i;
        for (i = nextDistributionRecipient; i < limit; i++) {
            address recipient = holders[i];
            uint256[] memory receipts = new uint256[](
                distributableERC20s.length
            );
            for (uint j = 0; j < distributableERC20s.length; j++) {
                IERC20 toDistribute = IERC20(distributableERC20s[j]);
                uint256 entitlement = erc20EntitlementPerUnit[j] *
                    this.balanceOf(recipient);
                if (toDistribute.transfer(recipient, entitlement)) {
                    receipts[j] = entitlement;
                }
            }

            emit Distribution(recipient, distributableERC20s, receipts);
        }
        nextDistributionRecipient = i;

        if (nextDistributionRecipient == holders.length) {
            _endDistribution();
        }
```

Isolate external token transfer failures using a low-level call with a bounded gas stipend (or `try/catch` with gas limits) and skip zero-amount transfers so that a single reverting token or recipient cannot block `nextDistributionRecipient` from advancing and reaching `_endDistribution()`:

```solidity
        uint i;
        for (i = nextDistributionRecipient; i < limit; i++) {
            address recipient = holders[i];
            if (isApprovedHolder(recipient)) {
                uint256[] memory receipts = new uint256[](
                    distributableERC20s.length
                );
                for (uint j = 0; j < distributableERC20s.length; j++) {
                    address toDistribute = distributableERC20s[j];
                    uint256 entitlement = erc20EntitlementPerUnit[j] *
                        this.balanceOf(recipient);
                    if (entitlement > 0) {
                        (bool success, bytes memory data) = toDistribute.call{
                            gas: 100000
                        }(
                            abi.encodeWithSelector(
                                IERC20.transfer.selector,
                                recipient,
                                entitlement
                            )
                        );
                        if (
                            success &&
                            (data.length == 0 || abi.decode(data, (bool)))
                        ) {
                            receipts[j] = entitlement;
                        }
                    }
                }

                emit Distribution(recipient, distributableERC20s, receipts);
            }
        }
        nextDistributionRecipient = i;

        if (nextDistributionRecipient == holders.length) {
            _endDistribution();
        }
```

Alternatively, adopt a pull-based reward claiming pattern so individual recipient transfer failures are isolated to the claiming user.

findings.technical_details:
In `MagicLP.getPMMState` (`src/mimswap/MagicLP.sol:193-202`), the pool loads the current reserves (`_BASE_RESERVE_`, `_QUOTE_RESERVE_`), targets (`_BASE_TARGET_`, `_QUOTE_TARGET_`), and `R` state (`_RState_`), and then calls `PMMPricing.adjustedTarget(state)` at line 201 (`getPMMStateForCall` at lines 204-213 calls `getPMMState()`):

```solidity
state.B = _BASE_RESERVE_;
state.Q = _QUOTE_RESERVE_;
state.B0 = _BASE_TARGET_; // will be calculated in adjustedTarget
state.Q0 = _QUOTE_TARGET_;
state.R = PMMPricing.RState(_RState_);
PMMPricing.adjustedTarget(state);
```

`PMMPricing.adjustedTarget` (`src/mimswap/libraries/PMMPricing.sol:190-201`) recomputes the dynamic target reserve `Q0` (when `R == RState.BELOW_ONE`) or `B0` (when `R == RState.ABOVE_ONE`) by calling `Math._SolveQuadraticFunctionForTarget`:

```solidity
if (state.R == RState.BELOW_ONE) {
    state.Q0 = Math._SolveQuadraticFunctionForTarget(state.Q, state.B - state.B0, state.i, state.K);
} else if (state.R == RState.ABOVE_ONE) {
    state.B0 = Math._SolveQuadraticFunctionForTarget(
        state.B,
        state.Q - state.Q0,
        DecimalMath.reciprocalFloor(state.i),
        state.K
    );
}
```

In `Math._SolveQuadraticFunctionForTarget` (`src/mimswap/libraries/Math.sol:79-104`), lines 93-100 compute `_sqrt`:

```solidity
uint256 ki = (4 * k) * i;
if (ki == 0) {
    _sqrt = DecimalMath.ONE;
} else if ((ki * delta) / ki == delta) {
    _sqrt = sqrt(((ki * delta) / V1) + DecimalMath.ONE2);
} else {
    _sqrt = sqrt(((ki / V1) * delta) + DecimalMath.ONE2);
}
```

In the original DODO V2 codebase (written for Solidity 0.6.9), `(ki * delta) / ki == delta` relied on wrapping `uint256` arithmetic to detect whether `ki * delta` overflowed `2^256 - 1`; if it overflowed, execution safely entered the `else` branch and evaluated `((ki / V1) * delta) + DecimalMath.ONE2` by dividing `ki` by `V1` first.

When ported to Solidity `>=0.8.0`, `ki * delta` at line 96 is evaluated using default checked arithmetic. Consequently:
1. Whenever `ki * delta > type(uint256).max`, the condition `(ki * delta) / ki == delta` immediately reverts with `Panic(0x11)` (arithmetic overflow) rather than evaluating to `false`.
2. The fallback `else` branch at lines 98-100 is dead code and can never be reached.

Because `k <= 10^18`, the effective price `i` (or `DecimalMath.reciprocalFloor(state.i) = 10^36 / state.i` when `R == ABOVE_ONE`) can be up to `10^36`, and `delta` (`state.B - state.B0` or `state.Q - state.Q0`) can be up to `type(uint112).max` (`~5.19 * 10^33`), the product `ki * delta = 4 * k * i * delta` can reach `~2.07 * 10^88`, far exceeding `type(uint256).max` (`~1.1579 * 10^77`).

findings.remediation:
Wrap the overflow-detection multiplication in an `unchecked` block (or use `uint256 prod; unchecked { prod = ki * delta; }`) in `Math._SolveQuadraticFunctionForTarget` so that overflow is properly detected and routed to the fallback division-first branch:

```solidity
    function _SolveQuadraticFunctionForTarget(uint256 V1, uint256 delta, uint256 i, uint256 k) internal pure returns (uint256) {
        if (k == 0) {
            return V1 + DecimalMath.mulFloor(i, delta);
        }

        if (V1 == 0) {
            return 0;
        }
        uint256 _sqrt;
        uint256 ki = (4 * k) * i;
        if (ki == 0) {
            _sqrt = DecimalMath.ONE;
        } else {
            uint256 prod;
            unchecked {
                prod = ki * delta;
            }
            if (prod / ki == delta) {
                _sqrt = sqrt((prod / V1) + DecimalMath.ONE2);
            } else {
                _sqrt = sqrt(((ki / V1) * delta) + DecimalMath.ONE2);
            }
        }
        uint256 premium = DecimalMath.divFloor(_sqrt - DecimalMath.ONE, k * 2) + DecimalMath.ONE;
        // V0 is greater than or equal to V1 according to the solution
        return DecimalMath.mulFloor(V1, premium);
    }
```

findings.technical_details:
In `MagicLP`, the PMM pricing invariant depends on the consistency between the current reserves (`B = _BASE_RESERVE_`, `Q = _QUOTE_RESERVE_`), the reference targets at equilibrium (`B0 = _BASE_TARGET_`, `Q0 = _QUOTE_TARGET_`), and the regime indicator (`R = _RState_`):

- When `R == RState.ONE`, the pool is at equilibrium and the PMM algorithm assumes `B == B0` and `Q == Q0`.
- When `R == RState.BELOW_ONE`, `B > B0` and `Q < Q0`, and `B0` is the fixed reference target while `Q0` is dynamically reconstructed from `Q` and `B - B0`.
- When `R == RState.ABOVE_ONE`, `Q > Q0` and `B < B0`, and `Q0` is the fixed reference target while `B0` is dynamically reconstructed from `B` and `Q - Q0`.

In `MagicLP.getPMMState()` (lines 193–202):

```solidity
function getPMMState() public view returns (PMMPricing.PMMState memory state) {
    state.i = _I_;
    state.K = _K_;
    state.B = _BASE_RESERVE_;
    state.Q = _QUOTE_RESERVE_;
    state.B0 = _BASE_TARGET_; // will be calculated in adjustedTarget
    state.Q0 = _QUOTE_TARGET_;
    state.R = PMMPricing.RState(_RState_);
    PMMPricing.adjustedTarget(state);
}
```

`PMMPricing.adjustedTarget(state)` only recomputes `state.Q0` when `state.R == RState.BELOW_ONE` and only recomputes `state.B0` when `state.R == RState.ABOVE_ONE`. When `state.R == RState.ONE`, `adjustedTarget` performs no adjustment at all, leaving `state.B0 = _BASE_TARGET_` and `state.Q0 = _QUOTE_TARGET_`.

This design breaks PMM state consistency during swap and flash loan transitions in two ways:

1. **Incomplete target synchronization when transitioning to `RState.ONE`:**
   When `state.R == RState.ABOVE_ONE` and a trader calls `sellBase` with `payBaseAmount == backToOnePayBase` (`state.B0 - state.B`), `PMMPricing.sellBaseToken` sets `receiveQuoteAmount = backToOneReceiveQuote` (`state.Q - state.Q0`) and `newR = RState.ONE`. `querySellBase` then deducts `lpFee` and `mtFee` from `receiveQuoteAmount`. Because `lpFee` is retained in the pool, the post-swap quote reserve becomes `_QUOTE_RESERVE_ = state.Q0 + lpFee > _QUOTE_TARGET_`. However, `sellBase` (lines 256–260) only updates `_BASE_TARGET_ = newBaseTarget.toUint112()` and `_RState_ = uint32(RState.ONE)`, leaving `_QUOTE_TARGET_` at the pre-fee `state.Q0` (and in `flashLoan`, the caller can leave even more excess quote tokens in the pool while still triggering the transition to `RState.ONE`). Symmetrically, when `sellQuote` transitions from `BELOW_ONE` to `ONE`, `_BASE_RESERVE_` retains `lpFee` (`_BASE_RESERVE_ = state.B0 + lpFee > _BASE_TARGET_`), while only `_QUOTE_TARGET_` is updated.
   On subsequent calls to `getPMMState()`, because `state.R == RState.ONE`, `PMMPricing.adjustedTarget(state)` leaves `state.B0 = _BASE_TARGET_ < state.B` or `state.Q0 = _QUOTE_TARGET_ < state.Q`.

2. **R-state and reserve imbalance mismatch when crossing `RState.ONE` with small overshoot:**
   When `state.R == RState.ABOVE_ONE` and `sellBase` is called with `payBaseAmount = backToOnePayBase + deltaB` where `_ROneSellBaseToken(state, deltaB) < lpFee`, `newRState` transitions to `RState.BELOW_ONE`, yet the net quote tokens leaving the pool (`grossReceiveQuote - lpFee`) is less than `state.Q - state.Q0`. Consequently, the pool enters `RState.BELOW_ONE` with `_QUOTE_RESERVE_ > _QUOTE_TARGET_`, and `getPMMState()` reconstructs `state.Q0` from the inflated `_QUOTE_RESERVE_` while `_QUOTE_TARGET_` in storage remains stale. Similarly, if the pool is at `RState.ONE` with `_BASE_RESERVE_ = _BASE_TARGET_ + lpFee` and a tiny `sellBase` (`1 wei`) transitions `_RState_` to `BELOW_ONE`, `state.B - state.B0` in `getPMMState()` abruptly jumps from `0` to `lpFee + 1`, causing an immediate discontinuity in reconstructed `state.Q0` and `getMidPrice()`.

findings.remediation:
Ensure that `getPMMState()` (and `PMMPricing.adjustedTarget()`) maintains reserve–target consistency across all `RState` regimes—including synchronizing targets with reserves when `state.R == RState.ONE` and guarding against reserve–target inversions:

```solidity
    function getPMMState() public view returns (PMMPricing.PMMState memory state) {
        state.i = _I_;
        state.K = _K_;
        state.B = _BASE_RESERVE_;
        state.Q = _QUOTE_RESERVE_;
        state.B0 = _BASE_TARGET_;
        state.Q0 = _QUOTE_TARGET_;
        state.R = PMMPricing.RState(_RState_);
        if (
            (state.R == PMMPricing.RState.BELOW_ONE && state.B < state.B0) ||
            (state.R == PMMPricing.RState.ABOVE_ONE && state.Q < state.Q0)
        ) {
            state.R = PMMPricing.RState.ONE;
        }
        if (state.R == PMMPricing.RState.ONE) {
            state.B0 = state.B;
            state.Q0 = state.Q;
        } else {
            PMMPricing.adjustedTarget(state);
        }
    }
```

To ensure reserve observations reflect the pool's equilibrium value rather than transient post-swap spot skews, return the equilibrium target reserves (`state.B0` and `state.Q0`) computed by `getPMMState()` in `getReserves()` (and guard against read-only reentrancy with `nonReadReentrant`):

```solidity
    function getReserves() external view nonReadReentrant returns (uint256 baseReserve, uint256 quoteReserve) {
        PMMPricing.PMMState memory state = getPMMState();
        baseReserve = state.B0;
        quoteReserve = state.Q0;
    }
```

*(Note: Internal periphery helpers that require raw spot reserve accounting to compute pending token inputs, such as `Router`, should read `_BASE_RESERVE_` and `_QUOTE_RESERVE_` directly.)*

Ensure that rebasing tokens are either strictly configured as claimable upon initialization (reverting if a rebasing token cannot be set to claimable) or explicitly synchronize/account for accrued yield prior to computing swap inputs, and pull exact user-specified input amounts or cap/synchronize reserve divergences before executing trades:

```solidity
    function getQuoteInput() public view returns (uint256 input) {
        uint256 quoteBalance = _QUOTE_TOKEN_.balanceOf(address(this));
        return quoteBalance > uint256(_QUOTE_RESERVE_) ? quoteBalance - uint256(_QUOTE_RESERVE_) : 0;
    }

    function version() external pure virtual returns (string memory) {
        return "MagicLP 1.0.0";
    }

    //////////////////////////////////////////////////////////////////////////////////////
    /// TRADE FUNCTIONS
    //////////////////////////////////////////////////////////////////////////////////////

    function sellBase(address to, uint256 payBaseAmount) external nonReentrant returns (uint256 receiveQuoteAmount) {
        _BASE_TOKEN_.safeTransferFrom(msg.sender, address(this), payBaseAmount);
        uint256 baseBalance = _BASE_TOKEN_.balanceOf(address(this));
        uint256 baseInput = payBaseAmount;
```

findings.technical_details:
In `MagicLP`, the PMM pricing state (`PMMPricing.PMMState`) relies on strict regime invariants between reserves (`B = _BASE_RESERVE_`, `Q = _QUOTE_RESERVE_`), targets (`B0 = _BASE_TARGET_`, `Q0 = _QUOTE_TARGET_`), and the regime state `_RState_`:
- In `RState.ONE`: `B == B0` and `Q == Q0`.
- In `RState.ABOVE_ONE`: `B <= B0` and `Q >= Q0`, where `Q0` is fixed in storage (`_QUOTE_TARGET_`) and `B0` is dynamically computed in `PMMPricing.adjustedTarget(state)` via `Math._SolveQuadraticFunctionForTarget(state.B, state.Q - state.Q0, DecimalMath.reciprocalFloor(state.i), state.K)`.
- In `RState.BELOW_ONE`: `B >= B0` and `Q <= Q0`, where `B0` is fixed in storage (`_BASE_TARGET_`) and `Q0` is dynamically computed in `PMMPricing.adjustedTarget(state)`.

When `sellBase(address to)` (at `src/mimswap/MagicLP.sol:244`) is called while `_RState_ == uint32(PMMPricing.RState.ABOVE_ONE)`:
1. `querySellBase(tx.origin, baseInput)` fetches `state = getPMMState()` (where `state.B0` is dynamically solved so that paying `backToOnePayBase = state.B0 - state.B` base tokens corresponds to withdrawing `backToOneReceiveQuote = state.Q - state.Q0` quote tokens to return the curve to `R = 1`).
2. Inside `PMMPricing.sellBaseToken(state, payBaseAmount)`:
   - **Case 2.2 (`payBaseAmount == backToOnePayBase`)**: Returns `receiveQuoteAmount = backToOneReceiveQuote = state.Q - state.Q0` and `newR = RState.ONE`.
   - **Case 2.3 (`payBaseAmount > backToOnePayBase`)**: Returns `receiveQuoteAmount = backToOneReceiveQuote + _ROneSellBaseToken(state, payBaseAmount - backToOnePayBase)` and `newR = RState.BELOW_ONE`.
3. `querySellBase` then deducts both the LP fee and maintainer fee from `receiveQuoteAmount`:
   ```solidity
   mtFee = DecimalMath.mulFloor(receiveQuoteAmount, mtFeeRate);
   receiveQuoteAmount = receiveQuoteAmount - DecimalMath.mulFloor(receiveQuoteAmount, lpFeeRate) - mtFee;
   newBaseTarget = state.B0;
   ```
4. In `sellBase`, only `receiveQuoteAmount` and `mtFee` are transferred out of the pool (`_transferQuoteOut`). The LP fee (`lpFee = DecimalMath.mulFloor(receiveQuoteAmount, lpFeeRate)`) remains inside the contract's quote token balance.
5. `sellBase` then updates the target and reserve state:
   ```solidity
   if (_RState_ != uint32(newRState)) {
       _BASE_TARGET_ = newBaseTarget.toUint112();
       _RState_ = uint32(newRState);
       emit RChange(newRState);
   }

   _setReserve(baseBalance, _QUOTE_TOKEN_.balanceOf(address(this)));
   ```

This creates two curve-transition inconsistencies:
- **Transition from `ABOVE_ONE` to `ONE` (`baseInput == backToOnePayBase`)**: The pool transfers out `(state.Q - state.Q0) - lpFee` quote tokens, leaving `_QUOTE_RESERVE_ = state.Q0 + lpFee`, while `_QUOTE_TARGET_` remains at `state.Q0`. `_RState_` is set to `RState.ONE`, where `PMMPricing.adjustedTarget` performs no adjustment on `state.B0` or `state.Q0`. Thus, the pool enters `RState.ONE` with `_QUOTE_RESERVE_ > _QUOTE_TARGET_`. If a subsequent `sellQuote` is executed (even for 1 wei), `_RState_` transitions back to `ABOVE_ONE` and sets `_QUOTE_TARGET_ = state.Q0` (still excluding `lpFee`). On the next `getPMMState()` call, `state.Q - state.Q0` still contains `lpFee`, causing `adjustedTarget` to inflate `state.B0` a second time by the already-accounted LP fee.
- **Transition from `ABOVE_ONE` to `BELOW_ONE` (`baseInput > backToOnePayBase`)**: In Case 2.3, `_ROneSellBaseToken(state, payBaseAmount - backToOnePayBase)` prices the `BELOW_ONE` leg using the stale `state.Q0` rather than the actual post-fee quote reserve at the `R = 1` boundary (`state.Q0 + lpFee_from_leg1`).

findings.remediation:
When `sellBase` transitions `_RState_` to `RState.ONE` (or when syncing targets at the `R = 1` boundary), update `_QUOTE_TARGET_` to match the post-transfer quote balance so that retained LP fees are reflected in `_QUOTE_TARGET_` and the `RState.ONE` invariant (`_QUOTE_RESERVE_ == _QUOTE_TARGET_`) holds:

```solidity
    function sellBase(address to) external nonReentrant returns (uint256 receiveQuoteAmount) {
        uint256 baseBalance = _BASE_TOKEN_.balanceOf(address(this));
        uint256 baseInput = baseBalance - uint256(_BASE_RESERVE_);
        uint256 mtFee;
        uint256 newBaseTarget;
        PMMPricing.RState newRState;
        (receiveQuoteAmount, mtFee, newRState, newBaseTarget) = querySellBase(tx.origin, baseInput);

        _transferQuoteOut(to, receiveQuoteAmount);
        _transferQuoteOut(_MT_FEE_RATE_MODEL_.maintainer(), mtFee);

        uint256 quoteBalance = _QUOTE_TOKEN_.balanceOf(address(this));

        // update TARGET
        if (_RState_ != uint32(newRState)) {
            _BASE_TARGET_ = newBaseTarget.toUint112();
            if (newRState == PMMPricing.RState.ONE) {
                _QUOTE_TARGET_ = quoteBalance.toUint112();
            }
            _RState_ = uint32(newRState);
            emit RChange(newRState);
        }

        _setReserve(baseBalance, quoteBalance);

        emit Swap(address(_BASE_TOKEN_), address(_QUOTE_TOKEN_), baseInput, receiveQuoteAmount, msg.sender, to);
    }
```

Validate that `to != address(this)` and update reserves consistently with the pre-settlement reserve state and actual settled amounts, or synchronize reserves before computing the PMM state transition.

```solidity
    function sellBase(address to) external nonReentrant returns (uint256 receiveQuoteAmount) {
        if (to == address(this)) {
            revert ErrInvalidRecipient();
        }
        uint256 baseBalance = _BASE_TOKEN_.balanceOf(address(this));
        uint256 baseInput = baseBalance - uint256(_BASE_RESERVE_);
        uint256 mtFee;
        uint256 newBaseTarget;
        PMMPricing.RState newRState;
        (receiveQuoteAmount, mtFee, newRState, newBaseTarget) = querySellBase(tx.origin, baseInput);

        _transferQuoteOut(to, receiveQuoteAmount);
        _transferQuoteOut(_MT_FEE_RATE_MODEL_.maintainer(), mtFee);

        // update TARGET
        if (_RState_ != uint32(newRState)) {
            _BASE_TARGET_ = newBaseTarget.toUint112();
            _RState_ = uint32(newRState);
            emit RChange(newRState);
        }

        _setReserve(baseBalance, uint256(_QUOTE_RESERVE_) - receiveQuoteAmount - mtFee);

        emit Swap(address(_BASE_TOKEN_), address(_QUOTE_TOKEN_), baseInput, receiveQuoteAmount, msg.sender, to);
    }
```

findings.technical_details:
`MagicLP.sellQuote(address to)` computes the swap output and PMM state transition from the cached reserves (`_BASE_RESERVE_` and `_QUOTE_RESERVE_`) and the incoming quote token delta:

```solidity
uint256 quoteBalance = _QUOTE_TOKEN_.balanceOf(address(this));
uint256 quoteInput = quoteBalance - uint256(_QUOTE_RESERVE_);
uint256 mtFee;
uint256 newQuoteTarget;
PMMPricing.RState newRState;
(receiveBaseAmount, mtFee, newRState, newQuoteTarget) = querySellQuote(tx.origin, quoteInput);
```

Inside `querySellQuote`, `getPMMState()` loads `state.B = _BASE_RESERVE_` and `state.Q = _QUOTE_RESERVE_`, adjusts the active target (`state.Q0` or `state.B0`), and `PMMPricing.sellQuoteToken(state, quoteInput)` computes `receiveBaseAmount` and `newRState` under the invariant that `receiveBaseAmount + mtFee` of `_BASE_TOKEN_` will leave the pool (reducing the pool's base reserve to `_BASE_RESERVE_ - receiveBaseAmount - mtFee`).

However, `sellQuote` then performs:

```solidity
_transferBaseOut(to, receiveBaseAmount);
_transferBaseOut(_MT_FEE_RATE_MODEL_.maintainer(), mtFee);

// update TARGET
if (_RState_ != uint32(newRState)) {
    _QUOTE_TARGET_ = newQuoteTarget.toUint112();
    _RState_ = uint32(newRState);
    emit RChange(newRState);
}

_setReserve(_BASE_TOKEN_.balanceOf(address(this)), quoteBalance);
```

Because `sellQuote` does not validate `to != address(this)` and blindly overwrites `_BASE_RESERVE_` with `_BASE_TOKEN_.balanceOf(address(this))` at line 285 (rather than accounting only for the expected reserve delta or syncing prior to pricing):

1. **Self-transfer via `to == address(this)`:** When `to == address(this)`, `_transferBaseOut(to, receiveBaseAmount)` transfers `receiveBaseAmount` of `_BASE_TOKEN_` from the pool back to itself. `_BASE_TOKEN_.balanceOf(address(this))` only decreases by `mtFee` instead of `receiveBaseAmount + mtFee`. Line 285 then sets `_BASE_RESERVE_` to this unreduced balance while `_QUOTE_RESERVE_` is set to `quoteBalance` and `_RState_` / `_QUOTE_TARGET_` are updated as though `receiveBaseAmount` had exited the pool.
2. **PMM Target and Oracle Corruption:**
   - When `newRState == PMMPricing.RState.ABOVE_ONE`, `getPMMState()` calls `PMMPricing.adjustedTarget()`, which computes `state.B0 = Math._SolveQuadraticFunctionForTarget(state.B, state.Q - state.Q0, DecimalMath.reciprocalFloor(state.i), state.K)`. Because `state.B` (`_BASE_RESERVE_`) still contains `receiveBaseAmount` while `state.Q - state.Q0` reflects the full `quoteInput`, `state.B0` is solved from an inflated `V1 = state.B`. This immediately distorts `getMidPrice()` (called during `_twapUpdate()` inside `_setReserve`) and, when a subsequent `sellBase` transitions `_RState_` back to `ONE` or `BELOW_ONE`, permanently writes the inflated `state.B0` to `_BASE_TARGET_`.
   - When `_RState_ == PMMPricing.RState.BELOW_ONE` and `quoteInput == backToOnePayQuote`, `newRState` transitions to `RState.ONE` while `_BASE_RESERVE_` remains greater than `_BASE_TARGET_`, violating the PMM invariant that `B <= B0` when `R >= 1` (`RState.ONE` / `RState.ABOVE_ONE`) because `adjustedTarget()` is a no-op in `RState.ONE`.

findings.remediation:
Validate that `to != address(this)` in `sellQuote` (and `sellBase`), and update `_BASE_RESERVE_` based on the accounted reserve or ensure no self-transfer can leave `receiveBaseAmount` in the pool's balance when updating reserves:

```solidity
    function sellQuote(address to) external nonReentrant returns (uint256 receiveBaseAmount) {
        if (to == address(this)) {
            revert ErrZeroAddress();
        }
        uint256 quoteBalance = _QUOTE_TOKEN_.balanceOf(address(this));
        uint256 quoteInput = quoteBalance - uint256(_QUOTE_RESERVE_);
        uint256 mtFee;
        uint256 newQuoteTarget;
        PMMPricing.RState newRState;
        (receiveBaseAmount, mtFee, newRState, newQuoteTarget) = querySellQuote(tx.origin, quoteInput);

        _transferBaseOut(to, receiveBaseAmount);
        _transferBaseOut(_MT_FEE_RATE_MODEL_.maintainer(), mtFee);

        // update TARGET
        if (_RState_ != uint32(newRState)) {
            _QUOTE_TARGET_ = newQuoteTarget.toUint112();
            _RState_ = uint32(newRState);
            emit RChange(newRState);
        }

        _setReserve(_BASE_TOKEN_.balanceOf(address(this)), quoteBalance);

        emit Swap(address(_QUOTE_TOKEN_), address(_BASE_TOKEN_), quoteInput, receiveBaseAmount, msg.sender, to);
    }
```

findings.technical_details:
In DODO V2 / `MagicLP`'s PMM model, the pool tracks reserves `(_BASE_RESERVE_, _QUOTE_RESERVE_)` and equilibrium targets `(_BASE_TARGET_, _QUOTE_TARGET_)` across three regimes (`RState.ONE`, `RState.ABOVE_ONE`, `RState.BELOW_ONE`):

1. When `_RState_ == RState.BELOW_ONE`, `_BASE_RESERVE_ > _BASE_TARGET_` (`B > B0`) and `_QUOTE_RESERVE_ < state.Q0` (`Q < Q0`). `getPMMState()` calls `PMMPricing.adjustedTarget(state)`, which dynamically computes `state.Q0` from `state.Q` and `state.B - state.B0` while using the stored `_BASE_TARGET_` as `state.B0`.
2. When `sellQuote` is called in `RState.BELOW_ONE` with `quoteInput == backToOnePayQuote` (`state.Q0 - state.Q`), `PMMPricing.sellQuoteToken` returns:
   - `receiveBaseAmount = backToOneReceiveBase = state.B - state.B0`
   - `newR = RState.ONE`
3. In `querySellQuote` (lines 187–190), the LP fee (`lpFee = DecimalMath.mulFloor(receiveBaseAmount, lpFeeRate)`) and maintainer fee (`mtFee`) are deducted from `receiveBaseAmount`:
   ```solidity
   mtFee = DecimalMath.mulFloor(receiveBaseAmount, mtFeeRate);
   receiveBaseAmount = receiveBaseAmount - DecimalMath.mulFloor(receiveBaseAmount, lpFeeRate) - mtFee;
   newQuoteTarget = state.Q0;
   ```
4. In `sellQuote` (lines 275–285), only `receiveBaseAmount + mtFee = (state.B - state.B0) - lpFee` base tokens are transferred out of the pool. The `lpFee` base tokens remain in the contract, so the new base balance is `_BASE_TARGET_ + lpFee`.
5. However, lines 279–283 only update `_QUOTE_TARGET_` and `_RState_`:
   ```solidity
   if (_RState_ != uint32(newRState)) {
       _QUOTE_TARGET_ = newQuoteTarget.toUint112();
       _RState_ = uint32(newRState);
       emit RChange(newRState);
   }
   ```
   `_BASE_TARGET_` is left unchanged at the old `B0`, while `_BASE_RESERVE_` is set to `B0 + lpFee` on line 285.

Because `PMMPricing.adjustedTarget(state)` performs no target adjustment when `state.R == RState.ONE`, the pool enters `RState.ONE` with `state.B0 < state.B` (`_BASE_TARGET_ < _BASE_RESERVE_`), violating the equilibrium invariant `B == B0` and `Q == Q0`:
- `_setReserve` immediately calls `_twapUpdate() -> getMidPrice()`, which executes the `else` branch of `PMMPricing.getMidPrice`:
  ```solidity
  uint256 R = DecimalMath.divFloor((state.B0 * state.B0) / state.B, state.B);
  R = (DecimalMath.ONE - state.K) + DecimalMath.mulFloor(state.K, R);
  return DecimalMath.mulFloor(state.i, R);
  ```
  Since `state.B0 < state.B`, `R < 1e18` inside the `R >= 1` branch, producing an underestimated mid-price `< state.i` at equilibrium.
- If the next swap is `sellBase`, `_ROneSellBaseToken` transitions `_RState_` back to `BELOW_ONE` and sets `_BASE_TARGET_ = state.B0` (still missing `lpFee`), leaving `state.B - state.B0` permanently inflated by `lpFee` without corresponding quote tokens having left the pool, which causes `adjustedTarget` in `BELOW_ONE` to over-calculate `state.Q0`.
- Similarly, when `quoteInput > backToOnePayQuote` (`BELOW_ONE -> ABOVE_ONE`), `_ROneSellQuoteToken` computes the `ONE -> ABOVE_ONE` leg using the unadjusted `state.B0` rather than accounting for the LP fee retained on the `BELOW_ONE -> ONE` leg, and `_BASE_TARGET_` in storage remains stale.

findings.remediation:
When `sellQuote` transitions `_RState_` to `PMMPricing.RState.ONE`, update `_BASE_TARGET_` to match the new base reserve (which includes the retained base-token LP fee):

```solidity
        uint256 baseBalance = _BASE_TOKEN_.balanceOf(address(this));

        // update TARGET
        if (_RState_ != uint32(newRState)) {
            if (newRState == PMMPricing.RState.ONE) {
                _BASE_TARGET_ = baseBalance.toUint112();
            }
            _QUOTE_TARGET_ = newQuoteTarget.toUint112();
            _RState_ = uint32(newRState);
            emit RChange(newRState);
        }

        _setReserve(baseBalance, quoteBalance);
```

findings.technical_details:
`MagicLP` is a Solidity 0.8 port of DODO V2's `DODOStablePool`. In `_twapUpdate` (`src/mimswap/MagicLP.sol`), the contract tracks the 32-bit truncated timestamp and cumulative price following the Uniswap V2 / DODO V2 TWAP pattern:

```solidity
function _twapUpdate() internal {
    uint32 blockTimestamp = uint32(block.timestamp % 2 ** 32);
    uint32 timeElapsed = blockTimestamp - _BLOCK_TIMESTAMP_LAST_;

    if (timeElapsed > 0 && _BASE_RESERVE_ != 0 && _QUOTE_RESERVE_ != 0) {
        /// @dev It is desired and expected for this value to
        /// overflow once it has hit the max of `type.uint256`.
        unchecked {
            _BASE_PRICE_CUMULATIVE_LAST_ += getMidPrice() * timeElapsed;
        }
    }

    _BLOCK_TIMESTAMP_LAST_ = blockTimestamp;
}
```

At line 546, `block.timestamp` is explicitly reduced modulo `2 ** 32` into a `uint32`. In the original Solidity 0.6 implementation, `blockTimestamp - _BLOCK_TIMESTAMP_LAST_` relied on modular `uint32` wraparound semantics when `block.timestamp` crosses a multiple of `2 ** 32` so that `timeElapsed` still equals the true elapsed time.

When porting the contract to Solidity 0.8, the developers wrapped the cumulative price update at line 553 in an `unchecked` block to preserve wraparound behavior, but left line 547 (`uint32 timeElapsed = blockTimestamp - _BLOCK_TIMESTAMP_LAST_;`) under Solidity 0.8's default checked arithmetic.

Once `block.timestamp` reaches `2 ** 32` (4,294,967,296) and rolls over in `uint32(block.timestamp % 2 ** 32)`, `blockTimestamp` becomes smaller than `_BLOCK_TIMESTAMP_LAST_` (which holds a value prior to the rollover). Consequently, `blockTimestamp - _BLOCK_TIMESTAMP_LAST_` reverts with `Panic(0x11)` (arithmetic underflow).

Because `_twapUpdate()` is invoked unconditionally at the end of `_setReserve()`, `_sync()`, `_resetTargetAndReserve()`, and `ratioSync()`, every function that updates reserves or synchronizes balances — including `buyShares()`, `sellShares()`, `sellBase()`, `sellQuote()`, `flashLoan()`, `sync()`, `setParameters()`, and `ratioSync()` — will permanently revert.

findings.remediation:
Compute `timeElapsed` inside an `unchecked` block so that `uint32` subtraction wraps around cleanly across the `2 ** 32` boundary, matching the intended modular timestamp design.

```solidity
    function _twapUpdate() internal {
        uint32 blockTimestamp = uint32(block.timestamp % 2 ** 32);
        uint32 timeElapsed;
        unchecked {
            timeElapsed = blockTimestamp - _BLOCK_TIMESTAMP_LAST_;
        }

        if (timeElapsed > 0 && _BASE_RESERVE_ != 0 && _QUOTE_RESERVE_ != 0) {
            /// @dev It is desired and expected for this value to
            /// overflow once it has hit the max of `type.uint256`.
            unchecked {
                _BASE_PRICE_CUMULATIVE_LAST_ += getMidPrice() * timeElapsed;
            }
        }

        _BLOCK_TIMESTAMP_LAST_ = blockTimestamp;
    }
```

findings.technical_details:
Time-Weighted Average Price (TWAP) accumulators must attribute the elapsed time since the last observation (`timeElapsed = blockTimestamp - _BLOCK_TIMESTAMP_LAST_`) to the price that was in effect *during* that interval—namely, the price prior to the current state-changing operation.

In `MagicLP`, `_twapUpdate()` computes the cumulative price update as:

```solidity
if (timeElapsed > 0 && _BASE_RESERVE_ != 0 && _QUOTE_RESERVE_ != 0) {
    unchecked {
        _BASE_PRICE_CUMULATIVE_LAST_ += getMidPrice() * timeElapsed;
    }
}
_BLOCK_TIMESTAMP_LAST_ = blockTimestamp;
```

Here, `getMidPrice()` calls `getPMMState()`, which derives the current mid price from `_I_`, `_K_`, `_BASE_RESERVE_`, `_QUOTE_RESERVE_`, `_BASE_TARGET_`, `_QUOTE_TARGET_`, and `_RState_`.

However, in `_setReserve()` (lines 560–565) and `_sync()` (lines 567–579), `_BASE_RESERVE_` and `_QUOTE_RESERVE_` are overwritten with the new post-operation balances *before* `_twapUpdate()` is called:

```solidity
function _setReserve(uint256 baseReserve, uint256 quoteReserve) internal {
    _BASE_RESERVE_ = baseReserve.toUint112();
    _QUOTE_RESERVE_ = quoteReserve.toUint112();

    _twapUpdate();
}
```

Furthermore, in all callers that invoke `_setReserve()` or `_sync()` (such as `sellBase`, `sellQuote`, `flashLoan`, `buyShares`, `sellShares`, `setParameters`, and `ratioSync`), the target and R-state variables (`_BASE_TARGET_`, `_QUOTE_TARGET_`, `_RState_`) are also mutated prior to calling `_setReserve()` or `_sync()`.

Because `_twapUpdate()` is executed after the reserves and PMM state are updated:
1. The first transaction in a block (where `timeElapsed > 0`) records `getMidPrice() * timeElapsed` using the **new** post-transaction price rather than the historical price that prevailed over `timeElapsed`.
2. Any subsequent transaction in the same block sees `timeElapsed == 0` (since `_BLOCK_TIMESTAMP_LAST_` was already updated to `blockTimestamp`), so restoring the pool's reserves in the same block or transaction does not undo the corrupted accumulator delta.

findings.remediation:
Update `_twapUpdate()` **before** modifying `_BASE_RESERVE_`, `_QUOTE_RESERVE_`, `_BASE_TARGET_`, `_QUOTE_TARGET_`, `_RState_`, `_I_`, or `_K_` in all state-changing functions, or pass the pre-mutation `PMMState` (or pre-mutation `midPrice`) into `_twapUpdate()` / `_setReserve()` / `_sync()`.

Specifically, if `_twapUpdate()` is called at the beginning of state-changing operations (prior to updating targets, R-state, and reserves) or if `_setReserve` / `_sync` receive the pre-trade mid price, the accumulator will properly weight the historical price over `timeElapsed`:

```solidity
    function _twapUpdate() internal {
        uint32 blockTimestamp = uint32(block.timestamp % 2 ** 32);
        uint32 timeElapsed = blockTimestamp - _BLOCK_TIMESTAMP_LAST_;

        if (timeElapsed > 0 && _BASE_RESERVE_ != 0 && _QUOTE_RESERVE_ != 0) {
            /// @dev It is desired and expected for this value to
            /// overflow once it has hit the max of `type.uint256`.
            unchecked {
                _BASE_PRICE_CUMULATIVE_LAST_ += getMidPrice() * timeElapsed;
            }
        }

        _BLOCK_TIMESTAMP_LAST_ = blockTimestamp;
    }

    function _setReserve(uint256 baseReserve, uint256 quoteReserve) internal {
        _BASE_RESERVE_ = baseReserve.toUint112();
        _QUOTE_RESERVE_ = quoteReserve.toUint112();
    }

    function _sync() internal {
        uint256 baseBalance = _BASE_TOKEN_.balanceOf(address(this));
        uint256 quoteBalance = _QUOTE_TOKEN_.balanceOf(address(this));

        if (baseBalance != _BASE_RESERVE_) {
            _BASE_RESERVE_ = baseBalance.toUint112();
        }
        if (quoteBalance != _QUOTE_RESERVE_) {
            _QUOTE_RESERVE_ = quoteBalance.toUint112();
        }
    }
```

*(Ensure `_twapUpdate()` is invoked at the start of `sellBase`, `sellQuote`, `flashLoan`, `buyShares`, `sellShares`, `setParameters`, `ratioSync`, and `sync` before any reserves, targets, or PMM parameters are modified.)*

findings.technical_details:
In `src/mimswap/MagicLP.sol`, every reserve-updating operation—including `sellBase`, `sellQuote`, `buyShares` (via `_setReserve` at lines 560–565), `sellShares`, `flashLoan`, `sync` (via `_sync` at lines 567–579), `setParameters` (via `_resetTargetAndReserve` at line 542), and `ratioSync` (line 521)—calls `_twapUpdate()`:

```solidity
    function _twapUpdate() internal {
        uint32 blockTimestamp = uint32(block.timestamp % 2 ** 32);
        uint32 timeElapsed = blockTimestamp - _BLOCK_TIMESTAMP_LAST_;

        if (timeElapsed > 0 && _BASE_RESERVE_ != 0 && _QUOTE_RESERVE_ != 0) {
            /// @dev It is desired and expected for this value to
            /// overflow once it has hit the max of `type.uint256`.
            unchecked {
                _BASE_PRICE_CUMULATIVE_LAST_ += getMidPrice() * timeElapsed;
            }
        }

        _BLOCK_TIMESTAMP_LAST_ = blockTimestamp;
    }
```

Although `getMidPrice() * timeElapsed` is placed inside an `unchecked` block on line 553, Solidity's `unchecked` semantics do not propagate into internal or external function calls. Inside `getMidPrice()` (line 215), `getPMMState()` calls `PMMPricing.adjustedTarget(state)` and then `PMMPricing.getMidPrice(state)` using checked Solidity 0.8 arithmetic:

1. **Pre-trade vs. post-trade and `timeElapsed == 0` bypass:**
   - When `timeElapsed == 0` (i.e., after an initial state update in the same block), `_twapUpdate()` skips calling `getMidPrice()`.
   - Furthermore, `buyShares()` and `sync()` do not call `getPMMState()` or `getMidPrice()` during their own logic, and `sellBase()` / `sellQuote()` only evaluate `getPMMState()` on the *pre-trade* reserves before updating `_BASE_RESERVE_` and `_QUOTE_RESERVE_` via `_setReserve()`.

2. **Extreme-state pricing reverts inside `getMidPrice()`:**
   Once `_BASE_RESERVE_` and `_QUOTE_RESERVE_` are updated, `getMidPrice()` can revert on the new reserve state in several ways:
   - **Target squaring and ratio overflow in `PMMPricing.getMidPrice`:**
     `PMMPricing.getMidPrice` computes `DecimalMath.divFloor((state.Q0 * state.Q0) / state.Q, state.Q)` (when `R == BELOW_ONE`) or `DecimalMath.divFloor((state.B0 * state.B0) / state.B, state.B)` (otherwise), followed by `DecimalMath.mulFloor(state.K, R)` and `DecimalMath.divFloor(state.i, R)` or `DecimalMath.mulFloor(state.i, R)`. When `state.Q` or `state.B` becomes very small relative to `state.Q0` or `state.B0` (for example, after a large trade in a low-`K` or `K = 0` pool, or after a large imbalance), or when `state.Q0` / `state.B0` computed in `adjustedTarget` exceeds `type(uint128).max` (which occurs for large `i` up to `MAX_I = 10**36` or small `i` where `reciprocalFloor(i)` is large), `state.Q0 * state.Q0`, `state.B0 * state.B0`, `((B0 * B0) / B) * 1e18`, `state.K * R`, or `state.i * R` overflows `uint256` and reverts.
   - **Checked overflow in `Math._SolveQuadraticFunctionForTarget`:**
     Called by `getPMMState() -> PMMPricing.adjustedTarget(state)`, line 96 checks `else if ((ki * delta) / ki == delta)` outside `unchecked`. Because `ki = 4 * k * i` can reach `4 * 10**54` and `delta` (`state.B - state.B0` or `state.Q - state.Q0`) can reach `type(uint112).max`, `ki * delta` reverts with an arithmetic overflow panic in Solidity 0.8 instead of falling back to the `else` branch `((ki / V1) * delta)`.
   - **Division by zero when `R == 0`:**
     When `R` rounds down to `0` (for example, in `BELOW_ONE` if `state.K == MAX_K` and `(state.Q0 * state.Q0) / state.Q` is small relative to `state.Q`), `DecimalMath.divFloor(state.i, R)` reverts due to division by zero.
   - **Target underflow before `correctRState()`:**
     If `_BASE_RESERVE_ < _BASE_TARGET_` while `_RState_ == BELOW_ONE` or `_QUOTE_RESERVE_ < _QUOTE_TARGET_` while `_RState_ == ABOVE_ONE` (the exact states `correctRState()` on lines 138–149 is designed to fix), `state.B - state.B0` or `state.Q - state.Q0` in `adjustedTarget` underflows and reverts.

Because `_twapUpdate()` does not guard against reverts from `getMidPrice()`, any pricing failure on the updated reserves causes `_setReserve()` and `_sync()` to revert whenever `timeElapsed > 0`.

findings.remediation:
Prevent pricing calculation failures in `_twapUpdate()` from reverting reserve updates by wrapping the mid-price retrieval in a safe try/catch call (or computing the mid-price with overflow-safe bounds checking) so that `_BLOCK_TIMESTAMP_LAST_` and pool reserves can always be updated even when the pool is in an extreme state:

```solidity
    function _twapUpdate() internal {
        uint32 blockTimestamp = uint32(block.timestamp % 2 ** 32);
        uint32 timeElapsed;
        unchecked {
            timeElapsed = blockTimestamp - _BLOCK_TIMESTAMP_LAST_;
        }

        if (timeElapsed > 0 && _BASE_RESERVE_ != 0 && _QUOTE_RESERVE_ != 0) {
            try this.getMidPrice() returns (uint256 midPrice) {
                /// @dev It is desired and expected for this value to
                /// overflow once it has hit the max of `type.uint256`.
                unchecked {
                    _BASE_PRICE_CUMULATIVE_LAST_ += midPrice * timeElapsed;
                }
            } catch {}
        }

        _BLOCK_TIMESTAMP_LAST_ = blockTimestamp;
    }
```

Avoid pre-truncating `1 / state.i` via `DecimalMath.reciprocalFloor(state.i)` before solving the quadratic target equation. Instead, pass `state.i` directly to a dedicated target solver (or use full 512-bit precision via `Math.mulDiv`) that divides by `state.i` only after multiplying by `delta`, and compute the quadratic root without intermediate `1e18` truncation:

```solidity
        } else if (state.R == RState.ABOVE_ONE) {
            state.B0 = Math._SolveQuadraticFunctionForTargetReciprocal(
                state.B,
                state.Q - state.Q0,
                state.i,
                state.K
            );
        }
```

Where `Math._SolveQuadraticFunctionForTargetReciprocal(uint256 V1, uint256 delta, uint256 i, uint256 k)` computes `delta / i` integrated with `4 * k` using high-precision arithmetic (`(4 * k * delta * DecimalMath.ONE2) / (i * V1)`) before taking the square root.

findings.technical_details:
In `src/mimswap/libraries/PMMPricing.sol`, `getMidPrice` computes the PMM pricing multiplier $R = (1 - k) + k \cdot (Q_0 / Q)^2$ (when `state.R == RState.BELOW_ONE`) or $R = (1 - k) + k \cdot (B_0 / B)^2$ (when `state.R != RState.BELOW_ONE`):

```solidity
    function getMidPrice(PMMState memory state) internal pure returns (uint256) {
        if (state.R == RState.BELOW_ONE) {
            uint256 R = DecimalMath.divFloor((state.Q0 * state.Q0) / state.Q, state.Q);
            R = (DecimalMath.ONE - state.K) + DecimalMath.mulFloor(state.K, R);
            return DecimalMath.divFloor(state.i, R);
        } else {
            uint256 R = DecimalMath.divFloor((state.B0 * state.B0) / state.B, state.B);
            R = (DecimalMath.ONE - state.K) + DecimalMath.mulFloor(state.K, R);
            return DecimalMath.mulFloor(state.i, R);
        }
    }
```

`DecimalMath.divFloor(target, d)` is defined in `src/mimswap/libraries/DecimalMath.sol` as `(target * ONE) / d` where `ONE = 10 ** 18`. Because lines 205 and 209 evaluate `(state.Q0 * state.Q0) / state.Q` and `(state.B0 * state.B0) / state.B` prior to calling `DecimalMath.divFloor(..., state.Q)` and `DecimalMath.divFloor(..., state.B)`, the first division is executed in raw token units without `1e18` fixed-point scaling:

$$R_{\text{raw}} = \left\lfloor \frac{\lfloor V_0^2 / V \rfloor \cdot 10^{18}}{V} \right\rfloor$$

This division-before-multiplication flaw has two direct consequences:

1. **Precision Loss in `R` and TWAP (`_BASE_PRICE_CUMULATIVE_LAST_`)**: Whenever reserves `state.Q` or `state.B` are small (such as pools with low-decimal tokens, pools initialized near the minimum share threshold of `2001` wei in `MagicLP.buyShares`, or pools after liquidity withdrawals in `MagicLP.sellShares`), the unscaled integer quotient `(V0 * V0) / V` truncates the fractional component before scaling by `1e18`. Since `MagicLP._twapUpdate()` accumulates `getMidPrice() * timeElapsed` on every state-modifying operation, this rounding error permanently distorts the pool's mid-price and TWAP accumulator.
2. **Truncation to Zero and Division-by-Zero DoS**: When `state.R == RState.ONE`, `PMMPricing.adjustedTarget` does not recompute `state.B0`. If `state.B > state.B0` (for example, after an unbalanced initial liquidity deposit in `MagicLP.buyShares` where `quoteBalance < DecimalMath.mulFloor(baseBalance, _I_)` sets `_BASE_TARGET_ = shares < baseBalance`, or after a direct token transfer followed by `sync()`), `state.B` can exceed `state.B0 * state.B0`, causing `(state.B0 * state.B0) / state.B` on line 209 to truncate to `0`. Similarly, if `(state.Q0 * state.Q0) / state.Q` on line 205 truncates to `0` when `state.K == DecimalMath.ONE` (`1e18`), `R` evaluates to `0`, and `DecimalMath.divFloor(state.i, R)` on line 207 reverts with a division-by-zero panic, blocking `_twapUpdate()` and all core pool operations (`sellBase`, `sellQuote`, `buyShares`, `sellShares`, `flashLoan`, and `sync`).

findings.remediation:
Compute the scaled ratio first using `DecimalMath.divFloor` (or scale by `DecimalMath.ONE` before dividing) and then square the fixed-point ratio using `DecimalMath.mulFloor`, avoiding unscaled integer division before multiplication:

```solidity
    function getMidPrice(PMMState memory state) internal pure returns (uint256) {
        if (state.R == RState.BELOW_ONE) {
            uint256 R = DecimalMath.divFloor(state.Q0, state.Q);
            R = DecimalMath.mulFloor(R, R);
            R = (DecimalMath.ONE - state.K) + DecimalMath.mulFloor(state.K, R);
            return DecimalMath.divFloor(state.i, R);
        } else {
            uint256 R = DecimalMath.divFloor(state.B0, state.B);
            R = DecimalMath.mulFloor(R, R);
            R = (DecimalMath.ONE - state.K) + DecimalMath.mulFloor(state.K, R);
            return DecimalMath.mulFloor(state.i, R);
        }
    }
```

Use explicit unchecked `uint32` subtraction so elapsed time follows the intended modulo-`2^32` semantics. This preserves the existing storage layout and is safe provided checkpoints occur less than `2^32` seconds apart.

```solidity
function _twapUpdate() internal {
    uint32 blockTimestamp = uint32(block.timestamp);
    uint32 timeElapsed;

    unchecked {
        timeElapsed = blockTimestamp - _BLOCK_TIMESTAMP_LAST_;
    }

    if (timeElapsed > 0 && _BASE_RESERVE_ != 0 && _QUOTE_RESERVE_ != 0) {
        unchecked {
            _BASE_PRICE_CUMULATIVE_LAST_ += getMidPrice() * timeElapsed;
        }
    }

    _BLOCK_TIMESTAMP_LAST_ = blockTimestamp;
}
```

Alternatively, use a non-truncating timestamp type, but that requires careful storage-layout migration for existing pools. Add boundary tests covering timestamps immediately before and after `2^32`.

findings.technical_details:
`MagicLP` implements the DODO V2 Proactive Market Maker (PMM) algorithm (`PMMPricing.sol`), which prices assets based on the relationship between current reserves (`B = _BASE_RESERVE_`, `Q = _QUOTE_RESERVE_`), target reserves (`B0 = _BASE_TARGET_`, `Q0 = _QUOTE_TARGET_`), and the pricing regime `_RState_`:
- When `_RState_ == RState.ONE`: the curve requires `B == B0` and `Q == Q0`. `PMMPricing.adjustedTarget()` performs no target recalculation in this state.
- When `_RState_ == RState.BELOW_ONE`: `B >= B0` and `Q <= Q0`, and `adjustedTarget()` dynamically computes `state.Q0` from `state.Q` and `state.B - state.B0`.
- When `_RState_ == RState.ABOVE_ONE`: `Q >= Q0` and `B <= B0`, and `adjustedTarget()` dynamically computes `state.B0` from `state.B` and `state.Q - state.Q0`.

To account for exogenous token balance changes (such as rebases, airdrops, or direct transfers) while preserving the PMM invariant ratios, `MagicLP` defines `ratioSync()` (lines 504–522), restricted to `onlyImplementationOwner`:

```solidity
if (baseBalance != _BASE_RESERVE_) {
    _BASE_TARGET_ = uint112((uint256(_BASE_TARGET_) * baseBalance) / uint256(_BASE_RESERVE_));
    _BASE_RESERVE_ = uint112(baseBalance);
}
if (quoteBalance != _QUOTE_RESERVE_) {
    _QUOTE_TARGET_ = uint112((uint256(_QUOTE_TARGET_) * quoteBalance) / uint256(_QUOTE_RESERVE_));
    _QUOTE_RESERVE_ = uint112(quoteBalance);
}
```

However, `MagicLP.sync()` (lines 134–136) exposes `_sync()` (lines 567–579) as a permissionless external function:

```solidity
function sync() external nonReentrant {
    _sync();
}
```

`_sync()` directly overwrites `_BASE_RESERVE_` and `_QUOTE_RESERVE_` with `baseBalance.toUint112()` and `quoteBalance.toUint112()` without updating `_BASE_TARGET_`, `_QUOTE_TARGET_`, or `_RState_`. This creates multiple state consistency failures:

1. **Order-Dependent Maintenance Neutralization (`sync()` before `ratioSync()`):** `ratioSync()` relies on the difference between `baseBalance` and `_BASE_RESERVE_` (and `quoteBalance` and `_QUOTE_RESERVE_`) to scale `_BASE_TARGET_` and `_QUOTE_TARGET_`. If any caller invokes `sync()` before `ratioSync()`, `_BASE_RESERVE_` and `_QUOTE_RESERVE_` are set equal to the current balances. A subsequent call to `ratioSync()` evaluates `baseBalance != _BASE_RESERVE_` and `quoteBalance != _QUOTE_RESERVE_` as `false`, permanently skipping the target adjustment.
2. **Reserve-Target Desynchronization and Unsafe Pricing-Regime Transitions:**
   - When `_RState_ == RState.ONE`, calling `sync()` after a balance increase sets `B > B0` or `Q > Q0` while keeping `_RState_ == RState.ONE`. A subsequent small swap transitions `_RState_` into `BELOW_ONE` or `ABOVE_ONE`, where `PMMPricing.adjustedTarget()` treats the unscaled `B - B0` or `Q - Q0` delta as excess inventory caused by trading, inflating the opposite target (`state.Q0` or `state.B0`) and mispricing pool swaps.
   - When `_RState_ == RState.BELOW_ONE` (or `ABOVE_ONE`), an increase in `_BASE_RESERVE_` (or `_QUOTE_RESERVE_`) via `sync()` increases `state.B - state.B0` (or `state.Q - state.Q0`) without scaling `B0` (or `Q0`). `adjustedTarget()` then computes an inflated `state.Q0` (or `state.B0`), which gets written to storage as `_QUOTE_TARGET_` (or `_BASE_TARGET_`) when a swap transitions `_RState_`.
   - Conversely, if a negative balance change occurs in `BELOW_ONE` such that `baseBalance < _BASE_TARGET_` (or `quoteBalance < _QUOTE_TARGET_` in `ABOVE_ONE`) and `sync()` is called, `state.B - state.B0` (or `state.Q - state.Q0`) in `PMMPricing.adjustedTarget()` reverts with an arithmetic underflow on all swaps, flash loans, and `getMidPrice()` queries unless `correctRState()` is called—which forcefully resets `_RState_ = RState.ONE` and overwrites both targets with the current reserves.

findings.remediation:
Restrict `sync()` to `onlyImplementationOwner` or remove the external `sync()` entry point so that exogenous balance updates must go through `ratioSync()` (or a properly synchronized admin maintenance call).

```solidity
    function sync() external nonReentrant onlyImplementationOwner {
        _sync();
    }
```

Checkpoint the cumulative price before modifying any reserve or other price-defining state. Apply the same ordering invariant to every helper that updates reserves or PMM targets.

For `_sync()`, use:

```solidity
function _sync() internal {
    uint256 baseBalance = _BASE_TOKEN_.balanceOf(address(this));
    uint256 quoteBalance = _QUOTE_TOKEN_.balanceOf(address(this));

    _twapUpdate();

    if (baseBalance != _BASE_RESERVE_) {
        _BASE_RESERVE_ = baseBalance.toUint112();
    }
    if (quoteBalance != _QUOTE_RESERVE_) {
        _QUOTE_RESERVE_ = quoteBalance.toUint112();
    }
}
```

Add regression tests that wait for a nonzero interval, alter balances immediately before `sync()`, and assert that the elapsed interval is accumulated using the pre-sync price.

findings.technical_details:
In `src/mimswap/MagicLP.sol`, all state-changing pool operations—`sync()` (line 134), `sellBase()` (line 244), `sellQuote()` (line 267), `flashLoan()` (line 290), `buyShares()` (line 360), `sellShares()` (line 420), `setParameters()` (line 479), and `ratioSync()` (line 504)—are protected by the `nonReentrant` modifier.

However, the state-maintenance function `correctRState()` at line 138 omits the `nonReentrant` modifier:

```solidity
function correctRState() external {
    if (_RState_ == uint32(PMMPricing.RState.BELOW_ONE) && _BASE_RESERVE_ < _BASE_TARGET_) {
        _RState_ = uint32(PMMPricing.RState.ONE);
        _BASE_TARGET_ = _BASE_RESERVE_;
        _QUOTE_TARGET_ = _QUOTE_RESERVE_;
    }
    if (_RState_ == uint32(PMMPricing.RState.ABOVE_ONE) && _QUOTE_RESERVE_ < _QUOTE_TARGET_) {
        _RState_ = uint32(PMMPricing.RState.ONE);
        _BASE_TARGET_ = _BASE_RESERVE_;
        _QUOTE_TARGET_ = _QUOTE_RESERVE_;
    }
}
```

During execution of `nonReentrant` functions such as `sellShares()`, `flashLoan()`, `sellBase()`, and `sellQuote()`, external calls are made while `_BASE_RESERVE_`, `_QUOTE_RESERVE_`, `_BASE_TARGET_`, `_QUOTE_TARGET_`, and `_RState_` are only partially updated:

1. **In `sellShares()` (lines 438–448):** `_BASE_TARGET_` and `_QUOTE_TARGET_` are decremented at lines 438–439 *before* `_transferBaseOut()` and `_transferQuoteOut()` at lines 446–447, while `_BASE_RESERVE_` and `_QUOTE_RESERVE_` are only updated afterward via `_sync()` at line 448. If `correctRState()` is invoked during the token transfer callback, it overwrites `_BASE_TARGET_` and `_QUOTE_TARGET_` with the stale pre-withdrawal `_BASE_RESERVE_` and `_QUOTE_RESERVE_` and sets `_RState_ = ONE`. When `_sync()` subsequently executes at line 448, reserves are reduced to the post-withdrawal balances while targets remain at the pre-withdrawal values, breaking the core PMM invariant (`B == B0` and `Q == Q0` when `R == ONE`).
2. **In `flashLoan()` (lines 290–353) and swap functions (`sellBase()` / `sellQuote()`):** External calls (`ICallee(assetTo).FlashLoanCall` at line 295 and outbound token transfers at lines 252–253, 275–276, 291–292, 319, and 341) occur before reserves are synchronized with actual token balances at line 350 (`_sync()`) or lines 262 / 285 (`_setReserve()`). Re-entering `correctRState()` during these callbacks allows mutating `_RState_`, `_BASE_TARGET_`, and `_QUOTE_TARGET_` based on stale reserve values mid-execution.

findings.remediation:
Add the `nonReentrant` modifier to `correctRState()` in `src/mimswap/MagicLP.sol` so that it cannot be invoked reentrantly during another pool operation.

```solidity
    function correctRState() external nonReentrant {
        if (_RState_ == uint32(PMMPricing.RState.BELOW_ONE) && _BASE_RESERVE_ < _BASE_TARGET_) {
            _RState_ = uint32(PMMPricing.RState.ONE);
            _BASE_TARGET_ = _BASE_RESERVE_;
            _QUOTE_TARGET_ = _QUOTE_RESERVE_;
        }
        if (_RState_ == uint32(PMMPricing.RState.ABOVE_ONE) && _QUOTE_RESERVE_ < _QUOTE_TARGET_) {
            _RState_ = uint32(PMMPricing.RState.ONE);
            _BASE_TARGET_ = _BASE_RESERVE_;
            _QUOTE_TARGET_ = _QUOTE_RESERVE_;
        }
    }
```

Checkpoint cumulative pricing whenever a recovery branch changes the PMM regime and targets. Since the pre-recovery state may be mathematically invalid, perform the checkpoint immediately after installing the recovered state.

```solidity
function correctRState() external {
    if (_RState_ == uint32(PMMPricing.RState.BELOW_ONE) && _BASE_RESERVE_ < _BASE_TARGET_) {
        _RState_ = uint32(PMMPricing.RState.ONE);
        _BASE_TARGET_ = _BASE_RESERVE_;
        _QUOTE_TARGET_ = _QUOTE_RESERVE_;
        _twapUpdate();
    } else if (_RState_ == uint32(PMMPricing.RState.ABOVE_ONE) && _QUOTE_RESERVE_ < _QUOTE_TARGET_) {
        _RState_ = uint32(PMMPricing.RState.ONE);
        _BASE_TARGET_ = _BASE_RESERVE_;
        _QUOTE_TARGET_ = _QUOTE_RESERVE_;
        _twapUpdate();
    }
}
```

Alternatively, introduce a dedicated recovery checkpoint that advances the timestamp without accumulating an undefined pre-recovery price. The chosen policy should be applied consistently across every function that changes reserves, targets, or the PMM regime.

findings.technical_details:
`MagicLP` is a Solidity 0.8 port of DODO V2's `DODOStablePool`. When `MagicLP.querySellBase` (`src/mimswap/MagicLP.sol:167-178`) is called (directly or via `sellBase` and `flashLoan`), it executes:
1. `PMMPricing.PMMState memory state = getPMMState();` (`src/mimswap/MagicLP.sol:171`), which calls `PMMPricing.adjustedTarget(state)` (`src/mimswap/libraries/PMMPricing.sol:190-201`) and invokes `Math._SolveQuadraticFunctionForTarget` (`src/mimswap/libraries/Math.sol:79-104`).
2. `(receiveQuoteAmount, newRState) = PMMPricing.sellBaseToken(state, payBaseAmount);` (`src/mimswap/MagicLP.sol:172`), which invokes `Math._SolveQuadraticFunctionForTrade` (`src/mimswap/libraries/Math.sol:131-205`).

In the original Solidity 0.6 DODO V2 implementation, SafeMath `.mul()` was used for checked multiplications, while raw `*` was intentionally used in two intermediate overflow checks so that wrapping multiplication would cause the equality check to evaluate to `false` and fall back to dividing before multiplying:

1. In `Math._SolveQuadraticFunctionForTarget` (`src/mimswap/libraries/Math.sol:93-100`):
```solidity
uint256 ki = (4 * k) * i;
if (ki == 0) {
    _sqrt = DecimalMath.ONE;
} else if ((ki * delta) / ki == delta) {
    _sqrt = sqrt(((ki * delta) / V1) + DecimalMath.ONE2);
} else {
    _sqrt = sqrt(((ki / V1) * delta) + DecimalMath.ONE2);
}
```
2. In `Math._SolveQuadraticFunctionForTrade` (`src/mimswap/libraries/Math.sol:152-159`):
```solidity
uint256 idelta = i * delta;
if (idelta == 0) {
    temp = 0;
} else if ((idelta * V1) / idelta == V1) {
    temp = (idelta * V1) / (V0 * V0);
} else {
    temp = (((delta * V1) / V0) * i) / V0;
}
```

Because `Math.sol` is compiled with Solidity `>=0.8.0`, the multiplications `ki * delta` (line 96) and `idelta * V1` (line 155) are performed with default checked arithmetic. Whenever the intermediate product `ki * delta` or `idelta * V1` exceeds `type(uint256).max`, the transaction immediately reverts with `Panic(0x11)` at the `else if` condition rather than entering the `else` branch (lines 98-100 and 157-159), rendering both fallback branches unreachable dead code.

Within valid pool parameters (`k <= MAX_K = 1e18`, `i <= MAX_I = 1e36` or `DecimalMath.reciprocalFloor(i) <= 1e36`, and reserves/deltas up to `type(uint112).max ≈ 5.19e33`), `ki * delta` can reach `~2.07e88` and `idelta * V1` can reach `~2.69e103`, both of which exceed `type(uint256).max ≈ 1.1579e77`.

findings.remediation:
Perform the overflow-check multiplications inside an `unchecked` block (or use `FixedPointMathLib.fullMulDiv`) so that intermediate `uint256` overflow is handled gracefully without reverting.

```solidity
    function _SolveQuadraticFunctionForTarget(uint256 V1, uint256 delta, uint256 i, uint256 k) internal pure returns (uint256) {
        if (k == 0) {
            return V1 + DecimalMath.mulFloor(i, delta);
        }

        if (V1 == 0) {
            return 0;
        }
        uint256 _sqrt;
        uint256 ki = (4 * k) * i;
        if (ki == 0) {
            _sqrt = DecimalMath.ONE;
        } else {
            uint256 kiDelta;
            unchecked {
                kiDelta = ki * delta;
            }
            if (kiDelta / ki == delta) {
                _sqrt = sqrt((kiDelta / V1) + DecimalMath.ONE2);
            } else {
                _sqrt = sqrt(((ki / V1) * delta) + DecimalMath.ONE2);
            }
        }
        uint256 premium = DecimalMath.divFloor(_sqrt - DecimalMath.ONE, k * 2) + DecimalMath.ONE;
        return DecimalMath.mulFloor(V1, premium);
    }
```

And in `Math._SolveQuadraticFunctionForTrade`:

```solidity
        if (k == DecimalMath.ONE) {
            uint256 temp;
            uint256 idelta = i * delta;
            if (idelta == 0) {
                temp = 0;
            } else {
                uint256 ideltaV1;
                unchecked {
                    ideltaV1 = idelta * V1;
                }
                if (ideltaV1 / idelta == V1) {
                    temp = ideltaV1 / (V0 * V0);
                } else {
                    temp = (((delta * V1) / V0) * i) / V0;
                }
            }
            return (V1 * temp) / (temp + DecimalMath.ONE);
        }
```

findings.technical_details:
When a `MagicLP` pool is in `RState.ABOVE_ONE` (after quote tokens have been sold into the pool via `sellQuote`), `_QUOTE_TARGET_` (`Q0`) is fixed in storage while the base target `B0` is dynamically recomputed on each query/trade inside `MagicLP.querySellBase` (lines 167–178) via `getPMMState()` -> `PMMPricing.adjustedTarget(state)` -> `Math._SolveQuadraticFunctionForTarget`:

```solidity
// src/mimswap/libraries/PMMPricing.sol
} else if (state.R == RState.ABOVE_ONE) {
    state.B0 = Math._SolveQuadraticFunctionForTarget(
        state.B,
        state.Q - state.Q0,
        DecimalMath.reciprocalFloor(state.i),
        state.K
    );
}
```

In `Math._SolveQuadraticFunctionForTarget(V1, delta, i, k)` (lines 79–104), the target reserve $V_0 = V_1 \left(1 + \frac{\sqrt{1 + 4 k i \Delta / V_1} - 1}{2k}\right)$ is computed in three fixed-point steps that round down:

```solidity
// src/mimswap/libraries/Math.sol
_sqrt = sqrt(((ki * delta) / V1) + DecimalMath.ONE2);
uint256 premium = DecimalMath.divFloor(_sqrt - DecimalMath.ONE, k * 2) + DecimalMath.ONE;
return DecimalMath.mulFloor(V1, premium);
```

This introduces severe fixed-point precision loss when `delta = state.Q - state.Q0` is small relative to `V1 / (2 * k * i)`:
1. Because `DecimalMath.ONE2` is $10^{36}$ and $(10^{18} + 1)^2 = 10^{36} + 2 \cdot 10^{18} + 1$, whenever $\lfloor(4 k i \Delta) / V_1\rfloor \le 2 \cdot 10^{18}$ (i.e., $i \cdot \Delta \le \frac{V_1 \cdot 10^{36}}{2k}$), integer `sqrt` truncates `_sqrt` to `DecimalMath.ONE` ($10^{18}$). Every 1-unit truncation in `_sqrt` is subsequently amplified by $\frac{V_1}{2k}$ in `DecimalMath.divFloor(..., k * 2)` and `DecimalMath.mulFloor(V1, premium)`.
2. Furthermore, when `V1` (`state.B`) is denominated in a low-decimal token (e.g., 6 or 8 decimals), `DecimalMath.mulFloor(V1, premium)` truncates `(V1 * (premium - 1e18)) / 1e18` to `0` whenever `premium - 1e18 < 1e18 / V1`.

In both cases, `_SolveQuadraticFunctionForTarget` returns `state.B0 == state.B` even though `state.Q > state.Q0`.

Next, `MagicLP.querySellBase` calls `PMMPricing.sellBaseToken(state, payBaseAmount)` (lines 45–62):

```solidity
// src/mimswap/libraries/PMMPricing.sol
} else if (state.R == RState.ABOVE_ONE) {
    uint256 backToOnePayBase = state.B0 - state.B;
    uint256 backToOneReceiveQuote = state.Q - state.Q0;
    if (payBaseAmount < backToOnePayBase) {
        ...
    } else if (payBaseAmount == backToOnePayBase) {
        // case 2.2: R status changes to ONE
        receiveQuoteAmount = backToOneReceiveQuote;
        newR = RState.ONE;
    }
```

When `state.B0 == state.B`, `backToOnePayBase` is `0`, while `backToOneReceiveQuote` is `state.Q - state.Q0 > 0`. Although `MagicLP` declares `error ErrNoBaseInput()` (line 45), `MagicLP.sellBase` never validates that `baseInput > 0` (nor does `querySellBase` check `payBaseAmount > 0`). Consequently, calling `sellBase` with `baseInput == 0` satisfies `payBaseAmount == backToOnePayBase` (`0 == 0`) and enters Case 2.2:
- `querySellBase` returns `receiveQuoteAmount = state.Q - state.Q0` (minus fees), `newRState = RState.ONE`, and `newBaseTarget = state.B0 = state.B`.
- `MagicLP.sellBase` transfers `receiveQuoteAmount` of quote tokens to the caller for **0** base tokens, transitions `_RState_` from `ABOVE_ONE` to `ONE`, and overwrites `_BASE_TARGET_` with the reduced `state.B`.

findings.remediation:
1. Enforce non-zero trade inputs in `sellBase` and `sellQuote` (using `ErrNoBaseInput` / `ErrZeroQuoteAmount`), and return `0` without changing `RState` in `PMMPricing.sellBaseToken` / `PMMPricing.sellQuoteToken` when the input amount is `0`.
2. In `Math._SolveQuadraticFunctionForTarget`, avoid premature truncation when `delta > 0` by rounding `_sqrt` or `premium` up (or falling back to the linear/first-order Taylor term `V1 + DecimalMath.mulCeil(i, delta)` when `_sqrt == DecimalMath.ONE` and `delta > 0`) so that `B0 > B` whenever `Q > Q0`.

```solidity
// In src/mimswap/MagicLP.sol
    function querySellBase(
        address trader,
        uint256 payBaseAmount
    ) public view returns (uint256 receiveQuoteAmount, uint256 mtFee, PMMPricing.RState newRState, uint256 newBaseTarget) {
        PMMPricing.PMMState memory state = getPMMState();
        if (payBaseAmount == 0) {
            return (0, 0, state.R, state.B0);
        }
        (receiveQuoteAmount, newRState) = PMMPricing.sellBaseToken(state, payBaseAmount);

        (uint256 lpFeeRate, uint256 mtFeeRate) = _MT_FEE_RATE_MODEL_.getFeeRate(trader, _LP_FEE_RATE_);
        mtFee = DecimalMath.mulFloor(receiveQuoteAmount, mtFeeRate);
        receiveQuoteAmount = receiveQuoteAmount - DecimalMath.mulFloor(receiveQuoteAmount, lpFeeRate) - mtFee;
        newBaseTarget = state.B0;
    }

    function sellBase(address to) external nonReentrant returns (uint256 receiveQuoteAmount) {
        uint256 baseBalance = _BASE_TOKEN_.balanceOf(address(this));
        uint256 baseInput = baseBalance - uint256(_BASE_RESERVE_);
        if (baseInput == 0) {
            revert ErrNoBaseInput();
        }
        uint256 mtFee;
        uint256 newBaseTarget;
        PMMPricing.RState newRState;
        (receiveQuoteAmount, mtFee, newRState, newBaseTarget) = querySellBase(tx.origin, baseInput);

        _transferQuoteOut(to, receiveQuoteAmount);
        _transferQuoteOut(_MT_FEE_RATE_MODEL_.maintainer(), mtFee);

        // update TARGET
        if (_RState_ != uint32(newRState)) {
            _BASE_TARGET_ = newBaseTarget.toUint112();
            _RState_ = uint32(newRState);
            emit RChange(newRState);
        }

        _setReserve(baseBalance, _QUOTE_TOKEN_.balanceOf(address(this)));

        emit Swap(address(_BASE_TOKEN_), address(_QUOTE_TOKEN_), baseInput, receiveQuoteAmount, msg.sender, to);
    }
```

findings.technical_details:
The highlighted call to `PMMPricing.sellBaseToken` delegates pricing to `Math._SolveQuadraticFunctionForTrade`. For `0 < K < 1e18`, that function calculates the quadratic curvature term at `Math.sol:184`.

The calculation first derives a value proportional to `K * V0² / 1e18`, then passes it to `DecimalMath.mulFloor` with a factor proportional to `4 * (1e18 - K)`. `DecimalMath.mulFloor` evaluates `target * d` using ordinary checked uint256 multiplication before dividing by `1e18`.

Consequently, the intermediate product can overflow even though:

- `V0` fits in the pool’s uint112 reserve representation;
- all configured curve parameters satisfy their documented bounds;
- the final fixed-point result fits in uint256.

For example, consider a balanced pool with:

- `V0 = V1 = 10^30`;
- `K = 5 * 10^17`;
- `i = 10^18`;
- `payBaseAmount = 1`;
- `RState.ONE`.

These values are valid because `10^30 < type(uint112).max`.

The relevant intermediate values are:

- `DecimalMath.mulFloor(K, V0) = 5 * 10^29`;
- multiplying that by `V0` gives `5 * 10^59`, which fits uint256;
- `4 * (1e18 - K) = 2 * 10^18`;
- the raw product passed through `DecimalMath.mulFloor` is therefore `10^78`.

Since `10^78 > type(uint256).max`, Solidity raises arithmetic panic `0x11`. However, the intended result after division by `1e18` is only `10^60`, which fits comfortably in uint256. This is therefore an avoidable intermediate-range failure, not an intrinsically unrepresentable PMM result.

The failure occurs before fee calculation. Any execution path relying on `querySellBase`, including an actual base sale, consequently reverts.

findings.remediation:
Use a 512-bit full-precision multiply-divide operation for the curvature term. This preserves the intended fixed-point result without requiring the numerator product to fit in uint256.

```solidity
import {Math as OZMath} from "openzeppelin-contracts/contracts/utils/math/Math.sol";

uint256 curvature = DecimalMath.mulFloor(k, V0) * V0;
uint256 squareRoot = OZMath.mulDiv(
    (DecimalMath.ONE - k) * 4,
    curvature,
    DecimalMath.ONE
);
squareRoot = sqrt((bAbs * bAbs) + squareRoot);
```

Apply the same full-precision approach to other PMM expressions that multiply before dividing. As a less desirable alternative, enforce a conservative reserve and target ceiling during liquidity operations, derived from the maximum intermediate value for every permitted `K`.

Use `DecimalMath.mulCeil` instead of `DecimalMath.mulFloor` when calculating both the maintainer fee and the LP fee so that fee rounding always favors the pool and protocol maintainer:

```solidity
        (uint256 lpFeeRate, uint256 mtFeeRate) = _MT_FEE_RATE_MODEL_.getFeeRate(trader, _LP_FEE_RATE_);
        mtFee = DecimalMath.mulCeil(receiveQuoteAmount, mtFeeRate);
        receiveQuoteAmount = receiveQuoteAmount - DecimalMath.mulCeil(receiveQuoteAmount, lpFeeRate) - mtFee;
        newBaseTarget = state.B0;
    }

    function querySellQuote(
        address trader,
        uint256 payQuoteAmount
    ) public view returns (uint256 receiveBaseAmount, uint256 mtFee, PMMPricing.RState newRState, uint256 newQuoteTarget) {
        PMMPricing.PMMState memory state = getPMMState();
        (receiveBaseAmount, newRState) = PMMPricing.sellQuoteToken(state, payQuoteAmount);

        (uint256 lpFeeRate, uint256 mtFeeRate) = _MT_FEE_RATE_MODEL_.getFeeRate(trader, _LP_FEE_RATE_);
        mtFee = DecimalMath.mulCeil(receiveBaseAmount, mtFeeRate);
        receiveBaseAmount = receiveBaseAmount - DecimalMath.mulCeil(receiveBaseAmount, lpFeeRate) - mtFee;
        newQuoteTarget = state.Q0;
    }
```

findings.technical_details:
In `MagicLP`, `querySellBase` (lines 167–178) and `querySellQuote` (lines 180–191) determine the swap output, maintainer fee (`mtFee`), post-swap `RState` (`newRState`), and updated target (`newBaseTarget` or `newQuoteTarget`):

```solidity
    function querySellBase(
        address trader,
        uint256 payBaseAmount
    ) public view returns (uint256 receiveQuoteAmount, uint256 mtFee, PMMPricing.RState newRState, uint256 newBaseTarget) {
        PMMPricing.PMMState memory state = getPMMState();
        (receiveQuoteAmount, newRState) = PMMPricing.sellBaseToken(state, payBaseAmount);

        (uint256 lpFeeRate, uint256 mtFeeRate) = _MT_FEE_RATE_MODEL_.getFeeRate(trader, _LP_FEE_RATE_);
        mtFee = DecimalMath.mulFloor(receiveQuoteAmount, mtFeeRate);
        receiveQuoteAmount = receiveQuoteAmount - DecimalMath.mulFloor(receiveQuoteAmount, lpFeeRate) - mtFee;
        newBaseTarget = state.B0;
    }
```

`querySellQuote` performs the symmetric calculation via `PMMPricing.sellQuoteToken(state, payQuoteAmount)` and sets `newQuoteTarget = state.Q0`.

When the pool is away from equilibrium (`RState.BELOW_ONE` or `RState.ABOVE_ONE`), `getPMMState()` calls `PMMPricing.adjustedTarget(state)` (lines 190–201 of `PMMPricing.sol`):
- In `RState.BELOW_ONE` ($B > B_0, Q < Q_0$), `state.Q0` is dynamically adjusted upward from `state.Q` and `state.B - state.B0` to account for accumulated LP fees, while `state.B0` remains `_BASE_TARGET_`.
- In `RState.ABOVE_ONE` ($Q > Q_0, B < B_0$), `state.B0` is dynamically adjusted upward from `state.B` and `state.Q - state.Q0`, while `state.Q0` remains `_QUOTE_TARGET_`.
- In `RState.ONE`, `adjustedTarget(state)` performs no adjustment and assumes $B = B_0$ and $Q = Q_0$.

When a trade moves the pool toward or across equilibrium—for example, `sellQuote` when `state.R == RState.BELOW_ONE` in `PMMPricing.sellQuoteToken` (lines 83–99 of `PMMPricing.sol`):

```solidity
        } else {
            uint256 backToOnePayQuote = state.Q0 - state.Q;
            uint256 backToOneReceiveBase = state.B - state.B0;
            if (payQuoteAmount < backToOnePayQuote) {
                ...
            } else if (payQuoteAmount == backToOnePayQuote) {
                receiveBaseAmount = backToOneReceiveBase;
                newR = RState.ONE;
            } else {
                receiveBaseAmount = backToOneReceiveBase + _ROneSellQuoteToken(state, payQuoteAmount - backToOnePayQuote);
                newR = RState.ABOVE_ONE;
            }
        }
```

`PMMPricing.sellQuoteToken` assumes the full gross `backToOneReceiveBase = state.B - state.B0` exits the pool so that the base reserve reaches `state.B0` at `payQuoteAmount == backToOnePayQuote`. However, `querySellQuote` subsequently deducts `lpFee = DecimalMath.mulFloor(receiveBaseAmount, lpFeeRate)` from `receiveBaseAmount` (and `querySellBase` deducts `lpFee` from `receiveQuoteAmount`). Because `sellQuote` (lines 275–276) only transfers out `receiveBaseAmount + mtFee = receiveBaseAmount_gross - lpFee`, the `lpFee` remains in the pool's reserve.

This causes three interrelated state-transition defects (symmetrically in both `querySellQuote` / `sellQuote` and `querySellBase` / `sellBase`):

1. **Equilibrium-Boundary State & Target Divergence (`BELOW_ONE -> ONE` and `ABOVE_ONE -> ONE`):**
   When `payQuoteAmount == backToOnePayQuote` in `BELOW_ONE`, `newRState` is `RState.ONE`. `sellQuote` updates `_QUOTE_TARGET_ = state.Q0` and `_RState_ = RState.ONE`, leaving `_BASE_TARGET_ = state.B0`. However, `_BASE_RESERVE_` becomes `state.B0 + lpFee > _BASE_TARGET_`. Because `PMMPricing.adjustedTarget` does nothing when `state.R == RState.ONE`, subsequent calls to `getPMMState()` return `state.B0 = _BASE_TARGET_ < state.B`. The retained `lpFee` is excluded from `state.B0` during subsequent `RState.ONE` pricing (`_ROneSellQuoteToken`) and target persistence (`newBaseTarget = state.B0` if the next trade is `sellBase`).

2. **Reserve-Target Invariant Violation Across Equilibrium (`BELOW_ONE -> ABOVE_ONE` and `ABOVE_ONE -> BELOW_ONE`):**
   When `payQuoteAmount > backToOnePayQuote` in `BELOW_ONE`, let $\Delta Q = \text{payQuoteAmount} - \text{backToOnePayQuote}$ and $\Delta B = \text{\_ROneSellQuoteToken}(\text{state}, \Delta Q)$.
   - First, `_ROneSellQuoteToken` prices $\Delta Q$ using the unadjusted `state.B0` rather than `state.B0 + lpFee_leg1`, creating a pricing discontinuity relative to splitting the trade just after the boundary.
   - Second, whenever $\Delta B < \text{lpFee}$, the net base leaving the pool is $(B - B_0) + \Delta B - \text{lpFee} < B - B_0$, so the new `_BASE_RESERVE_` is $B_0 + \text{lpFee} - \Delta B > B_0$. `sellQuote` sets `_RState_ = RState.ABOVE_ONE` and updates `_QUOTE_TARGET_ = state.Q0`, but leaves `_BASE_TARGET_ = B_0`. Consequently, the pool enters `RState.ABOVE_ONE` with `_BASE_RESERVE_ > _BASE_TARGET_`, violating the PMM invariant that base reserve is below base target in `ABOVE_ONE` (and causing persisted `_BASE_TARGET_` to diverge from the adjusted `state.B0` computed in `getPMMState()`).

findings.remediation:
Update target calculation and persistence when transitioning to or across `RState.ONE` so that the retained LP fee is accounted for in the target of the output token. Specifically, in `querySellBase` and `querySellQuote` (and the corresponding target updates in `sellBase`, `sellQuote`, and `flashLoan`), ensure that:
1. When a trade reaches `RState.ONE`, both targets match the post-swap reserves (or the output token target is increased by the retained `lpFee`).
2. When a trade crosses `RState.ONE` (`BELOW_ONE -> ABOVE_ONE` or `ABOVE_ONE -> BELOW_ONE`), the LP fee earned on the `backToOne` portion is reflected in the target before pricing and transitioning into the opposite `RState`.

```solidity
    function querySellBase(
        address trader,
        uint256 payBaseAmount
    ) public view returns (uint256 receiveQuoteAmount, uint256 mtFee, PMMPricing.RState newRState, uint256 newBaseTarget) {
        PMMPricing.PMMState memory state = getPMMState();
        (receiveQuoteAmount, newRState) = PMMPricing.sellBaseToken(state, payBaseAmount);

        (uint256 lpFeeRate, uint256 mtFeeRate) = _MT_FEE_RATE_MODEL_.getFeeRate(trader, _LP_FEE_RATE_);
        uint256 lpFee = DecimalMath.mulFloor(receiveQuoteAmount, lpFeeRate);
        mtFee = DecimalMath.mulFloor(receiveQuoteAmount, mtFeeRate);
        receiveQuoteAmount = receiveQuoteAmount - lpFee - mtFee;
        newBaseTarget = state.B0;
    }
```

And in `sellBase` / `sellQuote` / `flashLoan`, when `_RState_` transitions from `ABOVE_ONE` or `BELOW_ONE`, update both `_BASE_TARGET_` and `_QUOTE_TARGET_` (including the retained `lpFee` when reaching or crossing `RState.ONE`, and resetting `newRState` to `RState.ONE` if the retained `lpFee` prevents the reserve from dropping below target).

Handle zero input before calling `PMMPricing.sellQuoteToken`. The preferred behavior is to return the current regime and adjusted target without manufacturing a transition. As defense in depth, `sellQuote` may instead reject zero observed input.

```solidity
function querySellQuote(
    address trader,
    uint256 payQuoteAmount
) public view returns (uint256 receiveBaseAmount, uint256 mtFee, PMMPricing.RState newRState, uint256 newQuoteTarget) {
    PMMPricing.PMMState memory state = getPMMState();

    if (payQuoteAmount == 0) {
        return (0, 0, state.R, state.Q0);
    }

    (receiveBaseAmount, newRState) = PMMPricing.sellQuoteToken(state, payQuoteAmount);

    (uint256 lpFeeRate, uint256 mtFeeRate) = _MT_FEE_RATE_MODEL_.getFeeRate(trader, _LP_FEE_RATE_);
    mtFee = DecimalMath.mulFloor(receiveBaseAmount, mtFeeRate);
    receiveBaseAmount = receiveBaseAmount - DecimalMath.mulFloor(receiveBaseAmount, lpFeeRate) - mtFee;
    newQuoteTarget = state.Q0;
}
```

Implement the target discriminant using overflow-safe fixed-point arithmetic. Given the protocol’s parameter and `uint112` reserve bounds, the multiplication can be decomposed around the fixed-point denominator without losing precision:

```solidity
function _SolveQuadraticFunctionForTarget(
    uint256 V1,
    uint256 delta,
    uint256 i,
    uint256 k
) internal pure returns (uint256 V0) {
    uint256 fourDelta = delta * 4;
    uint256 ik = i * k;

    uint256 scaledTerm =
        (ik / DecimalMath.ONE) * fourDelta +
        ((ik % DecimalMath.ONE) * fourDelta) / DecimalMath.ONE;

    uint256 discriminant = (V1 * V1) + scaledTerm;
    V0 = (sqrt(discriminant) + V1) / 2;
}
```

Alternatively, use a proven 512-bit `mulDiv` implementation to calculate the scaled term. Add boundary tests for both R-state branches, maximum supported `i` and `K`, and cases where the intermediate numerator exceeds `uint256` while the final target remains representable.

findings.technical_details:
When `MagicLP.buyShares` is called for the first time (`totalSupply() == 0`), lines 381–383 compute the initial `shares`, `_BASE_TARGET_`, and `_QUOTE_TARGET_` using only the smaller side of the deposit relative to the oracle price `_I_`:

```solidity
shares = quoteBalance < DecimalMath.mulFloor(baseBalance, _I_) ? DecimalMath.divFloor(quoteBalance, _I_) : baseBalance;
_BASE_TARGET_ = shares.toUint112();
_QUOTE_TARGET_ = DecimalMath.mulFloor(shares, _I_).toUint112();
```

However, at the end of `buyShares` (line 407), `_setReserve(baseBalance, quoteBalance)` sets `_BASE_RESERVE_` and `_QUOTE_RESERVE_` to the full `baseBalance` and `quoteBalance`.

When `quoteBalance != DecimalMath.mulFloor(baseBalance, _I_)` (which occurs naturally via `Router.createPool` / `Router.createPoolETH` since they do not call `_adjustAddLiquidity`, via pre-existing token balances, or via a malicious initial deposit), two critical accounting failures occur:

1. **Disproportionate Share Minting and Subsequent LP Theft**:
   `totalSupply()` is initialized to `shares = min(baseBalance, quoteBalance / _I_)`, completely ignoring the excess balance on the larger side, while `_BASE_RESERVE_` and `_QUOTE_RESERVE_` record the full balances. On subsequent `buyShares` calls (`totalSupply() > 0`, lines 395–404):
   ```solidity
   uint256 baseInputRatio = DecimalMath.divFloor(baseInput, baseReserve);
   uint256 quoteInputRatio = DecimalMath.divFloor(quoteInput, quoteReserve);
   uint256 mintRatio = quoteInputRatio < baseInputRatio ? quoteInputRatio : baseInputRatio;
   shares = DecimalMath.mulFloor(totalSupply(), mintRatio);
   ```
   Because `mintRatio` is bounded by the inflated reserve on the larger side (`quoteInput / quoteReserve` or `baseInput / baseReserve`) and multiplied by the artificially small `totalSupply()`, subsequent liquidity providers depositing at the true price `_I_` receive drastically fewer shares than their contributed value. The initial depositor retains ownership of the majority of `totalSupply()` and can immediately call `sellShares` to withdraw a proportional share of both `baseBalance` and `quoteBalance`, stealing the victim's deposit on the smaller-reserve token.

2. **PMM Target-Reserve Invariant Violation (`_BASE_TARGET_ < _BASE_RESERVE_` or `_QUOTE_TARGET_ < _QUOTE_RESERVE_`)**:
   The pool starts in `_RState_ == RState.ONE` (0) with `_QUOTE_RESERVE_ > _QUOTE_TARGET_` (or `_BASE_RESERVE_ > _BASE_TARGET_`). In DODO/PMM pricing (`Math.sol`), the curve integration requires `V0 >= V1 >= V2 > 0` (`_QUOTE_TARGET_ >= _QUOTE_RESERVE_` when `RState == BELOW_ONE`, and `_BASE_TARGET_ >= _BASE_RESERVE_` when `RState == ABOVE_ONE`). Once a swap transitions `_RState_` from `ONE` to `BELOW_ONE` (or `ABOVE_ONE`) while the reserve still exceeds the target, reverse swaps revert with an arithmetic underflow when computing `state.Q0 - state.Q` (or `state.B0 - state.B`).

