        if (_RState_ != uint32(newRState)) {
            _BASE_TARGET_ = (newBaseTarget > type(uint112).max ? type(uint112).max : newBaseTarget).toUint112();
            _RState_ = uint32(newRState);
            emit RChange(newRState);
        }
```

