            receiveBaseAmount = _ROneSellQuoteToken(state, payQuoteAmount);
            if (receiveBaseAmount > maxFairBase) {
                receiveBaseAmount = maxFairBase;
            }
            newR = receiveBaseAmount > 0 ? RState.ABOVE_ONE : RState.ONE;
