findings.technical_details:
In `contracts/asd/asdRouter.sol`, the internal function `_refundToken` is responsible for returning tokens (`_from` OFT, `asdUSDC`, `noteAddress`, or `_cantoAsdAddress`) and any accompanying native value to `_refundAddress` whenever a validation, swap, vault deposit, or cross-chain send fails during `lzCompose`:

```solidity
function _refundToken(bytes32 _guid, address _tokenAddress, address _refundAddress, uint _amount, uint _nativeAmount, string memory _reason) internal {
    // emit event
    emit TokenRefund(_guid, _tokenAddress, _refundAddress, _amount, _nativeAmount, _reason);
    // transfer tokens to refund address
    IERC20(_tokenAddress).transfer(_refundAddress, _amount);
    // transfer native tokens to refund address and check that this value is less than or equal to msg.value
    if (_nativeAmount > 0 && _nativeAmount <= msg.value) {
        payable(_refundAddress).transfer(_nativeAmount);
    }
}
```

At line 181, `IERC20(_tokenAddress).transfer(_refundAddress, _amount)` is invoked directly, and its boolean return value is ignored:
1. If `_tokenAddress` is an ERC20 implementation that returns `false` instead of reverting when a transfer fails (e.g., due to insufficient balance, blacklisted/blocked recipient, or paused state), execution continues without reverting.
2. Because `TokenRefund` is emitted on line 179 prior to the transfer and the return value on line 181 is not checked, the transaction completes and logs a successful refund event even though no tokens were delivered to `_refundAddress`.
3. Furthermore, if `_tokenAddress` is a non-standard ERC20 token that does not return a boolean on `transfer`, calling `IERC20(_tokenAddress).transfer` will revert during ABI decoding of the expected `bool` return value.
4. This directly breaks the protocol's stated main invariant that "`ASDRouter` balance of any token should always be zero after `lzCompose` has completed", leaving tokens stranded in `ASDRouter` where there is no recovery mechanism.

findings.remediation:
Use OpenZeppelin's `SafeERC20.safeTransfer` (or check the return value of `transfer`) to ensure that standard and non-standard ERC20 token transfers are properly validated.

```solidity
    function _refundToken(bytes32 _guid, address _tokenAddress, address _refundAddress, uint _amount, uint _nativeAmount, string memory _reason) internal {
        // emit event
        emit TokenRefund(_guid, _tokenAddress, _refundAddress, _amount, _nativeAmount, _reason);
        // transfer tokens to refund address
        SafeERC20.safeTransfer(IERC20(_tokenAddress), _refundAddress, _amount);
        // transfer native tokens to refund address and check that this value is less than or equal to msg.value
        if (_nativeAmount > 0 && _nativeAmount <= msg.value) {
            payable(_refundAddress).transfer(_nativeAmount);
        }
    }
```

findings.technical_details:
In `contracts/asd/asdRouter.sol`, the `lzCompose` function is designed to never revert so that bridged OFT tokens do not become stuck in the `ASDRouter` contract if any step of the swap, deposit, or cross-chain send fails. Whenever an error condition is encountered (such as an invalid `composeMsg` length, an un-whitelisted token, a failed swap, a failed vault deposit, or an insufficient/failed LayerZero send), `lzCompose` invokes `_refundToken` to return both the ERC20 tokens and any `msg.value` to the refund address:

```solidity
function _refundToken(bytes32 _guid, address _tokenAddress, address _refundAddress, uint _amount, uint _nativeAmount, string memory _reason) internal {
    // emit event
    emit TokenRefund(_guid, _tokenAddress, _refundAddress, _amount, _nativeAmount, _reason);
    // transfer tokens to refund address
    IERC20(_tokenAddress).transfer(_refundAddress, _amount);
    // transfer native tokens to refund address and check that this value is less than or equal to msg.value
    if (_nativeAmount > 0 && _nativeAmount <= msg.value) {
        payable(_refundAddress).transfer(_nativeAmount);
    }
}
```

Line 184 uses `payable(_refundAddress).transfer(_nativeAmount)`. This creates two critical issues for refund availability:

1. **2,300 Gas Stipend Limitation:** Solidity's `.transfer()` only forwards 2,300 gas. If `_refundAddress` is a smart contract wallet, multisig (such as Safe), or protocol contract whose `receive()` or `fallback()` function executes logic requiring more than 2,300 gas, the native transfer will run out of gas and revert.
2. **Unchecked Revert Propagation:** If `_refundAddress` is a contract that does not implement a `payable` `receive()`/`fallback()` function (for instance, when `composeMsg.length != 224` at line 71 and `_refundAddress` defaults to `composeFrom`, which is the caller contract on the source chain, or when `_cantoRefundAddress` is a contract without a payable fallback), `.transfer()` reverts the entire transaction.

Because `_refundToken` coupled the ERC20 transfer (line 181) and the native transfer (line 184) in the same atomic execution without handling native transfer failures, a failure in sending `_nativeAmount` rolls back the ERC20 refund as well. This directly violates the core protocol requirement stated in the documentation that `lzCompose` should never revert and that all errors must result in refunds so tokens do not get trapped in the router.

findings.remediation:
Replace `payable(_refundAddress).transfer(_nativeAmount)` with a low-level `.call{value: _nativeAmount}("")` so that sufficient gas is forwarded to smart contract recipients. Additionally, to guarantee that `lzCompose` never reverts and ERC20 token refunds always succeed even if `_refundAddress` completely rejects native token transfers, handle a failed native transfer gracefully (or fallback to holding/wrapping the native token) rather than reverting the ERC20 token refund.

```solidity
    function _refundToken(bytes32 _guid, address _tokenAddress, address _refundAddress, uint _amount, uint _nativeAmount, string memory _reason) internal {
        // transfer tokens to refund address
        IERC20(_tokenAddress).transfer(_refundAddress, _amount);
        // transfer native tokens to refund address and check that this value is less than or equal to msg.value
        uint refundedNative = 0;
        if (_nativeAmount > 0 && _nativeAmount <= msg.value) {
            (bool success, ) = payable(_refundAddress).call{value: _nativeAmount}("");
            if (success) {
                refundedNative = _nativeAmount;
            }
        }
        // emit event
        emit TokenRefund(_guid, _tokenAddress, _refundAddress, _amount, refundedNative, _reason);
    }
```

findings.technical_details:
In `contracts/asd/asdRouter.sol`, the function `_depositNoteToASDVault` is called during `lzCompose` to deposit `$NOTE` into the target ASD vault specified by `payload._cantoAsdAddress`:

```solidity
function _depositNoteToASDVault(address _asdVault, uint _amountNote) internal returns (bool, string memory) {
    // approve asd vault to spend $NOTE
    IERC20(noteAddress).approve(_asdVault, _amountNote);
    // deposit $NOTE to asd vault (use call, so this doesn't revert)
    (bool success, bytes memory errReason) = _asdVault.call(abi.encodeWithSelector(ASDOFT.mint.selector, _amountNote));
    return (success, string(errReason));
}
```

The function grants an ERC-20 allowance of `_amountNote` on `noteAddress` to `_asdVault` (line 195) and then invokes `_asdVault.call(...)` (line 197) so that a failure in `ASDOFT.mint` does not revert the entire `lzCompose` execution.

However, because `IERC20(noteAddress).approve(_asdVault, _amountNote)` is executed in the caller's execution frame prior to the low-level `.call`, a revert inside `_asdVault.call(...)` only rolls back state changes made within that sub-call frame. The allowance granted to `_asdVault` on `noteAddress` remains active in storage. Furthermore, `_asdVault` (`payload._cantoAsdAddress`) is an unvalidated address supplied in the compose message payload. When `_depositNoteToASDVault` fails (or if `_asdVault` does not pull the full `_amountNote`), the residual allowance is not reset to `0`, leaving `_asdVault` with lingering spending authority over `$NOTE` held by `ASDRouter`.

findings.remediation:
Revoke any remaining allowance by resetting the approval to `0` if the low-level call fails (or unconditionally after the call completes), and verify that the expected tokens were actually consumed.

```solidity
    function _depositNoteToASDVault(address _asdVault, uint _amountNote) internal returns (bool, string memory) {
        // approve asd vault to spend $NOTE
        IERC20(noteAddress).approve(_asdVault, _amountNote);
        // deposit $NOTE to asd vault (use call, so this doesn't revert)
        (bool success, bytes memory errReason) = _asdVault.call(abi.encodeWithSelector(ASDOFT.mint.selector, _amountNote));
        if (!success) {
            IERC20(noteAddress).approve(_asdVault, 0);
        }
        return (success, string(errReason));
    }
```

findings.technical_details:
In `contracts/asd/asdOFT.sol`, `ASDOFT.mint(uint256 _amount)` transfers `_amount` of `NOTE` from the caller, supplies it to the Compound V2 `cNote` market via `cNoteToken.mint(_amount)`, and unconditionally mints `_amount` of `asD` to `msg.sender`:

```solidity
function mint(uint256 _amount) external {
    CErc20Interface cNoteToken = CErc20Interface(cNote);
    IERC20 note = IERC20(cNoteToken.underlying());
    SafeERC20.safeTransferFrom(note, msg.sender, address(this), _amount);
    note.approve(cNote, _amount);
    uint256 returnCode = cNoteToken.mint(_amount);
    // Mint returns 0 on success: https://docs.compound.finance/v2/ctokens/#mint
    require(returnCode == 0, "Error when minting");
    _mint(msg.sender, _amount);
}
```

In Compound V2 (which the Canto Lending Market is based on), `CToken.mint(uint256 mintAmount)` calculates the number of `cTokens` to mint as:

$$\text{mintTokens} = \left\lfloor \frac{\text{actualMintAmount} \times 10^{18}}{\text{exchangeRate}} \right\rfloor$$

Because the `cNote` exchange rate increases above $10^{18}$ as interest accrues, this integer division truncates downward. Consequently, the actual increase in `ASDOFT`'s underlying `NOTE` balance held in `cNote`—computed in `withdrawCarry` as `CTokenInterface(cNote).balanceOfUnderlying(address(this))` ($\lfloor \text{cNoteBalance} \times \text{exchangeRate} / 10^{18} \rfloor$)—can be strictly less than `_amount` by up to $\lfloor \text{exchangeRate} / 10^{18} \rfloor$ wei per `mint` call.

Furthermore, Compound V2's `mintFresh` does not require `mintTokens > 0`. When `_amount * 1e18 < exchangeRate`, `cNoteToken.mint(_amount)` transfers `_amount` of `NOTE` into `cNote`, mints `0` `cNote` tokens to `ASDOFT`, and returns `0` (`NO_ERROR`). However, `ASDOFT.mint` still mints `_amount` of `asD` tokens to `msg.sender` on line 46.

This causes three direct issues:
1. **Violation of 1:1 Peg & Solvency Invariant:** `totalSupply()` increases by `_amount`, while `cNote.balanceOfUnderlying(address(this))` increases by less than `_amount` (or `0`).
2. **DoS of `withdrawCarry` and `burn`:** When `cNote.balanceOfUnderlying(address(this)) < totalSupply()`, line 65 in `withdrawCarry` (`CTokenInterface(cNote).balanceOfUnderlying(address(this)) - totalSupply()`) reverts due to arithmetic underflow in Solidity 0.8+, and the last users calling `burn` will fail to redeem their full `asD` balance.
3. **Carry / Yield Theft:** When `ASDOFT` has accrued interest (`balanceOfUnderlying > totalSupply()`), an attacker can repeatedly call `mint` with `_amount` smaller than `exchangeRate / 1e18` (receiving `asD` while `ASDOFT` receives `0` `cNote`) and then call `burn` to redeem those `asD` tokens against the contract's accrued `cNote` carry.

findings.remediation:
Calculate the exact underlying amount corresponding to the `cNote` tokens actually minted (or round the required `NOTE` transfer up / mint `asD` based on the actual `balanceOfUnderlying` increase) and revert if zero `asD` would be minted. Alternatively, measure the `cNote` balance change and mint `asD` equal to `(cNoteMinted * exchangeRate) / 1e18`:

```solidity
    function mint(uint256 _amount) external {
        CErc20Interface cNoteToken = CErc20Interface(cNote);
        IERC20 note = IERC20(cNoteToken.underlying());
        uint256 balanceBefore = CTokenInterface(cNote).balanceOfUnderlying(address(this));
        SafeERC20.safeTransferFrom(note, msg.sender, address(this), _amount);
        note.approve(cNote, _amount);
        uint256 returnCode = cNoteToken.mint(_amount);
        // Mint returns 0 on success: https://docs.compound.finance/v2/ctokens/#mint
        require(returnCode == 0, "Error when minting");
        uint256 balanceAfter = CTokenInterface(cNote).balanceOfUnderlying(address(this));
        uint256 mintedUnderlying = balanceAfter - balanceBefore;
        require(mintedUnderlying > 0, "Zero minted");
        _mint(msg.sender, mintedUnderlying);
    }
```

Track the total net minted `asD` supply (or total deposited `NOTE` principal) in a dedicated state variable that is only incremented in `mint()` and decremented in `burn()`, rather than relying on `ERC20.totalSupply()` which fluctuates during cross-chain `OFT` transfers.

```solidity
contract ASDOFT is OFT {
    address public immutable cNote;
    uint256 public totalNoteDeposited;

    event CarryWithdrawal(uint256 amount);

    constructor(string memory _name, string memory _symbol, address _lzEndpoint, address _cNote, address _csrRecipient) OFT(_name, _symbol, _lzEndpoint, msg.sender) {
        cNote = _cNote;
        if (block.chainid == 7700 || block.chainid == 7701) {
            Turnstile turnstile = Turnstile(0xEcf044C5B4b867CFda001101c617eCd347095B44);
            turnstile.register(_csrRecipient);
        }
    }

    function mint(uint256 _amount) external {
        CErc20Interface cNoteToken = CErc20Interface(cNote);
        IERC20 note = IERC20(cNoteToken.underlying());
        SafeERC20.safeTransferFrom(note, msg.sender, address(this), _amount);
        note.approve(cNote, _amount);
        uint256 returnCode = cNoteToken.mint(_amount);
        require(returnCode == 0, "Error when minting");
        totalNoteDeposited += _amount;
        _mint(msg.sender, _amount);
    }

    function burn(uint256 _amount) external {
        CErc20Interface cNoteToken = CErc20Interface(cNote);
        IERC20 note = IERC20(cNoteToken.underlying());
        uint256 returnCode = cNoteToken.redeemUnderlying(_amount);
        require(returnCode == 0, "Error when redeeming");
        totalNoteDeposited -= _amount;
        _burn(msg.sender, _amount);
        SafeERC20.safeTransfer(note, msg.sender, _amount);
    }

    function withdrawCarry(uint256 _amount) external onlyOwner {
        uint256 maximumWithdrawable = CTokenInterface(cNote).balanceOfUnderlying(address(this)) - totalNoteDeposited;
        if (_amount == 0) {
            _amount = maximumWithdrawable;
        } else {
            require(_amount <= maximumWithdrawable, "Too many tokens requested");
        }
        uint256 returnCode = CErc20Interface(cNote).redeemUnderlying(_amount);
        require(returnCode == 0, "Error when redeeming");
        IERC20 note = IERC20(CErc20Interface(cNote).underlying());
        SafeERC20.safeTransfer(note, msg.sender, _amount);
        emit CarryWithdrawal(_amount);
    }
}
```

