    struct PendingRefund {
        address token;
        uint32 srcEid;
        bytes32 composeFrom;
        uint256 amount;
        uint256 nativeAmount;
    }

    function lzCompose(address _from, bytes32 _guid, bytes calldata _message, address _executor, bytes calldata _extraData) external payable {
        /* log event */
        emit LZReceived(_guid, _from, _message, _executor, _extraData, msg.value);

        /* decode OFT composed message */
        (, uint32 srcEid, uint256 amountLD, bytes32 composeFrom, bytes memory composeMsg) = _decodeOFTComposeMsg(_message);

        /* decode composed message payload */

        // check the composed message for proper formatting
        if (composeMsg.length != 224) {
            pendingRefunds[_guid] = PendingRefund({
                token: _from,
                srcEid: srcEid,
                composeFrom: composeFrom,
                amount: amountLD,
                nativeAmount: msg.value
            });
            return;
        }
```

Determine the actual token balance held by `ASDRouter` (or cap `amountLD` to `IERC20(_from).balanceOf(address(this))`) before refunding or depositing into `ASDUSDC`, and wrap the `ASDUSDC.deposit` call so any deposit failure safely refunds the tokens rather than reverting `lzCompose`:

```solidity
