Pass a valid directional `limitPrice` (`MAX_SQRT_RATIO - 1` when `isBuy == true`, and `MIN_SQRT_RATIO` when `isBuy == false`) to both `calcImpact` and `swap`, and wrap `calcImpact` in a `try/catch` block so unexpected failures trigger a refund rather than reverting `lzCompose`.

```solidity
    uint128 internal constant MIN_SQRT_RATIO = 65537;
    uint128 internal constant MAX_SQRT_RATIO = 21267647932558653966460912964485513216;

    function _swapOFTForNote(address _oftAddress, uint _amount, uint _minAmountNote) internal returns (uint, bool) {
        // sort tokens
        address baseToken;
        address quoteToken;
        if (_oftAddress < noteAddress) {
            baseToken = _oftAddress;
            quoteToken = noteAddress;
        } else {
            baseToken = noteAddress;
            quoteToken = _oftAddress;
        }
        // check if pool exists
        if (ambientPoolFor(baseToken, quoteToken, ambientPoolIdx) == 0) {
            // nothing swapped, swapped failed
            return (0, false);
        }

        // convert amount to uint128
        uint128 amountConverted = uint128(_amount);
        // query impact to make sure user will receive at least _minAmountNote
        bool isNoteBase = baseToken == noteAddress;
        uint128 limitPrice = !isNoteBase ? MAX_SQRT_RATIO - 1 : MIN_SQRT_RATIO;
        int128 baseFlow;
        int128 quoteFlow;
        try ICrocImpact(crocImpactAddress).calcImpact(baseToken, quoteToken, ambientPoolIdx, !isNoteBase, !isNoteBase, amountConverted, 0, limitPrice) returns (int128 _baseFlow, int128 _quoteFlow, uint128) {
            baseFlow = _baseFlow;
            quoteFlow = _quoteFlow;
        } catch {
            return (0, false);
        }

        // check if amount note received is greater than or equal to _minAmountNote
        int minAmountInt = int(_minAmountNote);
        if (isNoteBase && -baseFlow < minAmountInt) {
            return (0, false);
        } else if (!isNoteBase && -quoteFlow < minAmountInt) {
            return (0, false);
        }
        uint128 uintMinAmount = uint128(_minAmountNote);

        // swap is good to make, use call just in case revert occurs
        (bool successSwap, bytes memory data) = crocSwapAddress.call(abi.encodeWithSelector(ICrocSwapDex.swap.selector, baseToken, quoteToken, ambientPoolIdx, !isNoteBase, !isNoteBase, amountConverted, 0, limitPrice, uintMinAmount, 0));
        if (!successSwap) {
            return (0, false);
        }
        // return amount of note received
        (int128 baseUsed, int128 quoteUsed) = abi.decode(data, (int128, int128));
        return (uint128(-1 * (isNoteBase ? baseUsed : quoteUsed)), true);
    }
```

