findings.technical_details:
`BaseConnector` defines a `minimumHealthFactor` state variable (initialized to `15e17`, i.e., 150%, and configurable upwards via `updateMinimumHealthFactor`) intended to enforce a safety margin on all borrowing operations. As documented in `BaseConnector.updateMinimumHealthFactor`:
> *"for the connectors that borrowing is allowed, the health factor should be higher than this value (so we keep a safe margin)"*

In `PrismaConnector.adjustTrove` (lines 117–120), the contract enforces this invariant after modifying a trove's collateral or debt:
```solidity
uint256 healthFactor = ITroveManager(tm).getNominalICR(address(this));
if (minimumHealthFactor > healthFactor) {
    revert IConnector_LowHealthFactor(healthFactor);
}
```

However, in `PrismaConnector.openTrove` (lines 52–67), the function deposits `dAmount` of collateral and borrows `bAmount` of debt via `zap.openTrove(tm, maxFee, dAmount, bAmount, address(this), address(this))`, but completely omits the health factor check against `minimumHealthFactor`.

Consequently, a keeper/manager can call `openTrove` with a high `bAmount` relative to `dAmount` such that the trove's nominal ICR (`ITroveManager(tm).getNominalICR(address(this))`) is below `minimumHealthFactor` (as long as it satisfies Prisma's own lower minimum collateral ratio). This bypasses the vault's configured risk parameters and exposes the vault's collateral to liquidation.

findings.remediation:
Add the health factor check at the end of `PrismaConnector.openTrove` to ensure the newly opened trove respects `minimumHealthFactor`.

```solidity
    function openTrove(IStakeNTroveZap zap, address tm, uint256 maxFee, uint256 dAmount, uint256 bAmount)
        public
        onlyManager
        nonReentrant
    {
        bytes32 positionId = registry.calculatePositionId(address(this), PRISMA_POSITION_ID, abi.encode(zap, tm));
        PositionBP memory positionInfo = registry.getPositionBP(vaultId, positionId);
        address collateral = abi.decode(positionInfo.additionalData, (address));
        address debTtoken = ITroveManager(tm).debtToken();
        _approveOperations(collateral, address(zap), dAmount);
        zap.openTrove(tm, maxFee, dAmount, bAmount, address(this), address(this));
        uint256 healthFactor = ITroveManager(tm).getNominalICR(address(this));
        if (minimumHealthFactor > healthFactor) {
            revert IConnector_LowHealthFactor(healthFactor);
        }
        registry.updateHoldingPosition(vaultId, positionId, "", "", false);
        _updateTokenInRegistry(collateral);
        _updateTokenInRegistry(debTtoken);
        emit OpenTrove(address(zap), tm, maxFee, dAmount, bAmount);
    }
```

Support interacting directly with `IBorrowerOperations` using the `TroveManager`'s `collateralToken` (or allow choosing between zapping `WETH` via `IStakeNTroveZap` and depositing `collateralToken` directly into `IBorrowerOperations`), and ensure both the `WETH` token and `collateralToken` are validated and updated in the registry across all trove operations.

```solidity
    function openTrove(
        IStakeNTroveZap zap,
        address tm,
        uint256 maxFee,
        uint256 dAmount,
        uint256 bAmount,
        bool useZap
    ) public onlyManager nonReentrant {
        bytes32 positionId = registry.calculatePositionId(address(this), PRISMA_POSITION_ID, abi.encode(zap, tm));
        PositionBP memory positionInfo = registry.getPositionBP(vaultId, positionId);
        IBorrowerOperations borrowerOps = zap.borrowerOps();
        address collateral = useZap
            ? abi.decode(positionInfo.additionalData, (address))
            : borrowerOps.troveManagersData(tm).collateralToken;
        if (!registry.isTokenTrusted(vaultId, collateral, address(this))) {
            revert IConnector_UntrustedToken(collateral);
        }
        address debTtoken = ITroveManager(tm).debtToken();
        if (useZap) {
            _approveOperations(collateral, address(zap), dAmount);
            zap.openTrove(tm, maxFee, dAmount, bAmount, address(this), address(this));
        } else {
            _approveOperations(collateral, address(borrowerOps), dAmount);
            borrowerOps.openTrove(tm, address(this), maxFee, dAmount, bAmount, address(this), address(this));
        }
        uint256 healthFactor = ITroveManager(tm).getNominalICR(address(this));
        if (minimumHealthFactor > healthFactor) {
            revert IConnector_LowHealthFactor(healthFactor);
        }
        registry.updateHoldingPosition(vaultId, positionId, "", "", false);
        _updateTokenInRegistry(collateral);
        _updateTokenInRegistry(debTtoken);
        emit OpenTrove(address(zap), tm, maxFee, dAmount, bAmount);
    }
```

Ensure all collateral tokens (both the zap input token from `positionInfo.additionalData` and the `TroveManager`'s underlying collateral token from `borrowerOps.troveManagersData(tm).collateralToken`) as well as the debt token (`ITroveManager(tm).debtToken()`) are consistently reconciled via `_updateTokenInRegistry` across all trove operations in `PrismaConnector`:

