        public
        onlyManager
        nonReentrant
    {
        bytes32 positionId = registry.calculatePositionId(address(this), PRISMA_POSITION_ID, abi.encode(zap, tm));
        PositionBP memory positionInfo = registry.getPositionBP(vaultId, positionId);
        address collateral = abi.decode(positionInfo.additionalData, (address));
        address debTtoken = ITroveManager(tm).debtToken();
        _approveOperations(collateral, address(zap), dAmount);
        zap.openTrove(tm, maxFee, dAmount, bAmount, address(this), address(this));
        registry.updateHoldingPosition(vaultId, positionId, "", "", false);
        _updateTokenInRegistry(collateral);
        _updateTokenInRegistry(debTtoken);
        emit OpenTrove(address(zap), tm, maxFee, dAmount, bAmount);
    }

    function addColl(IStakeNTroveZap zapContract, address tm, uint256 amountIn) public onlyManager nonReentrant {
        bytes32 positionId =
            registry.calculatePositionId(address(this), PRISMA_POSITION_ID, abi.encode(zapContract, tm));
        PositionBP memory positionInfo = registry.getPositionBP(vaultId, positionId);
        if (registry.getHoldingPositionIndex(vaultId, positionId, address(this), "") == 0) {
            revert IConnector_InvalidPosition(positionId);
        }
        address collateral = abi.decode(positionInfo.additionalData, (address));
        _approveOperations(collateral, address(zapContract), amountIn);
        zapContract.addColl(tm, amountIn, address(this), address(this));
        _updateTokenInRegistry(collateral);
        emit AddColl(address(zapContract), tm, amountIn);
    }

    function adjustTrove(
        IStakeNTroveZap zapContract,
        address tm,
        uint256 mFee,
        uint256 wAmount,
        uint256 bAmount,
        bool isBorrowing
    ) public onlyManager nonReentrant {
        bytes32 positionId =
            registry.calculatePositionId(address(this), PRISMA_POSITION_ID, abi.encode(zapContract, tm));
        if (registry.getHoldingPositionIndex(vaultId, positionId, address(this), "") == 0) {
            revert IConnector_InvalidPosition(positionId);
        }
        IBorrowerOperations borrowerOps = zapContract.borrowerOps();
        if (bAmount > 0 && !isBorrowing) {
            _approveOperations(ITroveManager(tm).debtToken(), address(borrowerOps), bAmount);
        }
        borrowerOps.adjustTrove(tm, address(this), mFee, 0, wAmount, bAmount, isBorrowing, address(this), address(this));
        _updateTokenInRegistry(ITroveManager(tm).debtToken());
        _updateTokenInRegistry(borrowerOps.troveManagersData(tm).collateralToken);
        // get health factor
        uint256 healthFactor = ITroveManager(tm).getNominalICR(address(this));
        if (minimumHealthFactor > healthFactor) {
            revert IConnector_LowHealthFactor(healthFactor);
        }
        emit AdjustTrove(address(zapContract), tm, mFee, wAmount, bAmount, isBorrowing);
    }

    function closeTrove(IStakeNTroveZap zapContract, address troveManager) public onlyManager nonReentrant {
        bytes32 positionId =
            registry.calculatePositionId(address(this), PRISMA_POSITION_ID, abi.encode(zapContract, troveManager));
        IBorrowerOperations borrowerOperations = zapContract.borrowerOps();
        borrowerOperations.closeTrove(troveManager, address(this));
        registry.updateHoldingPosition(vaultId, positionId, "", "", true);
        _updateTokenInRegistry(ITroveManager(troveManager).debtToken());
        _updateTokenInRegistry(borrowerOperations.troveManagersData(troveManager).collateralToken);
        emit CloseTrove(address(zapContract), troveManager);
    }
```

findings.technical_details:
In `contracts/connectors/PrismaConnector.sol`, the `adjustTrove` function allows the manager to withdraw collateral (`wAmount`), borrow additional debt, or repay debt (`bAmount`). After executing `borrowerOps.adjustTrove(...)`, the contract attempts to verify that the position remains healthy above `minimumHealthFactor` (initialized to `15e17`, or `1.5e18` representing a 150% collateralization ratio):

```solidity
// get health factor
uint256 healthFactor = ITroveManager(tm).getNominalICR(address(this));
if (minimumHealthFactor > healthFactor) {
    revert IConnector_LowHealthFactor(healthFactor);
}
```

In Prisma Finance (a Liquity-based protocol), `ITroveManager` exposes two distinct collateralization ratio getters:
1. `getNominalICR(address _borrower)`: Computes the Nominal Individual Collateral Ratio (NICR) as `(collateral * 1e20) / debt`. This metric intentionally omits the collateral's market price and is used internally by Prisma solely to maintain the deterministic ordering of troves in the `SortedTroves` list when prices fluctuate.
2. `getCurrentICR(address _borrower, uint256 _price)`: Computes the actual Current Individual Collateral Ratio (ICR) as `(collateral * _price) / debt` in `1e18` precision, reflecting the real USD value of the collateral relative to the debt.

Using `getNominalICR` as `healthFactor` introduces three flaws:
1. **Price-dependent solvency gap**: The ratio is computed purely from raw token balances without multiplying by the collateral's oracle price.
2. **Unit and precision mismatch**: `getNominalICR` divides raw collateral units by raw debt units and scales by `1e20`, whereas `minimumHealthFactor` is denominated in `1e18` precision (`15e17` = 150%).
3. **Broken operational checks**: For high-unit-value collateral such as WETH or weETH against a USD-pegged debt token (e.g., `mkUSD` or `ULTRA`), a normal position with 1 weETH (~$3,000) and 1,500 ULTRA debt has a true ICR of ~200% (`2e18`), which is well above `minimumHealthFactor` (`1.5e18`). However, `getNominalICR` returns `(1e18 * 1e20) / 1500e18 = 6.66e16` (`0.0666e18`), causing `minimumHealthFactor > healthFactor` to revert with `IConnector_LowHealthFactor`. Conversely, if a collateral token has a low unit price or higher decimals relative to debt, an undercollateralized position near liquidation can yield a large nominal ratio and bypass the `minimumHealthFactor` safeguard.

findings.remediation:
Fetch the current collateral price from the `TroveManager`'s price feed (or `fetchPrice()`) and compute the real collateralization ratio using `ITroveManager(tm).getCurrentICR(address(this), price)` (or compute the health factor using `valueOracle` in `1e18` precision).

Update `ITroveManager` and `PrismaConnector.adjustTrove` as follows:

```solidity
    function adjustTrove(
        IStakeNTroveZap zapContract,
        address tm,
        uint256 mFee,
        uint256 wAmount,
        uint256 bAmount,
        bool isBorrowing
    ) public onlyManager nonReentrant {
        bytes32 positionId =
            registry.calculatePositionId(address(this), PRISMA_POSITION_ID, abi.encode(zapContract, tm));
        if (registry.getHoldingPositionIndex(vaultId, positionId, address(this), "") == 0) {
            revert IConnector_InvalidPosition(positionId);
        }
        IBorrowerOperations borrowerOps = zapContract.borrowerOps();
        if (bAmount > 0 && !isBorrowing) {
            _approveOperations(ITroveManager(tm).debtToken(), address(borrowerOps), bAmount);
        }
        borrowerOps.adjustTrove(tm, address(this), mFee, 0, wAmount, bAmount, isBorrowing, address(this), address(this));
        _updateTokenInRegistry(ITroveManager(tm).debtToken());
        // get health factor using current price-adjusted ICR
        uint256 price = ITroveManager(tm).fetchPrice();
        uint256 healthFactor = ITroveManager(tm).getCurrentICR(address(this), price);
        if (minimumHealthFactor > healthFactor) {
            revert IConnector_LowHealthFactor(healthFactor);
        }
        emit AdjustTrove(address(zapContract), tm, mFee, wAmount, bAmount, isBorrowing);
    }
```

findings.technical_details:
`_getPositionTVL` at contracts/connectors/PrismaConnector.sol:145-156:

```solidity
function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256 tvl) {
    PositionBP memory positionInfo = registry.getPositionBP(vaultId, p.positionId);
    if (positionInfo.positionTypeId == PRISMA_POSITION_ID) {
        (address zap, address troveManager) = abi.decode(positionInfo.data, (address, address));
        IBorrowerOperations borrowerOperations = IStakeNTroveZap(zap).borrowerOps();
        address collateral = borrowerOperations.troveManagersData(troveManager).collateralToken;
        address debTtoken = ITroveManager(troveManager).debtToken();
        (uint256 collateralBalance, uint256 debtBalance) =
            ITroveManager(troveManager).getTroveCollAndDebt(address(this));
        return _getValue(collateral, base, collateralBalance) - _getValue(debTtoken, base, debtBalance);
    }
}
```

Two Prisma state transitions close a trove externally while positive net collateral remains, and both were exercised in the test:

1. **Full redemption**: any mkUSD holder calls `redeemCollateral` against the connector's trove for its entire debt. The redeemer's debt tokens are burned, the redeemer is paid `debt / price` of collateral, the trove record is deleted (`coll = 0`, `debt = 0`), and the remainder (`coll - debt / price`) is credited to `surplusBalances[connector]`.
2. **Recovery Mode liquidation**: when the system is in Recovery Mode and the trove's ICR satisfies `MCR <= ICR < CCR`, anyone can liquidate it. The debt is cancelled, the liquidator receives `debt * MCR / price` worth of collateral, and the remainder is credited to `surplusBalances[connector]`.

After either transition `getTroveCollAndDebt(address(this))` returns `(0, 0)`, so `_getPositionTVL` returns 0 for a position that still has claimable collateral. Because the closure happened on Prisma rather than through `PrismaConnector.closeTrove` (which is the only path that calls `registry.updateHoldingPosition(..., true)` to deactivate the position), the holding position stays registered and keeps reporting the wrong value — 0 instead of the surplus.

The vault does not drop to zero, because the borrowed mkUSD still sits in the connector as a trusted token; the vault TVL drops by exactly the surplus amount (50 WETH in the redemption scenario, 34 WETH in the liquidation scenario, both asserted in the test).

`PrismaConnector` exposes no function to claim the surplus at all, so the understatement window stays open until a third party or keeper triggers Prisma's (permissionless) surplus claim and the connector's WETH balance is re-recognized; every deposit, withdrawal and share-price computation in that window uses the wrong TVL.

