The complete test file:

```solidity
// SPDX-License-Identifier: Apache-2.0
pragma solidity 0.8.20;

import "./utils/testStarter.sol";
import "./utils/mocks/MockDataFeed.sol";
import "contracts/connectors/PrismaConnector.sol";
import { IBorrowerOperations } from "contracts/external/interfaces/Prisma/IBorrowerOperations.sol";
import { IStakeNTroveZap } from "contracts/external/interfaces/Prisma/IStakeNTroveZap.sol";

import { ERC20 } from "@openzeppelin/contracts-5.0/token/ERC20/ERC20.sol";
import { ERC20Burnable } from "@openzeppelin/contracts-5.0/token/ERC20/extensions/ERC20Burnable.sol";

/**
 * @dev Mock ERC20 used for the vault base token (= Prisma collateral, WETH-like) and the Prisma debt token (mkUSD-like).
 */
contract MockERC20 is ERC20, ERC20Burnable {
    constructor(string memory n, string memory s) ERC20(n, s) { }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/**
 * @dev Minimal Prisma-side mock. The audited Noya code (PrismaConnector / AccountingManager / Registry /
 * NoyaValueOracle) is used verbatim; only the external Prisma system is simulated, fork-free, behind the
 * exact interfaces the connector consumes (ITroveManager / IBorrowerOperations / IStakeNTroveZap).
 *
 * Prisma behaviours modelled (per the finding):
 *  - BorrowerOperations.openTrove pulls collateral, records the trove, mints the debt token to the borrower.
 *  - redeemCollateral(full debt) burns the redeemer's debt tokens, pays out debt/price collateral and CLOSES
 *    the trove (coll = 0, debt = 0), crediting the remaining collateral to surplusBalances[borrower].
 *  - Recovery-mode liquidation (MCR <= ICR < CCR) cancels the debt, pays the liquidator debt*MCR/price
 *    collateral and credits the remainder to surplusBalances[borrower].
 *  - claimSurplusCollShares lets anyone push the recorded surplus to the borrower.
 */
contract MockTroveManager {
    struct Trove {
        uint256 coll;
        uint256 debt;
    }

    IERC20 public immutable collateralToken;
    ERC20Burnable public immutable _debtToken;
    uint256 public immutable price; // debt-token units per 1 collateral token (both 18 decimals)
    uint256 public immutable MCR = 1.1e18;
    uint256 public immutable CCR = 1.7e18;
    bool public recoveryMode;

    mapping(address => Trove) public troves;
    mapping(address => uint256) public surplusBalances;

    address public immutable borrowerOps;

    modifier onlyBorrowerOps() {
        require(msg.sender == borrowerOps, "TM: only borrower ops");
        _;
    }

    constructor(address collateral, address debtToken_, uint256 price_, address borrowerOps_) {
        collateralToken = IERC20(collateral);
        _debtToken = ERC20Burnable(debtToken_);
        price = price_;
        borrowerOps = borrowerOps_;
    }

    function setRecoveryMode(bool r) external {
        recoveryMode = r;
    }

    // ----- ITroveManager view surface used by PrismaConnector -----
    function getTroveCollAndDebt(address borrower) external view returns (uint256, uint256) {
        return (troves[borrower].coll, troves[borrower].debt);
    }

    function debtToken() external view returns (address) {
        return address(_debtToken);
    }

    function getNominalICR(address borrower) public view returns (uint256) {
        if (troves[borrower].debt == 0) {
            return type(uint256).max;
        }
        return troves[borrower].coll * price / troves[borrower].debt;
    }

    // ----- state transitions (called by BorrowerOperations) -----
    function openTrove(address borrower, uint256 coll, uint256 debt) external onlyBorrowerOps {
        // collateral was already pulled to the TroveManager by the zap / borrower ops
        require(troves[borrower].debt == 0, "TM: trove exists");
        troves[borrower] = Trove(coll, debt);
        MockERC20(address(_debtToken)).mint(borrower, debt);
    }

    function addColl(address borrower, uint256 amount) external onlyBorrowerOps {
        troves[borrower].coll += amount;
    }

    function closeTrove(address borrower) external onlyBorrowerOps {
        Trove memory t = troves[borrower];
        delete troves[borrower];
        _debtToken.burnFrom(borrower, t.debt);
        uint256 total = t.coll + surplusBalances[borrower];
        delete surplusBalances[borrower];
        collateralToken.transfer(borrower, total);
    }

    function openDebt(address borrower, uint256 amount) external onlyBorrowerOps {
        troves[borrower].debt += amount;
        MockERC20(address(_debtToken)).mint(borrower, amount);
    }

    function repayDebt(address borrower, uint256 amount) external onlyBorrowerOps {
        troves[borrower].debt -= amount;
        _debtToken.burnFrom(borrower, amount);
    }

    function withdrawColl(address borrower, uint256 amount) external onlyBorrowerOps {
        troves[borrower].coll -= amount;
        collateralToken.transfer(borrower, amount);
    }

    // ----- external Prisma entry points (anyone) -----
    function redeemCollateral(address borrower, uint256 debtAmount) external {
        Trove memory t = troves[borrower];
        require(t.debt != 0, "TM: no trove");
        require(debtAmount == t.debt, "TM: only full redemption modelled");
        uint256 collToRedeemer = debtAmount * 1e18 / price;
        require(t.coll >= collToRedeemer, "TM: coll");
        // burn the redeemer's debt tokens (approved above)
        _debtToken.burnFrom(msg.sender, debtAmount);
        // trove is closed by redemption: remaining collateral goes to the borrower's surplus
        delete troves[borrower];
        surplusBalances[borrower] += t.coll - collToRedeemer;
        collateralToken.transfer(msg.sender, collToRedeemer);
    }

    function liquidate(address borrower) external {
        Trove memory t = troves[borrower];
        require(t.debt != 0, "TM: no trove");
        uint256 icr = getNominalICR(borrower);
        require(icr < MCR || (recoveryMode && icr < CCR), "TM: not liquidatable");
        delete troves[borrower];
        if (icr < MCR) {
            // normal mode: liquidator takes the whole collateral, no surplus
            collateralToken.transfer(msg.sender, t.coll);
        } else {
            // recovery mode with ICR >= MCR: liquidator gets debt*MCR/price, rest is borrower surplus
            uint256 collToLiquidator = t.debt * MCR / price;
            surplusBalances[borrower] += t.coll - collToLiquidator;
            collateralToken.transfer(msg.sender, collToLiquidator);
        }
    }

    function claimSurplusCollShares(address borrower) external {
        uint256 s = surplusBalances[borrower];
        delete surplusBalances[borrower];
        collateralToken.transfer(borrower, s);
    }
}

contract MockBorrowerOperations is IBorrowerOperations {
    MockTroveManager public tm;
    mapping(address => mapping(address => bool)) public delegates;

    constructor() { }

    function setTroveManager(address tm_, address collateralToken, uint16 index) external {
        tm = MockTroveManager(tm_);
        TroveManagerData memory data = TroveManagerData(collateralToken, index);
        _data[tm_] = data;
    }

    mapping(address => TroveManagerData) internal _data;

    function troveManagersData(address troveManager) external view returns (TroveManagerData memory) {
        return _data[troveManager];
    }

    function setDelegateApproval(address delegate, bool approved) external {
        delegates[msg.sender][delegate] = approved;
    }

    function openTrove(address troveManager, address account, uint256, uint256 coll, uint256 debt, address, address)
        external
    {
        // collateral has already been transferred to the TroveManager by the caller (zap)
        MockTroveManager(troveManager).openTrove(account, coll, debt);
    }

    function addColl(address troveManager, address account, uint256 amount, address, address) external {
        MockTroveManager(troveManager).addColl(account, amount);
    }

    function adjustTrove(
        address troveManager,
        address account,
        uint256,
        uint256,
        uint256 withdrawAmount,
        uint256 debtChange,
        bool isBorrowing,
        address,
        address
    ) external {
        MockTroveManager m = MockTroveManager(troveManager);
        if (debtChange > 0) {
            if (isBorrowing) {
                m.openDebt(account, debtChange);
            } else {
                m.repayDebt(account, debtChange);
            }
        }
        if (withdrawAmount > 0) {
            m.withdrawColl(account, withdrawAmount);
        }
    }

    function closeTrove(address troveManager, address account) external {
        MockTroveManager(troveManager).closeTrove(account);
    }
}

contract MockStakeNTroveZap is IStakeNTroveZap {
    MockBorrowerOperations public immutable bo;
    IERC20 public immutable collateralToken;

    constructor(MockBorrowerOperations bo_, IERC20 collateralToken_) {
        bo = bo_;
        collateralToken = collateralToken_;
    }

    function borrowerOps() external view returns (IBorrowerOperations) {
        return bo;
    }

    function openTrove(address troveManager, uint256 _maxFeePercentage, uint256 ethAmount, uint256 _debtAmount, address, address)
        external
    {
        require(bo.delegates(msg.sender, address(this)), "ZAP: not delegated");
        collateralToken.transferFrom(msg.sender, troveManager, ethAmount);
        bo.openTrove(troveManager, msg.sender, _maxFeePercentage, ethAmount, _debtAmount, address(0), address(0));
    }

    function addColl(address troveManager, uint256 amount, address, address) external {
        require(bo.delegates(msg.sender, address(this)), "ZAP: not delegated");
        collateralToken.transferFrom(msg.sender, troveManager, amount);
        bo.addColl(troveManager, msg.sender, amount, address(0), address(0));
    }

    function adjustTrove(address, uint256, uint256, uint256, bool, address, address) external pure {
        revert("ZAP: adjustTrove not used");
    }

    function troveManagersData(address troveManager) external view returns (TroveManagerData memory) {
        IBorrowerOperations.TroveManagerData memory d = bo.troveManagersData(troveManager);
        return TroveManagerData(d.collateralToken, d.index);
    }
}

