    function test_poc_fullRedemption_understatesTVL_andDilutesShareholders() public {
        // 1. Alice deposits 100 WETH; vault opens a trove: 100 WETH collateral, 50k mkUSD debt (worth 50 WETH)
        _deposit(alice, 100e18);
        assertEq(accountingManager.balanceOf(alice), 100e18, "alice shares");
        assertEq(accountingManager.TVL(), 100e18, "TVL before openTrove");

        _openTrove(100e18, 50_000e18);
        (uint256 c, uint256 d) = tm.getTroveCollAndDebt(address(connector));
        assertEq(c, 100e18, "trove coll");
        assertEq(d, 50_000e18, "trove debt");
        assertEq(accountingManager.TVL(), 100e18, "TVL after openTrove");
        assertEq(_prismaPositionTVL(), 50e18, "position TVL = coll - debt");

        // 2. Bob, an external mkUSD holder, fully redeems against the connector's trove (Prisma public entry point)
        vm.startPrank(bob);
        mkUSD.mint(bob, 50_000e18);
        mkUSD.approve(address(tm), 50_000e18);
        tm.redeemCollateral(address(connector), 50_000e18);
        vm.stopPrank();

        (c, d) = tm.getTroveCollAndDebt(address(connector));
        assertEq(c, 0, "trove closed: coll");
        assertEq(d, 0, "trove closed: debt");
        assertEq(tm.surplusBalances(address(connector)), 50e18, "surplus recorded for connector");
        assertEq(weth.balanceOf(address(tm)), 50e18, "surplus still held by TroveManager");

        // 3. Defect: the Prisma position now reports zero TVL although 50 WETH are claimable
        assertEq(_prismaPositionTVL(), 0, "position TVL ignores surplus");
        assertEq(accountingManager.TVL(), 50e18, "vault TVL understated by exactly the surplus");

        // 4. Carol deposits 100 WETH during the understated window: shares are minted against TVL = 50 WETH
        _deposit(carol, 100e18);
        uint256 carolShares = accountingManager.balanceOf(carol);
        assertGt(carolShares, 199e18, "carol mints ~2x the fair amount of shares");
        assertLt(carolShares, 201e18, "carol mints ~2x the fair amount of shares");

        // 5. The surplus collateral is claimed and recognized
        _recoverSurplus();
        assertEq(tm.surplusBalances(address(connector)), 0, "surplus claimed");
        assertEq(weth.balanceOf(address(connector)), 150e18, "connector holds surplus + carol deposit");
        assertEq(accountingManager.TVL(), 200e18, "TVL back to true value");

        // 6. Measured impact: alice (who did not consent) can redeem only ~66.66 WETH of her 100 WETH;
        //    carol redeems ~133.33 WETH for the 100 WETH she put in.
        uint256 aliceAssets = accountingManager.previewRedeem(accountingManager.balanceOf(alice));
        uint256 carolAssets = accountingManager.previewRedeem(carolShares);
        assertGt(aliceAssets, 66e18, "alice redeemable lower bound");
        assertLt(aliceAssets, 67e18, "alice redeemable upper bound");
        assertGt(carolAssets, 133e18, "carol redeemable lower bound");
        assertLt(carolAssets, 134e18, "carol redeemable upper bound");
        console2.log("alice deposited 100e18 WETH, can redeem:", aliceAssets);
        console2.log("carol deposited 100e18 WETH, can redeem:", carolAssets);
        console2.log("alice loss in WETH (to carol):", 100e18 - aliceAssets);
    }

    // --------------- PoC 2: recovery-mode liquidation leaves surplus --------------- //

    function test_poc_recoveryModeLiquidation_understatesTVL() public {
        _deposit(alice, 100e18);
        // ICR = 100 * 1000 / 60_000 = 166.7%: above MCR (110%), below CCR (170%) => recovery-mode liquidatable
        _openTrove(100e18, 60_000e18);
        assertEq(accountingManager.TVL(), 100e18, "TVL after openTrove");

        tm.setRecoveryMode(true);
        vm.prank(bob);
        tm.liquidate(address(connector));

        (uint256 c, uint256 d) = tm.getTroveCollAndDebt(address(connector));
        assertEq(c, 0, "trove closed: coll");
        assertEq(d, 0, "trove closed: debt");
        assertEq(tm.surplusBalances(address(connector)), 34e18, "surplus = coll - debt*MCR/price");
        assertEq(_prismaPositionTVL(), 0, "position TVL ignores surplus");
        assertEq(accountingManager.TVL(), 60e18, "vault TVL understated by 34 WETH");

        _deposit(carol, 100e18);
        uint256 carolShares = accountingManager.balanceOf(carol);
        assertGt(carolShares, 166e18, "carol mints unfair shares (100 WETH in, TVL shown 60)");
        assertLt(carolShares, 167e18, "carol mints unfair shares (100 WETH in, TVL shown 60)");

        _recoverSurplus();
        // true value after recovery: 94 WETH before carol (60 mkUSD cash + 34 surplus);
        // the missing 6 WETH vs the initial 100 is the legitimate liquidation incentive (debt*MCR/price - debt),
        // not the bug: the bug is the 34 WETH surplus being invisible until claimed.
        assertEq(accountingManager.TVL(), 194e18, "TVL after recovery = true value");

        uint256 aliceAssets = accountingManager.previewRedeem(accountingManager.balanceOf(alice));
        uint256 carolAssets = accountingManager.previewRedeem(carolShares);
        assertGt(aliceAssets, 72e18, "alice redeemable lower bound");
        assertLt(aliceAssets, 73e18, "alice redeemable upper bound");
        uint256 carolGain = carolAssets - 100e18;
        assertGt(carolGain, 21e18, "carol gains more than her deposit's share");
        assertLt(carolGain, 22e18, "carol gains more than her deposit's share");
        console2.log("liquidation case - alice deposited 100e18 WETH, can redeem:", aliceAssets);
        console2.log("liquidation case - alice total loss in WETH:", 100e18 - aliceAssets);
        console2.log("liquidation case - legitimate liquidation incentive in WETH:", uint256(6e18));
        console2.log("liquidation case - loss to carol from TVL understatement:", carolGain);
    }

    // --------------- R3: negative control, trigger absent --------------- //

    function test_control_noExternalClosure_noDilution() public {
        _deposit(alice, 100e18);
        _openTrove(100e18, 50_000e18);
        assertEq(accountingManager.TVL(), 100e18, "TVL after openTrove");
        assertEq(_prismaPositionTVL(), 50e18, "position TVL correct");

        // Same deposit by carol with NO external redemption/liquidation
        _deposit(carol, 100e18);
        assertEq(accountingManager.balanceOf(carol), 100e18, "carol gets fair shares");
        assertEq(accountingManager.TVL(), 200e18, "TVL correct");

        uint256 aliceAssets = accountingManager.previewRedeem(accountingManager.balanceOf(alice));
        uint256 carolAssets = accountingManager.previewRedeem(accountingManager.balanceOf(carol));
        assertEq(aliceAssets, 100e18, "alice suffers no loss");
        assertEq(carolAssets, 100e18, "carol gains nothing extra");
    }
}
```

findings.remediation:
Value the claimable surplus as part of the collateral in `PrismaConnector._getPositionTVL` (contracts/connectors/PrismaConnector.sol:145), so the position keeps reporting the closed trove's leftover collateral until it is claimed:

```solidity
    function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256 tvl) {
        PositionBP memory positionInfo = registry.getPositionBP(vaultId, p.positionId);
        if (positionInfo.positionTypeId == PRISMA_POSITION_ID) {
            (address zap, address troveManager) = abi.decode(positionInfo.data, (address, address));
            IBorrowerOperations borrowerOperations = IStakeNTroveZap(zap).borrowerOps();
            address collateral = borrowerOperations.troveManagersData(troveManager).collateralToken;
            address debTtoken = ITroveManager(troveManager).debtToken();
            (uint256 collateralBalance, uint256 debtBalance) =
                ITroveManager(troveManager).getTroveCollAndDebt(address(this));
            collateralBalance += ITroveManager(troveManager).surplusBalances(address(this));
            uint256 collValue = _getValue(collateral, base, collateralBalance);
            uint256 debtValue = _getValue(debTtoken, base, debtBalance);
            return collValue > debtValue ? collValue - debtValue : 0;
        }
    }
```

With the surplus included, the position reports 50 WETH instead of 0 in the redemption scenario, so the vault TVL a depositor is priced against stays at the true 100 WETH through the closure window and the measured 33.33% dilution cannot occur — the share math returns to the parity the negative control demonstrates. Additionally, add a managed function to `PrismaConnector` that calls Prisma's surplus claim (and re-registers the collateral balance) so the surplus is actually recovered into the vault rather than relying on third parties to trigger the claim.

findings.technical_details:
In `contracts/connectors/PrismaConnector.sol`, `_getPositionTVL` computes the net value of a Prisma position (`PRISMA_POSITION_ID`) as the value of the trove's collateral minus the value of its debt:

```solidity
(uint256 collateralBalance, uint256 debtBalance) =
    ITroveManager(troveManager).getTroveCollAndDebt(address(this));
return _getValue(collateral, base, collateralBalance) - _getValue(debTtoken, base, debtBalance);
```

In Prisma's `TroveManager` contract, `getTroveCollAndDebt(address _borrower)` simply reads the static storage fields `Troves[_borrower].coll` and `Troves[_borrower].debt` that were recorded during the borrower's last state-changing trove operation:

```solidity
function getTroveCollAndDebt(address _borrower) external view returns (uint256 coll, uint256 debt) {
    debt = Troves[_borrower].debt;
    coll = Troves[_borrower].coll;
}
```

However, a Prisma trove's actual collateral and debt balances change continuously between direct user interactions due to two protocol mechanisms:
1. **Interest Accrual:** Prisma charges ongoing interest on debt via a global `activeInterestIndex`. Until `_updateTroveFromAdjustment` is triggered by an interaction on the trove, this accrued interest is not added to `Troves[_borrower].debt`.
2. **Liquidation Redistribution:** When other troves in the `TroveManager` are liquidated and absorbed via redistribution, each active trove receives a pro-rata share of the liquidated collateral (`pendingCollateralReward`) and debt (`pendingDebtReward`). Until `_applyPendingRewards` is called for the borrower, these pending rewards are not reflected in `Troves[_borrower].coll` or `Troves[_borrower].debt`.

Prisma provides `ITroveManager.getEntireDebtAndColl(address _borrower)` specifically to compute the real-time total debt (stored debt + `pendingDebtReward` + `accruedInterest`) and total collateral (stored collateral + `pendingCollateralReward`). By calling `getTroveCollAndDebt` instead of `getEntireDebtAndColl`, `PrismaConnector._getPositionTVL` reports stale collateral and debt figures to `AccountingManager.TVL()`.

findings.remediation:
Update `ITroveManager` to expose `getEntireDebtAndColl(address _borrower)` and use it in `PrismaConnector._getPositionTVL` to retrieve the up-to-date total debt and collateral balances (which already include pending rewards and accrued interest):

```solidity
    function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256 tvl) {
        PositionBP memory positionInfo = registry.getPositionBP(vaultId, p.positionId);
        if (positionInfo.positionTypeId == PRISMA_POSITION_ID) {
            (address zap, address troveManager) = abi.decode(positionInfo.data, (address, address));
            IBorrowerOperations borrowerOperations = IStakeNTroveZap(zap).borrowerOps();
            address collateral = borrowerOperations.troveManagersData(troveManager).collateralToken;
            address debTtoken = ITroveManager(troveManager).debtToken();
            (uint256 debtBalance, uint256 collateralBalance,,) =
                ITroveManager(troveManager).getEntireDebtAndColl(address(this));
            return _getValue(collateral, base, collateralBalance) - _getValue(debTtoken, base, debtBalance);
        }
```

findings.technical_details:
In `PrismaConnector.sol`, `_getPositionTVL` computes the net value of the connector's Prisma trove in terms of the vault's `base` token:

```solidity
function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256 tvl) {
    PositionBP memory positionInfo = registry.getPositionBP(vaultId, p.positionId);
    if (positionInfo.positionTypeId == PRISMA_POSITION_ID) {
        (address zap, address troveManager) = abi.decode(positionInfo.data, (address, address));
        IBorrowerOperations borrowerOperations = IStakeNTroveZap(zap).borrowerOps();
        address collateral = borrowerOperations.troveManagersData(troveManager).collateralToken;
        address debTtoken = ITroveManager(troveManager).debtToken();
        (uint256 collateralBalance, uint256 debtBalance) =
            ITroveManager(troveManager).getTroveCollAndDebt(address(this));
        return _getValue(collateral, base, collateralBalance) - _getValue(debTtoken, base, debtBalance);
    }
}
```

This valuation logic has two closely related oracle integrity flaws:

1. **Manipulable / Unreliable Debt Token Valuation (`_getValue(debTtoken, base, debtBalance)`)**:
   Prisma's debt tokens (`mkUSD` and `ULTRA`) do not have Chainlink price feeds. Within Noya's oracle architecture (`INoyaValueOracle`), tokens without Chainlink feeds must either be priced through `UniswapOracleConnector` or mapped to a proxy feed (such as `USDC/USD`, as done in `PrismaConnector.t.sol`).
   - If priced via DEX pools (`UniswapOracleConnector`), `mkUSD` and `ULTRA` have their primary liquidity on Curve rather than Uniswap V3, leaving Uniswap V3 pools with negligible liquidity that can be cheaply manipulated to skew `_getValue(debTtoken, base, debtBalance)`.
   - If `mkUSD` or `ULTRA` depegs on secondary markets while a fixed $1 USD proxy feed is configured, `_getValue(debTtoken, base, debtBalance)` diverges from the actual cost required to acquire `debtToken` to repay `debtBalance`. Conversely, within Prisma's `TroveManager`, debt is always denominated at face value ($1 USD per unit of debt) for redemptions and liquidation thresholds.

2. **Oracle Discrepancy and Underflow Risk in Net Position Valuation**:
   `PrismaConnector` values `collateralBalance` and `debtBalance` through external `_getValue` routes rather than consulting Prisma's `TroveManager` price feeds or bounding the subtraction. If the oracle price of `debTtoken` spikes (via manipulation on an illiquid pool) or the collateral price drops such that `_getValue(debTtoken, base, debtBalance) > _getValue(collateral, base, collateralBalance)` (for example, during recovery mode, pending liquidation, or transient price divergence between `NoyaValueOracle` and Prisma's internal oracle), the unchecked subtraction on line 154 reverts with an arithmetic underflow. Because `AccountingManager.TVL()` iterates over all active holding positions, a revert in `_getPositionTVL` blocks deposits, withdrawals, and fee accounting across the entire vault.

findings.remediation:
Ensure that `debTtoken` and `collateral` valuations use manipulation-resistant price feeds (such as Prisma's `TroveManager.fetchPrice()` / dedicated Chainlink feeds with Curve EMA fallbacks where appropriate) and guard against arithmetic underflow when subtracting debt value from collateral value:

```solidity
    function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256 tvl) {
        PositionBP memory positionInfo = registry.getPositionBP(vaultId, p.positionId);
        if (positionInfo.positionTypeId == PRISMA_POSITION_ID) {
            (address zap, address troveManager) = abi.decode(positionInfo.data, (address, address));
            IBorrowerOperations borrowerOperations = IStakeNTroveZap(zap).borrowerOps();
            address collateral = borrowerOperations.troveManagersData(troveManager).collateralToken;
            address debTtoken = ITroveManager(troveManager).debtToken();
            (uint256 collateralBalance, uint256 debtBalance) =
                ITroveManager(troveManager).getTroveCollAndDebt(address(this));
            uint256 collateralValue = _getValue(collateral, base, collateralBalance);
            uint256 debtValue = _getValue(debTtoken, base, debtBalance);
            return collateralValue > debtValue ? collateralValue - debtValue : 0;
        }
