// SPDX-License-Identifier: Apache-2.0
pragma solidity 0.8.20;

// PoC for finding #9 of 2024-04-noya (H-19):
// MorphoBlueConnector._getPositionTVL ADDS the borrowed debt (borrowAmount) to the
// position value instead of subtracting it, inflating the vault TVL by 2x borrowAmount.
//
// Fork-free: everything (Noya vault stack + a minimal but faithful Morpho Blue) is
// deployed inside this file / by the repo's own testStarter harness.
//
// Part 1 (base, contract PoC_2024_04_noya__H_19_f9): proves the TVL corruption itself.
// Part 2 (escalation, contract PoC_2024_04_noya__H_19_f9_Escalation): proves the loss the
// corrupted TVL causes through AccountingManager's ERC4626 share pricing (totalAssets()
// == TVL()). While the borrowed debt is outstanding, every queued deposit mints ~half
// the fair shares and every queued withdrawal is priced on the inflated TVL, so an
// early depositor exits with the vault's ENTIRE real value and a later depositor's
// principal is fully drained (shares left redeeming for zero).

import { Test } from "forge-std/Test.sol";

import { ERC20 } from "@openzeppelin/contracts-5.0/token/ERC20/ERC20.sol";
import { IERC20 } from "@openzeppelin/contracts-5.0/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts-5.0/token/ERC20/utils/SafeERC20.sol";

import { MorphoBlueConnector, BaseConnectorCP } from "contracts/connectors/MorphoBlueConnector.sol";
import { IMorpho, Id, MarketParams, Market, Position, IOracle } from "contracts/external/interfaces/Morpho/IMorpho.sol";
import { SharesMathLib } from "contracts/external/libraries/Morpho/SharesMathLib.sol";
import { PositionRegistry } from "contracts/accountingManager/Registry.sol";
import { AccountingManager } from "contracts/accountingManager/AccountingManager.sol";
import { NoyaValueOracle } from "contracts/helpers/valueOracle/NoyaValueOracle.sol";
import { SwapAndBridgeHandler } from "contracts/helpers/SwapHandler/GenericSwapAndBridgeHandler.sol";

import "./utils/testStarter.sol";

// ---------------------------------------------------------------- mocks (test-local) --

contract MockToken is ERC20 {
    constructor(string memory name, string memory symbol) ERC20(name, symbol) { }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev Morpho market oracle: price of 1 collateral unit quoted in loan units, scaled by 1e36.
///      Both mock tokens have 18 decimals, so 1e36 == 1:1.
contract FixedPriceOracle is IOracle {
    uint256 immutable p;
    constructor(uint256 _p) { p = _p; }
    function price() external view returns (uint256) { return p; }
}

/// @dev Minimal but faithful Morpho Blue: same share math (SharesMathLib), same health check
///      on borrow, same Position/Market semantics as production Morpho Blue for the functions
///      the connector uses. Zero interest (no accrual).
contract MinimalMorphoBlue {
    using SharesMathLib for uint256;
    using SafeERC20 for IERC20;

    uint256 internal constant ORACLE_PRICE_SCALE = 1e36;
    uint256 internal constant MARKET_PARAMS_BYTES_LENGTH = 5 * 32;

    mapping(Id => MarketParams) internal _idToMarketParams;
    mapping(Id => Market) internal _market;
    mapping(Id => mapping(address => Position)) internal _position;
    mapping(uint256 => bool) public isLltvEnabled;

    constructor() {
        isLltvEnabled[0.8e18] = true;
    }

    function id(MarketParams memory p) internal pure returns (Id i) {
        assembly ("memory-safe") {
            i := keccak256(p, MARKET_PARAMS_BYTES_LENGTH)
        }
    }

    function createMarket(MarketParams memory marketParams) external {
        Id i = id(marketParams);
        require(marketParams.loanToken != address(0) && marketParams.collateralToken != address(0));
        require(marketParams.oracle != address(0));
        require(isLltvEnabled[marketParams.lltv], "lltv not enabled");
        require(_idToMarketParams[i].loanToken == address(0), "market exists");
        _idToMarketParams[i] = marketParams;
    }

    function idToMarketParams(Id i) external view returns (MarketParams memory) {
        return _idToMarketParams[i];
    }

    function market(Id i) external view returns (Market memory) {
        return _market[i];
    }

    function position(Id i, address user) external view returns (Position memory) {
        return _position[i][user];
    }

    function supply(MarketParams memory marketParams, uint256 assets, uint256, address onBehalf, bytes memory)
        external
        returns (uint256, uint256)
    {
        require(assets > 0, "zero");
        Id i = id(marketParams);
        Market storage m = _market[i];
        IERC20(marketParams.loanToken).safeTransferFrom(msg.sender, address(this), assets);
        uint256 shares = assets.toSharesDown(m.totalSupplyAssets, m.totalSupplyShares);
        _position[i][onBehalf].supplyShares += shares;
        m.totalSupplyAssets += uint128(assets);
        m.totalSupplyShares += uint128(shares);
        return (assets, shares);
    }

    function supplyCollateral(MarketParams memory marketParams, uint256 assets, address onBehalf, bytes memory)
        external
    {
        require(assets > 0, "zero");
        Id i = id(marketParams);
        IERC20(marketParams.collateralToken).safeTransferFrom(msg.sender, address(this), assets);
        _position[i][onBehalf].collateral += uint128(assets);
    }

    function borrow(MarketParams memory marketParams, uint256 assets, uint256, address onBehalf, address receiver)
        external
        returns (uint256, uint256)
    {
        require(assets > 0, "zero");
        Id i = id(marketParams);
        Market storage m = _market[i];
        uint256 shares = assets.toSharesUp(m.totalBorrowAssets, m.totalBorrowShares);
        _position[i][onBehalf].borrowShares += uint128(shares);
        m.totalBorrowAssets += uint128(assets);
        m.totalBorrowShares += uint128(shares);
        require(_isHealthy(i, m, marketParams, onBehalf), "unhealthy");
        IERC20(marketParams.loanToken).safeTransfer(receiver, assets);
        return (assets, shares);
    }

    function repay(MarketParams memory marketParams, uint256 assets, uint256, address onBehalf, bytes calldata)
        external
        returns (uint256, uint256)
    {
        require(assets > 0, "zero");
        Id i = id(marketParams);
        Market storage m = _market[i];
        IERC20(marketParams.loanToken).safeTransferFrom(msg.sender, address(this), assets);
        uint256 shares = assets.toSharesDown(m.totalBorrowAssets, m.totalBorrowShares);
        _position[i][onBehalf].borrowShares -= uint128(shares);
        m.totalBorrowAssets -= uint128(assets);
        m.totalBorrowShares -= uint128(shares);
        return (assets, shares);
    }

    function withdraw(MarketParams memory marketParams, uint256 assets, uint256, address onBehalf, address receiver)
        external
        returns (uint256, uint256)
    {
        require(assets > 0, "zero");
        Id i = id(marketParams);
        Market storage m = _market[i];
        uint256 shares = assets.toSharesDown(m.totalSupplyAssets, m.totalSupplyShares);
        _position[i][onBehalf].supplyShares -= shares;
        m.totalSupplyAssets -= uint128(assets);
        m.totalSupplyShares -= uint128(shares);
        IERC20(marketParams.loanToken).safeTransfer(receiver, assets);
        return (assets, shares);
    }

    function withdrawCollateral(MarketParams memory marketParams, uint256 assets, address onBehalf, address receiver)
        external
    {
        require(assets > 0, "zero");
        Id i = id(marketParams);
        Market storage m = _market[i];
        _position[i][onBehalf].collateral -= uint128(assets);
        require(_isHealthy(i, m, marketParams, onBehalf), "unhealthy");
        IERC20(marketParams.collateralToken).safeTransfer(receiver, assets);
    }

    function _isHealthy(Id i, Market storage m, MarketParams memory params, address borrower)
        internal
        view
        returns (bool)
    {
        if (m.totalBorrowAssets == 0) return true;
        Position storage p = _position[i][borrower];
        uint256 borrowed = uint256(p.borrowShares).toAssetsUp(m.totalBorrowAssets, m.totalBorrowShares);
        uint256 collateralInLoan = uint256(p.collateral) * IOracle(params.oracle).price() / ORACLE_PRICE_SCALE;
        // lltv is WAD-scaled, exactly like production Morpho Blue's collateral.wMulDown(lltv)
        return collateralInLoan * params.lltv / 1e18 >= borrowed;
    }
}

