contract PoC_2024_04_noya__H_19_f9 is testStarter {
    using SharesMathLib for uint256;

    MinimalMorphoBlue morpho;
    MorphoBlueConnector connector;
    MockToken loanToken; // vault base token
    MockToken collateralToken;
    MarketParams marketParams;
    Id marketId;

    address lender = makeAddr("lender"); // ordinary Morpho liquidity provider

    uint256 constant LLTV = 0.8e18;
    uint256 constant COLLATERAL = 1000e18;
    uint256 constant LIQUIDITY = 3000e18;
    uint256 constant BORROW = 500e18;

    function setUp() public {
        vm.startPrank(owner);

        loanToken = new MockToken("Loan", "L");
        collateralToken = new MockToken("Coll", "C");

        // Repo's own harness: registry, oracles, accounting manager, watchers, swap
        // handler, addVault(vaultId = 0) with keeper = maintainer = governer = owner.
        deployEverythingNormal(address(loanToken));

        morpho = new MinimalMorphoBlue();
        FixedPriceOracle oracle = new FixedPriceOracle(1e36); // collateral == loan in value
        marketParams = MarketParams({
            loanToken: address(loanToken),
            collateralToken: address(collateralToken),
            oracle: address(oracle),
            irm: address(0), // zero-interest market (no accrual in the mock)
            lltv: LLTV
        });
        morpho.createMarket(marketParams);
        marketId = Id.wrap(keccak256(abi.encode(marketParams)));

        connector = new MorphoBlueConnector(address(morpho), BaseConnectorCP(registry, vaultId, swapHandler, noyaOracle));

        addConnectorToRegistry(vaultId, address(connector));
        addTrustedTokens(vaultId, address(accountingManager), address(loanToken));
        addTrustedTokens(vaultId, address(accountingManager), address(collateralToken));
        addTrustedTokens(vaultId, address(connector), address(loanToken));
        addTrustedTokens(vaultId, address(connector), address(collateralToken));

        // Morpho market position: connector is the calculator, isDebt = false
        // (this position is expected to net supply/borrow internally - as the finding states).
        registry.addTrustedPosition(
            vaultId, connector.MORPHO_POSITION_ID(), address(connector), true, false, abi.encode(marketId), ""
        );
        // Plain ERC20 holding position (borrowed tokens sitting on the connector).
        registry.addTrustedPosition(
            vaultId, 0, address(accountingManager), false, false, abi.encode(address(loanToken)), ""
        );

        // Reachable precondition 1: market liquidity exists (an ordinary lender supplies
        // loanToken through Morpho's public entry point).
        loanToken.mint(lender, LIQUIDITY);
        vm.stopPrank();
        vm.startPrank(lender);
        loanToken.approve(address(morpho), LIQUIDITY);
        morpho.supply(marketParams, LIQUIDITY, 0, lender, "");
        vm.stopPrank();

        // Reachable precondition 2: the vault connector holds collateral and supplies it
        // through the protocol's own manager entry point (owner is the vault keeper).
        vm.startPrank(owner);
        collateralToken.mint(address(connector), COLLATERAL);
        connector.supply(COLLATERAL, marketId, false); // supplyCollateral
        vm.stopPrank();
    }

    // ---- true (defect-free) net value of the vault, read straight from Morpho ----
    function trueNetValue() internal view returns (uint256) {
        Market memory m = morpho.market(marketId);
        Position memory p = morpho.position(marketId, address(connector));
        uint256 borrowed = uint256(p.borrowShares).toAssetsUp(m.totalBorrowAssets, m.totalBorrowShares);
        uint256 supplied = uint256(p.supplyShares).toAssetsUp(m.totalSupplyAssets, m.totalSupplyShares);
        uint256 collateralInLoan = uint256(p.collateral) * 1e36 / 1e36; // oracle price = 1e36
        uint256 cash = loanToken.balanceOf(address(connector));
        return supplied + collateralInLoan + cash - borrowed;
    }

    function morphoBorrowDebt() internal view returns (uint256) {
        Market memory m = morpho.market(marketId);
        Position memory p = morpho.position(marketId, address(connector));
        return uint256(p.borrowShares).toAssetsUp(m.totalBorrowAssets, m.totalBorrowShares);
    }

    /// @notice THE PoC: borrow through the connector and measure the vault TVL corruption.
    function test_PoC_borrow_inflates_vault_TVL_by_2x_borrow() public {
        // --- baseline: no debt, TVL is correct ---
        assertEq(morphoBorrowDebt(), 0, "baseline debt must be 0");
        assertEq(accountingManager.TVL(), COLLATERAL, "baseline TVL must equal true value");

        // --- the manager borrows through the connector (keeper = owner) ---
        vm.prank(owner);
        connector.borrow(BORROW, marketId);

        // Real state change (R1): the connector received 500 loanToken; Morpho booked 500 debt.
        assertEq(loanToken.balanceOf(address(connector)), BORROW, "connector must hold the borrowed tokens");
        assertApproxEqAbs(morphoBorrowDebt(), BORROW, 2, "Morpho must book the debt");

        // True net value did not change: 500 cash + 1000 collateral - 500 debt = 1000.
        uint256 net = trueNetValue();
        assertApproxEqAbs(net, COLLATERAL, 2, "true net value must stay 1000e18");

        // What the vault actually reports (TVLHelper.getTVL + AccountingManager.TVL):
        //   token position (accounting manager calculator):   500
        //   morpho position (buggy _getPositionTVL):  0 + 500 + 1000 = 1500
        //   => 2000 == true value + 2 * BORROW
        uint256 tvl = accountingManager.TVL();
        assertApproxEqAbs(tvl, 2000e18, 5, "buggy TVL must be collateral + 2x borrow");
        assertApproxEqAbs(tvl - net, 2 * BORROW, 8, "overstatement must be exactly 2x borrow");
        assertGt(tvl, net, "vault TVL must be overstated");
    }

    /// @notice R3 negative control: identical sequence with the borrow (the defect trigger)
    ///         absent - the vault TVL must equal the true net value.
