        uint256 net = trueNetValue();
        uint256 tvl = accountingManager.TVL();

        assertEq(morphoBorrowDebt(), 0, "control has no debt");
        assertEq(net, COLLATERAL, "control true net value is 1000e18");
        assertEq(tvl, net, "control TVL must equal the true net value");
        assertEq(tvl, COLLATERAL, "control TVL must be exactly the collateral value");
    }

    /// @notice Second control: after a full repay the reported TVL returns to the true value,
    ///         proving the inflation is caused specifically by the outstanding-borrow term.
    function test_negativeControl_repay_restores_TVL() public {
        vm.startPrank(owner);
        connector.borrow(BORROW, marketId);
        connector.repay(BORROW, marketId);
        vm.stopPrank();

        assertLe(morphoBorrowDebt(), 2, "debt repaid (<= 2 wei share-rounding dust)");
        assertApproxEqAbs(accountingManager.TVL(), COLLATERAL, 5, "TVL must return to the true value");
    }
}

