// Faithful-enough Morpho Blue core: the repo only carries interfaces + math libs, so the
// minimal production semantics needed by MorphoBlueConnector are reproduced here.
contract MorphoBlueMock {
    using SharesMathLib for uint256;

    uint256 public constant ORACLE_PRICE_SCALE = 1e36;

    mapping(Id => MarketParams) public idToMarketParams;
    mapping(Id => Market) public market;
    mapping(Id => mapping(address => Position)) public position;
    mapping(address => bool) public isIrmEnabled;
    mapping(uint256 => bool) public isLltvEnabled;
    address public immutable owner;

    constructor(address _owner) {
        owner = _owner;
    }

    modifier onlyMorphoOwner() {
        require(msg.sender == owner);
        _;
    }

    function enableIrm(address irm) external onlyMorphoOwner {
        isIrmEnabled[irm] = true;
    }

    function enableLltv(uint256 lltv) external onlyMorphoOwner {
        require(lltv > 0 && lltv < 1e18);
        isLltvEnabled[lltv] = true;
    }

    function idOf(MarketParams memory p) public pure returns (Id) {
        return Id.wrap(keccak256(abi.encode(p)));
    }

    function createMarket(MarketParams memory p) external {
        require(isIrmEnabled[p.irm]);
        require(isLltvEnabled[p.lltv]);
        idToMarketParams[idOf(p)] = p;
    }

    function supply(MarketParams memory p, uint256 assets, uint256, address onBehalf, bytes memory)
        external
        returns (uint256, uint256)
    {
        Id id = idOf(p);
        Market storage m = market[id];
        uint256 shares = assets.toSharesDown(m.totalSupplyAssets, m.totalSupplyShares);
        m.totalSupplyAssets += uint128(assets);
        m.totalSupplyShares += uint128(shares);
        position[id][onBehalf].supplyShares += shares;
        IERC20(p.loanToken).transferFrom(msg.sender, address(this), assets);
        return (assets, shares);
    }

    function withdraw(MarketParams memory p, uint256 assets, uint256, address onBehalf, address receiver)
        external
        returns (uint256, uint256)
    {
        Id id = idOf(p);
        Market storage m = market[id];
        uint256 shares = assets.toSharesUp(m.totalSupplyAssets, m.totalSupplyShares);
        position[id][onBehalf].supplyShares -= shares;
        m.totalSupplyAssets -= uint128(assets);
        m.totalSupplyShares -= uint128(shares);
        IERC20(p.loanToken).transfer(receiver, assets);
        return (assets, shares);
    }

    function supplyCollateral(MarketParams memory p, uint256 assets, address onBehalf, bytes memory) external {
        Id id = idOf(p);
        position[id][onBehalf].collateral += uint128(assets);
        IERC20(p.collateralToken).transferFrom(msg.sender, address(this), assets);
    }

    function withdrawCollateral(MarketParams memory p, uint256 assets, address onBehalf, address receiver) external {
        Id id = idOf(p);
        require(_isHealthy(p, id, onBehalf));
        position[id][onBehalf].collateral -= uint128(assets);
        IERC20(p.collateralToken).transfer(receiver, assets);
    }

    function borrow(MarketParams memory p, uint256 assets, uint256, address onBehalf, address receiver)
        external
        returns (uint256, uint256)
    {
        Id id = idOf(p);
        require(_isHealthy(p, id, onBehalf));
        Market storage m = market[id];
        uint256 shares = assets.toSharesUp(m.totalBorrowAssets, m.totalBorrowShares);
        position[id][onBehalf].borrowShares += uint128(shares);
        m.totalBorrowAssets += uint128(assets);
        m.totalBorrowShares += uint128(shares);
        IERC20(p.loanToken).transfer(receiver, assets);
        return (assets, shares);
    }

    function repay(MarketParams memory p, uint256 assets, uint256, address onBehalf, bytes calldata)
        external
        returns (uint256, uint256)
    {
        Id id = idOf(p);
        Market storage m = market[id];
        uint256 shares = assets.toSharesDown(m.totalBorrowAssets, m.totalBorrowShares);
        position[id][onBehalf].borrowShares -= uint128(shares);
        m.totalBorrowAssets -= uint128(assets);
        m.totalBorrowShares -= uint128(shares);
        IERC20(p.loanToken).transferFrom(msg.sender, address(this), assets);
        return (assets, shares);
    }

    function _isHealthy(MarketParams memory p, Id id, address user) internal view returns (bool) {
        Position storage pos = position[id][user];
        if (pos.borrowShares == 0) return true;
        Market storage m = market[id];
        uint256 borrowed = uint256(pos.borrowShares).toAssetsUp(m.totalBorrowAssets, m.totalBorrowShares);
        uint256 maxBorrow = uint256(pos.collateral) * IOracle(p.oracle).price() / ORACLE_PRICE_SCALE * p.lltv / 1e18;
        return maxBorrow >= borrowed;
    }
}

