        // repay
        borrowPositionProxy.closeBorrowPosition(accountId, 0, marketIds);
        bytes32 positionId = registry.calculatePositionId(address(this), DOL_POSITION_ID, "");
        if (dolomiteMargin.getAccountNumberOfMarketsWithBalances(Info(address(this), accountId)) == 0) {
