buyShareCred(credIdCounter, 1, 0);
```

More generally, refactor the shared buy path to complete all balance, supply, and timestamp effects before refunding ETH or making other external calls. Apply one consistent reentrancy guard to all creation, buy, and sell paths, preferably around the shared internal trade routine rather than independently guarding nested public calls.

Make the fixed-price curve’s supply validation direction-aware. Purchases should enforce the maximum resulting supply, while sales should only ensure that the amount does not exceed current supply.

```solidity
function getPriceData(
    uint256 credId_,
    uint256 supply_,
    uint256 amount_,
    bool isSign_
)
    public
    view
    returns (uint256 price, uint256 protocolFee, uint256 creatorFee)
{
    if (isSign_) {
        if (supply_ > MAX_SUPPLY || amount_ > MAX_SUPPLY - supply_) revert InvalidSupply();
    } else if (amount_ > supply_) {
        revert InvalidSupply();
    }

    price = FIXED_PRICE * amount_;
    protocolFee = _getProtocolFee(price);

    (uint16 buyShareRoyalty, uint16 sellShareRoyalty) = credContract.getCreatorRoyalty(credId_);
    uint16 royaltyRate = isSign_ ? buyShareRoyalty : sellShareRoyalty;
    creatorFee = (price * royaltyRate) / RATIO_BASE;
}
```

Add boundary tests covering purchases from supply 998 to 999 followed by sales of one and multiple shares, and require every supported bonding curve to provide valid sell quotes at maximum supply.

Make the portfolio-removal helper internal so it can only be reached through balance-accounting operations that maintain all related structures atomically.

```solidity
function _removeCredIdPerAddress(uint256 credId_, address sender_) internal {
    if (_credIdsPerAddress[sender_].length == 0) revert EmptyArray();

    uint256 indexToRemove = _credIdsPerAddressCredIdIndex[sender_][credId_];
    if (indexToRemove >= _credIdsPerAddress[sender_].length) revert IndexOutofBounds();

    uint256 credIdToRemove = _credIdsPerAddress[sender_][indexToRemove];
    if (credId_ != credIdToRemove) revert WrongCredId();

    uint256 lastIndex = _credIdsPerAddress[sender_].length - 1;
    uint256 lastCredId = _credIdsPerAddress[sender_][lastIndex];

    _credIdsPerAddress[sender_][indexToRemove] = lastCredId;

    if (indexToRemove < lastIndex) {
        _credIdsPerAddressCredIdIndex[sender_][lastCredId] = indexToRemove;
    }

    _credIdsPerAddress[sender_].pop();
    delete _credIdsPerAddressCredIdIndex[sender_][credIdToRemove];

    if (_credIdsPerAddressArrLength[sender_] > 0) {
        _credIdsPerAddressArrLength[sender_]--;
    }
}
```

