    !((addition <= MAX_M_DIGIT_NUMBER && addition >= MIN_M_DIGIT_NUMBER) ||
        (addition <= MAX_L_DIGIT_NUMBER && addition >= MIN_L_DIGIT_NUMBER))
) {
    uint digitsMantissa = findNumberOfDigits(addition);
    assembly {
        let mantissaReducer := sub(digitsMantissa, MAX_DIGITS_M)
        let isResultL := slt(MAXIMUM_EXPONENT, add(sub(rExp, ZERO_OFFSET), mantissaReducer))
        if isResultL {
            mantissaReducer := sub(mantissaReducer, DIGIT_DIFF_L_M)
            r := or(r, MANTISSA_L_FLAG_MASK)
        }
        ...
    }
} else if (
    addition >= MIN_L_DIGIT_NUMBER &&
    rExp < (ZERO_OFFSET - uint(MAXIMUM_EXPONENT * -1) - DIGIT_DIFF_L_M)
) {
    assembly {
        addition := sdiv(addition, BASE_TO_THE_DIGIT_DIFF)
        r := add(r, shl(EXPONENT_BIT, DIGIT_DIFF_L_M))
    }
}
```

Because the primary `if` branch is skipped whenever `addition` already has 38 digits (`[MIN_M_DIGIT_NUMBER, MAX_M_DIGIT_NUMBER]`) or 72 digits (`[MIN_L_DIGIT_NUMBER, MAX_L_DIGIT_NUMBER]`), three precision-flag and mantissa-width inconsistencies occur:

1. **72-digit `addition` with `rExp >= ZERO_OFFSET - uint(MAXIMUM_EXPONENT * -1) - DIGIT_DIFF_L_M` (`8140`):** Both the `if` and `else if` branches are skipped. `addition` remains a 72-digit mantissa, and line 243 (`r := or(r, addition)`) packs it into `r` **without setting `MANTISSA_L_FLAG_MASK`**.
2. **Off-by-one boundary at `rExp == 8140`:** In the `if` branch (line 190 / 392), a 72-digit value (`mantissaReducer = 34`) is kept as `L` only when `rExp - ZERO_OFFSET + 34 > MAXIMUM_EXPONENT` (`rExp > 8140`), and downscaled to `M` when `rExp <= 8140`. However, line 207 / 409 checks `rExp < 8140` instead of `rExp <= 8140`, so at `rExp == 8140` a 72-digit `addition` is neither downscaled to 38 digits nor tagged with `MANTISSA_L_FLAG_MASK`.
3. **38-digit `addition` with `rExp > ZERO_OFFSET - uint(MAXIMUM_EXPONENT * -1)` (`8174`):** Both branches are skipped, leaving a 38-digit `M` mantissa with an exponent greater than `MAXIMUM_EXPONENT` (`-18`) instead of upscaling it by `BASE_TO_THE_DIGIT_DIFF` ($10^{34}$) to a 72-digit `L` mantissa with `MANTISSA_L_FLAG_MASK` set.

Similarly, `Float128.toPackedFloat` (lines 1095–1129) uses the same guard and unconditionally sets `MANTISSA_L_FLAG_MASK` whenever a 72-digit `mantissa` is supplied (lines 1125–1129), failing to downscale it to a 38-digit `M` mantissa when `exponent <= MAXIMUM_EXPONENT - int(DIGIT_DIFF_L_M)` (`-52`).

